    class Program
    {
        static void Main(string[] args)
        {
            string str = Console.ReadLine();
            int index = str.IndexOf(' ');
            int n = Convert.ToInt32(str.Substring(0, index));
            int k = Convert.ToInt32(str.Substring(index));

            int time = 240 - k;
            int count = 0;

            for(int i = 1; i <= n; i++)
            {
                if (time - i * 5 >= 0)
