            public static long gcd(long a, long b)
            {
                if (b == 0)
                {
                    return a;
                }
                return gcd(b, a % b);
            }

            public static long getDividersImproved1(long n)
            {            
                long count = 0;
                //check why changing type from int to long makes it faster.
                for (long factor = 1; factor * factor <= n; ++factor)
                {
                    if (n % factor == 0)
                    {
                        count++;
                        //test if we can just check factor not to be equal to factor after divison: n / factor
                        if (factor != n / factor)
                        {
                            count++;
                        }
                    }
                }

                return count;
            }

            public static List<long> getDividersImproved2(long n)
            {
                List<long> result = new List<long>();

                for (int factor = 1; factor * factor <= n; ++factor)
                {
                    if (n % factor == 0)
                    {
                        result.Add(factor);
                        //test if we can just check factor not to be equal to factor after divison: n / factor
                        if (factor != n / factor)
                        {
                            result.Add(n / factor);
                        }
                    }
                }

                return result;
            }

            public static List<long> getDividersImproved(long n)
            {
                List<long> result = new List<long>();

                result.Add(1);
                for (long factor = 2; factor <= Math.Sqrt(n); ++factor)
                {
                    if (n % factor == 0)
                    {
                        result.Add(factor);
                        result.Add(n / factor);
                    }
                }

                if (n > 1)
                {
                    result.Add(n);
                }

                return result;
            }
        }
    }

