            else if (n > a && modN != 0)
                n += a - modN;
            else
                n = a;
            if (m > a && modM==0)
                m += modM;
            else if(m > a && modM != 0)
                m += a - modM;
            else
                m = a;

            Console.WriteLine(Convert.ToInt64(Math.Ceiling((m*n)/(a*a))));
        }
