    using System;

    class Program
    {
        public static int Nod(int a, int b)
        {
            int temp;
            if (b > a)
            {
                temp = b;
                b = a;
                a = temp;
            }
            while (true)
            {
                if (a % b == 0)
                {
                    return b;
                }
                else
                {
                    temp = b;
                    b = a % b;
                    a = temp;
                }
            }
        }

        static void Main(string[] args)
        {
            string d = Console.ReadLine();
            string[] q = d.Split(' ');
            int a = int.Parse(q[0]);
            int b = int.Parse(q[1]);
            int n = int.Parse(q[2]);
            int nod;
            while(true)
            {
                if (n == 0)
                {
                    Console.WriteLine("1");
                    break;
                }
                nod = Nod(a, n);
                if (n >= nod)
                {
                    n -= nod;
                }
                else
                {
                    Console.WriteLine("1");
                    break;
                }

                if (n == 0)
                {
                    Console.WriteLine("0");
                    break;
                }
                nod = Nod(b, n);
                if (n >= nod)
                {
                    n -= nod;
                }
                else
                {
                    Console.WriteLine("0");
                    break;
                }
            }
        }
    }
