   class Program
    { 
        static void Main(string[] args)
        {
            char[] input = Console.In.ReadToEnd().Split(new char[] { '\n', '\r'}, StringSplitOptions.RemoveEmptyEntries)[1].ToCharArray();
            Stack<int> stack = new Stack<int>();
            stack.Push(input.Length);
            {
                int lim = (int)Math.Sqrt(input.Length);
                for (int i = 2; i <= lim; ++i)
                {
                    if (input.Length % i == 0)
                    {
                        stack.Push(input.Length / i);
                        char temp;
                        for (int j = 0, c = i-1; j < c;)
                        {
                            temp = input[j];
                            input[j++] = input[c];
                            input[c--] = temp;
                        }
                    }
                }
                if (stack.Peek() == lim) stack.Pop();
                {
                    char temp;
                    while (stack.Count > 0)
                    {
                        for (int j = 0, c = stack.Pop()-1; j < c;)
                        {
                            temp = input[j];
                            input[j++] = input[c];
                            input[c--] = temp;
                        }
                    }
                }
            }
            Console.WriteLine(new string(input));
        }
    }

