public class Program
{
	public static void Main()
	{
		int[] k = Console.ReadLine().Split().Select(int.Parse).ToArray();
		int C256 = new[] { k[0], k[2], k[3] }.Min();
		k[0] -= C256;
		int C32 = Math.Min(k[0], k[1]);
		var X = 256 * C256 + 32 * C32;
		k[0] += C256;	// reset
		C32 = Math.Min(k[0], k[1]);
		k[0] -= C32;
		C256 = new[] { k[0], k[2], k[3] }.Min();
		var Y = 256 * C256 + 32 * C32;
		Console.WriteLine(Math.Max(X, Y));
	}
