using System;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

namespace Codeforces
{
    public class Solution
    {
        public void Execute()
        {
            var s = ReadLine();
            for (var i = 0; i < s.Length; ++i)
            {
                if(!Check(s[i]))
                {
                    if(s[i] != 'n')
                    {
                        if(i + 1 == s.Length || !Check(s[i+1]))
                        {
                            WriteLine("NO");
                            return;
                        }
                    }
                }
            }
            WriteLine("YES");
        }

        private bool Check(char c)
        {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

        private StreamReader reader;
        private StreamWriter writer;

        public Solution(StreamReader reader, StreamWriter writer)
        {
            this.reader = reader;
            this.writer = writer;
        }

        private string ReadLine() => reader.ReadLine();
        private int ReadInt() => int.Parse(ReadLine());
        private long ReadLong() => long.Parse(ReadLine());
        private double ReadDouble() => double.Parse(ReadLine());
        private string[] Split(char c = ' ') => ReadLine().Split(c);
        private int[] ReadInts(char c = ' ') => Split(c).Select(int.Parse).ToArray();
        private long[] ReadLongs(char c = ' ') => Split(c).Select(long.Parse).ToArray();
        private double[] ReadDoubles(char c = ' ') => Split(c).Select(double.Parse).ToArray();

        private void Write(string s) => writer.Write(s);
        private void WriteLine(string s) => writer.WriteLine(s);
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            CultureInfo.DefaultThreadCurrentCulture = CultureInfo.InvariantCulture;
            StreamReader reader = null;
            StreamWriter writer = null;
            MemoryStream output = null;

            var (test, name) = TestMode(args);

            if(test)
            {
                reader = new StreamReader($"in{name}.txt");
                output = new MemoryStream();
                writer = new StreamWriter(output);
            }
            else
            {
                reader = new StreamReader(Console.OpenStandardInput());
                writer = new StreamWriter(Console.OpenStandardOutput());
            }
            new Solution(reader, writer).Execute();
            writer.Flush();
            if(test)
            {
                var expect = new StreamReader($"out{name}.txt").ReadToEnd();
                var actual = Encoding.UTF8.GetString(output.ToArray());
                Console.WriteLine(actual);
                Console.WriteLine(actual.TrimEnd() == expect.TrimEnd() ? $"Test {name} passed." : $"Test {name} failed.");
            }
        }

        private static (bool, string) TestMode(string[] args)
        {
            if(args.Length > 1 && args.First() == "test")
            {
                return (true, args[1]);
            }
            return (false, null);
        }
    }
}

