    {
        var c = base.CompareTo(p);
        if (c == 0)
            c = Comparer<T3>.Default.Compare(v3, p.v3);
        return c;
    }
    public override string ToString() => $"{base.ToString()} {v3.ToString()}";
    public void Deconstruct(out T1 a, out T2 b, out T3 c) { Deconstruct(out a, out b); c = v3; }

    public static implicit operator Pair<T1, T2, T3>((T1 f, T2 s, T3 t) p) => new Pair<T1, T2, T3>(p.f, p.s, p.t);
}
#endregion

using System;
using System.IO;

class Test
{
	static Stream stdin = Console.OpenStandardInput();
	static byte[] buf = new byte[16 << 10];
	static int cap = 1;
	static int pos = 1;
	public static byte nextByte()
	{
		if (cap == 0) return 0;
		if (pos == cap)
		{
			cap = stdin.Read(buf, 0, 16 << 10);
			if (cap == 0) return 0;
			pos = 0;
		}
		return buf[pos++];
	}
	public static long nextInt()
	{
		byte c = nextByte();
		while ((c < '0' || c > '9') && c != '-') c= nextByte();
		long sign = 1;
		if (c == '-')
		{
			c = nextByte();
			sign = -1;
		}
		long res = 0;
		while (c >= '0' && c <= '9')
		{
			res = res * 10 + c - '0';
			c = nextByte();
		}
		return res * sign;
	}
	public static double nextDouble()
	{
		byte c = nextByte();
		while ((c < '0' || c > '9') && c != '-' && c != '.') c= nextByte();
		double sign = 1;
		if (c == '-')
		{
			sign = -1;
			c = nextByte();
		}
		int p = -1;
		long res = 0;
		while (c >= '0' && c <= '9' || c == '.')
		{
			if (c == '.') p = 0;
			else
			{
				res = res * 10 + c - '0';
				if (p != -1) ++p;
			}
			c = nextByte();
		}
		if (p != -1) sign *= Math.Pow(10.0, -p);
		return sign * (double)res;
	}


	public static void Main()
	{
		long n = nextInt();
		long m = nextInt();
		long a = nextInt();
		long b = nextInt();

		long make = (m - n % m) % m;
		long brake = n % m;

		if (a * make < b * brake) Console.WriteLine(a * make);
		else Console.WriteLine(b * brake);
	}
}

