        {
            var c1 = (a - 1 + i) % n;
            var c2 = (b - 1 - i) % n;
            c2 = c2 < 0 ? c2 + n : c2;
            if (c1 == c2 )
            {
                Console.WriteLine("YES");
                return;
            }
            if (c1 == x - 1 || c2 == y - 1)
            {
                Console.WriteLine("NO");
                return;
            }
        }
    }
}

