        static int nextInt()
        {
            int t = input.Read();
            while ((t < '0' || t > '9' || t < 'A' || t > 'Z') && t != '-') t = input.Read();
            if (t >= 'A' && t <= 'Z')
                return t;
            int sign = 1;
            if (t == '-')
            {
                sign = -1;
                t = input.Read();
            }
            int x = 0;
            while (t >= '0' && t <= '9')
            {
                x *= 10;
                x += t - '0';
                t = input.Read();
            }
            return x * sign;
        }

