class cin
{
    private static readonly System.IO.StreamReader reader = new System.IO.StreamReader(Console.OpenStandardInput(1024 * 16), Encoding.ASCII, false, 1024 * 10);

    static int read() { return reader.Read(); }

    public static string Scan()
    {
        int c;
        StringBuilder sb = new StringBuilder();
        do c = read(); while (c < 33 || c > 126);
        for (; c >= 33 && c <= 126; c = read()) sb.Append((char)c);
        return sb.ToString();
    }

    public static uint gu()
    {
        return gu(read());
    }

    static uint gu(int first)
    {
        uint u = 0;
        for (int c = first; c != -1; c = read())
        {
            if (!char.IsDigit((char)c)) return u;
            u = 10 * u + (uint)c - '0';
        }

        throw new System.IO.IOException();
    }

    public static int gi()
    {
        for (int c = read(); c != -1; c = read())
        {
            switch ((char)c)
            {
                case '-':
                    read();
                    return -(int)gu(read());

                default:
                    if (char.IsDigit((char)c)) return (int)gu(c);
                    break;
            }
        }

        throw new System.IO.IOException();
    }
}

