namespace The_Big_Race
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            long t = Next();
            long w = Next();
            long b = Next();

            long min = Math.Min(w, b);
            long max = Math.Max(w, b);
            long g = Gcd(w, b);
            long count = min - 1;
            if (w == b || t < min)
                count = t;
            else if (t/min >= max/g)
            {
                long d = min/g*max;
                long cnt = t/d - 1;

                count += cnt*(min);

                long tt = (cnt + 1)*d;

                count += Math.Min(t - tt + 1, min);
            }


            g = Gcd(count, t);
            writer.Write(count/g);
            writer.Write('/');
            writer.WriteLine(t/g);
            writer.Flush();
        }

        public static long Gcd(long a, long b)
        {
            return b == 0 ? a : Gcd(b, a%b);
        }

        private static long Next()
        {
            int c;
            long res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

