namespace _292C
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            long t = long.Parse(input[0]);
            long w = long.Parse(input[1]);
            long b = long.Parse(input[2]);

            long min = (w > b) ? b : w;
            if (t < min)
                Console.WriteLine("1/1");
            else
            {
                long nok = NOK(w, b, t+1);
                long extra = (t / nok) * nok + min - t - 1;
                if ((extra < 0) || (nok == 1))
                    extra = 0;
                long count = (t / nok + 1) * min - 1 - extra;
                if (count == 0)
                {
                    Console.WriteLine("0/1");
                    return;
                }

                long NOD = NOD_Evclid(t, count);
                t /= NOD;
                count /= NOD;

                Console.WriteLine(count.ToString() + "/" + t.ToString());
                Console.ReadLine();

            }
        }
        static long NOK(long a, long b, long def)
        {
            long min, max;
            if (a > b)
            {
                min = b;
                max = a;
            }
            else
            {
                min = a;
                max = b;
            }

            a = min / NOD_Evclid(max, min);
            if (def / max >= a)
                return a * max;
            else
                return def;
        }
        static long NOD_Evclid(long a, long b) // a>b !
        {
            //https://ru.wikipedia.org/wiki/Алгоритм_Евклида
            long r = a % b;
            while (r != 0)
            {
                a = b;
                b = r;
                r = a % b;
            }
            return b;
        }
    }
}

