﻿using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace Multiplication_Table
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();

            for (int i = 1; i < n; i++)
            {
                for (int j = 1; j < n; j++)
                {
                    writer.Write(ConvertToString(i*j, n));
                    writer.Write(' ');
                }
                writer.WriteLine();
            }

            writer.Flush();
        }

        private static string ConvertToString(int i, int b)
        {
            var st = new Stack<int>();
            while (i > 0)
            {
                st.Push(i%b);
                i /= b;
            }
            var bb = new StringBuilder();
            foreach (int j in st)
            {
                bb.Append((char) (j + '0'));
            }
            return bb.ToString();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

