public class Solver
{
    public object Solve()
    {
        var a = ReadLongArray();
        Array.Sort(a);
        long x = Math.Min(a[2] - a[1], a[0]);
        a[1] += x;
        a[0] -= x;

        a[1] += a[0] / 2;
        a[2] += (a[0] + 1) / 2;

        return Math.Min(a[1], (a[1] + a[2]) / 3);

        return null;
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;

    static void Main()
    {
#if DEBUG
        reader = new StreamReader("..\\..\\input.txt");
