namespace Pages
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();
            int p = Next();
            int k = Next();

            int first = p - k;
            bool ok = false;
            if (first > 1)
            {
                writer.Write("<<");
                ok = true;
            }
            for (int i = Math.Max(1, first); i < p; i++)
            {
                if (ok)
                    writer.Write(' ');
                writer.Write(i);
                ok = true;
            }

            if (ok)
                writer.Write(' ');
            writer.Write('(');
            writer.Write(p);
            writer.Write(')');

            first = Math.Min(n, p + k);
            for (int i = p + 1; i <= first; i++)
            {
                writer.Write(' ');
                writer.Write(i);
            }

            if (first!=n)
            {
                writer.Write(" >>");
            }

            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

