namespace C_Candies
{
    class Program
    {
        static void Main(string[] args)
        {
            long n = long.Parse(Console.ReadLine());

            Console.WriteLine(binarySearch(n) + 1);
        }

        static long binarySearch(long total) {
            long low = 1;
            long high = total;
		    while (low <= high) {
			    long middle = (low + high) / 2;

			    if (canEat(middle, total)) {
				    high = middle - 1;
			    }
			    else {
				    low = middle + 1;
			    }
		    }

		    return high;
	    }

        static bool canEat(long k, long total)
        {
            long eatenA = 0;
            long eatenB = 0;
            long current = total;

            while(current > 0)
            {
                eatenA += Math.Min(k, current);
                current = Math.Max(current - k, 0);
                eatenB += current / 10;
                current -= current / 10;
            }

            if(total % 2 == 0)
            {
                return eatenA >= total / 2;
            }
            else
            {
                return eatenA > total / 2;
            }
        }
    }
}

