namespace Olympo
{

    class Program
    {

        static long[] buildFact(long n, long M)
        {
            var res = new long[n + 1];
            res[0] = 1;
            for(long i = 1; i <= n; i++)
            {
                res[i] = (res[i - 1] * i) % M;
            }

            return res;
        }

        static long axar(long a, long b, long M)
        {
            a = a % M;
            if (b == 0)
                return 1;
            long res = b % 2 == 0 ? 1 : a;
            var rec = axar(a, b >> 1, M);
            res = (((rec * rec) % M) * res) % M;
            return res;
        }

        static long[] buildInv(long n, long M, long[] fact)
        {
            var res = new long[n + 1];
            res[0] = 1;
            for (long i = 1; i <= n; i++)
            {
                res[i] = axar(fact[i], M - 2, M);
            }

            return res;
        }

        static long getC(long n, long k, long M, long[] fact, long[] inv)
        {
            if (n < k) return 0;
            return (((fact[n] * inv[k]) % M) * inv[n - k]) % M;
        }

        static void Main(string[] args)
        {
            var inputs = Console.ReadLine().Split(' ').Select(long.Parse).ToList();
            long n = inputs[0], k = inputs[1];
            long M = 998244353l;
            var f = buildFact(n,  M);
            var inv = buildInv(n, M, f);
            var res = 0l;
            for(long i=1;i <= n; i++)
                res = (res + getC(  n / i - 1, k-1, M, f, inv )  )  % M;
            Console.WriteLine(res);
        }
    }
