using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    int N;
    int K;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        K = sc.NextInt();
        ModInt[] f = new ModInt[500000];
        f[0] = 1;
        for (int i = 1; i < 500000; i++)
        {
            f[i] = f[i - 1] * i;
        }
        // 長さKの配列がある　各要素 1<= a_i <=n

        // 任意の非負整数xについて x % a_i ... をaを並び替えても同じになるaを安定とよぶ
        ModInt ans = 0;
        for (int min = 1; min <= N; min++)
        {
            if (min * K > N) break;

            int d = (N - min * K) / min;

            // dをK個に分ける

            // d+K-1 C K-1
            var tmp = f[d + K - 1] * ModInt.Inverse(f[d] * f[K - 1]);

            // Console.WriteLine($"{d} {tmp}");
            ans += tmp;
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

