namespace q520b
{
    class Program
    {
	enum Op { R, B };

        static void Main(string[] args)
        {
	    var inputFirstLine = Console.ReadLine().Split(' ');
	    var n = int.Parse(inputFirstLine[0]);
	    var m = int.Parse(inputFirstLine[1]);
	    // 빨간 버튼: 숫자에 2를 곱한다
	    // 파란 버튼: 숫자에서 1을 뺀다
	    // 디스플레이: 현재 숫자를 출력한다
	    // n에서 m을 만들기 위한 최소한의 버튼 누름 회수?

	    if (n >= m)
	    {
		// 감소하는 버튼은 단 하나이고,
		// 숫자를 증가시켜 0으로 되돌릴 방법은 없으므로
		Console.WriteLine("{0}", n - m);
	    }
	    else
	    {
		// 문제는 숫자를 증가시키는 부분에 있다
		// DFS 버전은 Program_DFS.cs.bak 참고. 대실패함

		// 발상을 바꿔, 역으로 m에서 n으로 변화시키려면 어떻게
		// 계산해야할지를 생각해보자
		// X가 짝수라면 반드시 이전 연산에서 X' * 2가 이루어짐
		// X가 홀수라면 반드시 이전 연산에서 X' - 1이 이루어짐
		// 즉, 이 두 원리를 거꾸로 적용하여 원래 숫자를 구하자

		var steps = 0;
		var i = m; // m은 고정, m을 자유자재로 바꿀 i로 복사

		while (n != i)
		{
		    if (n < i)
		    {
			// 여전히 추가 연산(나눗셈)이 가능함
			if (i%2 == 0)
			{
			    i /= 2; // *= 2의 역원
			}
			else
			{
			    i += 1; // -= 1의 역원
			}

			steps++;
		    }
		    else
		    {
			// 나눌 수 없으므로 더해서 목표수로 되돌림
			steps += n - i;

			// 그리고 루프 종료를 위해,
			i = n;
		    }
		}

		Console.WriteLine("{0}", steps);
	    }
        }
    } 
}

