namespace ACM
{
    class Program
    {
        protected static StreamReader reader;
        protected static StreamWriter writer;

        static void Swap<T>(ref T x, ref T y)
        {
            T t = y;
            y = x;
            x = t;
        }

        public static bool NextPermutation<T>(T[] elements) where T : IComparable<T>
        {
            var count = elements.Length;
            var done = true;

            for (var i = count - 1; i > 0; i--)
            {
                var curr = elements[i];
                if (curr.CompareTo(elements[i - 1]) < 0) continue;
                done = false;
                var prev = elements[i - 1];
                var currIndex = i;
                for (var j = i + 1; j < count; j++)
                {
                    var tmp = elements[j];

                    if (tmp.CompareTo(curr) < 0 && tmp.CompareTo(prev) > 0)
                    {
                        curr = tmp;
                        currIndex = j;
                    }
                }

                elements[currIndex] = prev;
                elements[i - 1] = curr;

                for (var j = count - 1; j > i; j--, i++)
                {
                    var tmp = elements[j];
                    elements[j] = elements[i];
                    elements[i] = tmp;
                }
                break;
            }
            return done;
        }

        public static int[] GetArr()
        {
            return reader.ReadLine().Split(' ').ToList().Select(r => int.Parse(r)).ToArray();
        }

        public static long[] GetLongArr()
        {
            return reader.ReadLine().Split(' ').ToList().Select(r => long.Parse(r)).ToArray();
        }

        public static int GetInt()
        {
            return int.Parse(reader.ReadLine());
        }

        public static long GetLong()
        {
            return long.Parse(reader.ReadLine());
        }

        public static int[,] GetMatrix(int n, int m)
        {
            int[,] a = new int[n, m];
            for (int i = 0; i < n; i++)
            {
                int[] x = GetArr();
                for (int j = 0; j < m; j++)
                    a[i, j] = x[j];
            }
            return a;
        }

        public static void PrintArr(int[] a)
        {
            for (int i = 0; i < a.Count(); i++)
                writer.Write(a[i] + " ");
            writer.WriteLine();
        }

        static void Main()
        {
            reader = new StreamReader(Console.OpenStandardInput());
            writer = new StreamWriter(Console.OpenStandardOutput());
            int[] f = GetArr();
            int s = f[0];
            int v1 = f[1];
            int v2 = f[2];
            int t1 = f[3];
            int t2 = f[4];
            //reader = new StreamReader(File.OpenRead("D:\\ACM\\input.txt"));
            //writer = new StreamWriter(File.OpenWrite("D:\\ACM\\output.txt"));
            //var dt = DateTime.UtcNow;
            if (v1 * s + 2 * t1 < v2 * s + 2 * t2) writer.WriteLine("First");
            if (v1 * s + 2 * t1 > v2 * s + 2 * t2) writer.WriteLine("Second");
            if (v1 * s + 2 * t1 == v2 * s + 2 * t2) writer.WriteLine("Friendship");            

           writer.Flush();
           //Console.WriteLine(DateTime.UtcNow - dt);           
        }
    }
}

