using System;

namespace Buying_A_House
	{
	class Program
		{
		static int Main ()
			{
			string[] tmp = Console.ReadLine().Split();
			if (tmp.Length != 3)
				return -1;
			ushort n = 0;
			if (!UInt16.TryParse(tmp[0], out n))
				return -1;
			ushort m = 0;
			if (!UInt16.TryParse(tmp[1], out m))
				return -1;
			ushort k = 0;
			if (!UInt16.TryParse(tmp[2], out k))
				return -1;
			if (n < 2 || n > 100 || m < 1 || m > n || k < 1 || k > 100)
				return -1;
			tmp = Console.ReadLine().Split();
			if (tmp.Length != n)
				return -1;
			ushort[] a = new ushort[n];
			ushort mm = Convert.ToUInt16 (m-1);
			bool possiblePurchase = false;
			ushort minHouses = Convert.ToUInt16 (n-1);
			ushort houses;
			for (ushort i = 0; i < n; i++)
				{
				if (!UInt16.TryParse(tmp[i], out a[i]))
					return -1;
				if (i == mm && a[i] != 0)
					return -1;
				if (a[i] != 0 && a[i] <= k)
					{
					possiblePurchase = true;
					houses = (i < mm ? Convert.ToUInt16(mm-i) : Convert.ToUInt16(i-mm));
					if (houses < minHouses)
						minHouses = houses;
					}
				}
			if (!possiblePurchase)
				return -1;
			Console.WriteLine (minHouses*10);
			return 0;
			}
		}
	}

