    class Program
    {
        static void Main(string[] args)
        {
            var init = Console.ReadLine().Split(' ');

            var n = int.Parse(init[0]);
            var m = int.Parse(init[1]);
            var a = int.Parse(init[2]);
            var b = int.Parse(init[3]);

            var minCost = n % m == 0 ? (n/m) * b : ((n/m) + 1) * b;

            for (int i = 0; i < n; i++)
            {
                var cost1 = a * i + ((n - i) / m) * b + ((n - i) - ((n - i)/m) * m) * a;
                minCost = Math.Min(minCost, cost1);
            }

            Console.WriteLine(minCost);
            Console.ReadLine();

        }
    }
}

