        private static int binarySearch<T>(List<T> list, T target) where T : IComparable
        {
            int l = 0, r = list.Count - 1;
            while (l <= r)
            {
                var m = (int)Math.Floor((double)(l + r) / 2);
                if (list[m].CompareTo(target) <= 0)
                    if (m == r || list[m + 1].CompareTo(target) > 0)
                        return m;
                    else
                        l = m + 1;
                else
                    r = m - 1;
            }
            return -1;
        }

        private static int quickSortPartition<T>(List<T> list, int left, int right) where T : IComparable
        {
            T pivot = list[left];
            while (true)
            {
                while (list[left].CompareTo(pivot) < 0)
                    left++;
                while (list[right].CompareTo(pivot) > 0)
                    right--;
                if (left < right)
                {
                    if (list[left].CompareTo(list[right]) == 0)
                        return right;

                    T temp = list[left];
                    list[left] = list[right];
                    list[right] = temp;
                }
                else
                    return right;
            }
        }
        private static void quickSort<T>(List<T> list, int left, int right) where T : IComparable
        {
            if (left < right)
            {
                int pivot = quickSortPartition(list, left, right);
                if (pivot > 1)
                    quickSort(list, left, pivot - 1);
                if (pivot + 1 < right)
                    quickSort(list, pivot + 1, right);
            }
        }
        private static void quickSort<T>(List<T> list) where T : IComparable => quickSort(list, 0, list.Count - 1);

