public class Solver
{
    public void Solve()
    {
        // f3 = f2 - f1
        // f4 = f3 - f2
        // f5 = f4 - f3
        // ...
        // fn = f{n-1} - f{n-2}
        // fn = f{n-2} - f{n-3} - (f{n-3} - f{n-4}) 
        // fn = f{n-2} - 2*f{n-3} + f{n-4}
        // fn = f{n-3} - fn-4 - 2*(f{n-4} - fn-5) + f{n-5} - f(n-6)
        // fn = f{n-3} - fn-4 - 2*(f{n-4} - fn-5) + f{n-5} - f(n-6)
        //
        // f1 
        // f2 
        // f3 = f2 - f1
        // f4 = -f1
        // f5 = -f2
        // f6 = -f2 + f1
        // f7 = f1
        // f8 = f2
        // f9 = f2 - f1
        // ... 
        // 
        // n%6
        // 1 = f1
        // 2 = f2
        // ... 
        //
        //

        const long MOD = (int)(1e9 + 7);

        long x = ReadInt();
        long y = ReadInt();
        int n = ReadInt();
        Action<long> MWrite = (a) => Write((a%MOD) < 0 ? (a%MOD)+MOD : a%MOD);
        switch (n % 6)
        {
            case 1:
                MWrite(x);
                break;
            case 2:
                MWrite(y);
                break;
            case 3:
                MWrite(y - x);
                break;
            case 4:
                MWrite(-x);
                break;
            case 5:
                MWrite(-y);
                break;
            case 0:
                MWrite(-y + x);
                break;
            default:
                throw new Exception();
        }
    }

