namespace ConsoleApp2
{
    class Program
    {
        class element
        {
            public int index;
            public int count;
        }
        static int f(List<int> Even, List<int> Odd, ref int CountEven, ref int CountOdd, int count)
        {
            int i = 0;
            int c = 0;
            while (i < Even.Count && Even[i] <= CountEven)
            {
                CountEven -= Even[i]; i++;
                c++;
            }
            count += (Even.Count - c) * 2;
            i = 0; c = 0;
            while (i < Odd.Count && Odd[i] <= CountOdd)
            {
                CountOdd -= Odd[i]; i++;
                c++;
            }
            count += (Odd.Count - c) * 2;
            return count;
        }
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            if(n==1)
            {
                Console.WriteLine(0);
                return;
            }
            string[] str = Console.ReadLine().Split();
            int[] a = new int[n];
            int count = 0;
            int CountOdd = (n + 1) / 2, CountEven = n / 2;
            for (int i = 0; i < n; i++)
            {
                a[i] = int.Parse(str[i]);
                if (a[i] != 0)
                {
                    if (a[i] % 2 == 1)
                        CountOdd--;
                    else
                        CountEven--;
                }
            }
            int FirstEven = -1, FirstOdd = -1, LastEven = -1, LastOdd = -1;
            int CountZero = 0;
            List<int> Even = new List<int>();
            List<int> Odd = new List<int>();
            for (int i = -1; i < n - 1; i++)
            {
                if (a[i + 1] == 0)
                {
                    int first = i;
                    CountZero = 0;
                    for (++i; i < n && a[i] == 0; i++)
                        CountZero++;
                    if (first == -1 && i == n)
                    {
                        Console.WriteLine(1);
                        return;
                    }
                    if (first == -1)
                    {
                        if (a[i] % 2 == 0)
                            FirstEven = CountZero;
                        else
                            FirstOdd = CountZero;
                        i--;
                        continue;
                    }
                    if (i == n)
                    {
                        if (a[first] % 2 == 0)
                            LastEven = CountZero;
                        else
                            LastOdd = CountZero;
                        i--;
                        continue;
                    }
                    if (a[first] % 2 == a[i] % 2)
                    {

                        if (a[first] % 2 == 0)
                            Even.Add(CountZero);
                        else
                            Odd.Add(CountZero);
                    }
                    else
                        count++;
                    i--;
                }
                else
                {
                    if (i >= 0 && i + 1 < n)
                    {
                        if (a[i] % 2 != a[i + 1] % 2)
                            count++;
                    }
                }
            }
            Even.Sort();
            Odd.Sort();
            count = f(Even, Odd, ref CountEven, ref CountOdd, count);

            if (FirstEven != -1)
            {
                if (CountEven >= FirstEven)
                    CountEven -= FirstEven;
                else
                    count++;
            }
            if (FirstOdd != -1)
            {
                if (CountOdd >= FirstOdd)
                    CountOdd -= FirstOdd;
                else
                    count++;
            }
            if (LastEven != -1)
            {
                if (CountEven >= LastEven)
                    CountEven -= LastEven;
                else
                    count++;
            }
            if (LastOdd != -1)
            {
                if (CountOdd >= LastOdd)
                    CountOdd -= LastOdd;
                else
                    count++;
            }

            Console.WriteLine(count);
        }
    }
}

﻿using System;
