    class Compare
    {
        private void IncAB(ref int a, ref int b)
        {
            a++;
            b++;
        }


        private bool CompareAB(int A, int B)
        {
            if (A != B)
            {
                return false;
            }
            else
            {
                return true;
            }
        }

        public bool compares(int[] Player1, int[] Player2, int n)
        {
            int key;
            int p = 0;
            bool equil;
            for (int i = 0; i < n; ++i)
            {
                equil = true;
                key = i;
                p = 0;
                while ((key < n) && (equil))
                {
                    equil = CompareAB(Player1[key], Player2[p]);
                    IncAB(ref key, ref p);
                }
                key = 0;
                while ((key < i) && (equil))
                {
                    equil = CompareAB(Player1[key], Player2[p]);
                    IncAB(ref key, ref p);
                }
                if (equil)
                {
                    return true;
                }
            }
            return false;
        }
    }







