            int denum = 6;

            if (num == 6)
            {
                Console.WriteLine("1/1");
            }else
            {
                int df = gcd(num, denum);
                Console.WriteLine("{0}/{1}", num /= df, denum /= df);
            }
        }

        static int gcd (int a, int b)
        {
            if (a == 0)
            {
                return b;
            }else if (b == 0)
            {
                return a;
            }

            return a > b ? gcd (a & b, b) : gcd (a , b % a);
        }
        static int[] GetInts()
        {
