if (mod(i, p[2], p[0], p[1], p[3]) == i) k ++;
if (mod(i, p[2], p[0], p[3], p[1]) == i) k ++;
if (mod(i, p[2], p[3], p[0], p[1]) == i) k ++;
if (mod(i, p[2], p[3], p[1], p[0]) == i) k ++;

if (mod(i, p[3], p[1], p[2], p[0]) == i) k ++;
if (mod(i, p[3], p[1], p[0], p[2]) == i) k ++;
if (mod(i, p[3], p[2], p[1], p[0]) == i) k ++;
if (mod(i, p[3], p[2], p[0], p[1]) == i) k ++;
if (mod(i, p[3], p[0], p[2], p[1]) == i) k ++;
if (mod(i, p[3], p[0], p[1], p[2]) == i) k ++;                

              if (k >= 7)  answer++;

           }
            Console.WriteLine(answer);
        }

        static int mod(int x, int p1, int p2, int p3, int p4)
       {
          return (((x % p1) % p2) % p3) % p4;
       } 

    }
}

