using System;
using System.Collections.Generic;
namespace problems
{
    internal class _148A
    {
        private static void Main(string[] args)
        {
            var k = int.Parse(Console.ReadLine());
            var l = int.Parse(Console.ReadLine());
            var m = int.Parse(Console.ReadLine());
            var n = int.Parse(Console.ReadLine());
            var d = int.Parse(Console.ReadLine());
            int result=0;
            Calc(new[] { k, l, m, n }, 0, new List<int>(),d, ref result);

            //int result = d / k + d / l + d / m + d / n
            //             - d / lcm(k, m) - d / lcm(k, l) - d / lcm(k, n) - d / lcm(l, m) - d / lcm(n, m) - d / lcm(l, n)
            //             + d / lcm(k, l, n) + d / lcm(k,l, m) + d / lcm(m, l, n) + d / lcm(k, m, n)
            //    - d / lcm(k, l, m, n);
            Console.WriteLine(result);
        }

        private static void Calc(int[] array, int at, List<int> subset,int d, ref int result)
        {
            if (at == array.Length && subset.Count > 0)
            { 
                result += d * ((subset.Count % 2 == 0) ? -1 : 1) / lcm(subset);
                return;           
            }
            else if(at<array.Length)
            {
                Calc(array, at + 1, subset, d, ref result);
                subset.Add(array[at]);
                Calc(array, at + 1, subset, d, ref result);
                subset.RemoveAt(subset.Count - 1);
            }
        }

        private static int gcd(int a, int b)
        {
            while (b != 0)
            {
                var t = b;
                b = a % b;
                a = t;
            }
            return a;
        }

        private static int lcm(int a, int b)
        {
            return a * b / gcd(a, b);
        }

        private static int lcm(List<int> a)
        {
            var res = 1;
            foreach (int el in a)
            { 
                res = lcm(res, el); 
            }
            return res;
        }
    }
}

