namespace Brauzer
{
    class Program
    {
        private static int CalculateTime(int n,int pos,int l, int r)
        {
            if (l == 1 && r == n) return 0;
            int count = 0;
            if (l > 1 && r < n) count += r - l;
            if (pos >= l && pos <= r)
            {
                if (l == 1)
                    count += r - pos+1;
                else
                    if (r == n) count += pos - l+1; else count += Math.Min(r - pos, pos - l)+2;
                return count;
            }

            if (pos < l || (pos == l && l > 1)) 
            {
                count += l - pos+1;
                if (r < n) count++;
                return count;
            }

            if (pos > r || (pos == r && r < n)) 
            {
                count += pos - r+1;
                if (l > 1) count++;
            }

            return count;
        }

        static void Main(string[] args)
        {
            string[] s = Console.ReadLine().Split();

