        public static List<long> Factor(long n)
        {
            List<long> r = new List<long>();

            while (n % 2 == 0)
            {
                n /= 2;
                r.Add(2);
            }
            while (n % 3 == 0)
            {
                n /= 3;
                r.Add(3);
            }

            long sqrtn = (long)(Math.Sqrt(n)) + 1;
            long i = 6;
            while (n > 1 && i <= sqrtn)
            {
                bool nc = false;
                long a;
                while ((a = n % (i - 1)) == 0)
                {
                    r.Add(i - 1);
                    n /= i - 1;
                    nc = true;
                }
                while ((a = n % (i + 1)) == 0)
                {
                    r.Add(i + 1);
                    n /= i + 1;
                    nc = true;
                }
                i += 6;
                if (nc)
                    sqrtn = (long)(Math.Sqrt(n)) + 1;
            }
            if (n != 1) r.Add(n);
            return r;
        }
    } 
