        static int GetNum(ulong k, int n)
        {
            if (n == 1)
                return 1;

            ulong len = (ulong)Math.Pow(2, n) - 1;
            if ((len / 2 + 1) == k)
                return n;


            if (k > (len / 2 + 1))
                k -= (len / 2 + 1);

            return GetNum(k, n -1);
        }
