		public static void Merge<T> (T[] A, int p, int q, int r, T[] L, T[] R, Comparison<T> comp)
		{
			for (int i = p; i <= q; i++)
				L [i] = A [i];
			for (int i = q + 1; i <= r; i++)
				R [i] = A [i];

			for (int k = p, i = p, j = q + 1; k <= r; k++) {
				if (i > q) {
					for (; k <= r; k++, j++)
						A [k] = R [j];
					return;
				}
				if (j > r) {
					for (; k <= r; k++, i++)
						A [k] = L [i];
					return;
				}
				if (comp (L [i], R [j]) <= 0) {
					A [k] = L [i];
					i++;
				} else {
					A [k] = R [j];
					j++;
				}
			}
		}

