			bool isOkay = false;
			int n = a.Length;
			for (int i=n-2; i>=0; i--) {
				if (a [i] < a [i + 1]) {
					isOkay = true;
					int j = i + 1;
					while (j+1<n && a[j+1]>a[i]) {
						j++;
					}
					Swap (a, i, j);
					for (j=1; i+j<n-j; j++) {
						Swap (a, i + j, n - j);
