namespace Lift_Ladder
{
    class Program
    {
        static void Main(string[] args)
        {
            string input = Console.ReadLine();
            string[] splitted = input.Split(' ');

            int x = Convert.ToInt32(splitted[0]); //номер этажа, на котором находится Маша
            int y = Convert.ToInt32(splitted[1]); //номер этажа, на который хочет попасть Маша
            int z = Convert.ToInt32(splitted[2]); //номер этажа, на котором находится лифт
            int t1 = Convert.ToInt32(splitted[3]); //время, за которое Маша проходит между соседними этажами по лестнице
            int t2 = Convert.ToInt32(splitted[4]); //время, за которое лифт проезжает между этажами
            int t3 = Convert.ToInt32(splitted[5]); //время, за которое открываются и закрываются двери у лифта

            int LiftUsingTime = (Math.Abs(x - z) + Math.Abs(x - y)) * t2 + (t3 * 3);
            int LadderUsingTime = Math.Abs(x - y) * t1;

            if (LiftUsingTime <= LadderUsingTime)
            {
                Console.WriteLine("YES");
            } 
            else
            {
                Console.WriteLine("NO");
            }
        }
    }
}

