    class Program
    {
        static void Main(string[] args)
        {
            string str_Inputs = Console.ReadLine();
            string[] arr_Inputs = str_Inputs.Split(' ');
            long num_Cnt1 = Convert.ToInt32(arr_Inputs[0]);
            long num_Cnt2 = Convert.ToInt32(arr_Inputs[1]);
            long num_X = Convert.ToInt32(arr_Inputs[2]);
            long num_Y = Convert.ToInt32(arr_Inputs[3]);
            long num_Low = 1, num_High = long.MaxValue;
            while (num_Low < num_High)
            {
                long num_Mid = (num_High-num_Low)/2 +num_Low;
                if (num_Cnt1 <= AvailableArray(num_Mid, num_X) && num_Cnt2 <= AvailableArray(num_Mid, num_Y) && num_Cnt1 + num_Cnt2 <= AvailableArray(num_Mid, num_X * num_Y))
                {
                    num_High = num_Mid;
                }
                else
                {
                    num_Low = num_Mid + 1;
                }
            }
            Console.Write(num_High);
            Console.Read();
        }
        static long AvailableArray(long num_x,long num_y)
        {
            return num_x - num_x / num_y;
        }
    }
}

