        }

        public void Run()
        {
            int n = int.Parse(Console.ReadLine());
            StringBuilder ans = new StringBuilder(Console.ReadLine());
            int off = 0;
            bool b = false;
            do
            {
                b = false;
                for (int i = 0; i + 2 < ans.Length; i++)
                {
                    if (ans[i] == 'o' && ans[i + 1] == 'g' && ans[i + 2] == 'o')
                    {
                        off = i;
                        b = true;
                        break;
                    }
                }
                if (!b)
                    break;
                ans[off] = '*';
                ans[off + 1] = '*';
                ans[off + 2] = '*';
                off += 3;
