class Solution {

    public static int[]  ReadLine()
    {
        return Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
    }

    static void Main(string[] args)
    {
        var t = ReadLine()[0];

        for (int _ = 1; _ <= t; _++)
        {
            var n = ReadLine()[0];

            var total = 0;
            var digits = 1;
            var number = 1;
            var first = 1;

            while (number != n)
            {
                total += digits;

                digits++;
                if (digits == 5)
                {
                    digits = 1;
                    number = ++first;
                }
                else
                {
                    number = 10 * number + first;
                }
            }

            total += digits;

            Console.WriteLine(total);
        }
    }
}

