using System;
using System.Collections.Generic;
using System.Linq;

namespace Cod
{
    class Program
    {
        static void Main(string[] args)
        {
            var nB = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            var data = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            // Первая часть до следующего разделителя
            var currentOdd = 0;
            var currentEven = 0;
            var difs = new List<int>();
            for (int i = 0; i < nB[0]-1; i++)
            {
                if (data[i] % 2 == 0)
                {
                    currentEven++;
                }
                else
                {
                    currentOdd++;
                }
                if (currentEven != currentOdd) continue;
                difs.Add(Math.Abs(data[i] - data[i+1]));
                currentOdd = 0;
                currentEven = 0;
            }
            var prices = difs.OrderBy(m => m).ToArray();
            var sum = 0;
            var number = 0;
            foreach (var price in prices)
            {
                if (sum + price <= nB[1])
                {
                    sum += price;
                    number++;
                }
                else
                {
                    break;
                }
            }
            Console.WriteLine(number);
            //Console.ReadKey();
        }
    }
}

