namespace Task
{
  class Program
  {
    #region Read / Write
    protected static TextReader reader;
    protected static TextWriter writer;
    private static Queue<string> currentLineTokens = new Queue<string>();
    private static string[] ReadAndSplitLine() { return reader.ReadLine().Split(new[] { ' ', '\t', }, StringSplitOptions.RemoveEmptyEntries); }
    public static string ReadToken() { while (currentLineTokens.Count == 0) currentLineTokens = new Queue<string>(ReadAndSplitLine()); return currentLineTokens.Dequeue(); }
    public static int ReadInt() { return int.Parse(ReadToken()); }
    public static long ReadLong() { return long.Parse(ReadToken()); }
    public static double ReadDouble() { return double.Parse(ReadToken(), CultureInfo.InvariantCulture); }
    public static int[] ReadIntArray() { return ReadAndSplitLine().Select(int.Parse).ToArray(); }
    public static long[] ReadLongArray() { return ReadAndSplitLine().Select(long.Parse).ToArray(); }
    public static double[] ReadDoubleArray() { return ReadAndSplitLine().Select(s => double.Parse(s, CultureInfo.InvariantCulture)).ToArray(); }
    public static int[][] ReadIntMatrix(int numberOfRows) { int[][] matrix = new int[numberOfRows][]; for (int i = 0; i < numberOfRows; i++) matrix[i] = ReadIntArray(); return matrix; }
    public static int[][] ReadAndTransposeIntMatrix(int numberOfRows)
    {
      int[][] matrix = ReadIntMatrix(numberOfRows); int[][] ret = new int[matrix[0].Length][];
      for (int i = 0; i < ret.Length; i++) { ret[i] = new int[numberOfRows]; for (int j = 0; j < numberOfRows; j++) ret[i][j] = matrix[j][i]; }
      return ret;
    }
    public static string[] ReadLines(int quantity) { string[] lines = new string[quantity]; for (int i = 0; i < quantity; i++) lines[i] = reader.ReadLine().Trim(); return lines; }
    public static void WriteArray<T>(IEnumerable<T> array) { writer.WriteLine(string.Join(" ", array)); }
    public static void Write(params object[] array) { WriteArray(array); }
    public static void WriteLines<T>(IEnumerable<T> array) { foreach (var a in array) writer.WriteLine(a); }
    private class SDictionary<TKey, TValue> : Dictionary<TKey, TValue>
    {
      public new TValue this[TKey key]
      {
        get { return ContainsKey(key) ? base[key] : default(TValue); }
        set { base[key] = value; }
      }
    }
    private static T[] Init<T>(int size) where T : new() { var ret = new T[size]; for (int i = 0; i < size; i++) ret[i] = new T(); return ret; }
    #endregion=

    public static bool NextPermutation(List<int> perm)
    {
      for (int i = perm.Count - 2; i >= 0; i--)
      {
        if (perm[i] < perm[i + 1])
        {
          int min = i + 1;
          for (int j = min; j < perm.Count; j++)
            if (perm[j] > perm[i] && perm[j] < perm[min])
              min = j;

          int tmp = perm[i];
          perm[i] = perm[min];
          perm[min] = tmp;
          perm.Reverse(i + 1, perm.Count - i - 1);
          return true;
        }
      }

      return false;
    }

    public static int[] Perm(int[] mas1, int[] mas2, int numb1 = 0)
    {
      if (mas1 == null)
        return mas2;
      if (mas2 == null)
        return mas1;

      var ans = new int[mas1.Length];
      for (int i = 0; i < mas1.Length; i++)
      {
        ans[i] = mas2[mas1[i] - 1];
      }

      return ans;
    }

    public static void Build(int[][] a, int v, int tl, int tr)
    {
      hash = new Dictionary<long, int[]>();

      if (tl == tr)
        t[v] = a[tl];
      else
      {
        int tm = (tl + tr) / 2;
        Build(a, v * 2, tl, tm);
        Build(a, v * 2 + 1, tm + 1, tr);
        t[v] = Perm(t[v * 2], t[v * 2 + 1]);
      }
    }

    public static Dictionary<long, int[]> hash;

    public static int[] Query(int v, int tl, int tr, int l, int r)
    {
      if (l > r)
        return null;
      if (l == tl && r == tr)
        return t[v];

      var key = ((long)l << 17) + r;
      if (hash.ContainsKey(key))
        return hash[key];

      int tm = (tl + tr) / 2;
      var res = Perm(Query(v * 2, tl, tm, l, Math.Min(r, tm)), Query(v * 2 + 1, tm + 1, tr, Math.Max(l, tm + 1), r));
      hash[key] = res;
      return res;
    }

    public static int[][] t;

    static void Main(string[] args)
    {
      //long i = 0;
      long ans = 0;
      reader = new StreamReader(Console.OpenStandardInput());
      writer = new StreamWriter(Console.OpenStandardOutput());

      var n = ReadInt();
      var B = ReadInt();
      var mas = ReadIntArray();
      //var mas = ReadIntArray().Select((item, index) => new Tuple<int, int>(index, item)).ToArray();

      var lst = new List<int>();
      int evenNumb = 0, oddNumb = 0;
      for (int i = 0; i < n - 1; i++)
      {
        if ((mas[i] & 1) == 0)
        {
          evenNumb++;
        }
        else
        {
          oddNumb++;
        }

        if (evenNumb == oddNumb)
          lst.Add(Math.Abs(mas[i] - mas[i + 1]));
      }

      lst.Sort();
      for (int i = 0; i < lst.Count; i++)
      {
        if (lst[i] <= B)
        {
          ans++;
          B -= lst[i];
        }
        else
        {
          break;
        }
      }

      Write(ans);

      reader.Close();
      writer.Close();
    }
  }
}

