using System;

class ContestForRobots
    {
    static int Main ()
        {
        string line = Console.ReadLine ();
        if (line == null)
            return -1;
        char[] delims = {' ', '\t'};
        string[] words = line.Split (delims,StringSplitOptions.RemoveEmptyEntries);
        if (words.Length != 1)
            return -1;
        byte n;
        if (!Byte.TryParse (words[0], out n))
            return -1;
        if (n < 1 || n > 100)
            return -1;
        line = Console.ReadLine ();
        if (line == null)
            return -1;
        words = line.Split (delims,StringSplitOptions.RemoveEmptyEntries);
        if (words.Length != n)
            return -1;
        byte[] r = new byte[n];
        byte countSolvedProblemR = 0;
        for (byte i = 0; i < n; i++)
            {
            byte ri;
            if (!Byte.TryParse (words[i], out ri))
                return -1;
            if (ri > 1)
                return -1;
            if (ri == 1)
                countSolvedProblemR++;
            r[i] = ri;
            }
        line = Console.ReadLine ();
        if (line == null)
            return -1;
        words = line.Split (delims,StringSplitOptions.RemoveEmptyEntries);
        if (words.Length != n)
            return -1;
        byte countSolvedProblemB = 0;
        byte countPointSource = 0;
        for (byte i = 0; i < n; i++)
            {
            byte bi;
            if (!Byte.TryParse (words[i], out bi))
                return -1;
            if (bi > 1)
                return -1;
            if (bi == 1)
                countSolvedProblemB++;
            else if (r[i] == 1)
                countPointSource++;
            }
        sbyte ans = 0;
        if (countSolvedProblemR > countSolvedProblemB)
            ans = 1;
        else if (countPointSource == 0)
            ans = -1;
        else
            {
            byte needPoints = Convert.ToByte (countSolvedProblemB-countSolvedProblemR+1);
            ans = Convert.ToSByte (needPoints/countPointSource);
            ans += Convert.ToSByte (needPoints%countPointSource > 0 ? 2 : 1);
            }
        Console.WriteLine (ans);
        return 0;
        }
    }

