namespace ProblemsFun
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = Convert.ToInt32( Console.ReadLine());
            string[] line = Console.ReadLine().Split(' ');
            List<int> list = new List<int>(); 

            for (int i = 0; i < line.Length; i++)
            {

                list.Add(Convert.ToInt32(line[i]));
            }

            list = QuickSort(list, 0, list.Count - 1);

            if (n != 0)
            {
                int sum = 0;
                for (int i = list.Count-1; i > -1; i--)
                {
                    sum += list[i];
                    if (sum >= n)
                    {
                        Console.WriteLine(12 - i );
                        break;
                    }
                }

                if(sum < n)
                    Console.WriteLine("-1");
            }
            else
            {

                Console.WriteLine("0");
            }
        }

        static List<int> QuickSort(List<int> list, int first, int last)
        {
            if (first < last)
            {
                int pivot = Devide(list, first, last);
                list = QuickSort(list, first, pivot);
                list = QuickSort(list, pivot + 1, last);
            }
            return list;
        }

        static int Devide(List<int> list, int first, int last)
        {
            int pivotVal = list[first];
            int smallest = first - 1;
            int biggest = last + 1;

            while (true)
            {
                do
                {
                    biggest--;
                }
                while (list[biggest] > pivotVal);

                do
                {
                    smallest++;
                }
                while (list[smallest] < pivotVal);

                if (smallest < biggest)
                {
                    int temp = list[smallest];
                    list[smallest] = list[biggest];
                    list[biggest] = temp;
                }
                else
                {
                    return biggest;
                }
            }
        }
    }
}

