        static int SolveProblem(int [] inputs, int [] [] matches)
        {
            int result = 0;
            int biggestMBox = int.MinValue;
            int biggestMBIndx = 0;
            while (true)
            {
                for (int i = 0; i < matches.Length; i++)
                {
                    if (matches[i][1] > biggestMBox)
                    {
                        biggestMBox = matches[i][1];
                        biggestMBIndx = i;
                    };
                }

                inputs[0] -= matches[biggestMBIndx][0];

                if (inputs [0] > 0)
                {

                    result += (matches[biggestMBIndx][0]* matches[biggestMBIndx][1]);
                    matches[biggestMBIndx][1] = 0;
                    biggestMBox = int.MinValue;
                    biggestMBIndx = 0;
                } else
                {
                    inputs[0] += matches[biggestMBIndx][0];
                    break;
                }
            }

            result += inputs[0] * matches[biggestMBIndx][1];

            return result;

        }

