        private IEnumerable<Tuple<long, int>> Decompose(long n)
        {
            if (n == 1) yield break;

            int p = 2;
            while (p * p <= n)
            {
                int r = 0;
                while (n % p == 0)
                {
                    ++r;
                    n /= p;
                }
                if (r > 0)
                    yield return new Tuple<long, int>(p, r);

                ++p;
            }

            if (n > 1)
                yield return new Tuple<long, int>(n, 1);
        }

        private IEnumerable<long> Divs(Tuple<long, int>[] decomp, int start = 0)
        {
            if (decomp.Length == 0)
            {
                yield return 1;
                yield break;
            }

            if (decomp.Length - start == 1)
            {
                long ret = 1;
                yield return 1;
                for (int i = 0; i < decomp[start].Item2; ++i)
                {
                    ret *= decomp[start].Item1;
                    yield return (ret);
                }
            }
            else
            {
                long ret = 1;
                foreach(long d in Divs(decomp, start+1))
                {
                    yield return d;
                }
                for (int i = 0; i < decomp[start].Item2; ++i)
                {
                    ret *= decomp[start].Item1;
                    foreach (long d in Divs(decomp, start + 1))
                        yield return (ret * d);
                }
            }

        }

        private string Go()
        {
            long n = GetLong();
            Tuple<long, int>[] decompN = Decompose(n).ToArray();
            Tuple<long, int>[] decompNa;

            long m = long.MaxValue;
            long M = 0;

            foreach (long A1 in Divs(decompN))
            {
                decompNa = A1 == 1 ? decompN : Decompose(n / A1).ToArray();
                foreach (long B2 in Divs(decompNa))
                {
                    long C2 = n / A1 / B2;

                    long cand = (A1 + 1) * (B2 + 2) * (C2 + 2);
                    m = cand < m ? cand : m;
                    M = cand > M ? cand : M;
                }
            }

            Wl<long>(new long[] { m - n, M - n });

            return null;
        }

