class CFBR3C
{
	static void Main()
	{
		byte xCount;
		byte emptyCount;
		sbyte[,] gameState = GetGameState(out xCount, out emptyCount);
		Console.WriteLine(GetVerdict(gameState, xCount, emptyCount));
	}

	static string GetVerdict(sbyte[,] gs, byte xCount, byte eCount)
	{
		byte zCount = (byte)(9 - (xCount + eCount));
		bool firstPlayerWon = false;
		bool secondPlayerWon = false;
		if ((xCount == 0) && (zCount == 0)) return "first";
		else if (Math.Abs(xCount - zCount) > 1) return "illegal";
		else if (xCount < zCount) return "illegal";
		else if (((gs[0, 0] == 1) && (gs[1, 1] == 1) && (gs[2, 2] == 1)) || ((gs[0, 2] == 1) && (gs[1, 1] == 1) && (gs[2, 0] == 1))) firstPlayerWon = true;
		else if (((gs[0, 0] == 0) && (gs[1, 1] == 0) && (gs[2, 2] == 0)) || ((gs[0, 2] == 0) && (gs[1, 1] == 0) && (gs[2, 0] == 0))) secondPlayerWon = true;
		for (byte i = 0; i < 3; i++)
		{
			if (((gs[i, 0] == 1) && (gs[i, 1] == 1) && (gs[i, 2] == 1)) || ((gs[0, i] == 1) && (gs[1, i] == 1) && (gs[2, i] == 1))) firstPlayerWon = true;
			else if (((gs[i, 0] == 0) && (gs[i, 1] == 0) && (gs[i, 2] == 0)) || ((gs[0, i] == 0) && (gs[1, i] == 0) && (gs[2, i] == 0))) secondPlayerWon = true;
			if (firstPlayerWon == true && secondPlayerWon == true) return "illegal";
		}
		if (firstPlayerWon == true)
		{
			if (xCount == zCount) return "illegal";
			else return "the first player won";
		}
		else if (secondPlayerWon == true)
		{
			if (zCount < xCount) return "illegal";
			else return "the second player won";
		}

		if (eCount > 0)
		{
			if (xCount > zCount) return "second";
			else return "first";
		}
		return "draw";
	}

	static sbyte[,] GetGameState(out byte xCount, out byte emptyCount)
	{
		xCount = 0;
		emptyCount = 0;
		sbyte[,] gameState = new sbyte[3, 3];
		for (byte i = 0; i < 3; i++)
		{
			string line = Console.ReadLine();
			for (byte j = 0; j < 3; j++)
			{
				switch(line[j])
				{
					case 'X':
						{
							gameState[i, j] = 1;
							xCount++;
							break;
						}
					case '0':
						{
							gameState[i, j] = 0;
							break;
						}
					case '.':
						{
							gameState[i, j] = -1;
							emptyCount++;
							break;
						}
				}
			}
		}
		return gameState;
	}
}

