class Solution {
	static int Main () {
		string s; 
		int n;
		n = Convert.ToInt32(Console.ReadLine());
		s = Console.ReadLine();

		for (int i = 0; i < n-1; i++) {
			int tmp = 0;
			for (int j = 0; j <= i; j++) tmp += s[j]-'0';
			bool ans = false;
			int aux = 0;
			for (int j = i+1; j < n; j++) {
				aux += s[j]-'0';
				if (aux == tmp) {
					ans = true;
					if (j < n-1) aux = 0;
					else break;
				} else if (aux > tmp) {
					ans = false;
					break;
				}
			}
			if (aux != 0 && aux < tmp) ans = false;
			if (ans) {
				Console.WriteLine("YES");
				return 0;
			}
		}

		Console.WriteLine("NO");	
		return 0;
	}
}

