public class Program
{
    int N;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        // 長さ2Nのかっこ列すべて
        // Trieの最大マッチング

        // 木
        // 2色に塗って少ない方

        // 頂点増え方
        // 以降>しか置けない

        // < >>>>>


        //    0 1 2 3
        // 0: 1 
        // 1: 1 1 ... 1
        // 2: 2 2 1 ... 3
        // 3: 5 5 3 1
        // 4: 

        var dp = new ModInt[N + 1][];
        for (int i = 0; i <= N; i++)
        {
            dp[i] = new ModInt[i + 1];
        }

        dp[0][0] = 1;
        for (int i = 0; i < N; i++)
        {
            ModInt tmp = 0;
            for (int j = i; j >= 0; j--)
            {
                tmp += dp[i][j];
                dp[i + 1][j + 1] = tmp;
            }
            dp[i + 1][0] = tmp;
        }

        ModInt ans = 0;
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j <= i; j++)
            {
                ans += dp[i][j] * ((j + 2) / 2);
            }
        }

        Console.WriteLine(ans);
    }

