    internal class Task
    {
        public void Solve(InputReader sr, TextWriter sw)
        {
            var matrix = new char[4, 4];
            for (var i = 0; i < 4; i++) {
                var next = sr.NextString();
                for (var j = 0; j < 4; j++) {
                    matrix[i, j] = next[j];
                }
            }
            for (var i = 0; i < 4; i++) {
                for (var j = 0; j < 4; j++) {
                    var old = matrix[i, j];
                    if (matrix[i, j] == '.') {
                        matrix[i, j] = 'x';
                        if (Check(matrix)) {
                            sw.WriteLine("YES");
                            return;
                        }
                        matrix[i, j] = old;
                    }
                }
            }

            sw.WriteLine("NO");
        }

        private bool Check(char[,] matrix)
        {
            for (var i = 0; i < 4; i++) {
                for (var j = 0; j < 4; j++) {
                    if (i - 2 >= 0) {
                        if (matrix[i, j] == 'x' && matrix[i - 1, j] == 'x' && matrix[i - 2, j] == 'x') {
                            return true;
                        }
                    }
                    if (i + 2 < 4) {
                        if (matrix[i, j] == 'x' && matrix[i + 1, j] == 'x' && matrix[i + 2, j] == 'x') {
                            return true;
                        }
                    }
                    if (j - 2 >= 0)
                    {
                        if (matrix[i, j] == 'x' && matrix[i, j - 1] == 'x' && matrix[i, j - 2] == 'x')
                        {
                            return true;
                        }
                    }
                    if (j + 2 < 4)
                    {
                        if (matrix[i, j] == 'x' && matrix[i, j + 1] == 'x' && matrix[i, j + 2] == 'x')
                        {
                            return true;
                        }
                    }
                    if (i - 1 >= 0 && j - 1 >= 0 && i + 1 < 4 && j + 1 < 4) {
                        if (matrix[i, j] == 'x' && matrix[i - 1, j - 1] == 'x' && matrix[i + 1, j + 1] == 'x') {
                            return true;
                        }
                    }
                    if (i - 1 >= 0 && j + 1 < 4 && j - 1 >= 0 && i + 1 < 4) {
                        if (matrix[i, j] == 'x' && matrix[i - 1, j + 1] == 'x' && matrix[i + 1, j - 1] == 'x') {
                            return true;
                        }
                    }
                }
            }

            return false;
        }
    }
}

internal class InputReader : IDisposable
{
    private bool isDispose;
    private readonly TextReader sr;

    public InputReader(TextReader stream)
    {
        sr = stream;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public string NextString()
    {
        var result = sr.ReadLine();
        return result;
    }

    public int NextInt32()
    {
        return Int32.Parse(NextString());
    }

    public long NextInt64()
    {
        return Int64.Parse(NextString());
    }

    public string[] NextSplitStrings()
    {
        return NextString()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
    {
        return NextSplitStrings()
            .Select(s => func(s, CultureInfo.InvariantCulture))
            .ToArray();
    }

    public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
    {
        return
            str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => func(s, CultureInfo.InvariantCulture))
                .ToArray();
    }

    protected void Dispose(bool dispose)
    {
        if (!isDispose)
        {
            if (dispose)
                sr.Close();
            isDispose = true;
        }
    }

    ~InputReader()
    {
        Dispose(false);
    }
}

