    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            var nn = new int[10,10];
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    nn[i + 3, j + 3] = Next();
                }
            }

            var dx = new[] {0, 1, 1, -1};
            var dy = new[] {1, 0, 1, 1};
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    if (nn[i + 3, j + 3] == 0)
                    {
                        for (int k = 0; k < dx.Length; k++)
                        {
                            for (int l = -2; l <= 0; l++)
                            {
                                int c = 0;
                                for (int m = 0; m < 3; m++)
                                {
                                    c += nn[i + 3 + dx[k]*(l + m), j + 3 + dy[k]*(l + m)];
                                }
                                if (c == 2)
                                {
                                    writer.WriteLine("YES");
                                    writer.Flush();
                                    return;
                                }
                            }
                        }
                    }
                }
            }

            writer.WriteLine("NO");
            writer.Flush();
        }

        private static int Next()
        {
            do
            {
                int c = reader.Read();
                if (c == 'x')
                    return 1;
                if (c == '.')
                    return 0;
                if (c == 'o')
                    return -1;
                if (c == -1)
                    return -2;
            } while (true);
        }
    }
