/// <id guid="88cbde0b-19a8-421c-98c3-0b7b0a589973" />
public class Program
{
    static int[] primes = new int[] { 2, 3, 5, 7 };
    static Tuple<int, int, int, int>[] preCalc = new Tuple<int, int, int, int>[10];
    static Tuple<int, int, int, int>[] preCalcFact = new Tuple<int, int, int, int>[10];
    private static void init()
    {
        for (int i = 0; i <= 9; i++)
        {
            int[] states = new int[4];

            int tmp = i;
            for (int j = 0; j < primes.Length && i >= 2; j++)
            {
                while (tmp % primes[j] == 0)
                {
                    tmp /= primes[j];
                    states[j]++;
                }
            }

            preCalc[i] = new Tuple<int, int, int, int>(states[0], states[1], states[2], states[3]);
        }

        for (int i = 0; i <= 9; i++)
        {
            if (i - 1 >= 0)
            {
                preCalcFact[i] = new Tuple<int,int,int,int>(
                    preCalcFact[i - 1].Item1 + preCalc[i].Item1,
                    preCalcFact[i - 1].Item2 + preCalc[i].Item2,
                    preCalcFact[i - 1].Item3 + preCalc[i].Item3,
                    preCalcFact[i - 1].Item4 + preCalc[i].Item4);
            }
            else
            {
                preCalcFact[i] = preCalc[i];
            }
        }
    }

    private static Dictionary<Tuple<int, int, int, int>, string> dp;

    private static void Main()
    {
        init();

        int n = Int32.Parse(Console.ReadLine());

        string input = Console.ReadLine();

        dp = new Dictionary<Tuple<int, int, int, int>, string>();

        Console.WriteLine(solve(Convert(input)));
    }


    private static string solve(Tuple<int, int, int, int> state)
    {
        if (state.Item1 == 0 && state.Item2 == 0 && state.Item3 == 0 && state.Item4 == 0)
        {
            return "";
        }
        else if (dp.ContainsKey(state))
        {
            return dp[state];
        }
        else
        {
            string best = null;
            for (int i = 2; i <= 9; i++)
            {
                if (state.Item1 >= preCalcFact[i].Item1 && 
                    state.Item2 >= preCalcFact[i].Item2 &&
                    state.Item3 >= preCalcFact[i].Item3 &&
                    state.Item4 >= preCalcFact[i].Item4)
                {
                    string subString = solve(new Tuple<int, int, int, int>(state.Item1 - preCalcFact[i].Item1,
                        state.Item2 - preCalcFact[i].Item2,
                        state.Item3 - preCalcFact[i].Item3,
                        state.Item4 - preCalcFact[i].Item4));

                    if (subString != null)
                    {
                        string now = (char)('0' + i) + subString;

                        if (best == null || now.Length > best.Length || (now.Length == best.Length && String.Compare(now, best) > 0))
                        {
                            best = now;
                        }
                    }
                }
            }

            dp[state] = best;

            return best;
        }
    }

    static Tuple<int, int, int, int> Convert(string input)
    {
        int[] states = new int[4];
        for (int i = 0; i < input.Length; i++)
        {
            states[0] += preCalcFact[input[i] - '0'].Item1;
            states[1] += preCalcFact[input[i] - '0'].Item2;
            states[2] += preCalcFact[input[i] - '0'].Item3;
            states[3] += preCalcFact[input[i] - '0'].Item4;
        }

        return new Tuple<int, int, int, int>(states[0], states[1], states[2], states[3]);
    }
}

