        static int dp(string s,int c)
        {
            int res = -1;
            if ((c==0)&&(s.Length==0)) return 0;
            if ((c == 0) && (s.Length != 0)) return -1;
            if (s.Length >= c)
            {
                string num="";
                int sum=-1;
                for (int i = 0; i < 7 && i < s.Length - c + 1; i++)
                {
                    num += s[i];
                    int tt =int.Parse(num);
                    if (tt <= 1000000)
                    {
                        int t = dp(s.Substring(i + 1, s.Length - i - 1), c - 1);
                        if ((t != -1) && ((num[0] != '0') || (num.Length == 1)))
                            sum = Math.Max(sum, tt + t);
                    }
                }
                return sum;
            }
            return res;

        }
