namespace Dreamoon_and_WiFi
{
    class Program
    {
        static void Main(string[] args)
        {
  //Teste x = new Teste();
                //x.calcula(Console.ReadLine(), Console.ReadLine());
                Codigo cod = new Codigo(Console.ReadLine(), Console.ReadLine()); //Chama a função com os dois valores digitados
                cod.exibe(); //Exibe o resultado em decimal
        }
    }

    class Codigo
    {
        //Iniciando um vetor que vai guardar os dois valores possíveis nas instruções
        private int[] contaDreamon = new int[2];
        private int[] contaDrazil = new int[2];

        //Quantidade de valores desconhecidos passados ao drazil
        private int quantInt;

        private int distancia;
        private int posDreamoon;
        private int posDrazil;

        public Codigo(string drazil, string dreamoon)
        {
            contaDreamon[0] = dreamoon.Split(new char[] { '-' }).Length - 1; //Vai contar quantos '-' possui e vai passar para a variável, e assim respectivamente com as 3 próxima linhas
            contaDreamon[1] = dreamoon.Split(new char[] { '+' }).Length - 1;
            contaDrazil[0] = drazil.Split(new char[] { '-' }).Length - 1;
            contaDrazil[1] = drazil.Split(new char[] { '+' }).Length - 1;
            quantInt = dreamoon.Split(new char[] { '?' }).Length - 1; //Quantidade de códigos desconhecidos
            posDrazil = contaDrazil[1] - contaDrazil[0]; //Determina a posição do Drazil depois de enviar os comandos
            posDreamoon = contaDreamon[1] - contaDreamon[0]; //Determina a posição do dreamoon depois de receber os comandos
            distancia = posDrazil - posDreamoon; //Define a distância restante para Dreamoon chegar na mesma posição
        }

        private double compara()
        {
            if (contaDreamon[0] == contaDrazil[0] && contaDreamon[1] == contaDrazil[1]) //Se receberem a mesma quantidade de '+' e '-', a conta termina em 100%
            {
                return 1;
            }
            else if (quantInt < Math.Abs(distancia)) //Se a quantidade de caminhos duvidosos for maior que a distância restante, a chance é zero
                return 0;
            else
            {
                int m = (quantInt + Math.Abs(distancia)) / 2; //Calcula a quantidade de passos válidos para chegar na posição correta

                double combinacao = (fatorial(quantInt) / (fatorial(quantInt - m) * (fatorial(m)))); //Realiza o cálculo da combinação

                return (double)combinacao / (1 << quantInt); //Retorna o restante da formula C(Quantidade de ?, m) / 2 ^ quantidade de ?
            }
        }

        public void exibe()
        {
            string result = compara().ToString();
            result = result.Replace(',', '.');
            Console.WriteLine("{0:F12}", result); //Exibe o resultado com 12 algarismos
        }

        private double fatorial(int n)
        {
            if (n == 1 || n == 0)
                return 1;
            else
                return (n * fatorial(n - 1));
        }
    }


