        public class Task
        {
            public void Solve()
            {
                string cd = RL();
                string bd = RL();

                string[] cd_dd = cd.Split('.');

                string format = "dd.MM.yyyy";

                DateTime cd_date = DateTime.ParseExact(string.Format("{0}.{1}.{2}", cd_dd[0], cd_dd[1], 2000 + int.Parse(cd_dd[2])), format, CultureInfo.InvariantCulture);

                int[] dd = Array.ConvertAll<string, int>(bd.Split('.'), int.Parse);

                int[] p = { 0, 1, 2 };

                do
                {
                    string nd = string.Format("{0}.{1}.{2}", dd[p[0]].ToString().PadLeft(2, '0'), dd[p[1]].ToString().PadLeft(2, '0'), 2000 + dd[p[2]]);

                    DateTime ddt;
                    if (DateTime.TryParseExact(nd, format, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal, out ddt))
                    {
                        if (ddt.Year % 4 == 0 && ddt.Month == 2 && ddt.Day == 29)
                            ddt = new DateTime(ddt.Year, 3, 1);

                        if (ddt.AddYears(18) <= cd_date.AddMinutes(23 * 60 + 59))
                        {
                            Console.WriteLine("YES");
                            return;
                        }
                    }


                } while (GetNext(p));

                Console.WriteLine("NO");
            }

            public bool GetNext(int[] p)
            {
                int n = p.Length;
                int i = n - 2;
                while (i >= 0 && p[i] >= p[i + 1])
                    i--;
                if (i == -1)
                    return false;

                int k = i + 1;
                for (int j = i + 1; j < n; j++)
                    if (p[j] < p[k] && p[j] > p[i])
                        k = j;

                int t = p[i];
                p[i] = p[k];
                p[k] = t;

                for (int j = 0; j < (n - i - 1) / 2; j++)
                {
                    t = p[j + i + 1];
                    p[j + i + 1] = p[n - j - 1];
                    p[n - j - 1] = t;
                }

                return true;
            }
        }


    }
