            var b = long.Parse(s[1]);
            var f = long.Parse(s[2]);
            var k = long.Parse(s[3]);

            long sum = f;
            long dist = k*a;
            var points = new List<long>() {0,f};
            var forw = 2*(a-f);
            var back = 2*f;
            var sw = true;
            while (sum<dist)
            {
                if (sw)
