            var cnt = 0;
            var r = b;
            for (int i = 1; i < points.Count; i++)
            {
                var d = points[i]-points[i-1];
                if (d > r)
                {
                    cnt++;
                    r = b;
                    if (r < d)
                    {
                        Console.WriteLine(-1);
                        return;
                    }
                }
               r -= d;
            }
            Console.WriteLine(cnt);
        }


