        private abstract class SolverBase
        {
            protected readonly ExtendedReader _reader;
            protected readonly TextWriter _writer;

            protected SolverBase()
            {
#if DEBUG
                _reader = new ExtendedReader("input.txt");
                //_writer = new StreamWriter("output.txt");
                _writer = new StreamWriter(Console.OpenStandardOutput());
#else
                _reader = new ExtendedReader(Console.OpenStandardInput());
                _writer = new StreamWriter(Console.OpenStandardOutput());
#endif
            }

            public abstract Solver Solve();

            public abstract void OutputResult();
        }

        private class Solver : SolverBase
        {
            private bool result = false;

            public override Solver Solve()
            {
                // link to task: http://codeforces.com/problemset/problem/688/A

                var n = _reader.ReadInt();
                var s = _reader.ReadString();

                result = ShiftLeft(s) || ShiftRight(s) || ShiftUp(s) || ShiftDown(s);
                result = !result;

                return this;
            }

            private bool ShiftDown(string s)
            {
                return !s.Replace('0', '-').Replace('7', '-').Replace('9', '-').Contains("-");
            }

            private bool ShiftUp(string s)
            {
                return !s.Replace('1', '-').Replace('2', '-').Replace('3', '-').Contains("-");
            }

            private bool ShiftRight(string s)
            {
                return !s.Replace('0', '-').Replace('3', '-').Replace('6', '-').Replace('9', '-').Contains("-");
            }

            private bool ShiftLeft(string s)
            {
                return !s.Replace('0', '-').Replace('1', '-').Replace('4', '-').Replace('7', '-').Contains("-");
            }

            public override void OutputResult()
            {
                string answer = result ? "YES" : "NO";

                _writer.WriteLine(answer);
                _writer.Dispose();
            }
        }
    }
