		int[] ans = new int[T];
		for(int i = 0; i < T; i++)
			ans[i] = calc();

		Console.WriteLine(string.Join("\n", ans.Select(x => x.ToString()).ToArray()));
	}

	private int calc()
	{
		int N = GetInt();
		int K = GetInt();
		int D = GetInt();
		int[] a = GetInts(N);

		int res = D;
		int[] cnt = new int[1000001];
		int sum = 0;
		for(int i = 0; i < D; i++)
		{
			if(cnt[a[i]] == 0)
				sum++;

			cnt[a[i]]++;
		}
		chmin(ref res, sum);

		for(int i = D; i < N; i++)
		{
			if(cnt[a[i]] == 0)
				sum++;

			cnt[a[i]]++;

			if(cnt[a[i - D]] == 1)
				sum--;

			cnt[a[i - D]]--;

			chmin(ref res, sum);
		}

		return res;
	}

	private int chmin(ref int x, int y) => x = Math.Min(x, y);
}


