        for (int ni = 1; ni <= n; ni++)
        {
            for (int hi = 1; hi <= n; hi++)
            {
                long sum0 = 0;
                for (int m = 1; m <= ni; m++)
                {
                    long sum1 = 0;
                    for (int i = 0; i <= hi-1; i++)
                    {
                        sum1 += t[ni - m, i];
                    }

                    long sum2 = 0;
                    for (int i = 0; i <= hi-2; i++)
                    {
                        sum2 += t[m - 1, i];
                    }

                    sum0 += t[m - 1, hi - 1] * sum1 + t[ni - m, hi - 1] * sum2;
                }

                t[ni, hi] = sum0;
            }
        }

        long ans = 0;
        for (int i = h; i <= n; i++)
        {
            ans += t[n, i];
        }

        output.WriteLine(ans);
    }
}

