class Program
{
    long[,] dp;
    void solve()
    {
        string[] t = Console.ReadLine().Split();
        int n=int.Parse(t[0]);
        int h = int.Parse(t[1]);
        dp = new long[n + 1, n + 1];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= n; j++)
                dp[i, j] = -1;
        long ret = 0;
        for (int i = 1; i <= n; i++)
        {
            long num = go(n, i);
            if (i >= h)
            {
                ret += num;
            }
        }
        Console.WriteLine(ret);
    }

    private long go(int n, int h)
    {
        if (dp[n, h] != -1)
            return dp[n, h];
        if (n == 0)
        {
            if (h == 0)
                return dp[n, h] = 1;
            else
                return dp[n, h] = 0;
        }
        if(h==0)
        {
            return dp[n,h]=0;
        }
        long ret = 0;
        for (int i = 1; i <= n; i++)
        {
            int Left = i - 1;
            int right = n - i;
            for (int k = 0; k < h - 1; k++)
            {
                ret += go(Left, k) * go(right, h - 1);
            }
            for (int k = 0; k < h - 1; k++)
            {
                ret += go(right, k) * go(Left, h - 1);
            }
            ret += go(Left, h - 1) * go(right, h - 1);
        }
        return dp[n, h] = ret;
    }



    static void Main(string[] args)
    {
        new Program().solve();
    }
}

