public class Solver
{
    public object Solve()
    {
        long n = ReadInt();
        long m = ReadInt();
        long k = ReadLong();

        long l = 1;
        long r = n * m;
        while (true)
        {
            long mid = (l + r) / 2;
            long gleft = 0;
            long gright = 0;
            long closestLeft = 0;
            long closestRight = long.MaxValue;
            for (long i = 1; i <= m; i++)
            {
                if (mid > i * n)
                {
                    gleft += n;
                    closestLeft = Math.Max(closestLeft, i * n);
                    continue;
                }
                if (mid < i)
                {
                    gright += n;
                    closestRight = Math.Min(closestRight, i);
                    continue;
                }
                if (mid % i == 0)
                {
                    closestLeft = closestRight = mid;
                    gleft += mid / i - 1;
                    gright += n - mid / i;
                }
                else
                {
                    closestLeft = Math.Max(closestLeft, mid / i * i);
                    closestRight = Math.Min(closestRight, (mid / i + 1) * i);
                    gleft += mid / i;
                    gright += n - mid / i;
                }
            }
            if (gleft + gright == n * m)
            {
                if (gleft + 1 == k)
                    return closestRight;
                if (gleft + 1 < k)
                    l = closestRight;
                else
                    r = closestLeft;
            }
            else
            {
                if (k > gleft && k + gright <= n * m)
                    return closestLeft;
                if (k <= gleft)
                    r = closestLeft - 1;
                else
                    l = closestRight + 1;
            }
        }

        return null;
    }

