namespace Codeforces.R256
{
    public class Task_D
    {
        static void Main(string[] args)
        {
            new Task_D().Solve();
        }

        private long n;
        private long m;
        private long k;

        private void Solve()
        {
            var parts = Console.ReadLine().Split();
            n = long.Parse(parts[0]);
            m = long.Parse(parts[1]);
            k = long.Parse(parts[2]);

            long left = 1;
            long right = n * m;
            while (left < right)
            {
                var x = (left + right + 1) / 2;
                var before = GetLessThenCount(x);
                if (before < k)
                {
                    left = x;
                }
                else
                {
                    right = x - 1;
                }
            }
            Console.WriteLine(left);
        }

        private long GetLessThenCount(long num)
        {
            long sum = 0;
            for (int i = 1; i <= n; i++)
            {
                long w = Math.Min(m, (num - 1) / i);
                sum += w;
                if (w == 0)
                    break;
            }
            return sum;
        }
    }
}

