using System;

class LLPS
	{
	static int Main ()
		{
		string line = Console.ReadLine ();
		if (line == null)
			return -1;
		char[] delims = {' ', '\t'};
		string[] words = line.Split (delims,StringSplitOptions.RemoveEmptyEntries);
		if (words.Length != 1)
			return -1;
		string s = words[0];
		byte sLength = Convert.ToByte (s.Length);
		if (sLength > 10)
			return -1;
		byte[] countChars = new byte[26];
		Array.Clear (countChars,0,26);
		char maxChar = 'a';
		for (byte i = 0; i < sLength; i++)
			{
			char c = s[i];
			if (!Char.IsLower (c))
				return -1;
			countChars[c-'a']++;
			if (c > maxChar)
				maxChar = c;
			}
		string ans = new String (maxChar,countChars[maxChar-'a']);
		Console.WriteLine (ans);
		return 0;
		}
	}

