        {
            long b = Int64.Parse(Console.ReadLine());

            Console.WriteLine(DivNum(b));
        }
        static long NOK(long a, long b)
        {
            return a * b / (NOD(a, b));
        }
        static long NOD(long a, long b)
        {
            long min, max;

            if (a > b)
            {
                min = b;
                max = a;
            }
            else if (a < b)
            {
                min = a;
                max = b;
            }
            else
            {
                return a;
            }

            while (min != max)
            {
                max = max - min;
                if (max < min)
                {
                    long t = max;
                    max = min;
                    min = t;
                }
            }

            return min;
        }
        static long DivNum(long b)
        {
            int count = 0;

            if (b == 1)
                return 1;

            for (int i = 1; i < Math.Sqrt(b); i++)
            {
                if ((b % i) == 0)
                    count += 2;
            }
            if (b % Math.Sqrt(b) == 0)
                count++;

            return count;
        }
    }
}

