            for (int i = 0; i <= N - 4; i++)
            {
                int dif = 0;
                dif += Diff('A', S[i]);
                dif += Diff('C', S[i + 1]);
                dif += Diff('T', S[i + 2]);
                dif += Diff('G', S[i + 3]);
                min = Math.Min(dif, min);
            }

            Console.WriteLine(min);
        }

