namespace Console
{
    class Program
    {
        static void Main(string[] args)
        {
            var arr = new List<long>(System.Console.ReadLine().Split(' ').Select(long.Parse));
            var a = arr[0];
            var b = arr[1];
            var c = arr[2];
            var l = arr[3];

            long ans = (l + 1)*(l + 2)*(l + 3)/6;
            for (int i = 0; i <= l; ++i)
            {
                ans -= Fun(a + i, b, c, l - i);
                ans -= Fun(b + i, a, c, l - i);
                ans -= Fun(c + i, b, a, l - i);
            }
            System.Console.Write(ans);
            //System.Console.ReadLine();
        }

        static long Fun(long a, long b, long c, long x)
        {
            if (a < b + c)
                return 0;
            var min = Math.Min(a - b - c, x);
            return (min + 1)*(min + 2)/2;
        }
    }
}

