                }
            }

            throw new Exception("Invalid spin char");
        }

        private static bool isClockwise(int start, int end, int seconds) {
            for (int i = 0; i < seconds; i++) {
                start = (start + 1) % 4;
            }

            return start == end;
        }

        private static bool isCounterClockwise(int start, int end, int seconds) {
            for (int i = 0; i < seconds; i++) {
                end = (end + 1) % 4;
            }

            return start == end;
        }

