    class Program
    {
        struct Vector2
        {
            public long X;
            public long Y;

            public Vector2(long x, long y)
            {
                this.X = x;
                this.Y = y;
            }

            public override string ToString()
            {
                return $"{this.Y} {this.X}";
            }
        }

        static void Main(string[] args)
        {
            var line = Console.ReadLine();
            var words = line.Split(' ');
            var values = words.Select(long.Parse).ToArray();

            var sizeY = values[0];
            var sizeX = values[1];
            var moves = values[2];

            Console.Write(SimulateMoves(sizeX, sizeY, moves));
        }

        static Vector2 SimulateMoves(long sizeX, long sizeY, long moves)
        {
            if (moves < sizeY)
            {
                return new Vector2(1, (long) moves + 1);
            }

            moves -= sizeY;
            var result = new Vector2(2, sizeY);
            var halfDividor = sizeX - 1;
            var dividor = halfDividor * 2;
            var yJumps = moves / dividor;
            moves -= yJumps * dividor;
            result.Y -= yJumps * 2;

            if (moves < halfDividor)
            {
                result.X += moves;
                return result;
            }
            else
            {
                moves -= halfDividor;
                result.X = sizeX;
                result.Y -= 1;
                result.X -= moves;
                return result;
            }
        }
    }
}

