	class FastReader
	{
		private TextReader reader = null;
		private Queue<String> q = null;

		public FastReader(String fileName)
		{
			try
			{
				if (fileName != null)
				{
					reader = new StreamReader(fileName);
				}
				else
				{
					reader = System.Console.In;
				}
			}
			catch (FileNotFoundException e)
			{
				throw e;
			}
		}

		public FastReader()
		{
			reader = System.Console.In;
		}

		public String next() {
			while (q == null || q.Count == 0)
			{	
				q = new Queue<string>(reader.ReadLine().Split());
			}
			return q.Dequeue();
		}

		public int nextInt()
		{
			return Int32.Parse(next());
		}

		public long nextLong()
		{
			return Int64.Parse(next());
		}

		public double nextDouble()
		{
			return Double.Parse(next());
		}
	}

	class FastWriter
	{
		private TextWriter writer = null;

		public FastWriter (String fileName ) 
		{
			try
			{
				if (fileName != null)
				{
					writer = new StreamWriter(fileName);
				}
				else
				{
					writer = System.Console.Out;
				}
			}
			catch (FileNotFoundException e)
			{
				throw e;
			}
		}

		public FastWriter()
		{
			writer = System.Console.Out;
		}

		public void Write(params object[] parameters)
		{
			foreach (object o in parameters)
			{
				writer.Write(o.ToString());
			}
		}

		public void WriteLine(params object[] parameters)
		{
			foreach (object o in parameters)
			{
				writer.Write(o.ToString());
			}
			writer.WriteLine();
		}

		public void Close()
		{
			writer.Close();
		}
	}

}

