namespace Pipeline
{
    class Program
    {
        static void Main(string[] args)
        {
            long[] input = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
            if (input[0] == 1)
            {
                Console.WriteLine(0);
            }
            else if (input[0] <= input[1])
            {
                Console.WriteLine(1);
            }
            else
            {
                --input[1];
                --input[0];
                if (sum(input[1]) < input[0])
                {
                    Console.WriteLine(-1);
                }
                else
                {
                    Console.WriteLine(minSplitters(input[1], input[0]));
                }


            }
        }

        public static long sum(long n)
        {
            return (n * (n + 1)) / 2;
        }

        public static long sum(long s, long e)
        {
            if (s <= 1)
            {
                return sum(e);
            }

            return sum(e) - sum(s - 1);
        }


        public static long minSplitters(long k, long n)
        {
            long st = 1,
                en = k;
            while (st < en)
            {
                long md = (st + en) / 2;
                long s = sum(md, k);

                if (s == n)
                    return k - md + 1;
                if (s > n)
                    st = md + 1;
                else
                    en = md;
            }

            return k - st + 2;
        }
    }
}

