namespace ProgrammingContest.Codeforces.Round78
{
    class A
    {
        struct Dice
        {
            int[] val;

            public Dice(int[] ary) { val = (int[])ary.Clone(); }

            void Rotate1()
            {
                int v = val[3];
                for (int i = 2; i >= 0; i--)
                    val[i + 1] = val[i];
                val[0] = v;
            }

            void Rotate2()
            {
                int v = val[0];
                val[0] = val[4];
                val[4] = val[2];
                val[2] = val[5];
                val[5] = v;
            }

            public int GetHash()
            {
                int bs = 1, res = 0;
                for (int i = 0; i < val.Length; i++, bs *= 8)
                    res += val[i] * bs;
                return res;
            }

            public IEnumerable<int> Rotations()
            {
                int u = GetHash();
                for (int i = 0; i < 4; i++)
                {
                    Rotate1();
                    Rotate2();
                    int v = GetHash();
