        #region Dice
        struct Dice
        {
            /*
             * val[0]: 北
             * val[1]: 西
             * val[2]: 南
             * val[3]: 東
             * val[4]: 上
             * val[5]: 下
             */
            int[] val;

            // [0,8)
            public Dice(int[] ary) { val = (int[])ary.Clone(); }

            void Rotate(params int[] idx)
            {
                int n = idx.Length;
                int v = val[idx[0]];
                for (int i = 0; i < n - 1; i++)
                    val[idx[i]] = val[idx[i + 1]];
                val[idx[n - 1]] = v;
            }

            // 上下は変えずに、上から見て反時計回りに回転
            public void RotateZ() { Rotate(3, 2, 1, 0); }

            // 北方向に回転、東西は変わらない
            public void RotateX() { Rotate(0, 4, 2, 5); }

            // 東方向に回転、南北は変わらない
            public void RotateY() { Rotate(3, 4, 1, 5); }

            public int GetHash()
            {
                int bs = 1, res = 0;
                for (int i = 0; i < val.Length; i++, bs *= 8)
                    res += val[i] * bs;
                return res;
            }

            // Diceの回転同型を全て列挙
            public IEnumerable<int> Rotations()
            {
                for (int i = 0; i < 4; i++)
                {
                    RotateZ();
                    RotateY();
                    for (int j = 0; j < 4; j++)
                    {
                        RotateZ();
                        yield return GetHash();
                    }
                    for (int j = 0; j < 3; j++)
                        RotateY();
                }
                for (int j = 0; j < 2; j++)
                {
                    for (int i = 0; i < 4; i++)
                    {
                        RotateZ();
                        yield return GetHash();
                    }
                    for (int i = 0; i < 2; i++)
                        RotateX();
                }
            }
        }
        #endregion
        #region Permutations
        private static void Swap<T>(T[] ts, int i, int j)
        {
            T tmp = ts[i];
            ts[i] = ts[j];
            ts[j] = tmp;
        }

        public static IEnumerable<T[]> Permutations<T>(T[] ts)
        {
            foreach (T[] p in Permutations(ts, 0, ts.Length))
            {
                yield return p;
            }
        }

        private static IEnumerable<T[]> Permutations<T>(T[] ts, int start, int end)
        {
            if (start == end) yield return ts;
            for (int i = start; i < end; i++)
            {
                for (int j = i - 1; j >= start; j--) Swap(ts, j, j + 1);
                foreach (T[] p in Permutations(ts, start + 1, end)) yield return p;
                for (int j = start; j < i; j++) Swap(ts, j, j + 1);
            }
        }
        #endregion
    }
