public class Solver
{
    int Fun(ref int x, int p)
    {
        int ret = 0;
        while (x % p == 0)
        {
            x /= p;
            ret++;
        }
        return ret;
    }

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();

        int n2 = Fun(ref n, 2);
        int n3 = Fun(ref n, 3);
        int m2 = Fun(ref m, 2);
        int m3 = Fun(ref m, 3);

        if (n != m || n2 > m2 || n3 > m3)
            Write(-1);
        else
            Write(m2 - n2 + m3 - n3);
    }

