namespace Remove_The_Substring {
    class Program {
        static void Main( string[] args ) {
            var s = Console.ReadLine().ToArray();
            var t = Console.ReadLine().ToArray();

            var occ = new int[ t.Length ];

            var ind = Array.IndexOf( s, t[0] );
            occ[ 0 ] = ind;

            for ( var i = 1 ; i < t.Length; i++ ) {
                occ[ i ] = Array.IndexOf( s, t[ i ], occ[i-1] + 1 );
            }

            var occs = new List<List<int>>();
            occs.Add( occ.ToList() );

            for( var j = t.Length - 1; j >= 0; j-- ) {
                var next = 0;

                if( j == t.Length - 1 ) {
                    next = Array.LastIndexOf( s, t[ j ] );
                } else {
                    next = Array.LastIndexOf( s, t[ j ], occ[ j + 1 ] - 1 );
                }
                if( next != -1 && next != occ[j] ) {
                    occ[ j ] = next;
                    occs.Add( occ.ToList() );
                }
            }

            var length = 0;
            var maxLength = Math.Max( s.Length - occs[0][t.Length - 1] - 1, occs.Last().First() );

            foreach( var o in occs ) {
                for( var j = 0; j < o.Count - 1; j++ ) {
                    length = o[ j + 1 ] - o[ j ] - 1;
                    if( length > maxLength ) { maxLength = length; }
                }
            }

            Console.WriteLine( maxLength );
        }
    }
}

