            writer.Flush();
        }

        private static int Solve(string[] args)
        {
            int n = Next();
            int k = Next();
            int x = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next();
            }

            for (int i = 0; i < k; i++)
            {
                nn[n - 1 - i] = x;
            }

            return nn.Sum();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
