                var leftChildIndex = GetLeftChildIndex(index);
                var rightChildIndex = GetRightChildIndex(index);

                var leftChild = leftChildIndex.HasValue ? (KeyValuePair<TK, TV>?)_list[leftChildIndex.Value] : null;

                var rightChild = rightChildIndex.HasValue ? (KeyValuePair<TK, TV>?)_list[rightChildIndex.Value] : null;

