        public static int GetPower_(int num, int power)
        {
            if (power == 0) return 1;
            if (power == 1) return num;
            var prev = GetPower_(num, power / 2);
            var prev2 = ((long)prev * prev);
            if (power % 2 != 0) return (int)((prev2 * num));
            return (int)prev2;
        }

        public static int Modulo = 1000000007;
        public static int GetPower(int num, int power)
        {
            if (power == 0) return 1;
            if (power == 1) return num % Modulo;
            var prev = GetPower(num, power / 2);
            var prev2 = ((long)prev * prev) % Modulo;
            if (power % 2 != 0) return (int)((prev2 * num) % Modulo);
            return (int)prev2;
        }
        public static long GetFactorial(int num)
        {
            if (num == 0) return 1;
            var res = 1L;
            for (var index = 1; index <= num; ++index)
            {
                res = (res * index) % Modulo;
            }

            return res;
        }

