namespace _1426E
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.ReadLine();
            int[] alice = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            int[] Bob = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

            //most wins
            int mostWins = 0;
            mostWins += Math.Min(alice[0], Bob[1]);
            mostWins += Math.Min(alice[1], Bob[2]);
            mostWins += Math.Min(alice[2], Bob[0]);

            //least wins
            List<int[]> aliceDistribution = new List<int[]>()
            { new int[3] { 0, 0, 0 }, new int[3] { 0, 0, 0 }, new int[3] { 0, 0, 0 } };

            for (int a = 0; a < alice.Length; a++)
            {
                for (int b = 0; b < Bob.Length; b++)
                {
                    if ((a + b) % alice.Length == (a + 1) % alice.Length)
                        continue;
                    int c = Math.Min(Bob[(a + b) % alice.Length], alice[a]);
                    alice[a] -= c;
                    Bob[(a + b) % alice.Length] -= c;
                    aliceDistribution[a][(a + b) % alice.Length] += c;
                }

                if (alice[a] > 0)
                {
                    for (int a2 = 0; a2 < alice.Length; a2++)
                    {
                        if (a2 == a)
                            continue;
                        for (int ad = 0; ad < aliceDistribution.Count; ad++)
                        {
                            if (ad == (a + 1) % alice.Length)
                                continue;

                            int c = Math.Min(alice[a], aliceDistribution[a2][ad]);
                            alice[a] -= c;
                            aliceDistribution[a2][ad] -= c;
                            aliceDistribution[a2][(a + 1) % alice.Length] += c;
                        }
                    }
                }
            }

            int leastWins = 0;
            foreach (var item in alice)
                leastWins += item;

            Console.WriteLine(leastWins + " " + mostWins);
        }
    }
}

using System;
