        var B = GetIntArray();
        var dinic = new Dinic(8);
        dinic.AddEdge(0, 1, A[0]);
        dinic.AddEdge(0, 2, A[1]);
        dinic.AddEdge(0, 3, A[2]);
        dinic.AddEdge(1, 4, int.MaxValue);
        dinic.AddEdge(1, 5, 0);
        dinic.AddEdge(1, 6, int.MaxValue);
        dinic.AddEdge(2, 4, int.MaxValue);
        dinic.AddEdge(2, 5, int.MaxValue);
        dinic.AddEdge(2, 6, 0);
        dinic.AddEdge(3, 4, 0);
        dinic.AddEdge(3, 5, int.MaxValue);
        dinic.AddEdge(3, 6, int.MaxValue);
        dinic.AddEdge(4, 7, B[0]);
        dinic.AddEdge(5, 7, B[1]);
        dinic.AddEdge(6, 7, B[2]);

        var min = N - dinic.MaxFlow(0, 7);

        int max = 0;
