public class Solver
{
    class Edge<T>
    {
        public int To, Inv;
        public T Capacity;
        public Edge(int to, int inv, T capacity)
        {
            To = to;
            Inv = inv;
            Capacity = capacity;
        }
    }

    static void AddEdge<T>(List<Edge<T>>[] g, int from, int to, T capacity, bool directed = true)
    {
        g[from].Add(new Edge<T>(to, g[to].Count, capacity));
        g[to].Add(new Edge<T>(from, g[from].Count - 1, directed ? default(T) : capacity));
    }

    static class Flow
    {
        private static int[] level;
        private static int[] ptr;
        private static int n, source, sink;
        private static List<Edge<long>>[] g;

        public static long Find(List<Edge<long>>[] g, int source, int sink)
        {
            n = g.Length;
            level = new int[n];
            ptr = new int[n];
            Flow.g = g;
            Flow.source = source;
            Flow.sink = sink;

            long ret = 0;
            while (true)
            {
                Bfs();
                if (level[sink] < 0)
                    return ret;
                Array.Clear(ptr, 0, n);
                long f;
                while ((f = Dfs(source, int.MaxValue / 2)) > 0)
                    ret += f;
            }
        }

        static void Bfs()
        {
            for (int i = 0; i < n; i++)
                level[i] = -1;
            var q = new Queue<int>();
            level[source] = 0;
            q.Enqueue(source);
            while (q.Count > 0)
            {
                var v = q.Dequeue();
                foreach (var e in g[v])
                    if (e.Capacity > 0 && level[e.To] < 0)
                    {
                        level[e.To] = level[v] + 1;
                        q.Enqueue(e.To);
                    }
            }
        }

        static long Dfs(int v, long f)
        {
            if (v == sink)
                return f;
            for (; ptr[v] < g[v].Count; ptr[v]++)
            {
                var e = g[v][ptr[v]];
                if (e.Capacity <= 0 || level[v] >= level[e.To])
                    continue;
                long d = Dfs(e.To, Math.Min(f, e.Capacity));
                if (d <= 0)
                    continue;
                e.Capacity -= d;
                g[e.To][e.Inv].Capacity += d;
                return d;
            }
            return 0;
        }
    }

    public void Solve()
    {
        for (int tt = 1; tt > 0; tt--)
        {
            int n = ReadInt();
            var a = ReadIntArray();
            var b = ReadIntArray();

            long ans = 1L * Math.Min(a[0], b[1]) + Math.Min(a[1], b[2]) + Math.Min(a[2], b[0]);
            var g = Init<List<Edge<long>>>(8);
            for (int i = 0; i < 3; i++)
            {
                AddEdge(g, 6, i, a[i]);
                AddEdge(g, i + 3, 7, b[i]);
                for (int j = 0; j < 2; j++)
                    AddEdge(g, i, (i + 2 + j) % 3 + 3, long.MaxValue);
            }

            Write(a.Sum(aa => (long)aa) - Flow.Find(g, 6, 7), ans);
        }
    }

