: this(new StreamReader(s))
{

}
public Input(TextReader tr)
{
TextReader = tr;

if (emptyHandler == null)
emptyHandler = (a, b) => { };

OnEndOfStream = emptyHandler;
OnParseError = emptyHandler;
OnReadError = emptyHandler;

CanRead = true;
}

public static implicit operator Input(Stream s)
{
return new Input(s);
}
public static implicit operator Input(TextReader tr)
{
return new Input(tr);
}

private bool ReadStream()
{
if (!CanRead) return false;
if (pos < line.Length) return true;

Clear();

string s = TextReader.ReadLine();
if (s == null)
{
CanRead = false;
return false;
}

line = s;
return true;
}

public void SkipChar()
{
if (pos < line.Length) pos++;
else
{
ReadStream();
}
}
public void SkipChars(int length)
{
while (length > 0)
{
int dt = line.Length - pos;
if (dt <= 0)
{
length--;
if (!ReadStream()) return;
}
dt = Math.Min(length, dt);
pos += dt;
length -= dt;
}
}

public void SkipWhiteSpace()
{
while (true)
{
for (; pos < line.Length; pos++)
{
if (!char.IsWhiteSpace(line[pos])) return;
}
if (!ReadStream())
{
OnEndOfStream(this, DefaultEventArgs);
return;
}
}
}
public bool CanReadData()
{
SkipWhiteSpace();
return CanRead;
}

