private bool ReadCheck()
{
if (!CanRead)
{
OnReadError(this, DefaultEventArgs);
if (ThrowExceptions)
{
throw new Exception("!CanRead");
}
return false;
}
return true;
}
public T ReadData<T>()
{
return ReadData<T>(true);
}
public T ReadData<T>(bool skipWhiteSpace)
{
ParserDelegate<T> parser = Parser.GetPrimitiveParser<T>();
return ReadData<T>(parser, skipWhiteSpace);
}
public T ReadData<T>(ParserDelegate<T> parser)
{
return ReadData<T>(parser, true);
}
public T ReadData<T>(ParserDelegate<T> parser, bool skipWhiteSpace)
{
if (skipWhiteSpace)
SkipWhiteSpace();

if (!ReadCheck()) return default(T);

string s = ReadWord(false);

T res;
if (!parser.Invoke(s, out res))
{
OnParseError(this, DefaultEventArgs);
if (ThrowExceptions)
{
throw new Exception("!validate, word = " + Output.ToString(s, 256));
}
}
return res;
}

public string ReadWord()
{
return ReadWord(true);
}
public string ReadWord(bool skipWhiteSpace)
{
if (skipWhiteSpace)
SkipWhiteSpace();

if (!ReadCheck()) return string.Empty;

int from = pos;
int to = pos;
for (int i = pos; i < line.Length; i++)
{
if (char.IsWhiteSpace(line[i])) break;
to = i + 1;
}
pos = to;

return line.Substring(from, to - from);
}

public string ReadLine()
{
if (!ReadCheck()) return string.Empty;

ReadStream();
string res = line.Substring(pos);
pos = line.Length;

return res;
}

public void Close()
{
TextReader.Close();
}
public void Clear()
{
pos = 0;
line = string.Empty;
}

