public static class Parser
{
public static ParserDelegate<T> GetPrimitiveParser<T>()
{
if (!typeof(T).IsPrimitive) throw new Exception("Unknown type");
else if (default(T) is Byte) return new ParserDelegate<Byte>(Byte.TryParse) as ParserDelegate<T>;
else if (default(T) is Boolean) return new ParserDelegate<Boolean>(Boolean.TryParse) as ParserDelegate<T>;
else if (default(T) is Int16) return new ParserDelegate<Int16>(Int16.TryParse) as ParserDelegate<T>;
else if (default(T) is Int32) return new ParserDelegate<Int32>(Int32.TryParse) as ParserDelegate<T>;
else if (default(T) is Int64) return new ParserDelegate<Int64>(Int64.TryParse) as ParserDelegate<T>;
else if (default(T) is UInt16) return new ParserDelegate<UInt16>(UInt16.TryParse) as ParserDelegate<T>;
else if (default(T) is UInt32) return new ParserDelegate<UInt32>(UInt32.TryParse) as ParserDelegate<T>;
else if (default(T) is UInt64) return new ParserDelegate<UInt64>(UInt64.TryParse) as ParserDelegate<T>;
else if (default(T) is Single) return new ParserDelegate<Single>(Parser.SingleParser) as ParserDelegate<T>;
else if (default(T) is Double) return new ParserDelegate<Double>(Parser.DoubleParser) as ParserDelegate<T>;
else if (default(T) is Decimal) return new ParserDelegate<Decimal>(Parser.DecimalParser) as ParserDelegate<T>;
else if (default(T) is String) return new ParserDelegate<String>(Parser.StringParser) as ParserDelegate<T>;
else throw new Exception("Unknown type");
}
public static bool YesNoParser(string s, out Boolean result)
{
s = s.ToLower();
if (s == "yes") result = true;
else if (s == "no") result = false;
else
{
result = false;
return false;
}
return true;
}
public static bool StringParser(string s, out string result)
{
result = s;
return string.IsNullOrEmpty(s);
}
public static bool DecimalParser(string s, out Decimal result)
{
return Decimal.TryParse(s.Replace('.', ','), out result);
}
public static bool DoubleParser(string s, out Double result)
{
return Double.TryParse(s.Replace('.', ','), out result);
}
public static bool SingleParser(string s, out Single result)
{
return Single.TryParse(s.Replace('.', ','), out result);
}
}
