public class HelloWorld {
    const ulong MOD = 1000000007ul;

    public static void SolveCodeForces() {
        // ShowStats();
        Solve();
    }

    static void Solve() {
        var max = cin.NextInt();

        var Divs = Helpers.CreateArray(max + 1, _ => new List<int>());
        for (var g = 2; g <= max; g++)
            for (var a = g; a <= max; a += g)
                Divs[a].Add(g);

        var Map = Helpers.CreateArray(max + 1, _ => new Dictionary<int, int>());
        for (var g = 2; g <= max; g++) {
            var counter = Map[g];
            var divs = Divs[g];

            counter[g] = max / g;
            for (var i = divs.Count - 2; i >= 0; i--) {
                var sum = 0;
                for (var j = i + 1; j < divs.Count; j++)
                    if (divs[j] % divs[i] == 0)
                        sum += counter[divs[j]];
                counter[divs[i]] = max / divs[i] - sum;
            }
        }

// for (var g = 2; g <= max; g++) {
//     System.Console.WriteLine(new {g});
//     foreach (var kvp in Map[g])
//         System.Console.WriteLine("   " + new { gcd=kvp.Key, cnt=kvp.Value });
// }

        var maxU = (ulong)max;
        var anssum = 0ul;
        var F = new ulong[max + 1];
        for (var g = 2; g <= max; g++) {
            var ag = 0;
            var sum = 0ul;
            foreach (var kvp in Map[g]) {
                var gcd = kvp.Key;
                var count = kvp.Value;
                if (gcd == g)
                    ag = count;
                else
                    sum = (sum + F[gcd] * (ulong)count) % MOD;
            }
            F[g] = (maxU + sum) * ModInverse(maxU + MOD - (ulong)ag, MOD) % MOD;
            anssum = (anssum + F[g]) % MOD;

// System.Console.WriteLine(new { g, fg=F[g] });
        }

        var ans = (1ul + anssum * ModInverse(maxU, MOD)) % MOD;
        System.Console.WriteLine(ans);
    }

    public static ulong ModInverse(ulong x, ulong mod) { return ModPow(x, mod - 2L, mod); }

    public static ulong ModPow(ulong x, ulong exp, ulong mod) {
        ulong ret = 1ul;
        while (exp > 0) {
            if (exp % 2 == 1) ret = ret * x % mod;
            x = x * x % mod;
            exp /= 2;
        }
        return ret;
    }

    static void ShowStats() {
        foreach (var max in new[] { 100, 1000, 10000, 100000 }) {
            // var MapBrute = GetGcdsCounter_Brute(max);
            var Map = GetGcdsCounter_InnerLoop(max);
            System.Console.WriteLine(new { max });
            // Compare(Map, MapBrute);
            System.Console.WriteLine("Total counts: " + Map.Sum(c => (long)c.Dict.Values.Sum()));
            System.Console.WriteLine("Different GCDs: " + Map.Sum(c => c.Dict.Count));
            var maxcnt = Map.Max(c => c.Dict.Count);
            System.Console.WriteLine("Max number of divisors: {0} ({1})", maxcnt, Map.Select((c, i) => new { c, i }).Where(a => a.c.Dict.Count == maxcnt).Select(a => a.i).Join());
            System.Console.WriteLine();
        }
    }

    static Counter<int>[] GetGcdsCounter_InnerLoop(int max) {
        var Map = Helpers.CreateArray(max + 1, _ => new Counter<int>());

        var ops1 = 0;
        for (var g = 2; g <= max; g++) {
            for (var a = g; a <= max; a += g) {
                Map[a][g] = 0;
                ops1++;
            }
        }

        var ops2 = 0;
        for (var g = 2; g <= max; g++) {
            var counter = Map[g];
            counter[g] = max / g;

            var divs = counter.Dict.Keys.ToArray();
            Array.Sort(divs, 0, divs.Length);

            for (var i = divs.Length - 2; i >= 0; i--) {
                var cnt = max / divs[i];
                for (var j = i + 1; j < divs.Length; j++) {
                    if (divs[j] % divs[i] == 0)
                        cnt -= counter[divs[j]];
                }
                counter[divs[i]] = cnt;
            }

            ops2 += divs.Length * divs.Length;
        }

        if (max == 100) {
            for (var g = 1; g <= max; g++) {
                System.Console.WriteLine(new {g});
                foreach (var kvp in Map[g].Dict)
                    System.Console.WriteLine("   " + new { gcd=kvp.Key, cnt=kvp.Value });
            }
        }

        System.Console.WriteLine(new {max, ops1, ops2});

        return Map;
    }

    static Counter<int>[] GetGcdsCounter_Brute(int max) {
        var Map = Helpers.CreateArray(max + 1, _ => new Counter<int>());
        for (var g = 1; g <= max; g++) {
            for (var x = 1; x <= max; x++) {
                var gcd = (int)GCD((ulong)g, (ulong)x);
                if (gcd > 1)
                    Map[g][gcd]++;
            }
            if (max == 100) {
                System.Console.WriteLine(new {g});
                foreach (var kvp in Map[g].Dict)
                    System.Console.WriteLine("   " + new { gcd=kvp.Key, cnt=kvp.Value });
            }
        }
        return Map;
    }

    private static ulong GCD(ulong a, ulong b) {
        while (a != 0 && b != 0) {
            if (a > b)
                a %= b;
            else
                b %= a;
        }
        return a == 0 ? b : a;
    }

    static void Compare(Counter<int>[] A, Counter<int>[] B) {
        for (var i = 0; i < A.Length; i++) {
            var C = A[i].Dict;
            var D = B[i].Dict;
            if (C.Count != D.Count) {
                System.Console.WriteLine(new { i, ccount = C.Count, dcount = D.Count });
                return;
            }
            if (!C.Keys.OrderBy(c => c).SequenceEqual(D.Keys.OrderBy(c => c))) {
                System.Console.WriteLine(new { i, ckeys=C.Keys.OrderBy(c => c).Join(), dkeys=D.Keys.OrderBy(c => c).Join() });
                return;
            }
            foreach (var key in C.Keys) {
                if (C[key] != D[key]) {
                    System.Console.WriteLine(new { i, ckeys=C.Keys.OrderBy(c => c).Join(), dkeys=D.Keys.OrderBy(c => c).Join() });
                    System.Console.WriteLine(new { key, cval=C[key], dval=D[key] });
                }
            }
        }
        System.Console.WriteLine("compare ok");
    }

