namespace ReadWriteTemplate
{
    public static class Solver
    {
        public const long MOD = 1000000000 + 7;

        private static List<int> Primes;

        private static void SolveCase()
        {
            int m = ReadInt();

            Primes = GetPrimes(m);

            Frac[] f = new Frac[m + 1];
            f[1] = new Frac(0, 1);

            var p = new List<Pair>[m + 1];
            for (int i = 2; i <= m; i++)
            {
                p[i] = new List<Pair>();
                bool found = false;
                for (int j = 0; j < Primes.Count && Primes[j] * Primes[j] <= i; j++)
                {
                    if (i % Primes[j] == 0)
                    {
                        bool inc = false;
                        int d = i / Primes[j];
                        for (int k = 0; k < p[d].Count; k++)
                        {
                            Pair pair = new Pair(p[d][k].A, p[d][k].B);
                            if (p[d][k].A == Primes[j])
                            {
                                pair.B++;
                                inc = true;
                            }
                            p[i].Add(pair);
                        }
                        if (!inc)
                        {
                            p[i].Add(new Pair(Primes[j], 1));
                        }
                        found = true;
                        break;
                    }
                }
                if (!found)
                {
                    p[i].Add(new Pair(i, 1));
                }

                var pairs = new List<Pair>();
                Build(m, p[i], 0, i, 0, new int[10], pairs);

                int eqk = 0;
                var pr = new Frac(m, 1);
                for (int j = 0; j < pairs.Count; j++)
                {
                    var pair = pairs[j];
                    if (pair.A != i)
                    {
                        var c = new Frac(f[pair.A].X * pair.B % MOD, f[pair.A].Y);
                        pr = Sum(pr, c);
                    }
                    else
                    {
                        eqk += pair.B;
                    }
                }

                pr.Y = pr.Y * (m - eqk) % MOD;

                f[i] = pr;
            }

            Frac sum = new Frac(m, 1);
            for (int i = 0; i < m; i++)
            {
                sum = Sum(sum, f[i + 1]);
            }

            long ans = sum.X * BinPower(sum.Y, MOD - 2, MOD) % MOD * BinPower(m, MOD - 2, MOD) % MOD;

            Writer.WriteLine(ans);
        }

        private static Frac Sum(Frac a, Frac b)
        {
            return new Frac((a.X * b.Y + a.Y * b.X) % MOD, (a.Y * b.Y) % MOD);
        }

        private static void Build(int m, List<Pair> p, int t, int d, int q, int[] div, List<Pair> pairs)
        {
            if (t >= p.Count)
            {
                int count = Calc(m / d, 0, q, div, 0);
                pairs.Add(new Pair(d, count));
                return;
            }

            Build(m, p, t + 1, d, q, div, pairs);
            div[q] = p[t].A;
            for (int i = 1; i <= p[t].B; i++)
            {
                d /= p[t].A;
                Build(m, p, t + 1, d, q + 1, div, pairs);
            }
        }

        private static int Calc(int x, int t, int q, int[] div, int c)
        {
            if (t >= q)
            {
                return (((div.Length + c) & 1) == 0 ? 1 : -1) * x;
            }

            return Calc(x, t + 1, q, div, c) +
                   Calc(x / div[t], t + 1, q, div, c + 1);
        }

        public static long BinPower(long a, long n, long mod)
        {
            long result = 1;

            while (n > 0)
            {
                if ((n & 1) != 0)
                {
                    result = (result * a) % mod;
                }

                a = (a * a) % mod;
                n >>= 1;
            }

            return result;
        }

        public class Pair
        {
            public Pair(int a, int b)
            {
                A = a;
                B = b;
            }

            public int A;

            public int B;

            public override string ToString()
            {
                return $"({A}, {B})";
            }
        }

        public class Frac
        {
            public Frac(long x, long y)
            {
                X = x;
                Y = y;
            }

            public long X;

            public long Y;

            public override string ToString()
            {
                return $"{X} / {Y}";
            }
        }

        public static List<int> GetPrimes(long n)
        {
            var primes = new List<int>();

            n = Math.Max(n, 2);
            bool[] isPrime = new bool[n + 1];
            for (int i = 2; i <= n; i++)
            {
                isPrime[i] = true;
            }

            for (int i = 2; i <= n; i++)
            {
                if (isPrime[i])
                {
                    primes.Add(i);
                    if ((long)i * i <= n)
                    {
                        for (int j = i * i; j <= n; j += i)
                        {
                            isPrime[j] = false;
                        }
                    }
                }
            }

            return primes;
        }

