    #region Heap

    public static void InsertElementInHeap(int value, int[] arr, ref int sizeOfTree)
    {  
        arr[sizeOfTree + 1] = value;  
        sizeOfTree++;  
        HeapifyBottomToTop(sizeOfTree, arr);  
    }
    
    public static void HeapifyBottomToTop(int index, int[] arr)
    {  
      int parent = index / 2;  
      // We are at root of the tree. Hence no more Heapifying is required.  
      if (index <= 1) {  
        return;  
      }  
      // If Current value is smaller than its parent, then we need to swap  
      if (arr[index] > arr[parent]) {  
        int tmp = arr[index];  
        arr[index] = arr[parent];  
        arr[parent] = tmp;  
      }  
      HeapifyBottomToTop(parent, arr);  
    }
    
    public static int ExtractHeadOfHeap(ref int sizeOfTree, int[] arr) {  
      if(sizeOfTree == 0) {  
        return -1;  
      }else {  
        int extractedValue = arr[1];  
        arr[1] = arr[sizeOfTree]; //Replacing with last element of the array  
        sizeOfTree--;  
        HeapifyTopToBottom(1, sizeOfTree, arr);  
        return extractedValue;  
      }  
    }
    
    public static void HeapifyTopToBottom(int index, int sizeOfTree, int[] arr)
    {  
      int left  = index << 1;  
      int right = left + 1;  
      int smallestChild = 0;  
          
      if (sizeOfTree < left) { //If there is no child of this node, then nothing to do. Just return.  
        return;   
      }else if (sizeOfTree == left) { //If there is only left child of this node, then do a comparison and return.  
        if(arr[index] < arr[left]) {  
          int tmp = arr[index];  
          arr[index] = arr[left];  
          arr[left] = tmp;  
        }  
        return;  
      }else { //If both children are there  
        if(arr[left] > arr[right]) { //Find out the smallest child  
          smallestChild = left;  
        }else {  
          smallestChild = right;  
        }  
        if(arr[index] < arr[smallestChild]) { //If Parent is greater than smallest child, then swap  
          int tmp = arr[index];  
          arr[index] = arr[smallestChild];  
          arr[smallestChild] = tmp;  
        }  
      }  
      HeapifyTopToBottom(smallestChild, sizeOfTree, arr);  
    }

