    class Program
    {
        static List<int> s = new List<int>();

        static bool Rec(int a, int b)
        {
            if (a == b)
            {
                s.Add(b);
                return true;
            }
            else if (b > a)
            {
                bool w = false;

                if (b % 2 == 0)
                {
                    w = Rec(a, b / 2);
                    if (w)
                        s.Add(b);
                    return w;
                }
                if ((b - 1) % 10 == 0)
                {
                    w = Rec(a, (b - 1) / 10);
                    if (w)
                        s.Add(b);
                    return w;
                }
                return false;
            }
            return false;
        }

        static void Main()
        {
            string[] input = Console.ReadLine().Split(' ');
            if (Rec(int.Parse(input[0]), int.Parse(input[1])))
            {
                Console.WriteLine("YES");
                Console.WriteLine(s.Count.ToString());
                for (int i = 0; i < s.Count; i++)
                    Console.Write(s[i] + " ");
                return;
            }
            Console.Write("NO");
        }
    }
}

