    {
        public static int NOD(int a, int b)
        {
            int x;

            if (a > b)
            {
                x = a;
                a = b;
                b = x;
            }

            while (a > 0)
            {
                x = a;
                a = b % a;
                b = x;
            }

            return b;
        }

        static void Main(string[] args)
        {
            string s = Console.ReadLine();
            int n = int.Parse(s);

            string[] ss = Console.ReadLine().Split();
