                a[i] = int.Parse(ss[i]);

            int k = a[0];

            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++)
                {
                    k = Math.Min(k, NOD(a[i], a[j]));
                    if (k == 1)
                    {
                        Console.WriteLine(n);
                        return;
                    }
                }

            for (int i = 0; i < n; i++)
                k = Math.Min(k, NOD(a[i], k));

            Console.WriteLine(k * n);
        }
    }
