namespace Odds_and_Ends
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next()%2;
            }

            if (nn[0] == 0 || n%2 == 0)
            {
                writer.WriteLine("No");
                writer.Flush();
                return;
            }

            if (!Solve(nn, n))
            {
                Array.Reverse(nn);
                if (nn[0] == 0)
                {
                    writer.WriteLine("No");
                    writer.Flush();
                    return;
                }

                writer.WriteLine(!Solve(nn, n) ? "No" : "Yes");
            }
            else writer.WriteLine("Yes");

            writer.Flush();
        }

        private static bool Solve(int[] nn, int n)
        {
            int cross = 0;
            int g = 0;
            for (int i = 0; i < n; i++)
            {
                if (nn[i] == 0)
                {
                    for (int j = i + 1; j < n; j++)
                    {
                        if (nn[j] == 1 && nn[j - 1] == 1 && (j - i)%2 == 0)
                        {
                            g++;
                            cross += j - i + 1;
                            i = j;
                            break;
                        }
                    }
                    if (nn[i] == 0)
                    {
                        if (nn[n - 1] == 1 && (n - i)%2 == 0)
                        {
                            g++;
                            cross += n - i + 1;
                            i = n;
                        }
                        else
                        {
                            return false;
                        }
                    }
                }
            }

            return (n - cross + g)%2 == 1;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

