    class _236B
    {
        public static void Main()
        {
            const int Mod = 1073741824;

            var tokens = Console.ReadLine().Split();

            int a = int.Parse(tokens[0]);
            int b = int.Parse(tokens[1]);
            int c = int.Parse(tokens[2]);

            int Max = a * b * c;

            var isPrime = new bool[Max + 1];
            for (int i = 2; i <= Max; i++)
            {
                isPrime[i] = true;
            }

            for (int i = 2; i <= Max; i++)
            {
                if (isPrime[i])
                {
                    for (int j = 2 * i; j <= Max; j += i)
                    {
                        isPrime[j] = false;
                    }
                }
            }

            var primes = Enumerable.Range(1, Max).Where(i => isPrime[i]).ToList();

            var d = new int[Max + 1];
            for (int i = 1; i <= Max; i++)
            {
                if (i == 1)
                {
                    d[i] = 1;
                }
                else if (isPrime[i])
                {
                    d[i] = 2;
                    continue;
                }
                else
                {
                    int prime = primes.First(p => i % p == 0);

                    int x = i;
                    int count = 0;

                    while (x % prime == 0)
                    {
                        x /= prime;
                        count++;
                    }

                    d[i] = d[x] * (count + 1);
                }
            }

            int sum = 0;

            for (int i = 1; i <= a; i++)
            {
                for (int j = 1; j <= b; j++)
                {
                    for (int k = 1; k <= c; k++)
                    {
                        sum = (sum + d[i * j * k]) % Mod;
                    }
                }
            }

            Console.WriteLine(sum);
        }
    }
}

