        List<int> primes = new List<int>();
        primes.Add(2);
        for (int i = 3; i <= 100; i++)
        {
            bool ok = true;
            foreach (int p in primes)
            {
                if (i % p == 0) ok = false;
            }
            if (ok) primes.Add(i);
        }
        dl = primes.ToArray();

        for (int x = 2; x <= 100; x++)
        {
            int xx = x;

            for (int pi = 0; pi < dl.Length && dl[pi]<=x ; pi++)
            {
                int po = dl[pi];

                while (xx % po == 0)
                {
                    pows[x, pi]++;
                    xx /= po;
                }
            }
        }

        int[] total_pows = new int[100];
        long res = 0;

        for (int a = 1; a <= abc[0]; a++)
            for (int b = 1; b <= abc[1]; b++)
                for (int c = 1; c <= abc[2]; c++)
                {
                    for (int i = 0; i < dl.Length; i++)
                        total_pows[i] = 0;

                    for (int i = 0, n = a; i < dl.Length; i++)
                        total_pows[i] += pows[n, i];
                    for (int i = 0, n = b; i < dl.Length; i++)
                        total_pows[i] += pows[n, i];
                    for (int i = 0, n = c; i < dl.Length; i++)
                        total_pows[i] += pows[n, i];

                    long subres = 1;
                    for (int i = 0; i < dl.Length; i++)
                    {
                        subres = subres * (total_pows[i] + 1) % MODULO;
                    }
                    res = (res + subres) % MODULO;
                }

