            int next = 0;
            string way = Console.ReadLine();
            int steps=0;
            bool outofrange=false;

            for (int pointer = 0; pointer < wordLength-1; )
            {
                //Bring Maximum 1 after My Jump
                next = pointer + MaxJump;

                if (next < wordLength && way[next] == '1')
                {
                    steps++;
                    pointer = next;
                }
                else
                {
                    int j;
                    if (next > wordLength)
                    {
                        steps++;
                        break;
                    }
                    for ( j = next-1; j > pointer; j--)
                    {
                        if (j<wordLength && way[j] == '1'  )
                        {
                            next = j;
                            pointer = next;
                            steps++;
                        }
                    }
                    if (j == pointer)
                    {
                        outofrange = true;
                        break;
                    }
                }
            }
            if (outofrange)
                Console.WriteLine("-1");
            else
            Console.WriteLine(steps);

        }

    }
