using System;
using System.Text;
using System.Collections.Generic;
using System.Threading;
using System.IO;

namespace codeforces
{
    class Program
    {
        class Flow
        {
            public int to;
            public int capacity;
            public int flow;
            public int cost;
            public int iRevEdge;

            public Flow(int to, int capacity, int flow, int cost, int iRevEdge)
            {
                this.to = to;
                this.capacity = capacity;
                this.flow = flow;
                this.cost = cost;
                this.iRevEdge = iRevEdge;
            }
        }

        class CompareVertex : IComparer<int>
        {
            public int Compare(int x, int y)
            {
                int v = d[x].CompareTo(d[y]);
                return v != 0 ? v : x.CompareTo(y);
            }
        }

        const int N = 80;

        static int[] di = new int[4] { 0, 0, -1, 1 };
        static int[] dj = new int[4] { -1, 1, 0, 0 };

        static int n, m;
        static int[,] a = new int[N, N];

        static int[] d = new int[N * N + 2];
        static int[] phi = new int[N * N + 2];
        static int[] parent = new int[N * N + 2];
        static int[] numEdge = new int[N * N + 2];
        static List<Flow>[] G = new List<Flow>[N * N + 2];
        static SortedSet<int> sVertex = new SortedSet<int>(new CompareVertex());
        static int minCost = 0;

        static void AddEdge(int from, int to, int cap, int cost)
        {
            G[from].Add(new Flow(to, cap, 0, cost, G[to].Count));
            G[to].Add(new Flow(from, 0, 0, -cost, G[from].Count - 1));
        }

        static bool FindPath(int from, int to)
        {
            for (int i = 0; i <= to; ++i)
            {
                d[i] = int.MaxValue;
            }
            int v;
            sVertex.Clear();
            d[from] = 0;
            sVertex.Add(from);
            while (sVertex.Count > 0)
            {
                v = sVertex.Min;
                sVertex.Remove(v);

                for (int i = 0; i < G[v].Count; ++i)
                {
                    var f = G[v][i];
                    if (f.flow < f.capacity && d[f.to] > d[v] + f.cost - phi[v] + phi[f.to])
                    {
                        if (sVertex.Contains(f.to))
                        {
                            sVertex.Remove(f.to);
                        }
                        d[f.to] = d[v] + f.cost - phi[v] + phi[f.to];
                        sVertex.Add(f.to);
                        parent[f.to] = v;
                        numEdge[f.to] = i;
                    }
                }
            }

            if (d[to] == int.MaxValue)
            {
                return false;
            }
            for (int i = 0; i <= to; ++i)
            {
                if (d[i] != int.MaxValue)
                {
                    phi[i] += d[i]; 
                }
            }
            v = to;
            int flow = int.MaxValue;
            while (v != from)
            {
                int u = parent[v];
                flow = Math.Min(flow, G[u][numEdge[v]].capacity - G[u][numEdge[v]].flow);
                v = u;
            }

            v = to;
            while(v != from)
            {
                int u = parent[v];
                G[u][numEdge[v]].flow += flow;
                G[v][G[u][numEdge[v]].iRevEdge].flow -= flow;
                minCost += flow * G[u][numEdge[v]].cost;
                v = u;
            }
            return true;

        }


        static void Main(string[] args)
        {
            var t = Console.ReadLine().Split(' ');
            n = int.Parse(t[0]);
            m = int.Parse(t[1]);
            for (int i = 0; i < n; ++i)
            {
                t = Console.ReadLine().Split(' ');
                for (int j = 0; j < m; ++j)
                {
                    a[i, j] = int.Parse(t[j]);
                }
            }
            int from = n * m;
            int to = n * m + 1;
            for (int i = 0; i <= to; ++i)
            {
                phi[i] = 0;
                G[i] = new List<Flow>();
            }

            for (int i = 0; i < n; ++i)
            {
                for (int j = 0; j < m; ++j)
                {
                    if ((i + j) % 2 == 0)
                    {
                        AddEdge(from, i * m + j, 1, 0);
                        for (int k = 0; k < 4; ++k)
                        {
                            int ei = i + di[k];
                            int ej = j + dj[k];
                            if (ei >= 0 && ei < n && ej >= 0 && ej < m)
                            {
                                AddEdge(i * m + j, ei * m + ej, 1, a[i, j] == a[ei, ej] ? 0 : 1);
                            }
                        }
                    }
                    else
                    {
                        AddEdge(i * m + j, to, 1, 0);
                    }

                }
            }

            while (FindPath(from, to)) { }

            Console.WriteLine(minCost);

            Console.Read();
        }

    }
}

