// (づ°ω°)づﾐ★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
public class Solver
{
    class Edge<T>
    {
        public int To, Inv;
        public T Capacity, Cost, Flow;
        public Edge(int to, int inv, T capacity, T cost, T flow)
        {
            To = to;
            Inv = inv;
            Capacity = capacity;
            Cost = cost;
            Flow = flow;
        }
    }

    static void AddEdge(List<Edge<int>>[] g, int from, int to, int capacity, int cost)
    {
        g[from].Add(new Edge<int>(to, g[to].Count, capacity, cost, 0));
        g[to].Add(new Edge<int>(from, g[from].Count - 1, 0, -cost, 0));
    }

    int MinCost(List<Edge<int>>[] g, int source, int sink, int limit)
    {
        const int INF = int.MaxValue / 2;

        int n = g.Length;
        int flow = 0, cost = 0;
        while (flow < limit)
        {
            var id = new int[n];
            var dist = Enumerable.Repeat(INF, n).ToArray();
            var q = new int[n];
            var path = new int[n];
            var epath = new int[n];
            int qh = 0, qt = 0;
            q[qt++] = source;
            dist[source] = 0;
            while (qh != qt)
            {
                int v = q[qh++];
                if (qh == n)
                    qh = 0;
                id[v] = 2;
                for (int i = 0; i < g[v].Count; i++)
                {
                    var r = g[v][i];
                    if (r.Flow < r.Capacity && dist[v] + r.Cost < dist[r.To])
                    {
                        dist[r.To] = dist[v] + r.Cost;
                        if (id[r.To] == 0)
                        {
                            q[qt++] = r.To;
                            if (qt == n)
                                qt = 0;
                        }
                        else if (id[r.To] == 2)
                        {
                            if (--qh == -1)
                                qh = n - 1;
                            q[qh] = r.To;
                        }
                        id[r.To] = 1;
                        path[r.To] = v;
                        epath[r.To] = i;
                    }
                }
            }
            if (dist[sink] == INF)
                break;
            int addflow = limit - flow;
            for (int v = sink; v != source; v = path[v])
            {
                int pv = path[v];
                int pr = epath[v];
                addflow = Math.Min(addflow, g[pv][pr].Capacity - g[pv][pr].Flow);
            }
            for (int v = sink; v != source; v = path[v])
            {
                int pv = path[v];
                int pr = epath[v], r = g[pv][pr].Inv;
                g[pv][pr].Flow += addflow;
                g[v][r].Flow -= addflow;
                cost += g[pv][pr].Cost * addflow;
            }
            flow += addflow;
        }
        return cost;
    }

    private int[] dr = {1, 0, -1, 0};
    private int[] dc = {0, 1, 0, -1};

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadIntMatrix(n);

        var g = Enumerable.Repeat(0, n * m + 2).Select(x => new List<Edge<int>>()).ToArray();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
            {
                int x = i * m + j;
                if ((i + j) % 2 == 0)
                {
                    AddEdge(g, n * m, x, 1, 0);
                    for (int k = 0; k < 4; k++)
                    {
                        int ii = i + dr[k];
                        int jj = j + dc[k];
                        if (ii < 0 || ii == n || jj < 0 || jj == m)
                            continue;
                        AddEdge(g, x, ii * m + jj, 1, a[i][j] == a[ii][jj] ? 0 : 1);
                    }
                }
                else
                {
                    AddEdge(g, x, n * m + 1, 1, 0);
                }
            }

        Write(MinCost(g, n * m, n * m + 1, n * m / 2));
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;

    static void Main()
    {
#if DEBUG
        reader = new StreamReader("..\\..\\input.txt");
        writer = Console.Out;
        //writer = new StreamWriter("..\\..\\output.txt");
