class Solve{
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        string[] str = Console.ReadLine().Split(' ');
        int H = int.Parse(str[0]);
        int W = int.Parse(str[1]);
        int[,] D = new int[H,W];
        for(int i=0;i<H;i++){
            str = Console.ReadLine().Split(' ');
            for(int j=0;j<W;j++){
                D[i,j] = int.Parse(str[j]);
            }
        }
        int S = H*W;
        int G = H*W+1;
        List<int> F = new List<int>();
        List<int> T = new List<int>();
        List<long> capacity = new List<long>();
        List<long> cost = new List<long>();
        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                if((i+j) % 2 == 0){
                    F.Add(S);
                    T.Add(i*W+j);
                    capacity.Add(1);
                    cost.Add(0);
                    if(i != 0){
                        F.Add(i*W+j);
                        T.Add((i-1)*W+j);
                        capacity.Add(1);
                        cost.Add(D[i-1,j] == D[i,j] ? 0 : 1);
                    }
                    if(i != H-1){
                        F.Add(i*W+j);
                        T.Add((i+1)*W+j);
                        capacity.Add(1);
                        cost.Add(D[i+1,j] == D[i,j] ? 0 : 1);
                    }
                    if(j != 0){
                        F.Add(i*W+j);
                        T.Add(i*W+(j-1));
                        capacity.Add(1);
                        cost.Add(D[i,j-1] == D[i,j] ? 0 : 1);
                    }
                    if(j != W-1){
                        F.Add(i*W+j);
                        T.Add(i*W+(j+1));
                        capacity.Add(1);
                        cost.Add(D[i,j+1] == D[i,j] ? 0 : 1);
                    }
                }
                else{
                    T.Add(G);
                    F.Add(i*W+j);
                    capacity.Add(1);
                    cost.Add(0);
                }
            }
        }
        MinCostFlow Flow = new MinCostFlow(F.ToArray(),T.ToArray(),capacity.ToArray(),cost.ToArray(),G+1,S,G,H*W/2);
        sb.Append(Flow.res+"\n");
    }
}
