class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().solve();
        return 0;
    }

    void solve()
    {
        Scanner cin = new Scanner();

        int h = cin.nextInt();
        int w = cin.nextInt();
        int[,] board = new int[h, w];
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                board[i, j] = cin.nextInt();
            }
        }

        int MAX = 1 << w;
        int[] dp = new int[MAX];
        for (int i = 0; i < MAX; i++)
        {
            dp[i] = 1 << 16;
        }
        dp[0] = 0;

        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                int[] nextdp = new int[MAX];
                for (int k = 0; k < MAX; k++)
                {
                    nextdp[k] = 1 << 16;
                }

                for (int k = 0; k < MAX; k++)
                {
                    if (k % 2 == 0)
                    {
                        if (j != w - 1)
                        {
                            int add = 0;
                            if (board[i, j] != board[i, j + 1]) add = 1;
                            int next = k / 2 + 1;
                            nextdp[next] = Math.Min(nextdp[next], dp[k] + add);
                        }
                        if (i != h - 1)
                        {
                            int add = 0;
                            if (board[i, j] != board[i + 1, j]) add = 1;
                            int next = k / 2 + (1 << (w - 1));
                            nextdp[next] = Math.Min(nextdp[next], dp[k] + add);
                        }
                    }
                    else
                    {
                        nextdp[k / 2] = Math.Min(nextdp[k / 2], dp[k]);
                    }
                }
                dp = nextdp;
            }
        }
        Console.WriteLine(dp[0]);

    }


}



