class Solver
{
    void Solve()
    {
        var n = sc.Integer();
        var m = sc.Integer();
        var hori = sc.ScanLine().Select(x => x == '>' ? 1 : -1).ToArray();
        var ver = sc.ScanLine().Select(x => x == 'v' ? 1 : -1).ToArray();
        for (int r = 0; r < n; r++)
        {
            for (int c = 0; c < m; c++)
            {
                var used = new bool[n, m];
                var qr = new Queue<int>();
                var qc = new Queue<int>();
                qr.Enqueue(r);
                qc.Enqueue(c);
                while (qr.Any())
                {
                    var pr = qr.Dequeue();
                    var pc = qc.Dequeue();
                    if (used[pr, pc]) continue;
                    used[pr, pc] = true;
                    //horizon
                    {
                        var nc = pc + hori[pr];
                        if (nc < 0 || nc >= m || used[pr, nc]) { }
                        else
                        {
                            qr.Enqueue(pr);
                            qc.Enqueue(nc);
                        }

                    }
                    //vertical
                    {
                        var nr = pr + ver[pc];
                        if (nr < 0 || nr >= n || used[nr, pc]) { }
                        else
                        {
                            qr.Enqueue(nr);
                            qc.Enqueue(pc);
                        }
                    }
                }
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < m; j++)
                        if (!used[i, j])
                        {
                            Printer.PrintLine("NO");
                            return;
                        }
            }
        }
        Printer.PrintLine("YES");
    }

