	{ 	
		var  n = ar.Length;

		long max= 0;
		for (var ind = 0; ind < n; ind++)
		{
			if (ar[ind] == 0)
				continue;

			var arr = new int[n];
			Array.Copy(ar,arr,n);
			var p = arr[ind] / 14;
			var k = arr[ind] % 14;
			arr[ind] = 0;
			if (p > 0)
