				for (var i = 0; i < n; i++)
				{
					arr[i] = arr[i] + p;
				}
			}
			//Console.WriteLine( p + " " + k);
			if (k > 0)
			{
				for (var i = ind + 1; i < Math.Min(n, ind + k + 1); i++)
				{
					arr[i] += 1;
				}
				if (ind + k + 1 > n)
				{
					for (var i = 0; i <= ind + k - n; i++)
					{
						arr[i] += 1;
					}
				}
			}
			long sum = 0;
