    class Program
    {
        static int Main(string[] args)
        {
            string[] inArr = Console.ReadLine().Split(' ');
            int n = int.Parse(inArr[0]),
                m = int.Parse(inArr[1]);
            int[] originalArr = new int[n];
            for (int i = 0; i < n; i++)
                originalArr[i] = i + 1;
            string[] allArrays= new string[factorial(n)];
            for (int i=0; i<factorial(n); i++)
            {
                allArrays[i] = getNumbers(originalArr, i);
            }
            int[] allFp = new int[allArrays.Length];
            int maxFp = 0;
            for (int cur = 0; cur < allArrays.Length; cur++)
            {
                int fP = 0;
                string[] p = allArrays[cur].Split(' ');
                for (int i = 0; i < n; i++)
                {
                    for (int j = i; j < n; j++)
                    {
                        int min = int.Parse(p[i]);
                        for (int x = i; x <= j; x++)
                        {
                            if (int.Parse(p[x]) < min)
                                min = int.Parse(p[x]);
                        }
                        fP += min;
                    }
                }
                allFp[cur] = fP;
                if (fP > maxFp) maxFp = fP;
            }
            int curM = 1;
            for (int i = 0; i < allArrays.Length; i++)
            {
                if (allFp[i] == maxFp)
                {

                    if (curM == m)
                    {
                        Console.Write(allArrays[i]);
                        break;
                    }
                    curM++;
                }
            }
            return 0;
        }
        static string getNumbers(int[] nums, long cur)
        {

            int size = nums.Length;
            if (size == 1) return Convert.ToString(nums[0]);
            long amount = factorial(size);
            long ind = (long)(cur / (amount / size));
            int[] newNums = new int[size - 1];
            int Tx = 0;
            for (int x = 0; x < size; x++)
            {
                if (x == ind)
                    continue;
                newNums[Tx] = nums[x];
                Tx++;
            }
            return nums[ind] + " " + getNumbers(newNums, (cur - (amount / size) * ind));

        }
        static long factorial(int n)
        {
            return n <= 1 ? 1 : n * factorial(n - 1);
        }
    }
}

