using System;

class Round362P2{
	static string StripFrontZero(string str){
		string ret = "";
		bool fl = true;
		for(int i=0;i<str.Length;i++){
			if(fl && str[i] == '0')
				continue;
			if(str[i] != '0'){
				fl = false;
			}
			if(!fl){
				ret += str[i];
			}
		}
		return ret;
	}
	public static void Main(string[] args){
		string line = Console.ReadLine();
		string bd = "",ad = "" ,pow = "";
		bool dfl = false;
		bool efl = false;
		int ipow = 0;
		for(int i=0;i<line.Length;i++){
			if(line[i] == '.'){
				dfl = true;
				continue;
			}
			if(line[i] == 'e'){
				efl = true;
				continue;
			}
			if(dfl == false){
				bd += line[i];
			}
			else if(dfl == true && efl == false){
				ad += line[i];
			}
			else if(dfl == true && efl == true){
				pow += line[i];
				ipow = ipow*10+(int)line[i]-48;
			}
		}
		string nad = "";
		//not int
		if(ipow < ad.Length){
			nad = ad.Substring(0,ipow)+"."+ad.Substring(ipow,ad.Length-ipow);
			//Console.WriteLine("nad: "+nad);
		}
		else{
			nad = ad;
			for(int i=0;i<ipow - ad.Length;i++)
				nad += "0";
		}
		string ans = "";
		if(nad.CompareTo(".0") == 0){
			ans = bd;
		}
		else if(bd.CompareTo("0") != 0){
			ans  = bd+nad;
		}
		else{
			string temp = StripFrontZero(nad);
			if(temp[0] == '.')
				ans = '0'+temp;
			else ans  = temp;
		}
		Console.WriteLine(ans);
	}
}

