using System.Text.RegularExpressions;

class Program
{
    static void Main(string[] args)
    {
        string [] Input = Console.ReadLine().Split();
        int Parent = Int32.Parse(Input[0]);
        int Childs = Int32.Parse(Input[1]);
        int max, min;

        if (Childs == 0)
            max = Parent;
        else
            max = Parent + Childs - 1;
        if (Childs >= Parent) min = Parent + (Childs - Parent);
        else
            min = Parent;

        if (Parent == 0 && Childs != 0)
            Console.Write("Impossible");
        else
            Console.Write("{0} {1}", min, max);
    }
}

