namespace Problem831A
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.ReadLine();
            var a = Console.ReadLine().Split(' ').Select(_ => int.Parse(_)).ToArray();

            Console.WriteLine(Check(a) ? "YES" : "NO");
        }

        static bool Check(int[] a)
        {
            int le = -1;
            int l = a.Length;
            int i = 0;
            if (l == 1)
                return true;

            while (i < l && a[i] > le)
            {
                le = a[i];
                i++;
            }
            if (i == l && a[l - 1] > a[l - 2])
                return true;

            if (a[i] == le)
            {
                while (i < l && a[i] == le)
                {
                    le = a[i];
                    i++;
                }

                if (i == l && a[l - 1] == a[l - 2])
                    return true;
            }
            le = a[i - 1];
            while (i < l && a[i] < le)
            {
                le = a[i];
                i++;
            }

            if (i != l)
                return false;

            return true;
        }
    }
}

