class Solution
{
    static void Main(string[] args)
    {
        long[] ns = Array.ConvertAll(Console.ReadLine().Split(' '), item => Convert.ToInt64(item));
        long n = ns[0], s = ns[1], count = 0;
        for(long i=n;i>0;i--)
        {
            if (s == 0) break;
            if(s>=i)
            {
                count += s / i;
                s %= i;
            }
        }
        Console.Write(count);
    }
}

