class Solver
{
    public int Solve(int a1, int b1, int c1, int a2, int b2, int c2)
    {
        if (a1 == 0 && b1 == 0 && c1 != 0) return 0;
        if (a2 == 0 && b2 == 0 && c2 != 0) return 0;
        if ((a1 == 0 && b1 == 0) || (a2 == 0 && b2 == 0)) return -1;

        if ((a1 == 0 && b2 == 0) || (a2 == 0 && b1 == 0)) return 1;
        if (a1 == 0 && a2 == 0)
        {
            if (b1 * c2 == b2 * c1) return -1;
            return 0;
        }
        if (b1 == 0 && b2 == 0)
        {
            if (a1 * c2 == a2 * c1) return -1;
            return 0;
        }

        bool a_same = (a1 * b2 == a2 * b1);
        bool b_same = (c1 * b2 == b1 * c2);
        return (a_same && b_same) ? -1 : (a_same ? 0 : 1);

    }
}

