        {
            var mm = new bool[6,6];
            int m = Next();
            for (int i = 0; i < m; i++)
            {
                int a = Next();
                int b = Next();
                mm[a, b] = true;
                mm[b, a] = true;
            }

            for (int i = 1; i < 6; i++)
            {
                for (int j = i + 1; j < 6; j++)
                {
                    for (int k = j + 1; k < 6; k++)
                    {
