using Watch = System.Diagnostics.Stopwatch;
using StringBuilder = System.Text.StringBuilder;
namespace Solver
{
    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var a = sc.Integer();
            var b = sc.Integer();
            var k = sc.Integer();
            const long mod = (long)1e9 + 7;
            var dp = new long[5050];
            dp[a]++;
            for (int _ = 0; _ < k; _++)
            {
                var ndp = new long[5050];
                for (int i = 1; i <= n; i++)
                {
                    if (i == b) continue;
                    var d = Math.Abs(b - i) - 1;
                    var l = Math.Max(1, i - d);
                    var r = Math.Min(n, i + d);
                    ndp[l] += dp[i];
                    ndp[i] -= dp[i];
                    ndp[i + 1] += dp[i];
                    ndp[r + 1] -= dp[i];
                }
                for (int i = 1; i <= n; i++)
                    ndp[i] = (ndp[i] + ndp[i - 1]) % mod;
                dp = ndp;
            }
            long ret = 0;
            for (int i = 1; i <= n; i++)
                ret = (ret + dp[i]) % mod;
            IO.Printer.Out.WriteLine((ret + mod) % mod);
        }
        internal IO.StreamScanner sc;
    }

