using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            var tiles = Console.ReadLine().Split();
            var toGetJontsu = Kontsu(tiles);
            var toGetShuntsu = Shuntsu(tiles);
            Console.WriteLine(Math.Min(toGetJontsu, toGetShuntsu));
        }

        static int Shuntsu(string[] tiles)
        {
            var masts = new Dictionary<char, List<string>>();
            foreach (var tile in tiles)
            {
                if(!masts.ContainsKey(tile[1]))
                    masts.Add(tile[1], new List<string>());
                masts[tile[1]].Add(tile);
            }

            var res = 2;
            foreach (var mast in masts)
            {
                if (mast.Value.Count == 2)
                {
                    if (Math.Abs(mast.Value[0][0] - mast.Value[1][0]) == 1 ||
                        Math.Abs(mast.Value[0][0] - mast.Value[1][0]) == 2)
                        res = Math.Min(res, 1);
                }

                if (mast.Value.Count == 3)
                {
                    var ordered = mast.Value.OrderBy(x => x[0] - '1').ToArray();
                    if (ordered[1][0] - ordered[0][0] == 1 && ordered[2][0] - ordered[1][0] == 1)
                        res = Math.Min(res, 0);
                    for (int i = 0; i < 3; i++)
                    {
                        for (int j = 0; j < 3; j++)
                        {
                            if(Math.Abs(ordered[i][0] - ordered[j][0]) == 1 ||
                                Math.Abs(ordered[i][0] - ordered[j][0]) == 2)
                            res = Math.Min(res, 1);    
                        }
                    }

                }
            }

            return res;
        }

        static int Kontsu(string[] tiles)
        {
            var d = new Dictionary<string, int>();
            foreach (var tile in tiles)
            {
                if(!d.ContainsKey(tile))
                    d.Add(tile, 0);
                d[tile]++;
            }

            return 3 - d.Values.Max();
        }
    }
}

