    public class PetrAndACombinationLock
    {
        public static void Main()
        {
            StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            new PetrAndACombinationLock().Solve(Console.In, sw);
            sw.Flush();
        }

        public void Solve(TextReader tr, TextWriter tw)
        {
            var n = int.Parse(tr.ReadLine());
            var a = new int[n];
            for (int i = 0; i < n; i++)
            {
                a[i] = int.Parse(tr.ReadLine());
            }

            tw.WriteLine(Solve(a));
        }


        public string Solve(int[] v)
        {
            int n = v.Length;
            int maxN = (1 << n);

            for (int i = 0; i < maxN; i++)
            {
                int res = 0;
                for (int x = 0; x < n; x++)
                {
                    if ((i & (1 << x)) == 0)
                    {
                        res += v[x];
                    }
                    else
                    {
                        res -= v[x];
                    }
                }
                if (res % 360 == 0)
                {
                    return "YES";
                }
            }

            return "NO";
        }
    }
}

