        int d = Int32.Parse(l3[1]);

        // First, trying by himself:
        int footTime = Math.Abs(x1 - x2) * t2;

        // For the train, he first needs to wait to get on.
        int trainTime = 0;
        if (d * (x1 - p) >= 0)
        {
            trainTime = Math.Abs(x1 - p) * t1;
        }
        else
        {
            int dist = (d > 0) ? 2 * s - x1 - p : x1 + p;
            trainTime = dist * t1;
            d = -d;
        }

        // Then wait to arrive at the destination
        if (d * (x2 - x1) >= 0)
        {
            trainTime += Math.Abs(x2 - x1) * t1;
        }
        else
        {
            int dist = (d > 0) ? 2 * s - x1 - x2 : x1 + x2;
            trainTime += dist * t1;
        }

        Console.WriteLine(Math.Min(trainTime, footTime));
