            return solve(w, m/w);
        }
        else if (rem == 1) {
            return solve(w, ((m-1)/w));
        }
        else if (rem == (w - 1)) {
            return solve(w, ((m + 1) / w));
        }
        else {
            return false;
        }

    }
}

