        {
            int w = Next();
            int m = Next();

            writer.WriteLine(Check(w, m) ? "YES" : "NO");
            writer.Flush();
        }

        private static bool Check(int w, int m, bool first = true)
        {
            if (m == 0)
                return true;
            if (m%w == 0)
                return Check(w, m/w);
            return first && (Check(w, m - 1, false) || Check(w, m + 1, false));
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
