    class Program
    {
        static void Main(string[] args)
        {
            //Console.SetIn(new StreamReader("input.txt"));

            Console.WriteLine(solve_cfindahacks2016A());
        }

        public static string solve_cfindahacks2016A()
        {
            int n = Convert.ToInt32(Console.ReadLine());
            int[] t = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

            for (int i =  0; i < n; i++)
            {
                for (int j = i + 1; j < n; j++)
                {
                    for (int k = j + 1; k < n; k++)
                    {
                        if ((t[i] != t[j] && t[j] != t[k] && t[i] != t[k]) && (Math.Abs(t[i] - t[j]) <= 2 && Math.Abs(t[j] - t[k]) <= 2 && Math.Abs(t[i] - t[k]) <= 2))
                        {
                            return "YES";
                        }
                    }
                }
            }

            return "NO";
        }
        public static void solve_cf495A()
        {
            int[] nd = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            int n = nd[0];
            int d = nd[1];
            int[] x = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

            int cnt = 2;

            int prev = x[0];

            for (int i = 1; i < n; i++)
            {
                int diff = (prev < 0 && x[i] > 0 || prev > 0 && x[i] < 0) ? Math.Abs(prev) + Math.Abs(x[i]) : Math.Abs(Math.Abs(prev) - Math.Abs(x[i]));
                if (diff >= 2 * d && prev + d != x[i] - d)
                {
                    cnt += 2;
                }
                else if (diff - d >= d)
                {
                    cnt++;
                }
                prev = x[i];
            }

            Console.WriteLine(cnt);
        }
