using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace Codeforces
{
    class Program
    {

        public static readonly int MOD = Convert.ToInt32(1e9 + 7);
        public static readonly int oo = Convert.ToInt32(1e9);
        public static readonly long OO = Convert.ToInt64(1e18);

        static void Main(string[] args)
        {
            String[] data = Console.ReadLine().Split(' ');
            int LengthOfWord = int.Parse(data[0]);
            int alphabetSize = int.Parse(data[1]);
            int requiredPalindromLength = int.Parse(data[2]);
            if (requiredPalindromLength > LengthOfWord)
            {
                Console.WriteLine(ModPow(alphabetSize, LengthOfWord));
                return;
            }

            Dsu dsu = new Dsu(LengthOfWord + 1);
            if (requiredPalindromLength % 2 == 0)
            {

                for (int center = 1; center <= LengthOfWord; center++)
                {
                    if (Math.Min(center, LengthOfWord - center) >= requiredPalindromLength / 2)
                    {
                        for (int count = 0; count < requiredPalindromLength / 2; count++)
                        {
                            dsu.Unite(center - count, center + count + 1);
                        }
                    }
                }
            } else
            {
                for (int center = 1; center <= LengthOfWord; center++)
                {
                    if (Math.Min(center - 1, LengthOfWord - center) >= requiredPalindromLength / 2)
                    {
                        dsu.Unite(center, center);
                        for (int count = 1; count <= requiredPalindromLength / 2; count++)
                        {
                            dsu.Unite(center - count, center + count);
                        }
                    }
                }
            }

            long ans = 1;
            for (int vertex = 1; vertex <= LengthOfWord; vertex++)
            {
                if (dsu.Rank[vertex] > 0)
                {
                    ans = (ans * alphabetSize) % MOD;
                }
            }
            Console.WriteLine(ans);
        }

        static long ModPow(long num, long exponent)
        {
            if (exponent == 0) return 1;
            long m = ModPow(num, exponent / 2);
            return exponent % 2 == 0 ? m * m % MOD : m * m % MOD * num % MOD;
        }

        class Dsu
        {
            private int vertices;
            private int connectedComponent;
            private int[] parentOf;
            private int[] rank;

            public int Vertices { get; set; }
            public int ConnectedComponent { get; set; }
            public int[] ParentOf { get; set; }
            public int[] Rank { get; set; }

            public Dsu(int vertices)
            {
                Vertices = vertices;
                ConnectedComponent = vertices;
                ParentOf = Enumerable.Range(0, vertices).ToArray();
                Rank = Enumerable.Range(0, vertices).Select(v => v = 1).ToArray();
            }

            public bool IsConnected(int from, int to)
            {
                return GetAncestor(from) == GetAncestor(to);
            }

            public int GetAncestor(int descended)
            {
                while (descended != ParentOf[descended]) descended = ParentOf[descended];
                return descended;
            }

            public void Unite(int from, int to)
            {
                int ancestorOfFrom = GetAncestor(from);
                int ancestorOfTo = GetAncestor(to);
                if (ancestorOfFrom == ancestorOfTo) return;
                connectedComponent--;
                if (Rank[ancestorOfFrom] > Rank[ancestorOfTo])
                {
                    ParentOf[ancestorOfTo] = ParentOf[ancestorOfFrom];
                    Rank[ancestorOfFrom] += Rank[ancestorOfTo];
                    Rank[ancestorOfTo] = 0;
                } else
                {
                    ParentOf[ancestorOfFrom] = ParentOf[ancestorOfTo];
                    Rank[ancestorOfTo] += Rank[ancestorOfFrom];
                    Rank[ancestorOfFrom] = 0;
                }
            }


        }

    }

}

