    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        string[] str = Console.ReadLine().Split(' ');
        long M = int.Parse(str[0]);
        long B = int.Parse(str[1]);
        long count = 0;
        for(long i=0;i<=B;i++){
            long j = (B-i)*M;
            long S = (j+1)*i*(i+1)/2 + (i+1)*j*(j+1)/2;
            count = Math.Max(count,S);
        }
        sb.Append(count+"\n");
    }
}

