        public static bool IsSquare(string number) {

            return Math.Pow((int)Math.Sqrt(int.Parse(number)), 2) == int.Parse(number);
        }

        public static int[] Fill(int[] array, int value) {

            for(int i = 0; i < array.Length; i++) {

                array[i] = value;
            }

            return array;
        }

        public static string GetNumber(string number, int[] usage) {

            var result = new StringBuilder();

            for(int i = 0; i < usage.Length; i++) {

                if(usage[i] == 1) {

                    result.Append(number[i]);
                }
            }

            return result.ToString();
        }

        public static void MinStep(int counter, int total, string number, int[] usage, ref int min) {

            string newNum = GetNumber(number, usage);

            if(newNum != string.Empty && newNum[0] != '0' && IsSquare(GetNumber(number, usage))) {

                min = min == -1 ? total : Math.Min(min, total);

                return;
            }

            if(counter == number.Length) {

                return;
            }

            int[] newUsage = usage.ToList().ToArray();
            newUsage[counter] = 0;
            MinStep(counter + 1, total + 1, number, newUsage, ref min);
            MinStep(counter + 1, total, number, usage, ref min);
        }
    }
