            problems[N] = C;
            if (N == 1)
                problems[1] = Math.Min(D, C);
            problems[0] = 0;
            for (int i = 2; i < problems.Length; i++)
            {
                if (i - N >= 0)
                {
                    problems[i] = Math.Min(problems[i - N] + C, (problems[i - 1] + D));
                }
                else
                {
                    problems[i] = problems[i - 1] + D;
                }
            }
            int P = N * M - K;
            int min = int.MaxValue;
            if (P < 0)
                Console.Write(0);
            else
            {
                for (int i = P; i < problems.Length; i++)
                {
                    min = Math.Min(min, problems[i]);
                }
                Console.Write(min);
