class Pie{
   Dictionary<int,int>winSize;

   int getSum(int[]arr,int start){
      int sum = 0;
      int len = arr.Length;
      for(int i=start;i<len;i++){
         sum += arr[i];
      }
      return sum;
   }

   int getWinSize(int[]arr, int ind){
      int len = arr.Length;
      int retV = 0;
      int retSum = getSum(arr,ind+1);
      if(ind==(len-1)){
         retV = arr[ind];
      }else if(ind==(len-2)){
         retV = Math.Max(arr[len-1],arr[len-2]);
      }else{
      //dynamic programming 
         int remW = winSize[ind+1];
	 int s1 = arr[ind]+(retSum-remW);
	 int s2 = remW;
	 retV = Math.Max(s1,s2);
      }
      return retV;
   }

   public int[]getSizes(int[]slices){
      winSize = new Dictionary<int,int>();
      int nSlices = slices.Length;
      int totalSz = getSum(slices,0);
      for(int i=nSlices-1;i>=0;i--){
         int sz = getWinSize(slices,i);
	 winSize[i] = sz;
      }
      int bs = winSize[0];
      int az = totalSz-bs;
      int[]retArr = new int[]{az,bs};
      return retArr;
   }
