                {
                    newseq.Add(item + (char)('0' + j));
                }
            }
            seq = newseq;
        }
        int res = 0;
        Dictionary<string, int> freqs = new Dictionary<string, int>();
        foreach (var item in seq)
        {
            HashSet<string> set = new HashSet<string>() { "" };
            for (int i = 0; i < (1 << item.Length); i++)
            {
                string s = "";
                for (int j = 0; j < item.Length; j++)
                {
                    if ((i >> j & 1) == 1) s += item[j];
