    }
    static string ReadWord()
    {
        var str = string.Empty;
        while (true)
        {
            var chr = ReadChar();
            if (chr != ' ')
            {
                str += chr;
                break;
            }
        }//skip empty start
        while (true)
        {
            var chr = ReadChar();
            if (chr == ' ' || chr == '\n') break;
            str += chr;
        }
        return str;
    }
    static int ReadInt()
    {
        return int.Parse(ReadWord());
    }
    static long ReadLong()
    {
        return long.Parse(ReadWord());
    }
    #endregion

    static void Main(string[] args)
    {
        var n = ReadLong(); var m = ReadLong();

        long maxCom = GetMaxComPosses(n, m);

        long minCom = GetMinComPosses(n, m);

        Console.WriteLine($"{minCom} {maxCom}");

    }

    static long GetMinComPosses(long n, long m)
    {
        var lessTeamSize = n / m;
        var bigTeamSize = lessTeamSize + 1;

        var lessTeamCount = m - (n % m);
        var bigTeamCount = m - lessTeamCount;

        var minCom = (lessTeamCount * SumUntil(lessTeamSize)) + (bigTeamCount * SumUntil(bigTeamSize));
        return minCom;
    }

    static long GetMaxComPosses(long n, long m)
    {
        var bigTeam = n - m + 1; //all of other team will have one player, but this wil have the rest
        var maxCom = SumUntil(bigTeam);
        return maxCom;
    }

    static long SumUntil(long n)
    {
        return (n * (n - 1)) / 2;
    }
}

