{
    public Scanner sc;
    public void Solve()
    {
        long N, M;
        sc.Make(out N, out M);
        var min = Max(0, N - 2 * M);
        int i;var now = 0L;
        if (M == 0) Fail($"{min} {N}");
        for (i = 0; i < N; i++)
        {
            now += i;
            if (now >= M) break;
        }
        Console.WriteLine($"{min} {N-i-1}");
    }
}

