    {
        int z = 1;
        int ans = 0;
        for (int i = 0; i < t.Length; i++) {
            if(t[i] >= s)
                return false;
            ans += t[i] * z;
            z *= s;
        }
        if(type)
            if(ans >= 24)
                return false;
            else 
                return true;
        else
            if(ans >= 60)
                return false;
            else 
                return true;
    }
