using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
namespace ConsoleApp2
{
	class Program
	{
		static int dgt(char c)
		{
			if ('0' <= c && c <= '9')
			{
				return c - '0';
			}
			return 10 + c - 'A';
		}


		static int to_num(string s, int n)
		{
			int num = 0;
			int k = 1;
			for (int i = 1; i <= s.Length; i++)
			{
				num += dgt(s[s.Length - i]) * k;
				k *= n;
			}
			return num;
		}
		static bool fit(string s1, string s2, int n)
		{
			return to_num(s1, n) < 24 && to_num(s2, n) < 60;
		}

		static int get_min(string s)
		{
			int min = 0;
			for (int i = 0; i < s.Length; i++)
			{
				if (dgt(s[i]) > min)
				{
					min = dgt(s[i]);
				}
			}
			return min;
		}

		static void Main(string[] args)
		{
			string input = Console.ReadLine();
			var times = input.Split(':');
			int min = Math.Max(get_min(times[0]), get_min(times[1])) + 1;

			if (fit(times[0], times[1], 60))
			{
				Console.WriteLine(-1);
			}
			else
			{
				int i;
				for (i = min; i <= 59; i++)
				{
					if (!fit(times[0], times[1], i))
						break;
					Console.Write("{0} ", i);
				}
				if (i == min)
					Console.WriteLine(0);
			}
		}
	}
}

﻿using System;
using System.IO;
using System.Text;

namespace Symmetric_and_Transitive
{
    internal class Program
    {
        private const int mod = 1000000007;
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static readonly int[,] C = new int[4000,4000];
        private static readonly long[] a = new long[4001];

        private static long GetC(int n, int k)
        {
            if (n < k)
            {
                int c = k;
                k = n;
                n = c;
            }
            if (k == 0 || k == n)
                return 1;

            if (C[n, k] != 0)
                return C[n, k];

            return C[n, k] = (int)((GetC(n - 1, k - 1) + GetC(n - 1, k))%mod);
        }

        private static long A(int n)
        {
            if (n == 1)
                return 1;

            if (a[n] == 0)
            {
                //a(n+1) = 1 + sum { j=1, n, (1+binomial(n, j))*a(j)
                a[n] = 1;
                for (int j = 1; j < n; j++)
                {
                    a[n] = (a[n] + (1 + GetC(n - 1, j))*A(j))%mod;
                }
            }

            return a[n];
        }

        private static void Main(string[] args)
        {
            int n = Next();
            writer.WriteLine(A(n)%mod);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

