            int.TryParse(str, out n);
            int [][] C = new int[n + 1][];

            C[0] = new int[1];
            C[0][0] = 1;
            int[] prewrow =  C[1] = new int[2];
            prewrow[0] = 1;
            prewrow[1] = 1;
            for (int i = 2; i <= n; i++)
            {
                int[] row = C[i] = new int[i+1];
                row[i] = 1;
                row[0] = 1;
                for(int j = 1; j <i; j++)
                {
                    row[j] = (prewrow[j] + prewrow[j - 1])%MOD;
                }
                prewrow = row;
            }

            long[][] E = new long[n + 1][];
            long[] prow = E[0] = new long[1];
            prow[0] = 1;
            for (int i = 1; i <= n; i++)
            {
                long[] row = E[i] = new long[i + 1];
                row[i] = 1;
                row[0] = 0;
                for (int j = 1; j < i; j++)
                {
                    row[j] = (prow[j] * j + prow[j - 1]) % MOD;
                }
                prow = row;
            }

            long[] total = new long[n + 1];
            for(int i = 0; i <= n; i++)
            {
                long sum = 0;
                long[] row = E[i];
                 for (int j = 0; j <= i; j++)
                 {
                     sum = (sum + row[j]) %MOD;
                 }
                total[i] = sum;
            }

            long result = 0;
            for (int i = 1; i <= n; i++ )
            {
                result = (result + C[n][i] * total[n - i]) % MOD;
            }

            Console.WriteLine(result);
        }
