    {
        static int GCD(int a, int b)
        {
            if (b == 0) return a;
            return GCD(b, a % b);
        }
        static int LCM(int a, int b)
        {
            return a * b / GCD(a, b);
        }

        static void Main(string[] args)
        {
            string[] s = Console.ReadLine().Split();
            int x = int.Parse(s[0]);
            int y = int.Parse(s[1]);
            int a = int.Parse(s[2]);
            int b = int.Parse(s[3]);

            int lcm = LCM(x, y);
            int f = -1, l = -1;

            f = (a / lcm) * lcm;
            l = (b / lcm) * lcm;

            if (f < a) f += lcm;
            int cnt = 0;
            if (f <= l)
                cnt = (l - f) / lcm + 1;

            Console.WriteLine(cnt);
        }
    }
}

