using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        string input = Console.ReadLine();
        if (input.Length < 3 || !input.Contains('@')) { Console.WriteLine("NO"); return; };

        string[] splited = input.Split('@','/');
        if (splited.Length < 2 || splited.Length > 3) { Console.WriteLine("NO"); return; }
        string username = splited[0], hostname = splited[1];
        string resource = "***";
        if(splited.Length == 3)
        {
            resource = splited[2];
        }

        bool correct = CheckCorrectSymbols(username,hostname,resource);
        if (correct) Console.WriteLine("YES");
        else Console.WriteLine("NO");


    }
    static bool CheckCorrectSymbols(string username, string hostname, string resource)
    {
        string EngABC = "_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

        if (username.Length < 1 || username.Length > 16) return false;
        for (int i = 0; i < username.Length; ++i)
        {
            if (!EngABC.Contains(username[i])) return false;
        }

        if (hostname.Length < 1 || hostname.Length > 32) return false;
        for (int i = 0; i < hostname.Length; ++i)
        {
            if (hostname[i] != '.' && !EngABC.Contains(hostname[i])) return false;
        }

        string[] words = hostname.Split('.');
        if (words.Length < 1) return false;
        for (int i = 0; i < words.Length; ++i)
        {
            if (words[i].Length < 1 || words[i].Length > 16) return false;
        }

        if (resource != "***")
        {
            if (resource.Length < 1 || resource.Length > 16) return false;
            for (int i = 0; i < resource.Length; ++i)
            {
                if (!EngABC.Contains(resource[i])) return false;
            }
        }

        return true;
    }

}

