    class Program
    {
        private static int CardIndex(string card)
        {
            var num = card[1] - '1';
            int color = 0;
            if (card[0] == 'R')
                color = 0;
            if (card[0] == 'G')
                color = 1;
            if (card[0] == 'B')
                color = 2;
            if (card[0] == 'Y')
                color = 3;
            if (card[0] == 'W')
                color = 4;

            var index = (1 << num) | (1 << (color + 5));
            return index;
        }

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            var cards = Console.ReadLine().
                Split().
                Distinct().
                Select(x => CardIndex(x)).
                ToList();

            var minSuggest = int.MaxValue;

            var maxSuggest = 1 << 10;
            for (int suggest = 0; suggest < maxSuggest; suggest++)
            {
                var distinctCard = cards.Select(x => x & suggest).Distinct().Count();
                if (distinctCard == cards.Count)
                {
                    var suggestSize = SparseBitcount(suggest);
                    if (suggestSize < minSuggest)
                    {
                        minSuggest = suggestSize;
                    }
                }
            }

            Console.WriteLine(minSuggest);
        }

        static int SparseBitcount(int n)
        {
            int count = 0;
            while (n != 0)
            {
                count++;
                n &= (n - 1);
            }
            return count;
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

public class Test
{
    [Flags]
    enum Card
    {
        R = 1 << 0,
        G = 1 << 1,
        B = 1 << 2,
        Y = 1 << 3,
        W = 1 << 4,
        One = 1 << 5,
        Two = 1 << 6,
        Three = 1 << 7,
        Four = 1 << 8,
        Five = 1 << 9,
    }

    public static void Main()
    {
        int result = Solve();
        Console.WriteLine(result);
    }

    static int Solve()
    {

        // Don't care for n
        Console.ReadLine();

        var input = Console.ReadLine().Split(' ').Distinct().Select(x => ParseCard(x)).ToArray();
        if (input.Length == 1)
        {
            return 0;
        }
        List<Card> diffs = new List<Card>(input.Length * input.Length);
        for(int i = 0; i < input.Length - 1; i++)
        {
            for(int j = i + 1; j < input.Length; j++)
            {
                Card diff = Diff(input[i], input[j]);
                diffs.Add(diff);
            }
        }

        var subsets = Enumerable.Range(0, 1023).Select(x => (Card)x);
        int min = 11;
        foreach(var subset in subsets)
        {
            if(diffs.All(x => CanDistinguish(subset, x)))
            {
                // This is an answer
                min = Math.Min(min, CountBits((int)subset));
            }
        }

        return min;
    }

    static int CountBits(int num)
    {
        int res = 0;
        while(num > 0)
        {
            if ((num & 1) == 1) res++;
            num >>= 1;
        }
        return res;
    }

    static bool CanDistinguish(Card subset, Card diff)
    {
        return (subset & diff) != 0;
    }

    static Card Diff(Card f, Card s)
    {
        return f ^ s;
    }

    static Card ParseCard(string input)
    {
        Card colour = (Card)Enum.Parse(typeof(Card), input[0].ToString());
        Card num = Card.One;
        switch (input[1])
        {
            case '1': num = Card.One;break;
            case '2': num = Card.Two;break;
            case '3': num = Card.Three;break;
            case '4': num = Card.Four;break;
            case '5': num = Card.Five;break;
        }
        return colour | num;
    }
}

