namespace CodeForces800
{
    internal static class Program
    {
        public static long prime = 1000000007;
        public static long[] bprime = new long[2];
        public static Dictionary<long, long> invar = new Dictionary<long, long>();
        public static long[] fact = new long[1];
        public static void Main()
        {
            var cur = prime - 2;
            var list = new List<long>();
            while (cur != 0)
            {
                list.Add(cur % 2);
                cur = cur / 2;
            }
            bprime = list.ToArray();
            var str = Console.ReadLine().Split(' ').Select(x => Int32.Parse(x)).ToList();
            var n = str[0];
            var k = str[1];
            long res = 0;
            fact = new long[n + 1];
            fact[0] = 1;
            for (var i = 1; i < n + 1; i++)
            {
                fact[i] = (long)((long)fact[i - 1] * i) % prime;
            }
            for (var i = 0; i <= Math.Min(n,k); i++)
            {
                res += C(n, i);
                res = res % prime;
            }
            Console.WriteLine(res);
        }
        private static long C(long n, long k)
        {
            if (n >= k)
            {
                long res = fact[n];
                res = res * calcInv(fact[n - k]);
                res = res % prime;
                res = res * calcInv(fact[k]);
                res = res % prime;
                return (long)res;
            }
            else return 0;
        }

        public static long calcInv(long n)
        {
            if (invar.TryGetValue(n, out var invn))
                return invn;
            else
            {
                var ost = new long[bprime.Length];
                ost[0] = n;
                for (var i = 1; i < bprime.Length; i++)
                {
                    ost[i] = (ost[i - 1] * ost[i - 1]) % prime;
                }
                long inv = 1;
                for (var i = 0; i < bprime.Length; i++)
                {
                    inv *= (bprime[i] == 1) ? ost[i] : 1;
                    inv = inv % prime;
                }
                invar.Add(n, (long)inv);

                return (long)inv;
            }
        }
    }
}

