namespace C1
{
    static class RW
    {
        public static ulong RIntStdin()
        {
            // Read ONE integer, infinite input
            ulong res = 0;
            int symb = Console.Read();
            while ((symb < '0') || (symb > '9'))
            {
                symb = Console.Read();
            }
            while ((symb >= '0') && (symb <= '9'))
            {
                res = 10 * res + (ulong)symb - '0';
                symb = Console.Read();
            }
            return res;
        }
    }
    class Solution
    {
        ulong n;
        uint s;
        Dictionary<ulong, uint> d;
        public Solution()
        {
            n = RW.RIntStdin();
            d = new Dictionary<ulong, uint>();
        }
        public void EvalN(ulong num, uint steps)
        {
            int[] digits = new int[10];
            ulong copy = num;
            ulong novy_key;
            uint prev_steps;
            while (copy > 0)
            {
                digits[copy % 10]++;
                copy /= 10;
            }
            for (int i = 0; i < digits.Length; i++)
            {
                if (digits[i] > 0)
                {
                    novy_key = n - (ulong)i;
                    if (!d.ContainsKey(novy_key))
                    {
                        d.Add(novy_key, steps + 1);
                    }
                    else
                    {
                        d.TryGetValue(novy_key, out prev_steps);
                        if (prev_steps > steps + 1)
                        {
                            d[novy_key] = steps + 1;
                        }
                    }
                }
            }
        }
        public void Solve()
        {
            d.Add(n, 0);
            while (n > 0)
            {
                if (d.ContainsKey(n))
                {
                    d.TryGetValue(n, out s);
                    EvalN(n, s);
                    d.Remove(n);
                }
                n--;
            }
            uint r;  d.TryGetValue(0, out r); // result
            Console.WriteLine(r);
        }
    }
    class Program
    {
        static void Main(string[] args)
        {
            Solution s = new Solution();
            s.Solve();
        }
    }
}

