class Solver
{
    public void Solve(Scanner sc)
    {
        int N, M;
        sc.Make(out N, out M);
        int[] res = new int[N],ex=new int[N];
        int[] ct = new int[M],ts=new int[M];

        var pq = new PriorityQueue<Pi>((a,b)=>a.v1-b.v1);
        for(var i = 0; i < M; i++)
        {
            int s, t, c;
            sc.Make(out s, out t, out c);
            s--;t--;
            res[t] = M+1;
            ts[i] = t;
            ex[t] = i;
            pq.Push(new Pi(s,i));
            ct[i] = c;
        }
        var f = new PriorityQueue<Pair<int,int,int>>((a, b) => a.v1 - b.v1);
        var use = new bool[M];
        for(var i = 0; i < N; i++)
        {
            while (pq.Any() && pq.Top.v1 == i)
                f.Push(new Pair<int,int,int>(ts[pq.Top.v2], ct[pq.Top.v2],pq.Pop().v2));
            if (res[i] == M+1)
            {
                if (!use[ex[i]]) Fail(-1);
                continue;
            }
            if (!f.Any()) continue;
            var p = f.Pop();
            res[i] = p.v3+1;
            p.v2--;
            if (p.v2 != 0) f.Push(p);
            else use[p.v3] = true;
        }

        Console.WriteLine(string.Join(" ", res));

    }
}

public class PriorityQueue<T>
{
    private List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
}
