    public class DivideCandies
    {
        public static void Main()
        {
            Solve(Console.In, Console.Out);
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            var tokens = tr.ReadLine().Split();
            var n = long.Parse(tokens[0]);
            var m = long.Parse(tokens[1]);

            var t = new long[m, m];

            var res = 0L;
            for (long i = 0; i < m; i++)
            {
                for (long j = 0; j < m; j++)
                {
                    t[i, j] = ((i+1) * (i+1) + (j+1) * (j+1)) % m;
                    if (t[i, j] == 0)
                        res++;
                }
            }

            var p = n / m;
            res *= p * p;

            var r = n % m;

            var res2 = 0L;
            for (long i = 0; i < r; i++)
            {
                for (long j = 0; j < m; j++)
                {
                    if (t[i, j] == 0)
                        res2++;
                }
            }
            res += res2 * p * 2;

            for (long i = 0; i < r; i++)
            {
                for (long j = 0; j < r; j++)
                {
                    if (t[i, j] == 0)
                        res++;
                }
            }

            tw.WriteLine(res);
        }
    }
}

