            int first = 0;
            int last = 1;
            long d = 10;
            do
            {
                for (int i = first; i <= last; i++)
                {
                    lucky.Add(d*4 + lucky[i]);
                    lucky.Add(d*7 + lucky[i]);
                }
                d *= 10;
                first = last + 1;
                last = lucky.Count - 1;
            } while (lucky[last] < r);

            long sum = 0;

            lucky.Sort();

            int il = lucky.BinarySearch(l);
            if (il < 0)
