namespace Codeforces
{
	class Program
	{
		static void Main(string[] args) 
		{
			string input1 = Console.ReadLine();
			//string input2 = Console.ReadLine();

			//string input3 = Console.ReadLine();
			//string input4 = Console.ReadLine();

			var inputs1 = input1.Split(new[] {' ', '}', '{', ','}, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();
			//var inputs2 = input2.Split(new[] { ' ', '}', '{', ',' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToList();
			//var inputs3 = input3.Split(new[] { ' ', '}', '{', ',' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();
			//var inputs4 = input4.Split(new[] { ' ', '}', '{', ',' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();

			long l = inputs1[0];
			long r = inputs1[1];

			long end2 = (long)Math.Log(r, 2) + 1;

			var set = new HashSet<long>();
			for (long i = 0; i < end2 + 1; i++) 
			{
				long start3 = (long)Math.Log(l / Math.Pow(2, i), 3);
				if (start3 < 0) 
				{
					start3 = 0;
				}

				long end3 = (long)Math.Log(r / Math.Pow(2, i), 3) + 1;
				if (end3 < 0)
				{
					end3 = 0;
				}

				for (long j = start3; j < end3 + 1; j++) 
				{
					long current = (long)(Math.Pow(2, i) * Math.Pow(3, j));
					if (current < l || current > r) 
					{
						continue;
					}

					set.Add(current);
				}
			}

			Console.WriteLine(set.Count);
		}

		public class Team
		{
			public string Name { get; set; }

			public int Points { get; set; }

			public int GoalsFor { get; set; }

			public int GoalsAgainst { get; set; }
		}

		static long Factorial(long a) 
		{
			return a > 1 ? a * Factorial(a - 1) : 1;
		}
	}
