    internal class MR18R2C : ProblemBase
    {
        public override IEnumerable<string> GetResults()
        {
            var ints = this.ReadLongArray();
            var la = ints[0];
            var ra = ints[1];
            var ta = ints[2];

            ints = this.ReadLongArray();
            var lb = ints[0];
            var rb = ints[1];
            var tb = ints[2];

            var l = Math.Min(la, lb);

            la -= l;
            ra -= l;
            lb -= l;
            rb -= l;

            long result = 0;

            if (ta == tb)
            {
                result = GetLength(la, ra, lb, rb);
            }
            else
            {
                var t = Math.Max(ta, tb);
                var delta = t - Math.Min(ta, tb);

                var d = (int)this.Gcd(delta, t);
                if (d == 1)
                {
                    result = Math.Min(ra - la + 1, rb - lb + 1);
                }
                else // cycles
                {
                    var aDiff = (la / d) * d;
                    la -= aDiff;
                    ra -= aDiff;

                    var bDiff = (lb / d) * d;
                    lb -= bDiff;
                    rb -= bDiff;

                    var deltas = new[] {-2, -1, 0, 1, 2};

                    for (int i = 0; i < deltas.Length; i++)
                    {
                        long current = GetLength(la, ra, lb + deltas[i] * d, rb + deltas[i] * d);
                        if (current >= result)
                        {
                            result = current;
                        }

                    }
                }
            }

            yield return result.ToString();
        }

        private static long GetLength(long la, long ra, long lb, long rb)
        {
            var left = Math.Max(la, lb);
            var right = Math.Min(ra, rb);
            if (right >= left)
            {
                return right - left + 1;
            }

            return 0;
        }

        private long Gcd(long a, long b)
        {
            var first = a;
            var second = b;

            while (second != 0)
            {
                var temp = first % second;
                first = second;
                second = temp;
            }
            return first;
        }

    }

