    long gcda(long a, long b,out long x,out long y)
    {
        if (a == 0)
        {
            x = 0; y = 1;
            return b;
        }
        long x1, y1;
        long d = gcda(b % a, a,out x1,out y1);
        x = y1 - (b / a) * x1;
        y = x1;
        return d;
    }

    bool find_any_solution(long a, long b, long c, out long x0, out long y0, out long g)
    {
        g = gcda(Math.Abs(a), Math.Abs(b), out x0, out y0);
        if (c % g != 0)
            return false;
        change(a,b, c, g, ref x0, ref y0);
        return true;
    }

    void change(long a, long b, long c, long g, ref long x0, ref long y0)
    {
        x0 *= c / g;
        y0 *= c / g;
        if (a < 0) x0 *= -1;
        if (b < 0) y0 *= -1;
    }

        //////////////////////////////////////////////////
        void Solution()
    {
        var la = rl;
        var ra = rl;
        var ta = rl;
        var lb = rl;
        var rb = rl;
        var tb = rl;

        //kb*tb=ka*ta+la-lb
        //tb*kb-ta*ka=la-lb
        var c = la - lb;
        //long x = 0;// kb;
        var a = -ta;
        //long y = 0;// ka;
        var b = tb;

        if (c < 0)
        {
            c *= -1;
            a *= -1;
            b *= -1;
        }

        if (c == 0)
        {
            wln(Math.Min(rb, ra) - la + 1);
            return;
        }

        var flag = find_any_solution(a, b, c, out long x, out long y, out long g);
        if (flag)
        {
            wln(Math.Min(rb + y * tb - x * ta, ra) - la + 1);
        }
        else
        {

            var c1 = (c / g) * g;
            var c2 = c1 + g;
            var c0 = c1 - g;
            find_any_solution(a, b, c1, out long x1, out long y1, out long g1);
            find_any_solution(a, b, c2, out long x2, out long y2, out long g2);
            if (c0 < 0)
            {
                c0 *= -1;
                a *= -1;
                b *= -1;
            }
            find_any_solution(a, b, c0, out long x0, out long y0, out long g0);


            var res1 = Math.Min((rb + y1 * tb - x1 * ta), ra) - Math.Max(la, (lb + y1 * tb - x1 * ta)) + 1;
            var res2 = Math.Min((rb + y2 * tb - x2 * ta), ra) - Math.Max(la, (lb + y2 * tb - x2 * ta)) + 1;
            var res0 = Math.Min((rb + y0 * tb - x0 * ta), ra) - Math.Max(la, (lb + y0 * tb - x0 * ta)) + 1;
            wln(Math.Max(0, Math.Max(res0, Math.Max(res1, res2))));
        }
    }

