        }

        public static long Binomial(long n, long k)
        {
            long r = 1;
            long d;
            if (k > n) return 0;
            for (d = 1; d <= k; d++)
            {
                r *= n--;
                r /= d;
            }
            return r;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            int[] bounds = Console.ReadLine().ToArrayOf<int>(' ');
            int n = bounds[0];
            int x = Math.Min(bounds[1], bounds[2]);
            int y = Math.Max(bounds[1], bounds[2]);

            Node head = new Node(1);
            Node current = head;
            for (int i = 2; i <= n; i++)
            {
                Node next = new Node(i);
                next.Previous = current;
                current.Next = next;
                current = next;
            }

            int round = 1;
            bool stillPossible = true;
            int finalRound = (int)Math.Log(n, 2);
            while (round <= finalRound)
            {
                Node one = head;
                Node two = head.Next;
                while (one != null)
                {
                    int i = one.Value;
                    int j = two.Value;

                    if (i == x && j == y)
                    {
                        stillPossible = false;
                        break;
                    }
                    else
                    {
                        if (i == x || i == y)
                        {
                            one.Next = two.Next;

                            if (two.Next == null)
                            {
                                break;
                            }

                            two.Next.Previous = one;
                            two = one.Next;

                            one = one.Next;
                            two = two.Next;
                        }
                        else
                        {
                            if (one.Previous == null)
                            {
                                head = two;
                                two.Previous = null;
                                one = head;
                                two = one.Next;

                                one = one.Next;
                                two = two.Next;
                            }
                            else
                            {
                                one.Previous.Next = two;
                                two.Previous = one.Previous;
                                one = two;
                                two = one.Next;

                                if (two == null)
                                {
                                    break;
                                }

                                one = one.Next;
                                two = two.Next;
                            }
                        }
                    }
                }

                if (!stillPossible)
                {
                    break;
                }

                round++;
            }

            Console.WriteLine(round == finalRound ? "Final!" : round.ToString());
            //Console.ReadKey();
        }        
    }

    class Node
    {
        public int Value { get; set; }
        public Node Previous { get; set; }
        public Node Next { get; set; }

        public Node(int value)
        {
            Value = value;
        }
    }
}

