namespace CompLib
{
     public static class Algorithm
     {
         public static long LowerBound(long[] arr, long low, long high, long val)
         {
             if (low > high)
             {
                 return low;
             }

             long mid = low + (high - low) / 2;

             if (val <= arr[mid])
             {
                 return LowerBound(arr, low, mid - 1, val);
             }

             return LowerBound(arr, mid + 1, high, val);
         }

         public static long UpperBound(long[] arr, long low, long high, long val)
         {
             if (low > high || low == arr.Length)
             {
                 return low;
             }

             long mid = low + (high - low) / 2;

             if (val >= arr[mid])
             {
                 return UpperBound(arr, mid + 1, high, val);
             }

             return UpperBound(arr, low, mid - 1, val);
         }
     }






    public static class EMath
    {
        public static int Mod(int a, int m)
        {
            return (a % m + m) % m;
        }

        public static long Gcd(long a, long b)
        {
            long r;
            while (b != 0)
            {
                r = a % b;
                a = b;
                b = r;
            }

            return a;
        }

        public static long Lcm(long a, long b)
        {
            if (a > b)
            {
                return (a / Gcd(a, b)) * b;
            }

            return (b / Gcd(a, b)) * a;
        }
    }
}

