class Solution{
	 static void Main(string[] args) {
             var tmp = Console.ReadLine().Split(' ');
            long d = long.Parse(tmp[0]);
            long k = long.Parse(tmp[1]);
            long a = long.Parse(tmp[2]);
            long b = long.Parse(tmp[3]);
            long t = long.Parse(tmp[4]);

            if (d <= k) {
                Console.WriteLine(a * d);
                return;
            }

            long ans = k * a + (d - k) * b;
            long low = 0, high = 1000000000000;
            while (high - low > 1) {
                long mid = (high + low) / 2;

                long center = Calc(d, k, a, b, t, mid);
                long center1 = Calc(d, k, a, b, t, mid + 1);
                long center_1 = Calc(d, k, a, b, t, mid - 1);

                if (center != -1) ans = Math.Min(ans, center);
                if (center1 != -1) ans = Math.Min(ans, center1);
                if (center_1 != -1) ans = Math.Min(ans, center_1);

                if (center1 == -1) {
                    high = mid;
                } else {
                    if (center1 > center) high = mid; else low = mid;
                }
            }
            Console.WriteLine(ans);
	 }
     private static long Calc(long d, long k, long a, long b, long t, long mid) {
            long withCar = k * mid;

            long remaining = d - withCar;
            if (remaining < 0) {
                return -1;
            }

            long time = k * mid * a + Math.Max(0, (mid - 1)) * t;
             if (remaining <= k) return Math.Min(t+time + remaining * a, time + remaining * b);
            return time + remaining * b;
        }
}

