                    dp[i, 0] += dp[i - j, 0]%mod;
                    dp[i, 0] %= mod;
                    if (j >= d)
                    {
                        dp[i, 1] += dp[i - j, 0]%mod;
                        dp[i, 1] %= mod;
                    }
                    else
                    {
                        dp[i, 1] += dp[i - j, 1] % mod;
                        dp[i, 1] %= mod;
