namespace Codeforces_247_2
{
    class Program
    {
        static long[,] cache;
        static long Count(int n, int k)
        {
            long ret = cache[n, k];
            if (ret < 0)
            {
                ret = 0;
                for (int i = 1; i <= k; ++i) {
                    if (n > i) {
                        ret = (ret + Count(n - i, k)) % 1000000007;
                    }
                    else if (n == i) {
                        ret = ret + 1;
                    }
                }
                cache[n, k] = ret;
            }
            return ret;
        }
        static void Main(string[] args)
        {
            string[] s = Console.ReadLine().Split(' ');
            int n = int.Parse(s[0]);
            int k = int.Parse(s[1]);
            int d = int.Parse(s[2]);
            cache = new long[n + 1, k + 1];
            for (int i = 0; i <= n; ++i) for (int j = 0; j <= k; ++j) cache[i, j] = -1;
            Console.WriteLine((1000000007 + Count(n, k) - Count(n, d - 1)) % 1000000007);
        }
    }
}

