namespace k_Tree
{
    internal class Program
    {
        private const long TTT = 1000000007;

        private static readonly StreamReader reader =
            new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);

        private static readonly StreamWriter writer =
            new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            string[] ss = reader.ReadLine().Split(' ');
            int n = int.Parse(ss[0]);
            int k = int.Parse(ss[1]);
            int d = int.Parse(ss[2]);

            var kgood = new long[n + 1];
            var kbad = new long[n + 1];
            long sum = 0;
            for (int i = 1; i <= k && i <= n; i++)
            {
                if (i >= d)
                {
                    kgood[i] = 1;
                }
                else
                    kbad[i] = 1;
            }
            sum = (sum + kgood[n])%TTT;

            for (int j = 1; j <= n; j++)
            {
                var kgood1 = new long[n + 1];
                var kbad1 = new long[n + 1];

                for (int i = 1; i <= n; i++)
                {
                    for (int l = 1; l <= k; l++)
                    {
                        if (i + l > n)
                            break;

                        kgood1[l + i] += kgood[i];
                        if (l >= d)
                        {
                            kgood1[l + i] += kbad[i];
                        }
                        else
                        {
                            kbad1[l + i] += kbad[i];
                        }
                    }
                }
                sum = (sum + kgood1[n])%TTT;
                for (int i = 1; i <= n; i++)
                {
                    kbad[i] = kbad1[i]%TTT;
                    kgood[i] = kgood1[i]%TTT;
                }
            }

            writer.WriteLine("{0}", sum);
            writer.Flush();
        }
    }
}

