namespace A.Theatre_Square
{
    class Program
    {


        static void Main(string[] args)
        {
            int[,] step = { { 2, 2 }, { 1, 12 }, { 0, 22 } };
            string[] data = Console.ReadLine().Split(' ');
            int n = Int32.Parse(data[0]);
            int m = Int32.Parse(data[1]);
            bool isEnd = false;
            bool turn = false;
            while (!isEnd)
            {
                if (!turn)
                {
                    for (int i = 0; i < 3; i++)
                    {

                        if (n >= step[i, 0] && m >= step[i, 1])
                        {
                            n -= step[i, 0];
                            m -= step[i, 1];
                            goto next;
                        }

                    }
                    isEnd = true;
                }
                else
                {
                    for (int i = 2; i >=0; i--)
                    {

                        if (n >= step[i, 0] && m >= step[i, 1])
                        {
                            n -= step[i, 0];
                            m -= step[i, 1];
                            goto next;
                        }

                    }
                    isEnd = true;
                }
            next: turn = !turn;
            }

            if (turn)
            {
                Console.WriteLine("Hanako");
            }
            else
            {
                Console.WriteLine("Ciel");
            }
            Console.ReadKey();
        }

    }
