class Program
{
    string[] all;
    string dna = "ACGT";
    int[, ,] best;
    int[, ,] best2;
    long[, , ,] dp;
    int mod = 1000000009;
    int[, ,] p;
    void solve()
    {
        int n = nextInt();
        int m = nextInt();
        all = new string[m];
        for (int i = 0; i < m; i++)
            all[i] = nextString();
        int maxL = 0;
        for (int i = 0; i < m; i++)
            maxL = Math.Max(maxL, all[i].Length);
        best = new int[m, maxL + 1, 4];
        best2 = new int[m, maxL + 1, 4];

        p = new int[m, maxL + 1, 4];
        for (int i = 0; i < m; i++)
            for (int j = 0; j <= all[i].Length; j++)
                for (int k = 0; k < 4; k++)
                {
                    string cur = all[i].Substring(0, j) + dna[k];
                    for (int bestL = 0; bestL <= cur.Length; bestL++)
                    {
                        for (int r = 0; r < all.Length; r++)
                        {
                            if (all[r].StartsWith(cur.Substring(cur.Length - bestL)))
                            {
                                best[i, j, k] = r;
                                best2[i, j, k] = bestL;
                            }
                            if (all[r] == cur.Substring(cur.Length - bestL))
                                p[i, j, k] = bestL;
                        }
                    }
                }

        dp = new long[n + 1, m, maxL + 1, maxL + 1];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j < m; j++)
                for (int k = 0; k <= maxL; k++)
                    for (int oks = 0; oks <= maxL; oks++)
                        dp[i, j, k, oks] = -1;
        long res = go(n, 0, 0, 0);
        println(res);

    }

    private long go(int rem, int who, int len, int oks)
    {
        if (dp[rem, who, len, oks] != -1)
            return dp[rem, who, len, oks];
        long res = 0;
        if (rem == 0)
        {
            if (oks == len)
                res = 1;

            return dp[rem, who, len, oks] = res;
        }
        for (int i = 0; i < 4; i++)
        {
            int nwho = best[who, len, i];
            int nlen = best2[who, len, i];
            if (p[who, len, i] + oks >= len + 1)
            {
                res += go(rem - 1, nwho, nlen, nlen);
            }
            else
            {
                if (nlen + oks < len + 1)
                    continue;
                res += go(rem - 1, nwho, nlen, oks - (len + 1 - nlen));
            }
            if (res >= mod)
                res -= mod;
        }
        return dp[rem, who, len, oks] = res;
    }

