namespace Task
{
    internal class Program
    {
        int cnt = 0;
        Dictionary<Pair, long> data = new Dictionary<Pair, long>();
        bool[,] was = new bool[100, 100];

        long xfx(int x, int y, long z)
        {
            if (x == -1)
                return 0;
            if (z == 0)
                return 0;
            if (y == 1)
            {
                if (x == 0)
                    return 1;
                return 0;
            }

            var key = new Pair((x << 16) | y, z);

            if (data.ContainsKey(key))
                return data[key];

            long hsize = getSize(y - 1);

            long ans = 0;

            if (z >= hsize)
            {
                long temp1 = xfx(x, y - 1, hsize);
                long temp2 = xfx(x - 1, y - 1, z - hsize);
                ans += temp1 + temp2;
            }
            else
            {
                long temp = xfx(x, y - 1, z);
                ans += temp;
            }

            data[key] = ans;
            return ans;
        }



        long getSize(int y)
        {
            return 1L << (y - 1);
        }

        long get(int x, long z)
        {
            long ans = 0;

            int num = 1;
            while (z > 0)
            {
                long size = getSize(num);
                long temp = xfx(x, num, Math.Min(size, z));

                z -= size;
                ans += temp;

                num++;
            }

            return ans;

        }

