    class _371B
    {
        public static void Main()
        {
            var tokens = Console.ReadLine().Split();

            var a = Operations(int.Parse(tokens[0]));
            var b = Operations(int.Parse(tokens[1]));

            Console.WriteLine(a.Keys.Intersect(b.Keys).Select(key => a[key] + b[key]).DefaultIfEmpty(-1).Min());
        }

        private static Dictionary<int, int> Operations(int n)
        {
            var operations = new Dictionary<int, int> { { n, 0 } };
            var queue = new Queue<int>(new int[] { n });

            while (queue.Any())
            {
                int x = queue.Dequeue();

                if (x % 2 == 0 && !operations.ContainsKey(x / 2))
                {
                    operations.Add(x / 2, operations[x] + 1);
                    queue.Enqueue(x / 2);
                }

                if (x % 3 == 0 && !operations.ContainsKey(x / 3))
                {
                    operations.Add(x / 3, operations[x] + 1);
                    queue.Enqueue(x / 3);
                }

                if (x % 5 == 0 && !operations.ContainsKey(x / 5))
                {
                    operations.Add(x / 5, operations[x] + 1);
                    queue.Enqueue(x / 5);
                }
            }

            return operations;
        }
    }
}

