        public static T[] ReadArrayFromString<T>(string s, char separator)
        {
            Type type = typeof(T);

            MethodInfo[] methods = type.GetMethods();

            MethodInfo parseMethod = methods.Where(m => m.Name == "Parse").FirstOrDefault();

            if (parseMethod == null)
            {
                throw new InvalidOperationException($"The type {type} does not contain Parse method");
            }

            T[] result = s.Split(separator).Select(e => parseMethod.Invoke(type, new object[] { e })).Cast<T>().ToArray();

            return result;
        }

