        public static T[] PrefixSumOfArray<T>(T[] array) where T : struct
        {
            T currentSum = default(T);

            T[] prefixSum = new T[array.Length];

            for (int i = 0; i < array.Length; i++)
            {
                currentSum = sumTwoElements(currentSum, array[i]);
                prefixSum[i] = currentSum;
            }

            return prefixSum;
        }

