        {
            int lo = 0;
            int hi = a.Length - 1;

            int ans = -1;

            while (lo <= hi)
            {
                int med = hi - (hi - lo) / 2;

                if (target == a[med])
                {
                    ans = med;
                    hi = med - 1;
                }
                else if (target > a[med])
                {
                    lo = med + 1;
                }
                else
                {
                    hi = med - 1;
                }
            }

            return ans;
