        {
            char[] c = s.ToCharArray();

            for (int i = 0; i < c.Length / 2; i++)
            {
                char temp = c[i];
                c[i] = c[c.Length - 1 - i];
                c[c.Length - 1 - i] = temp;
            }

            return new string(c);
        }

