        {
            int n = Next()+1;

            long f = 1;
            for (int i = 2; i <= n; i++)
            {
                f = (f*i)%mod;
            }
            long f2 = f;
            for (int i = n + 1; i <= 2*n; i++)
            {
                f2 = (f2*i)%mod;
            }

            long f1 = Pow(f, mod - 2);

            long res = (((f2*f1)%mod)*f1)%mod;


            writer.WriteLine(res-1);
            writer.Flush();
