        long m = nm[1];
        long modulo = 1000000000 + 7;

        long x = fastPow((fastPow(2, m, modulo) - 1), n, modulo);

        ConsoleWriteLine("" + x);
    }

    //returns a^pw % mod
    private static long fastPow(long a, long pw, long mod) {
        long res = 1;
        a %= mod;
        while(pw > 0) {
            if((pw & 1) != 0) res = (res*a)%mod;
            a = (a*a)%mod;
            pw >>= 1;
        }
        return res;
    }

    private static long poww(long a, long b, long modulo)
    {
        long x = 1;
        for(int i = 0; i < b; ++i)
        {
            x *= a;
            x %= modulo;
        }
        return x;
    }

