using System;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using System.IO;

public class Program
{
    string go(int k, char[] a)
    {
        bool[] used = new bool[k];
        for (int c = 0; c < k; ++c) used[c] = false;

        int n = a.Length;
        for (int c = 0; c < n; ++c)
            if (a[c] != '?') used[a[c] - 'a'] = true;

        int i = 0, j = n - 1;
        for (; i < j; ++i, --j)
        {
            if (a[i] != '?' && a[j] != '?' && a[i] != a[j]) return "IMPOSSIBLE";
            if (a[i] != '?')
            {
                a[j] = a[i];
                continue;
            }
            if (a[j] != '?')
            {
                a[i] = a[j];
                continue;
            }
        }

        for (; j >= 0 && i < n; ++i, --j)
        {
            if (a[i] != '?') continue;

            int c = k - 1;
            while (c >= 0 && used[c]) --c;

            if (c < 0) c = 0;
            a[i] = a[j] = (char)(c + 'a');
            used[c] = true;
        }

        for (int c = 0; c < k; ++c)
            if (!used[c]) return "IMPOSSIBLE";

        return new string(a);
    }

    void doit()
    {
        int k = int.Parse(Console.ReadLine());
        char[] a = Console.ReadLine().ToCharArray();
        Console.WriteLine(go(k, a));
    }

    public static void Main(string[] args)
    {
        (new Program()).doit();
    }
}

