		var s = Console.ReadLine().ToArray();
		var n = s.Length;
		for (var i = 0 ; i < n / 2 ; i++) if (s[n - 1 - i] != '?') {
			if (s[n - 1 - i] == s[i]) continue;
			if (s[i] != '?') return null;
			s[i] = s[n - 1 - i];
		}
		var requiredChars = Enumerable.Range(0, k).Select(i => (char) ('a' + i)).ToArray();

		var firstHalf = Enumerable.Range(0, (n + 1) / 2);
		var spots = firstHalf.Count(i => s[i] == '?');
		var currentChars = requiredChars.Count(s.Contains);
		var missingChars = requiredChars.Where(c => !s.Contains(c)).ToArray();
		if (missingChars.Count() > spots) return null;
		foreach (var q in Enumerable.Range(0, spots - missingChars.Count())) {
			var i = firstHalf.First(ix => s[ix] == '?');
			s[i] = 'a';
		}
		foreach (var c in missingChars) {
			var i = firstHalf.First(ix => s[ix] == '?');
			s[i] = c;
		}

		foreach (var i in firstHalf) s[n - 1 - i] = s[i];
