    private int[] dr = {1, 0, -1, 0};
    private int[] dc = {0, 1, 0, -1};

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadLines(n);

        int nt = 0, nb = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (char.IsDigit(a[i][j]))
                    nt = Math.Max(nt, a[i][j] - '0');
                else if (a[i][j] == 'B')
                    nb++;
        if (nt == 0)
        {
            Write(0);
            return;
        }
        var price = ReadAndTransposeIntMatrix(nt)[0];

        var pos = new int[nt + nb][];
        nb = 0;
        int sr = 0, sc = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (char.IsDigit(a[i][j]))
                    pos[a[i][j] - '1'] = new[] { i, j };
                else if (a[i][j] == 'B')
                    pos[nt + nb++] = new[] { i, j };
                else if (a[i][j] == 'S')
                {
                    sr = i;
                    sc = j;
                }

        var f = new bool[n,m,1 << nt + nb];
        f[sr, sc, 0] = true;
        var q = new Queue<Tuple<int, int, int>>();
        q.Enqueue(Tuple.Create(sr, sc, 0));
        int ans = 0;
        int step = 0;
        int badSubMask = ((1 << nb) - 1) << nt;
        while (q.Count > 0)
        {
            var nq = new Queue<Tuple<int, int, int>>();
            while (q.Count > 0)
            {
                int r = q.Peek().Item1;
                int c = q.Peek().Item2;
                int mask = q.Dequeue().Item3;

                if (r == sr && c == sc && (mask & badSubMask) == 0)
                {
                    int s = 0;
                    for (int i = 0; i < nt; i++)
                        if ((mask >> i & 1) == 1)
                            s += price[i];
                    ans = Math.Max(ans, s - step);
                }

                for (int i = 0; i < 4; i++)
                {
                    int nr = r + dr[i];
                    int nc = c + dc[i];
                    if (nr < 0 || nr == n || nc < 0 || nc == m || a[nr][nc] != '.' && a[nr][nc] != 'S')
                        continue;
                    int nmask = mask;
                    if (i == 0)
                    {
                        for (int j = 0; j < nt + nb; j++)
                            if (nr == pos[j][0] && nc < pos[j][1])
                                nmask ^= 1 << j;
                    }
                    else if (i == 2)
                    {
                        for (int j = 0; j < nt + nb; j++)
                            if (nr == pos[j][0] - 1 && nc < pos[j][1])
                                nmask ^= 1 << j;
                    }
                    if (!f[nr, nc, nmask])
                    {
                        f[nr, nc, nmask] = true;
                        nq.Enqueue(Tuple.Create(nr, nc, nmask));
                    }
                }
            }
            q = nq;
            step++;
        }

        Write(ans);
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;
    static void Main()
    {
#if DEBUG
        reader = new StreamReader("..\\..\\input.txt");
        //reader = new StreamReader(Console.OpenStandardInput());
        writer = Console.Out;
        //writer = new StreamWriter("..\\..\\output.txt");
#else
        reader = new StreamReader(Console.OpenStandardInput());
        writer = new StreamWriter(Console.OpenStandardOutput());
        //reader = new StreamReader("hull.in");
        //writer = new StreamWriter("hull.out");
#endif
        try
        {
//            var thread = new Thread(new Solver().Solve, 1024 * 1024 * 128);
//            thread.Start();
//            thread.Join();
            new Solver().Solve();    
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
#if DEBUG
#else
            throw;
#endif
        }
        reader.Close();
        writer.Close();
    }

    #endregion

    #region Read / Write
    private static Queue<string> currentLineTokens = new Queue<string>();
    private static string[] ReadAndSplitLine() {return reader.ReadLine().Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);}
    public static string ReadToken(){while (currentLineTokens.Count == 0)currentLineTokens = new Queue<string>(ReadAndSplitLine());return currentLineTokens.Dequeue();}
    public static int ReadInt(){return int.Parse(ReadToken());}
    public static long ReadLong(){return long.Parse(ReadToken());}
    public static double ReadDouble(){return double.Parse(ReadToken(), CultureInfo.InvariantCulture);}
    public static int[] ReadIntArray(){return ReadAndSplitLine().Select(int.Parse).ToArray();}
    public static long[] ReadLongArray(){return ReadAndSplitLine().Select(long.Parse).ToArray();}
    public static double[] ReadDoubleArray(){return ReadAndSplitLine().Select(s => double.Parse(s, CultureInfo.InvariantCulture)).ToArray();}
    public static int[][] ReadIntMatrix(int numberOfRows){int[][] matrix = new int[numberOfRows][];for (int i = 0; i < numberOfRows; i++)matrix[i] = ReadIntArray();return matrix;}
    public static int[][] ReadAndTransposeIntMatrix(int numberOfRows){int[][] matrix = ReadIntMatrix(numberOfRows);int[][] ret = new int[matrix[0].Length][];
        for (int i = 0; i < ret.Length; i++){ret[i] = new int[numberOfRows];for (int j = 0; j < numberOfRows; j++)ret[i][j] = matrix[j][i];}return ret;}
    public static string[] ReadLines(int quantity){string[] lines = new string[quantity];for (int i = 0; i < quantity; i++)lines[i] = reader.ReadLine().Trim();return lines;}
    public static void WriteArray<T>(IEnumerable<T> array){writer.WriteLine(string.Join(" ", array));}
    public static void Write(params object[] array){WriteArray(array);}
    public static void WriteLines<T>(IEnumerable<T> array){foreach (var a in array)writer.WriteLine(a);}
    private class SDictionary<TKey, TValue> : Dictionary<TKey, TValue>{public new TValue this[TKey key]{
        get { return ContainsKey(key) ? base[key] : default(TValue); }set { base[key] = value; }}}
    private static T[] Init<T>(int size) where T : new(){var ret = new T[size];for (int i = 0; i < size; i++)ret[i] = new T();return ret;}
    #endregion
}

