using System;
using System.Linq;
using CompLib.Util;

public class Program
{
    int N, K;
    public void Solve()
    {
        checked
        {
            var sc = new Scanner();
            N = sc.NextInt();
            K = sc.NextInt();

            /*
             * n順列p
             * 
             * n-k個以上 p_i = i
             * 
             * 
             */


            long ans = 0;
            for (int i = 0; i <= K; i++)
            {
                // i個選ぶ
                // i個並べる
                // !i

                ans += C(N, i) * A(i);
            }
            ans++;

            Console.WriteLine(ans);
        }
    }

    long C(int n, int m)
    {
        long r = 1;
        for (int i = 0; i < m; i++)
        {
            r *= n - i;
        }

        for (int i = 1; i <= m; i++)
        {
            r /= i;
        }
        return r;
    }

    long A(int n)
    {
        if (n <= 1) return 0;
        if (n == 2) return 1;
        else return (n - 1) * (A(n - 1) + A(n - 2));
    }

    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Util
{
    using System;
    using System.Linq;

    class Scanner
    {
        private string[] _line;
        private int _index;
        private const char Separator = ' ';

        public Scanner()
        {
            _line = new string[0];
            _index = 0;
        }

        public string Next()
        {
            if (_index >= _line.Length)
            {
                string s;
                do
                {
                    s = Console.ReadLine();
                } while (s.Length == 0);

                _line = s.Split(Separator);
                _index = 0;
            }

            return _line[_index++];
        }

        public string ReadLine()
        {
            _index = _line.Length;
            return Console.ReadLine();
        }

        public int NextInt() => int.Parse(Next());
        public long NextLong() => long.Parse(Next());
        public double NextDouble() => double.Parse(Next());
        public decimal NextDecimal() => decimal.Parse(Next());
        public char NextChar() => Next()[0];
        public char[] NextCharArray() => Next().ToCharArray();

        public string[] Array()
        {
            string s = Console.ReadLine();
            _line = s.Length == 0 ? new string[0] : s.Split(Separator);
            _index = _line.Length;
            return _line;
        }

        public int[] IntArray() => Array().Select(int.Parse).ToArray();
        public long[] LongArray() => Array().Select(long.Parse).ToArray();
        public double[] DoubleArray() => Array().Select(double.Parse).ToArray();
        public decimal[] DecimalArray() => Array().Select(decimal.Parse).ToArray();
    }
}

using System;

class Program
{
        const int nMax = 53; // NOTE: Levels greater that 53 will be definately greater that any k.
        static string f0 = "What are you doing at the end of the world? Are you busy? Will you save us?";
        static string pa1 = "What are you doing while sending \"";
        static string pa2 = "\"? Are you busy? Will you send \"";
        static string pa3 = "\"?";
        static long[] fnLen = new long[nMax + 1];

        static void Main(string[] args)
        {
                fnLen[0] = f0.Length;
                for (var i = 1; i <= nMax; ++i)
                {
                        fnLen[i] = 2 * fnLen[i - 1] + pa1.Length + pa2.Length + pa3.Length;
                }

                var q = int.Parse(Console.ReadLine());
                var answer = new char[q];
                for (var i = 0; i < q; ++i)
                {
                        string[] input = Console.ReadLine().Split(' ');
                        int n = int.Parse(input[0]);
                        long k = long.Parse(input[1]) - 1;

                        answer[i] = Scan(n, k) ?? '.';

                }
                Console.WriteLine(string.Join(string.Empty, answer));
        }

        static char? Scan(int n, long k)
        {
                if (n == 0 && f0.Length <= k)
                        return null;

                if (n > 0 && n < nMax && (pa1.Length + fnLen[n - 1] + pa2.Length + fnLen[n - 1] + pa3.Length) <= k)
                        return null;

                for (var l = n; l > 0; --l)
                {
                        if (pa1.Length > k)
                        {
                                return pa1[(int)k];
                        }
                        k -= pa1.Length;
                        if (l - 1 > nMax || fnLen[l - 1] > k)
                        {
                                continue;
                        }
                        k -= fnLen[l - 1];
                        if (pa2.Length > k)
                        {
                                return pa2[(int)k];
                        }
                        k -= pa2.Length;
                        if (l - 1 > nMax || fnLen[l - 1] > k)
                        {
                                continue;
                        }
                        k -= fnLen[l - 1];
                        if (pa3.Length > k)
                        {
                                return pa3[(int)k];
                        }
                }

                return f0[(int)k];
        }
}

