    const ulong MOD = 1000000007ul;

    public static ulong ModPow(ulong x, ulong exp, ulong mod) {
        ulong ret = 1ul;
        while (exp > 0) {
            if (exp % 2 == 1) ret = ret * x % mod;
            x = x * x % mod;
            exp /= 2;
        }
        return ret;
    }

    static bool[] GetPrimeSieve(int max) {
        var sieve = new bool[max + 1];
        for (var a = 2; 2 * a <= max; a++) {
            if (!sieve[a]) {
                for (var b = 2 * a; b <= max; b += a)
                    sieve[b] = true;
            }
        }
        return sieve;
    }

    public static bool IsPrime(ulong n) {
        if (n == 2) return true;

        if (n < 2 || n % 2 == 0)
            return false;

        var d = n - 1;
        var s = 0ul;
        while (d % 2 == 0) {
            d /= 2;
            s += 1;
        }

        var arr =
            n < 4759123141ul ? new ulong[] {2, 7, 61}
            : n < 341550071728321ul ? new ulong[] {2, 3, 5, 7, 11, 13, 17}
            : new ulong[] {2, 3, 5, 7, 11, 13, 17, 19, 23};

        foreach (var a in arr)
        {
            if (a >= n) return true;

            var x = ModPow(a, d, n);

            if (x == 1) continue;
            if (x == n - 1) continue;

            for (var r = 1ul; r < s; r++) {
                x = ModPow(x, 2, n);
                if (x == 1) return false;
                if (x == n - 1) break;
            }

            if (x != n - 1) return false;
        }
        return true;
    }

