public class HelloWorld {
    public static void SolveCodeForces() {
        var x = cin.NUL();
        var n = cin.NUL();

        var divs = new List<ulong>();
        for (var p = 2ul; p * p <= x; p++) {
            if (x % p == 0) {
                divs.Add(p);
                while (x % p == 0) x /= p;
            }
        }
        if (x > 1)
            divs.Add(x);

// System.Console.WriteLine(divs.Join());

        var ans = 1ul;

        foreach (var p in divs) {
            var pow = 0ul;

            var ppow = 1ul;
            while (ppow <= n / p) {
                ppow *= p;
                pow += n / ppow;
            }

            ans = ans * ModPow(p, pow, MOD) % MOD;
        }

        System.Console.WriteLine(ans);
    }

    const ulong MOD = 1000000007ul;

    public static ulong ModPow(ulong x, ulong exp, ulong mod) {
        ulong ret = 1ul;
        while (exp > 0) {
            if (exp % 2 == 1) ret = ret * x % mod;
            x = x * x % mod;
            exp /= 2;
        }
        return ret;
    }

