using Enu = System.Linq.Enumerable;

class Solution {
    void calc() {
        long p, q;
        rlo(out p, out q);
        int n = 5000000;
        var primes = sieveOfEratosthenes(n);
        //Console.WriteLine(primes.Count);
        //Console.WriteLine(Enu.Range(1, n).Count(e => isPalindorome(e)));
        int idx = 0;
        long pi = 0, rub = 0;
        int ans = 0, last = primes.Last();
        for(int i = 1; i <= last; i++) {
            if(primes[idx] == i) {
                pi++;
                idx++;
            }
            if(isPalindorome(i)) rub++;
            if(q * pi <= p * rub) {
                ans = i;
            }
        }
        if(ans > 0) Console.WriteLine(ans);
        else Console.WriteLine("Palindromic tree is better than splay tree");
    }
    bool isPalindorome(int n) {
        string s = n.ToString();
        for(int i = 0; i < s.Length; i++) {
            if(s[i] != s[s.Length - 1 - i]) return false;
        }
        return true;
    }
    public static List<int> sieveOfEratosthenes(int n) {
        List<int> primes = new List<int>();
        bool[] isPrime = Enumerable.Repeat(true, n + 1).ToArray();
        isPrime[0] = isPrime[1] = false;
        for(int i = 2; i <= n; i++) {
            if(isPrime[i]) {
                primes.Add(i);
                for(int j = 2 * i; j <= n; j += i) isPrime[j] = false;
            }
        }
        return primes;
    }

    static void Main(string[] args) {
        new Solution().calc();
    }

