			long ans = (a * (a + 1) / 2) % Osn;
			ans = (ans * b + a) % Osn;
			ans = (((b * (b - 1) / 2) % Osn) * ans) % Osn;
			Console.WriteLine(ans);
			Console.ReadLine();
		}
	}
