    class Program
    {
        static void Main(string[] args)
        {
            string[] werte = Console.ReadLine().Split(' ');
            int a, b, c, d, e, f;

            a = Convert.ToInt32(werte[0]);
            b = Convert.ToInt32(werte[1]);
            c = Convert.ToInt32(werte[2]);
            d = Convert.ToInt32(werte[3]);
            e = Convert.ToInt32(werte[4]);
            f = Convert.ToInt32(werte[5]);

            if (istOk(a, b, c, d, e, f) == true)
            {
                Console.WriteLine("Ron");
            }
            else
            {
                Console.WriteLine("Hermione");
            }

            Console.ReadLine();
        }

        public static bool istOk(int a, int b, int c, int d, int e, int f)
        {
            bool ex_istOk = false;

            int a1, b1, c1, d1, e1, f1;
            a1 = 0;
            b1 = 0;
            c1 = 0;
            d1 = 0;
            e1 = 0;
            f1 = 0;



            if ( d != 0 )
            {
                if(c==0) ex_istOk = true;

                if (c != 0 && b != 0)
                {
                    if (a == 0) ex_istOk = true;

                    else if(a != 0 && f != 0)
                    {
                        if (e == 0) ex_istOk = true;
                        else
                        {
                            e1 = Delimoe((Delimoe(b, c) / c * d), e);
                            d1 = e1;
                            f1 = e1 / e * f;
                            c1 = d1 / d * c;
                            b1 = c1;
                            a1 = b1 / b * a;

                            if (f1 > a1) ex_istOk = true;
                        }
                    }
                }

            }
            return ex_istOk;
        }

        public static int Delimoe (int a, int b)
        {
            int maxDel = Math.Max(a,b);

            while (maxDel % a != 0 || maxDel % b != 0)
                    maxDel++;

            return maxDel;
        }

