using Watch = System.Diagnostics.Stopwatch;
using StringBuilder = System.Text.StringBuilder;
namespace Solver
{

    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var k = sc.Integer();
            var t = sc.Integer();
            var l = new List<Pair<int>>();
            for (int i = 0; i < n; i++)
            {
                var v = sc.Integer();
                if (l.Count == 0)
                    l.Add(new Pair<int>(v, 1));
                else
                {
                    var end = l[l.Count - 1];
                    if (end.L == v)
                        l[l.Count - 1] = new Pair<int>(v, end.R + 1);
                    else l.Add(new Pair<int>(v, 1));
                }
            }
            var ret = 1;
            for (int u = 0; u < l.Count; u++)
            {
                var st = new Stack<Pair<int>>();
                var count = 0;
                for (int i = 0; i < u; i++)
                    st.Push(l[i]);
                st.Push(new Pair<int>(t, 1));
                for (int i = u; i < l.Count; i++)
                {
                    if (!st.Any())
                        break;
                    var last = st.Peek();
                    var next = l[i];
                    if (last.L == next.L && last.R + next.R >= 3)
                    {
                        st.Pop();
                        count += last.R + next.R;
                    }
                    else break;
                }
                ret = Math.Max(ret, count);

            }
            IO.Printer.Out.PrintLine(ret - 1);

        }
        internal IO.StreamScanner sc;
    }

