    public class _430B_BallsGame
    {
        public static void Run()
        {
            var s1 = Console.ReadLine().Split(' ');
            var n = Int32.Parse(s1[0]);
            //var k = Int32.Parse(s1[1]);
            var x = Int32.Parse(s1[2]);

            var s2 = Console.ReadLine().Split(' ');
            var cols = new int[n];
            for (var i = 0; i < n; i++)
            {
                cols[i] = Int32.Parse(s2[i]);
            }

            var d = DoIt(cols, n, x);
            Console.WriteLine(d);
        }

        private static int DoIt(int[] cols, int n, int x)
        {
            var max = 0;
            for (var i = 1; i < n; i++)
            {
                var c = InsertItem(cols, i, x);
                while (c.Length > 0)
                {
                    var old = c.Length;
                    c = Delete3S(c);
                    if (c.Length == old) break;
                }
                var len = n - c.Length;
                if (len > max) max = len;
                if (max == n) return max;
            }

            return max;
        }

        private static int[] InsertItem(int[] num, int index, int x)
        {
            var len = num.Length + 1;
            var arr = new int[len];

            for (var i = 0; i < index; i++)
            {
                arr[i] = num[i];
            }
            arr[index] = x;
            for (var i = index + 1; i < len; i++)
            {
                arr[i] = num[i - 1];
            }

            return arr;
        }

        private static int[] Delete3S(int[] num)
        {
            var len = num.Length;
            if (len == 0) return new int[0];
            var start = 0;
            var ctr = 1;
            var prev = num[0];
            for (var i = 1; i < len; i++)
            {
                var cur = num[i];
                if (cur == prev)
                {
                    ++ctr;
                }else {
                    if (ctr > 2)
                    {
                        break;
                    }
                    ctr = 1;
                    start = i;
                }
                prev = cur;
            }

            var end = start + ctr;
            if (ctr > 2)
            {
                var arr = new int[len - ctr];
                for (var i = 0; i < start; i++)
                {
                    arr[i] = num[i];
                }
                for (var i = end; i < len; i++)
                {
                    arr[i - ctr] = num[i];
                }

                return arr;
            }
            return num;
        }
    }
}

