public static class Cin
{
    public static string ReadString()
    {
        StringBuilder tokenChars = new StringBuilder();
        bool tokenFinished = false;
        bool skipWhiteSpaceMode = true;
        while (!tokenFinished)
        {
            int nextChar = Console.Read();
            if (nextChar == -1)
            {
                // End of stream reached
                tokenFinished = true;
            }
            else
            {
                char ch = (char) nextChar;
                if (char.IsWhiteSpace(ch))
                {
                    if (!skipWhiteSpaceMode)
                    {
                        tokenFinished = true;
                        if (ch == '\r' && (Environment.NewLine == "\r\n"))
                        {
                            // Reached '\r' in Windows --> skip the next '\n'
                            Console.Read();
                        }
                    }
                }
                else
                {
                    // Character reached --> append it to the output
                    skipWhiteSpaceMode = false;
                    tokenChars.Append(ch);
                }
            }
        }

        string token = tokenChars.ToString();
        return token;
    }

    public static int ReadInt()
    {
        string token = ReadString();
        return int.Parse(token);
    }

    public static long ReadLong()
    {
        string token = ReadString();
        return long.Parse(token);
    }

    public static T[] ReadArrayFromLine<T>(Func<string, T> factory)
    {
        return Console.ReadLine()?.Split(' ').Select(factory).ToArray();
    }

    public static int[] ReadIntArrayFromLine()
    {
        return ReadArrayFromLine(int.Parse);
    }

    public static long[] ReadLongArrayFromLine()
    {
        return ReadArrayFromLine(long.Parse);
    }

    public static double ReadDouble(bool acceptAnyDecimalSeparator = true)
    {
        string token = ReadString();
        if (acceptAnyDecimalSeparator)
        {
            token = token.Replace(',', '.');
            double result = double.Parse(token, CultureInfo.InvariantCulture);
            return result;
        }
        else
        {
            double result = double.Parse(token);
            return result;
        }
    }
}

