                        double t = getTemp(t1, t2, i, j);
                        if (t == temp && i + j > y1 + y2)
                        {
                            y1 = i;
                            y2 = j;
                        }
                        if (t >= t0 && (Math.Abs(t0 - t) < Math.Abs(t0 - temp) || temp < t0))
                        {
                            y1 = i;
                            y2 = j;
                            temp = t;
                        }
                    }
                }
            }

            else if (y2 == x2 && y2 != 0)
            {
                double rat = ((double)y1) / y2;
                for (int i = x2 - 1; i >= 0; i--)
                {
                    int ny1 = (int)(i * rat);
                    for (int j = ny1 - 1; j <= ny1 + 1; j++)
                    {
                        if (j < 0 || j > x1)
                            continue;

                        double t = getTemp(t1, t2, j, i);
                        if (t == temp && i + j > y1 + y2)
                        {
                            y1 = j;
                            y2 = i;
                        }
                        if (t >= t0 && (Math.Abs(t0 - t) < Math.Abs(t0 - temp) || temp < t0))
                        {
                            y2 = i;
                            y1 = j;
                            temp = t;
                        }
                    }
                }
            }

            Console.Write("{0} {1}", y1, y2);
            Console.ReadLine();
        }
    }
}

