    internal class Solution
    {
        private int[,,,] pos;

        private Card[] cards;

        public void Solve()
        {
            int n;
            Reader.ReadInt(out n);

            cards = new Card[n];

            string s = Reader.ReadLine();
            var split = s.Split();
            for (int i = 0; i < n; i++)
            {
                cards[i] = new Card(split[i], i);
            }

            pos = new int[n + 1,n,n,n];

            Console.Write(this.IsPossible(n, n - 3, n - 2, n - 1) == 1 ? "YES" : "NO");
        }

        private int IsPossible(int n, int a, int b, int c)
        {
            if (n == 1)
            {
                return 1;
            }

            if (n == 2)
            {
                return this.Compatible(cards[b], cards[c]) ? 1 : 2;
            }

            if (pos[n, a, b, c] != 0)
            {
                return pos[n, a, b, c];
            }

            if (this.Compatible(cards[b], cards[c]) && this.IsPossible(n - 1, n - 4, a, c) == 1 ||
                n > 3 && this.Compatible(cards[n - 4], cards[c]) && this.IsPossible(n - 1, c, a, b) == 1)
            {
                pos[n, a, b, c] = 1;
                return 1;
            }
            else
            {
                pos[n, a, b, c] = 2;
                return 2;
            }
        }

        class Card
        {
            public Card(string card, int id)
            {
                Value = card[0];
                Suit = card[1];
                Id = id;
            }

            public char Value;

            public char Suit;

            public int Id;
        }

        private bool Compatible(Card a, Card b)
        {
            return a.Value == b.Value || a.Suit == b.Suit;
        }
    }
