        for (int i = 0; i < n; i++)
            if (!visited[i])
            {
                int cnt = 0;
                int t = i;
                while (!visited[t])
                {
                    visited[t] = true;
                    t = next[t] - 1;
                    cnt++;
                }

                size.Add(cnt);
            }

        size.Sort();
        for (int i = 0; i < size.Count; i++)
            if (size[i] % 2 == 0)
            {
                size[i] /= 2;
            }

        long answer = 1;
        for (int i = 0; i < size.Count; i++)
        {
            var gcd = GCD(answer, size[i]);
            answer = (answer / gcd) * size[i];
        }

        Console.Write(answer);
    }

