	{
		static void Main(string[] args) 
		{
			string input1 = Console.ReadLine();
			//string input2 = Console.ReadLine();
			//string input3 = Console.ReadLine();
			//string input4 = Console.ReadLine();

			var inputs1 = input1.Split(new[] { ' ', '}', '{' , ',' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();
			//var inputs2 = input2.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).Select(long.Parse).ToArray();

			long n = inputs1[0];
			long a = inputs1[1];
			long b = inputs1[2];
			long p = inputs1[3];
			long q = inputs1[4];

			var ab = LCM(a, b);

			var nAB = n / ab;
			var nA = n / a - nAB;
			var nB = n / b - nAB;

			Console.WriteLine(nA * p + nB * q + nAB * Math.Max(p, q));
		}

		private static long GCD(long a, long b)
		{
			long max = Math.Max(a, b);
			long min = Math.Min(a, b);

			if (min == 0)
			{
				return max;
			}
			a = min;
			b = max % min;
			return GCD(a, b);
		}

		private static long LCM(long a, long b)
		{
			return Math.Abs(a * b) / GCD(a, b);
		}

		static long Factorial(long a) 
		{
			return a > 1 ? a * Factorial(a - 1) : 1;
		}
	}
}

