		{
			return x*y/Nod(x, y);
		}
		private long Nod(long x, long y)
		{
			long max = Math.Max(x, y);
			long min = Math.Min(x, y);


			while (true)
			{
				long rem = max % min;
				if (rem == 0)
				{
					return min;
				}
				max = min;
				min = rem;
			}
