class Solution {
    public void solve(TextReader input, TextWriter output) {
        var inp = input.ReadLine().Split(' ').Select(i => ulong.Parse(i)).ToArray();
        ulong x = inp[0];
        ulong y = inp[1];
        ulong l = inp[2];
        ulong r = inp[3];

        var xi = new ulong[61];
        xi[0] = 1;
        int powa = 0;
        for (int i = 1; xi[i-1] <= r; i++)
        {
            if(Math.Log10((double)xi[i - 1] * (double)x) > Math.Log10(r))
            {
                break;
            }

            xi[i] = xi[i - 1] * x;
            powa = i;
        }

        var yj = new ulong[61];
        yj[0] = 1;
        int powb = 0;
        for (int j = 1; yj[j-1] <= r; j++)
        {
            if (Math.Log10((double)yj[j - 1] * (double)y) > Math.Log10(r))
            {
                break;
            }

            yj[j] = yj[j - 1] * y;
            powb = j;
        }

        var shits = new SortedSet<ulong>();
        for (int i = 0; i <= powa; i++)
        {
            for (int j = 0; j <= powb; j++)
            {
                ulong n = xi[i] + yj[j];
                if(l <= n && n <= r)
                    shits.Add(n);
            }
        }

        ulong res = 0;
        if (shits.Count == 0)
            res = r - l + 1;
        else
        {
            var shitArray = shits.ToArray();
            ulong shitLength;
            for (int i = 0; i < shitArray.Count() - 1; i++)
            {
                shitLength = shitArray[i + 1] - shitArray[i] - 1;
                if (shitLength > res)
                    res = shitLength;
            }

            shitLength = shitArray[0] - l;
            if (shitLength > res)
                res = shitLength;

            shitLength = r - shitArray[shitArray.Count() - 1];
            if (shitLength > res)
                res = shitLength;
        }

        output.WriteLine(res);
    }
}

