        var dx = new List<long>();
        var now = 1L;
        while (now <= R)
        {
            dx.Add(now);
            if ((double)now * X > R) break;
            now *= X;
        }
        var v = new List<long>() { L-1, R+1 };
        now = 1;
        while (now <= R)
        {
            foreach(var e in dx)
            {
                var s = e + now;
                if (L <= s && s <= R) v.Add(s);
            }
            if ((double)now * Y > R) break;
            now *= Y;
        }
        v.Sort();
        var res = 0L;
        for (int i = 0; i < v.Count - 1; i++)
            chmax(ref res, v[i + 1] - v[i] - 1);
        Console.WriteLine(res);
    }
}

