	{
		Scanner sr;
		StreamWriter sw;

		bool isMultipleTestCases = false;

		public void Solve()
		{
			var n = sr.ReadInt();
			var devisor = Enumerable.Range(0, n + 1).ToArray();
			for (int i = 2; i * i <= n; i++)
			{
				if (devisor[i] != i) continue;
				var t = i * 2;
				while (t <= n)
				{
					devisor[t] = i;
					t += i;
				}
			}
			var dp = new ModInt[n + 1];
			dp[1] = 1;
			ModInt dpsum = 1;
			for (int i = 2; i <= n; i++)
			{
				dp[i] = 1;
				var factors = new Dictionary<int, int>();
				var cur = i;
				while (cur > 1)
				{
					if (!factors.ContainsKey(devisor[cur])) factors.Add(devisor[cur], 0);
					factors[devisor[cur]]++;
					cur /= devisor[cur];
				}
				foreach (var (key, value) in factors)
				{
					dp[i] *= value + 1;
				}
				dp[i] += dpsum;
				dpsum += dp[i];
			}
			Console.WriteLine(dp[n]);
		}

