public class Solver
{
    public object Solve()
    {
        int hp1 = ReadInt();
        int at1 = ReadInt();
        int df1 = ReadInt();
        int hp2 = ReadInt();
        int at2 = ReadInt();
        int df2 = ReadInt();
        int h = ReadInt();
        int a = ReadInt();
        int d = ReadInt();

        int ans = 0;
        if (at1 <= df2)
        {
            int need = df2 + 1 - at1;
            at1 += need;
            ans += a * need;
        }

        int min = int.MaxValue;
        for (int at = 0; at < 200; at++)
            for (int df = 0; df < 200; df++)
            {
                int x = 0;
                int dm = at1 + at - df2;
                int t = (hp2 - 1) / dm + 1;
                int dm2 = Math.Max(0, at2 - df1 - df);
                if (dm2 > 0)
                {
                    int tot = t * dm2;
                    if (tot >= hp1)
                        x += (tot + 1 - hp1) * h;
                }
                x += at * a + df * d;
                min = Math.Min(x, min);
            }

        return ans + min;

        return null;
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;

    static void Main()
    {
#if DEBUG
        reader = new StreamReader("..\\..\\input.txt");
        writer = Console.Out;
