namespace Solver
{
    public class Solver
    {
        public void Solve()
        {
            var hp = sc.Integer();
            var atk = sc.Integer();
            var def = sc.Integer();
            var mH = sc.Integer();
            var mA = sc.Integer();
            var mD = sc.Integer();
            var h = sc.Integer();
            var a = sc.Integer();
            var d = sc.Integer();
            var min = int.MaxValue;
            for (int i = 0; i <= 200; i++)
                for (int j = 0; j <= 100; j++)
                {
                    var cost = i * a + j * d;
                    var res = battle(hp, atk + i, def + j, mH, mA, mD);
                    if (res < 0) continue;
                    min = Math.Min(min, cost + res * h);
                }
            IO.Printer.Out.WriteLine(min);
        }
        int battle(int hp, int atk, int def, int HP, int ATK, int DEF)
        {
            if (atk <= DEF) return -1;
            var d = Math.Max(0, atk - DEF);
            var hidame = Math.Max(0, ATK - def);
            var turn = HP / d;
            if (HP % d > 0) turn++;
            var damage = hidame * turn;
            if (hp > damage)
                return 0;
            var diff = Math.Abs(hp - damage);
            return diff + 1;
        }
        internal IO.StreamScanner sc;
        static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; i++) a[i] = f(i); return a; }
    }

