        private static int solve(int len, int last)
        {
            if (len == k)
                return 1;
            if (dp[len][last] != -1)
                return dp[len][last];
            dp[len][last] = 0;
            for (int j = 1; j * last <= n; ++j)
                dp[len][last] = (dp[len][last] + solve(len + 1, last * j)) % MOD;
            return dp[len][last];
        }
