    {
        static Input csin = new Input();

        static void Main(string[] args)
        {
            int n = csin.GetInt();
            long k = csin.GetLong();
            List<int> s = csin.GetString().Select(x => (int)(x - 'a')).ToList();
            s.Add(26);

            long[,] d = new long[n + 1, n + 1]; // i - length, j - first index

            d[0, n] = 1;

            bool[] ex = new bool[27];

            for (int len = 1; len <= n; len++)
                for (int start = 0; start < n; start++)
                {
                    for (int i = 0; i < 27; i++) ex[i] = false;

                    for (int j = start + 1; j <= n; j++)
                    {
                        if (ex[s[j]]) continue;
                        ex[s[j]] = true;
                        d[len, start] += d[len - 1, j];
                    }
                }


            long[] lenans = new long[n + 1];
            for (int i = 0; i <= n; i++)
            {
                for (int j = 0; j < 27; j++) ex[j] = false;

                for (int j = 0; j <= n; j++)
                {
                    if (ex[s[j]]) continue;

                    lenans[i] += d[i, j];
                    ex[s[j]] = true;
                }
            }

            long ans = 0;

            for (int i = n; i >= 0 && k > 0; i--)
            {
                long curr = Math.Min(k, lenans[i]);
                k -= curr;
                ans += curr * (n - i);
            }

            if (k > 0) ans = -1;


            Console.WriteLine(ans);
            //Console.ReadKey();
        }

    }
