public class Solver
{
    List<int> Fun(int x)
    {
        var ret = new List<int>();
        if (x == 0)
        {
            ret.Add(0);
            return ret;
        }
        while (x > 0)
        {
            ret.Add(x % 7);
            x /= 7;
        }
        ret.Reverse();
        return ret;
    }

    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();

        var dp = new int[1 << 7, 2];
        dp[0, 0] = 1;
        foreach (int x in Fun(n - 1))
        {
            var ndp = new int[1 << 7, 2];
            for (int i = 0; i < 1 << 7; i++)
                for (int j = 0; j < 2; j++)
                    for (int k = 0; k < 7; k++)
                        if ((i >> k & 1) == 0)
                        {
                            if (j == 0 && k > x)
                                continue;
                            int nj = j;
                            if (k < x)
                                nj = 1;
                            ndp[i | 1 << k, nj] += dp[i, j];
                        }
            dp = ndp;
        }

        for (int i = 0; i < 1 << 7; i++)
        {
            dp[i, 0] += dp[i, 1];
            dp[i, 1] = 0;
        }

        foreach (int x in Fun(m - 1))
        {
            var ndp = new int[1 << 7, 2];
            for (int i = 0; i < 1 << 7; i++)
                for (int j = 0; j < 2; j++)
                    for (int k = 0; k < 7; k++)
                        if ((i >> k & 1) == 0)
                        {
                            if (j == 0 && k > x)
                                continue;
                            int nj = j;
                            if (k < x)
                                nj = 1;
                            ndp[i | 1 << k, nj] += dp[i, j];
                        }
            dp = ndp;
        }

        int ans = 0;
        for (int i = 0; i < 1 << 7; i++)
            for (int j = 0; j < 2; j++)
                ans += dp[i, j];

        Write(ans);
    }

