                var numberOfPeople = input[0];
                var numberOfMessage = input[1];

                bool[] seen = new bool[100000 + 1];
                int leaderId = -1;
                bool leaderOnline = false;
                var peopleOnline = 0;

                for (int i = 0; i < numberOfMessage; i++)
                {
                    var status = Console.ReadLine().Split(' ');
                    var symbol = status[0][0];
                    var id = int.Parse(status[1]);

                    if (symbol == '+')
                    {

                            if(i== 0)
                            {
                               leaderId = id;
                               leaderOnline = true;
                            }

                        else // there is a leader
                        {
                            if (leaderOnline)
                            {
                                //do nothing
                            }
                            else
                            {
                                if (leaderId == id)
                                {
                                    leaderOnline = true;
                                }
                                else
                                {
                                    leaderId = -1;
                                    leaderOnline = false;
                                }
                            }
                        }
                        peopleOnline++;                     
                    }

                    if (symbol == '-')
                    {
                        if (!seen[id])
                        {
                            if (peopleOnline == 0)
                            {
                                leaderId = id;
                                leaderOnline = false;
                            }
                            else
                            {
                                leaderId = -1;
                                leaderOnline = false;
                            }
                        }

                        else
                        {
                            peopleOnline = Math.Max(--peopleOnline, 0);
