        if (K[0].v == 1) Fail("YES");
        if (K.Select(k => k.v).Count(a => a <= 2) >= 2) Fail("YES");
        if (K.Select(k => k.v).All(v => v == 3)) Fail("YES");
        if (K[0].v == 2 && K[1].v == 4 && K[2].v == 4) Fail("YES");
        Console.WriteLine("NO");
    }
