            long T = 0, periods = 0;
            if (n > 2) T = m * (2 * n - 2);
            else T = m * n;
            if (T > 0)
            {
                periods = k / T;
                k = k % T;
            }
            long[,] matrix = new long[n, m];
            long min = long.MaxValue, max = 0;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                {
                    matrix[i, j] = periods * ((i == 0 || i == n - 1) ? 1 : 2);
                    if (k > 0)
                    {
                        matrix[i, j]++;
                        k--;
                    }
                }
            for (int i = (int)n - 2; i >= 0; i--)
                for (int j = 0; j < m; j++)
                {
                    if (k > 0)
                    {
                        matrix[i, j]++;
                        k--;
                    }
                }
            for (int i = 0; i < n; i++)
                for (int j = 0; j < m; j++)
                {
                    if (matrix[i, j] < min) min = matrix[i, j];
                    if (matrix[i, j] > max) max = matrix[i, j];
                }
            Console.WriteLine(max + " " + min + " " + matrix[x - 1, y - 1]);
        }
    }
}

