    private static bool IsSimple(int x)
    {
        if ((x & 1) == 0) return x == 2;

        int end = (int)Math.Sqrt(x);
        for (int i = 3; i <= end; i += 2)
            if (x % i == 0)
                return false;

        return true;
    }

