namespace codeforces
{

    class Program
    {
        const int N = 2000;
        const int MOD = 998244353;

        static int n, m, k;
        static int[,] dp = new int[N, N];

        static int mul(int a, int b)
        {
            return (int) ((1L * a * b) % MOD);
        }

        static int add(int a, int b)
        {
            int result = a + b;
            if (result >= MOD)
            {
                result -= MOD;
            }
            return result;
        }

        static void Main(string[] args)
        {
            var s = Console.ReadLine().Split(' ');
            n = int.Parse(s[0]);
            m = int.Parse(s[1]);
            k = int.Parse(s[2]);
            for (int i = 0; i < n; ++i)
            {
                for (int j = 0; j < n; ++j)
                {
                    dp[i, j] = 0;
                }
            }
            dp[0, 0] = m;
            for (int i = 1; i < n; ++i)
            {
                for (int j = 0; j <= i; ++j)
                {
                    dp[i, j] = j == 0
                        ? dp[i - 1, j]
                        : add(dp[i - 1, j], mul(m - 1, dp[i - 1, j - 1]));
                }
            }
            Console.WriteLine(dp[n - 1, k]);
        }
    }
}

