  {
    long N = long.Parse ( Console.ReadLine ( ) );
    for ( int b = 0; b <= 90; b++ )
    {
      long D = GetDisc ( 1, b, -N );
      if ( D < 0 )
        continue;
      long sqrtd = ( long ) Math.Sqrt ( D );
      if ( sqrtd * sqrtd != D )
        continue;
      double x1 = ( -b + sqrtd ) / 2.0;
      if ( x1 == Math.Floor ( x1 ) && x1 >= 0 )
      {
        if ( b == sumd ( ( int ) x1 ) )
          return ( int ) x1;
      }

      double x2 = ( -b - sqrtd ) / 2.0;
      if ( x2 == Math.Floor ( x2 ) && x2 >= 0 )
      {
        if ( b == sumd ( ( int ) x2 ) )
          return ( int ) x2;
      }
    }

    return -1;
  }

  static int sumd ( int x )
  {
    int sum=0;
    while ( x > 0 )
    {
      sum += x % 10;
      x = x / 10;
    }
    return sum;
  }

