#region Tropical Matrix
public class TropicalMatrix
{
    int row, col;
    public long[] mat;
    const long min = -1L << 60;
    public long this[int r, int c]
    {
        get { return mat[r * col + c]; }
        set { mat[r * col + c] = value; }
    }
    public TropicalMatrix(int r, int c)
    {
        row = r; col = c;
        mat = new long[row * col];
        for (int i = 0; i < row * col; i++)
            mat[i] = min;
    }
    public static TropicalMatrix operator +(TropicalMatrix l, TropicalMatrix r)
    {
        check(l, r);
        var ret = new TropicalMatrix(l.row, l.col);
        for (int i = 0; i < l.row; i++)
            for (int j = 0; j < l.col; j++)
                ret.mat[i * ret.col + j] = Math.Max(l.mat[i * l.col + j], r.mat[i * r.col + j]);
        return ret;

    }
    public static TropicalMatrix operator *(TropicalMatrix l, TropicalMatrix r)
    {
        checkMul(l, r);
        var ret = new TropicalMatrix(l.row, l.col);


        for (int i = 0; i < l.row; i++)
            for (int k = 0; k < l.row; k++)
                for (int j = 0; j < l.col; j++)
                    ret.mat[i * l.col + j] = Math.Max(ret.mat[i * l.col + j],
                        l.mat[i * l.col + k] + r.mat[k * l.col + j]);
        return ret;
    }
    public static TropicalMatrix Pow(TropicalMatrix m, long n)
    {
        var ret = new TropicalMatrix(m.row, m.col);
        for (int i = 0; i < m.row; i++)
            ret.mat[i * m.col + i] = 0;
        for (; n > 0; m *= m, n >>= 1)
            if ((n & 1) == 1)
                ret = ret * m;
        return ret;

    }
    public static TropicalMatrix Trans(TropicalMatrix m)
    {
        var ret = new TropicalMatrix(m.col, m.row);
        for (int i = 0; i < m.row; i++)
            for (int j = 0; j < m.col; j++)
                ret.mat[j * m.col + i] = m.mat[i * m.col + j];
        return ret;
    }
    [System.Diagnostics.Conditional("DEBUG")]
    static private void check(TropicalMatrix a, TropicalMatrix b)
    {
        if (a.row != b.row || a.col != b.col)
            throw new Exception("row and col have to be same.");

    }
    [System.Diagnostics.Conditional("DEBUG")]
    static private void checkMul(TropicalMatrix a, TropicalMatrix b)
    {
        if (a.col != b.row)
            throw new Exception("row and col have to be same.");

    }
}
