    {
        static void Main(string[] args)
        {
            string[] s = Console.ReadLine().Split();
            int x = int.Parse(s[0]);
            int y = int.Parse(s[1]);
            int n = int.Parse(s[2]);
            double dx = (double) x;
            double dy = (double) y;

            long mina = 0, minb = 0;
            double min = long.MaxValue;
            for (long b = 1; b <= n; b++)
            {
                double db = (double)b;
                long aMin = b * x / y;
                long aMax = Convert.ToInt64(Math.Ceiling(db * dx / dy));

                for (long a = aMin; a <= aMax; a++)
                {
                    double da = (double)a;
                    double d = Math.Abs(dx / dy - da / db);
                    d = Math.Floor(d * 1e15) / 1e15;
                    if (d < min)
                    {
                        min = d;
                        mina = a;
                        minb = b;
                    }
                }
            }

            Console.WriteLine(mina + "/" + minb);

        }
    }
