namespace Codeforces.R281.B
{
    public static class Solver
    {
        public static void Main()
        {
            using (var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Solve(Console.In, sw);
            }
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            var w = tr.ReadLine().Split().Select(x => int.Parse(x)).ToArray();
            tw.WriteLine(Calc(w[0], w[1], w[2]));
        }

        private static string Calc(int x, int y, int n)
        {
            var e = long.MaxValue;
            var eDenominator = 1L;

            var resA = 0L;
            var resB = 0L;

            for (var b = 1L; b <= n; ++b)
            {
                var l = 0L;
                var h = (x / y + 1) * b + 3;

                for (; l + 2 < h; )
                {
                    var m1 = (l * 2 + h) / 3;
                    var m2 = (l + h * 2) / 3;
                    var err1 = Math.Abs(x * b - y * m1);
                    var err2 = Math.Abs(x * b - y * m2);

                    if (err1 <= err2)
                    {
                        h = m2;
                    }
                    else
                    {
                        l = m1;
                    }
                }

                for (var a = l; a <= h; ++a)
                {
                    var currentError = Math.Abs(x * b - y * a);
                    if (currentError * eDenominator < e * b)
                    {
                        e = currentError;
                        eDenominator = b;
                        resA = a;
                        resB = b;
                    }
                }
            }

            return resA + "/" + resB;
        }
    }
}

