    class Program
    {
        static void Main(string[] args)
        {


            string[] tokens = Console.ReadLine().Split(' ');

            long   x=0, y=0, m = 0;
            x =long.Parse(tokens[0]);
            y = long.Parse(tokens[1]);
            m = long.Parse(tokens[2]);

            long p=mperfect(x, y, m);

            Console.WriteLine(p);
            Console.ReadLine();



        }

        protected static long mperfect(long x, long y, long m)
        {
            long i = 0;

            if (x >= m || y >= m)
                return 0;
             if (x <= 0 && y <= 0 )
                return -1;

             if (x > y)
             {
                 x ^= y;
                 y ^= x;
                 x ^= y;

            //     x ^= (y ^= (x ^= y));
             }

                if (x < 0 && y > 0)
                {
                    i = -x / y;
                    x = x + y * i;
                }
                else if (y < 0 && x > 0)
                {
                    i = -y / x;
                    y = y + x * i;
                }

                while (x < m && y < m)
                {
                    if (x < y)
                    {
                        x = x + y;
                        i++;
                        if (x >= m || y >= m)
                            return i;
                    }
                    else
                    {
                        y = x + y;
                        i++;
                        if (x >= m || y >= m)
                            return i;
                    }

                }

                return i;



        }
    }
