            int currPos = 0;
            string[] tokens = new string[0];

            private string getNextToken() {
                if (currPos < tokens.Length) return tokens[currPos++];
                currPos = 0;
                tokens = Console.ReadLine().Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                return tokens[currPos++];
            }

            public int nextInt() {
                return int.Parse(getNextToken());
            }

            public string nextString() {
                return getNextToken();
            }

            public double nextDouble() {
                return double.Parse(getNextToken());
            }

            public long nextLong() {
                return long.Parse(getNextToken());
            }
        }

        public static void swap<T>(ref T a, ref T b) {
            T c = a;
            a = b;
            b = c;
        }



        public static void Main(string[] args) {
            StdIn std = new StdIn();

            long x = std.nextLong();
            long y = std.nextLong();
            long m = std.nextLong();

            if (x >= m || y >= m) {
                Console.WriteLine(0);
                return;
            }
            if (x <= 0 && y <= 0) {
                Console.WriteLine(-1);
                return;
            }

            long ans = 0;
            if (x < 0) {
                ans += (-x) / y;
                x += ans * y;
            }
            if (y < 0) {
                ans += (-y) / x;
                y += ans * x;
            }

            while (x < m && y < m) {
                ++ans;
                if (x < y) x += y;
                else y += x;
            }

            Console.WriteLine(ans);

            //Console.ReadLine();
        }
