    class Program
    {
        static void Main(string[] args)
        {
            string[] str = Console.ReadLine().Split();
            int a, b, c, d;
            a = int.Parse(str[0]);
            b = int.Parse(str[1]);
            c = int.Parse(str[2]);
            d = int.Parse(str[3]);
            a = int.Parse(str[0]);
            if (a == b &&  c==d )
            {
                Console.WriteLine(0 + "/" + 1);return;
            }
                int ad = a * d;
                int bc = b * c;
                int up = Math.Abs(ad - bc);
                int dow = Math.Max(ad,bc);
                int G = GCD(up, dow);
                if (G==-1)
                {
                    Console.WriteLine(up.ToString() + "/" + dow.ToString());
                }
            else
                    Console.WriteLine((up/G).ToString() + "/" + dow/G);

        }
       public static int GCD(int a, int b)
        {
            double u = Math.Min(a, b);
            double d = Math.Max(a,b);
            int it = (int)u;
            while (true)
            {
                if ((u / it) == Math.Ceiling(u / it * 1.0) && (d / it) == Math.Ceiling(d / it * 1.0))
                {
                    return it;
                }
                it--;
            }
            return -1;

        }
    }
}

