        {
            int n = int.Parse(Console.ReadLine());

            string commands = Console.ReadLine();

            int result = ContigouseCiclesSubstrings(commands);

            Console.WriteLine(result);

            Console.ReadLine();
        }

        public static int ContigouseCiclesSubstrings(string commands)
        {
            int result = 0;
            Dictionary<int, int> dic = new Dictionary<int, int>(commands.Length + 1);
            dic.Add(0, 1);

            int x = 0;
            int y = 0;
            int key;

            foreach (var command in commands)
            {
                switch (command)
                {
                    case 'U': y++;
                        break;
                    case 'R': x++;
                        break;
                    case 'D': y--;
                        break;
                    case 'L': x--;
                        break;
                    default: throw new ArgumentException("Grong command");
                }
                key = GetUniqueKey(x, y);

                if (dic.ContainsKey(key))
                {
                    result += dic[key];
                    dic[key]++;
                }
                else
                    dic.Add(key, 1);
            }

            return result;
        }

        private static int GetUniqueKey(int x, int y)
        { 
            //the hash function is putting the x;y as a single number in 201 base
            return x * 201 + y;
        }
    }
}

