namespace Vasyas_Function
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static IEnumerable<long> Gi()
        {
            yield return 2;
            for (int i = 3;; i += 2)
            {
                yield return i;
            }
        }

        private static void Main(string[] args)
        {
            long x = Next();
            long y = Next();

            var list = new List<long>();
            foreach (long i in Gi())
            {
                if (i*i > x)
                    break;

                while (x%i == 0)
                {
                    list.Add(i);
                    x /= i;
                }
            }
            if (x != 1)
                list.Add(x);

            long count = list.Count == 0 ? y : 0;

            long yy = y;
            long d = 1;
            while (yy > 0 && list.Count > 0)
            {
                long min = list.Select(l => y%l).Concat(new[] {y}).Min();

                count += min;
                y -= min;
                yy -= d*min;

                for (int i = 0; i < list.Count; i++)
                {
                    if (y%list[i] == 0)
                    {
                        y /= list[i];
                        d *= list[i];
                        list.RemoveAt(i);
                        i--;
                    }
                }

                if (list.Count == 0)
                {
                    count += yy/d;
                }
            }

            writer.WriteLine(count);
            writer.Flush();
        }

        private static long Next()
        {
            int c;
            long res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

