using System;

class TheFairNutAndElevator
    {
    static int Main ()
        {
        string[] words = ReadSplitLine (1);
        if (words == null)
            return -1;
        byte n;
        if (!Byte.TryParse (words[0], out n))
            return -1;
        if (n < 1 || n > 100)
            return -1;
        words = ReadSplitLine (n);
        if (words == null)
            return -1;
        byte[] a = new byte[n];
        ushort sumA = 0;
        uint term1 = 0;
        for (byte i = 0; i < n; i++)
            {
            byte ai;
            if (!Byte.TryParse (words[i], out ai))
                return -1;
            if (ai > 100)
                return -1;
            a[i] = ai;
            sumA += ai;
            term1 += Convert.ToUInt32 (i*ai);
            }
        uint ans = 6000000;
        ushort sumSub = sumA;
        uint term2 = 0;
        for (byte i = 0; i < n; i++)
            {
            uint numEU = 4*(term1+term2);
            if (numEU < ans)
                ans = numEU;
            sumSub -= a[i];
            term1 -= sumSub;
            term2 += sumA;
            }
        Console.WriteLine (ans);
        return 0;
        }

