        {
        string line = Console.ReadLine ();
        if (line == null)
            return null;
        char[] delims = new char[2] {' ', '\t'};
        string[] words = line.Split (delims,StringSplitOptions.RemoveEmptyEntries);
        return (words.Length == numWordNeed ? words : null);
        }        
    }

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ProgrammingContest.Codeforces.Round59
{
    class E
    {
        int[][] dx = new int[][]{
            new int[]{2,4,6},
            new int[]{1,3,5,7},
            new int[]{0,2,4,6,8},
            new int[]{1,3,5,7},
            new int[]{2,4,6}
        };

        char[][] cs = new char[5][];
        int[,] id = new int[10, 10];
        List<int> chk = new List<int>();

        bool ok(int x, int y)
        {
            return 0 <= y && y < 5 && dx[y].Contains(x);
        }

        void proc(int x, int y, int dx, int dy)
        {
            int hash = 0;
            for (; ok(x, y); x += dx, y += dy)
            {
                hash |= 1 << id[x, y];
                chk.Add(hash);
            }
        }

        E()
        {
            for (int i = 0; i < 5; i++)
                cs[i] = Console.ReadLine().ToCharArray();

            int state = 0;
            for(int y = 0, idx = 0; y < 5; y++)
                for (int i = 0; i < dx[y].Length; i++)
                {
                    int x = dx[y][i];
                    id[x,y] = idx++;
                    if (cs[y][x] == 'O')
                        state |= 1 << id[x, y];
                }

            for (int y = 0; y < 5; y++)
                for (int i = 0; i < dx[y].Length; i++)
                {
                    int x = dx[y][i];
                    proc(x, y, 2, 0);
                    proc(x, y, 1, 1);
                    proc(x, y, -1, 1);
                }

            bool[] win = new bool[1<<19];
            for (int i = 1; i < 1 << 19; i++)
            {
                foreach (int hash in chk)
                {
                    if ((i & hash) == hash && !win[i ^ hash])
                    {
                        win[i] = true;
                        break;
                    }
                }
            }

            Console.WriteLine(win[state] ? "Karlsson" : "Lillebror");
        }

        public static void Main()
        {
            new E();
        }
    }
}

