                        endOfFile = line == null;
                        if (endOfFile)
                        {
                            break;
                        }

                        if (line.StartsWith(_delim, StringComparison.Ordinal))
                        {
                            break;
                        }

                        nextText.AppendLine(line);
                    }

                    yield return new StringReader(nextText.ToString());

                    if (endOfFile)
                    {
                        break;
                    }
                }
            }
        }
#endif
    }
}

