    long maxK = 1000;
    long maxPrime = 2 * 1000000 + 10;
    int[] minDiv;
    List<long> primes = new List<long>();
    void solve()
    {
        getDiv();
        long a = nextLong();
        long b = nextLong();
        long k = nextLong();
        long res = get(b, k);
        res -= get(a - 1, k);
        println(res);

