    private void getDiv()
    {
        minDiv = new int[maxPrime];
        for (int i = 2; i < minDiv.Length; i++)
            minDiv[i] = i;
        for (int i = 2; i < minDiv.Length; i++)
            if (minDiv[i] == i)
                for (int j = 2 * i; j < minDiv.Length; j += i)
                    if (minDiv[j] == j)
                        minDiv[j] = i;
    }

    private long get(long n, long k)
    {
        if (n <= 0)
            return 0;
        if (!prime(k))
            return 0;
        long res=0;
        if (k >= maxK)
        {

            if (k <= n)
                res++;
            for (long x = k; x * k <= n; x++)
                if (minDiv[x] >= k)
                    res++;
            return res;
        }
        else
        {
            for(int i=2;i<k;i++)
                if (minDiv[i] == i)
                {
                    primes.Add(i);
                }

            res =rec(0, n/k);
            res = n/k - res;
            primes = new List<long>();
        }
        return res;
    }

    private long rec(int at, long n)
    {
        if (at >= primes.Count)
            return 0;
        if (n < primes[at])
            return 0;
        long res = n / primes[at];
        res+=rec(at+1,n);
        res -= rec(at + 1, n / primes[at]);
        return res;

    }

    bool prime(long p)
    {
        for (int i = 2; i * i <= p; i++)
            if (p % i == 0)
                return false;
        return true;
