using System;
using System.Collections.Generic;
using System.Linq;

public class HelloWorld {
    static public void Main () {
        SolveCodeForces();
        // System.Console.WriteLine(PrimeHelpers.PollardRho(new Random(), 10967535067ul));
    }

    public static void SolveCodeForces() {
        var ab = Console.ReadLine().Split().Select(long.Parse).ToArray();
        var a = ab[0];
        var b = ab[1];

        System.Console.WriteLine(Math.Min(Solve(a, b), Solve(b, a)));
    }

    public static long Solve(long a, long b) {
        var alowdivs = GetLowDivisors(a).ToArray();

        // System.Console.WriteLine(new {a, b});
        // System.Console.WriteLine("alowdivs = " + string.Join(" ", alowdivs));

        var p = long.MaxValue;

        foreach (var x in GetLowDivisors(a+b)) {
            var y = (a+b) / x;
            // a+b = xy,  x <= sqrt(a+b),  y >= sqrt(a+b)
            var i = BinarySearchRightmost(alowdivs, ad => ad - x);
            // System.Console.WriteLine(new { x, y, i });
            if ((i >= 0) && (a / alowdivs[i]) <= y) {
                // System.Console.WriteLine("Found a solution with perimeter " + (2L * (x + y)));
                p = Math.Min(p, 2L * (x + y));
            }
        }

        return p;
    }

    public static IEnumerable<long> GetLowDivisors(long x) {
        yield return 1L;
        if (x % 2L == 0) yield return 2L;

        var sqrt = Math.Sqrt(x);
        for (var d = 3L; d <= sqrt; d++)
            if (x % d == 0)
                yield return d;
    }

    private static int BinarySearchRightmost<T>(IList<T> arr, Func<T, long> compare) {
        var a = 0;
        var b = arr.Count;
        while (a < b) {
            var mid = (a + b) / 2;
            var cmp = compare(arr[mid]);

            if (cmp <= 0)
                a = mid + 1;
            else
                b = mid;
        }
        return a - 1;
    }
}

