public class Solver
{
    private long[] pows = new[]
    {
        1, 11, 111, 1111, 11111, 111111, 1111111, 11111111, 111111111, 1111111111, 11111111111, 111111111111, 1111111111111,
        11111111111111, 111111111111111, 1111111111111111
    };

    int Fun(long t)
    {
        if (t < 10)
            return (int)(t > 6 ? 13 - t : t);

        int k = 0;
        while (pows[k] <= t)
            k++;

        int tp = (int)((pows[k] - t) / pows[k - 1]);
        int ret = Fun(pows[k] - t - tp * pows[k - 1]) + k + 1 + tp * k;

        tp = (int)(t / pows[k - 1]);
        ret = Math.Min(ret, Fun(t - tp * pows[k - 1]) + tp * k);

        return ret;
    }

    public object Solve()
    {
        return Fun(ReadLong());
    }

