namespace DivisaoConquista
{
    public static class Operacao
    {
        static public long[] Vetor; //vetor auxiliar

        static public long Calcula(long n, int i)
        {
            long m = n / Vetor[i]; //auxiliar para dividir o número {aplicação da técnica}
            n = n % Vetor[i]; //atualização de n para o resto da divisão

            if (n == 0) //Se chegar ao fim
                return m * i; //auxiliar * 'posição' atual
            else //retorna o produto do auxiliar pelo menor valor entre a qtd de 1 para o número e a posição anterior e para a 
                return m * i + Math.Min(Calcula(n, i - 1), i + Calcula(Vetor[i] - n, i - 1));
        }
    }
    class Program
    {
