        {
            long n;
            long[] vetor = new long[17];

            for (int i = 1; i < vetor.Length; i++)
            {
                vetor[i] = vetor[i - 1] * 10 + 1;
            }

            Operacao.Vetor = vetor;
            n = long.Parse(Console.ReadLine());
            Console.Write(Operacao.Calcula(n, 16));
        }
    }
