    internal class Program
    {
        private static readonly StreamReader reader =
            new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);

        private static readonly StreamWriter writer =
            new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            long n = long.Parse(reader.ReadLine());

            var nn = new List<long>();
            nn.Add(1);
            nn.Add(1);
            for (int i = 1;; i++)
            {
                long next = nn[i]*10 + 1;
                nn.Add(next);
                if (next > n)
                    break;
            }

            int min = int.MaxValue;

            find(n, nn.Count - 1, nn, 0, ref min);


            writer.WriteLine(min);
            writer.Flush();
        }

        private static void find(long n, int index, List<long> nn, int sum, ref int min)
        {
            if (n == 0)
            {
                if (min > sum)
                    min = sum;
            }
            if (index <= 0)
                return;

            for (int i = -10; i < 11; i++)
            {
                if (n == nn[index]*i)
                {
                    find(n - nn[index]*i, index - 1, nn, sum + index*Math.Abs(i), ref min);
                    break;
                }
            }

            for (int i = -10; i < 11; i++)
            {
                if (n < nn[index] * i)
                {
                    find(n - nn[index] * i, index - 1, nn, sum + index * Math.Abs(i), ref min);
                    break;
                }
            }

            for (int i = 10; i > -11; i--)
            {
                if (n > nn[index] * i)
                {
                    find(n - nn[index] * i, index - 1, nn, sum + index * Math.Abs(i), ref min);
                    break;
                }
            }
        }
    }
}

