namespace ConsoleApplication1.BFS
{
    class NewYearFireworks
    {
        class Node
        {
            public int Level { get; set; }
            public int Direction { get; set; }
            public int X { get; set; }
            public int Y { get; set; }
        }

        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var t = new int[N];
            var s = Console.ReadLine().Split(' ').ToArray();
            for (var i = 0; i < N; i++)
            {
                t[i] = int.Parse(s[i]);
            }

            var directions = new int[][] {
                new int []{0,1},
                new int []{1,1},
                new int []{1,0},
                new int []{1,-1},
                new int []{0,-1},
                new int []{-1,-1},
                new int []{-1,0},
                new int []{-1,1}
            };


            var visited = new bool[600, 600];

            var q = new Queue<Node>();
            q.Enqueue(new Node()
            {
                Level = 0,
                Direction = 0,
                X = 300,
                Y = 300
            });
            visited[300, 300] = true;
            var res = 1;
            for (var k = 0; k < N; k++)
            {
                var used = new bool[600, 600, 8];
                var queue = new Queue<Node>();
                while (q.Count > 0)
                {
                    var current = q.Dequeue();

                    for (var i = 1; i < t[k]; i++)
                    {
                        if (!visited[current.Y + i * directions[current.Direction][0], current.X + i * directions[current.Direction][1]])
                        {
                            res++;
                            visited[current.Y + i * directions[current.Direction][0], current.X + i * directions[current.Direction][1]] = true;
                        }
                    }
                    current.Y += (t[current.Level] - 1) * directions[current.Direction][0];
                    current.X += (t[current.Level] - 1) * directions[current.Direction][1];


                    if (current.Level == N - 1)
                    {
                        continue;
                    }
                    var direction = (current.Direction + 1) % 8;
                    if (!used[current.Y + directions[direction][0], current.X + directions[direction][1], direction])
                    {
                        used[current.Y + directions[direction][0], current.X + directions[direction][1], direction] = true;
                        queue.Enqueue(new Node()
                        {
                            Direction = direction,
                            Level = current.Level + 1,
                            Y = current.Y + directions[direction][0],
                            X = current.X + directions[direction][1]
                        });
                    }
                    if (!visited[current.Y + directions[direction][0], current.X + directions[direction][1]])
                    {
                        visited[current.Y + directions[direction][0], current.X + directions[direction][1]] = true;
                        res++;
                    }

                    direction = (current.Direction - 1) % 8;
                    if (direction < 0)
                    {
                        direction = 8 + direction;
                    }
                    if (!used[current.Y + directions[direction][0], current.X + directions[direction][1], direction])
                    {
                        used[current.Y + directions[direction][0], current.X + directions[direction][1], direction] = true;
                        queue.Enqueue(new Node()
                        {
                            Direction = direction,
                            Level = current.Level + 1,
                            Y = current.Y + directions[direction][0],
                            X = current.X + directions[direction][1]
                        });
                    }
                    if (!visited[current.Y + directions[direction][0], current.X + directions[direction][1]])
                    {
                        visited[current.Y + directions[direction][0], current.X + directions[direction][1]] = true;
                        res++;
                    }

                }
                q = queue;
            }

            Console.WriteLine(res);
        }
    }
}

