    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next();
            }

            var dx = new[] {0, 1, 1, 1, 0, -1, -1, -1};
            var dy = new[] {1, 1, 0, -1, -1, -1, 0, 1};
            var move = new[,]
                           {
                               {7, 1}, {0, 2}, {1, 3}, {2, 4}, {3, 5}, {4, 6}, {5, 7}, {6, 0}
                           };


            var pole = new int[400,400];

            var q = new Queue<Tuple<int, int, int>>();
            q.Enqueue(new Tuple<int, int, int>(200, 200, 0));

            for (int i = 0; i < n; i++)
            {
                var next = new Queue<Tuple<int, int, int>>();
                var f = new bool[400,400,8];

                while (q.Count > 0)
                {
                    Tuple<int, int, int> point = q.Dequeue();
                    int x = point.Item1;
                    int y = point.Item2;
                    for (int j = 0; j < nn[i]; j++)
                    {
                        x = x + dx[point.Item3];
                        y = y + dy[point.Item3];
                        pole[x, y] = 1;
                    }

                    for (int j = 0; j < 2; j++)
                    {
                        int dir = move[point.Item3, j];
                        if (!f[x, y, dir])
                        {
                            f[x, y, dir] = true;
                            next.Enqueue(new Tuple<int, int, int>(x, y, dir));
                        }
                    }
                }

                q = next;
            }

            int count = 0;
            for (int i = 0; i < 400; i++)
            {
                for (int j = 0; j < 400; j++)
                {
                    count += pole[i, j];
                }
            }
            writer.WriteLine(count);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
