        public void Solve()
        {
            var n = sc.Integer();
            var a = sc.Integer(n);
            int[] dx = { 0, 1, 1, 1, 0, -1, -1, -1 };
            int[] dy = { 1, 1, 0, -1, -1, -1, 0, 1 };
            var otaku = new bool[400, 400];
            var dp = new int[400, 400];
            const int X = 200;
            dp[X, X] = 1;
            foreach (var x in a)
            {
                var next = new int[400, 400];
                for (int i = 0; i < 400; i++)
                    for (int j = 0; j < 400; j++)
                    {
                        if (dp[i, j] == 0) continue;
                        for (int d = 0; d < 8; d++)
                        {
                            if ((dp[i, j] >> d & 1) == 0) continue;
                            for (int v = 1; v <= x; v++)
