                            next[i + dx[d] * x, j + dy[d] * x] |= 1 << ((d + 1) % 8);
                            next[i + dx[d] * x, j + dy[d] * x] |= 1 << ((d + 7) % 8);
                        }
                    }

                dp = next;
            }
