            int[] tm = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int a = tm[0], b = tm[1];
            int BDa = FindBiggestDigit(a);
            int BDb = FindBiggestDigit(b);
            int BD = Math.Max(BDa, BDb);
            int nbase = BD + 1;

            Console.WriteLine(SumInBase(a,b,nbase).Length);
           // Console.ReadKey();
        }

        private static int FindBiggestDigit(int a)
        {
            int ans = 0, helper;
            while (a > 0)
            {
                helper = a % 10;
                if (ans < helper)
                    ans = helper;
                a /= 10;
            }

            return ans;
        }

        private static string SumInBase(int a, int b, int nbase)
        {
            string ans = "";
            if (a < b)
            {
                int temp = a;
                a = b;
                b = temp;
            }

            int leftOver = 0;
            while (b > 0)
            {
                int lastDigitA = a % 10;
                int lastDigitB = b % 10;

                int helper = lastDigitA + lastDigitB + leftOver;

                if (helper >= nbase)
                {
                    helper = ConvertToBase(helper, nbase);
                    ans = (helper % 10).ToString() + ans;
                    leftOver = helper / 10;
                }
                else {
                    ans = helper.ToString() + ans;
                    leftOver = 0;
                }



                a /= 10;
                b /= 10;

            }


            while (a > 0)
            {
                int lastDigitA = a % 10;
                int helper = lastDigitA + leftOver;
                if(helper >= nbase)
                {
                    helper = ConvertToBase(helper, nbase);
                    ans = (helper % 10).ToString() + ans;
                    leftOver = helper / 10;
                }
                else
                {
                  ans = helper.ToString() + ans;
                  leftOver = 0;
                }

                a /= 10;
            }


            if (leftOver != 0)
                ans = leftOver.ToString() + ans;


            return ans;
        }

        private static int ConvertToBase(int num, int nbase)
        {
            int ans = 0;
            List<int> lefts = new List<int>();

            while (num > 0)
            {
                lefts.Add(num % nbase);
                num /= nbase;
            }

            for (int i = lefts.Count - 1; i >= 0; i--)
                ans = ans * 10 + lefts[i];

            return ans;
        }
    }
}

