    {
        while (data[0] + data[1] + data[2] > 1)
        {
            if (data[0] == Math.Min(Math.Min(data[0], data[1]), data[2]))
            {
                int delta = 1;// Math.Min(data[1], data[2]);
                data[0] += delta;
                data[1] -= delta;
                data[2] -= delta;
            }
            else if (data[1] == Math.Min(Math.Min(data[0], data[1]), data[2]))
            {
                int delta = 1;// Math.Min(data[0], data[2]);
                data[1] += delta;
                data[0] -= delta;
                data[2] -= delta;
            }
            else
            {
                int delta = 1;// Math.Min(data[0], data[1]);
                data[2] += delta;
                data[0] -= delta;
                data[1] -= delta;
            }
        }
        if (data[0] == 1)
