class Solver
{
    public void Solve(Scanner sc)
    {
        int N, K;long M;
        sc.Make(out N, out K, out M);
        var T = sc.ArrInt;
        Array.Sort(T);
        var res = 0L;
        for(int i = 0; i <= N; i++)
        {
            var sum = 0L;
            for (int j = 0; j < K; j++)
                sum += i * T[j];
            if (sum > M) break;
            var rest = N - i;
            var max = i * (K+1L);
            for(int j = 0; j < K; j++)
            {
                if (rest * T[j] <= M - sum) { sum += rest * T[j];max += rest;continue; }
                max += (M - sum) / T[j];break;
            }
            chmax(ref res, max);
        }
        Console.WriteLine(res);
    }
}

