    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int K = re.i();
        long M = re.i();
        long[] A = re.la();
        Array.Sort(A);
        long sum = 0;
        for(int i=0;i<K;i++){
            sum += A[i];
        }
        long count = 0;
        for(int i=0;i<=N;i++){
            if(i*sum > M){
                break;
            }
            long rest = M - i*sum;
            long c = i*(K+1);
            for(int j=0;j<K;j++){
                for(int k=0;k<N-i;k++){
                    if(rest >= A[j]){
                        c++;
                        rest -= A[j];
                    }
                }
            }
            count = Math.Max(c,count);
        }
        sb.Append(count+"\n");
    }
}
