using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.IO;

class Program
{
	int[][] c;
	int n, m;
	int mod = 1000000007;
	int add(int x, int y)
	{
		x += y;
		return x < mod ? x : x - mod;
	}
	int mul(int x, int y)
	{
		return Convert.ToInt32(Convert.ToInt64(x) * y % mod);
	}
	int[][] newMatrix(int m)
	{
		int[][] ret = new int[m][];
		for (int i = 0; i < m; i++)
			ret[i] = new int[m];
		return ret;
	}
	void calcSum(ref int[][] sum, int[][] a)
	{
		for (int i = 1; i <= m; i++)
			for (int j = 1; j <= m; j++)
				sum[i][j] = add(sum[i - 1][j], a[i][j]);
		for (int i = 1; i <= m; i++)
			for (int j = 1; j <= m; j++)
				sum[i][j] = add(sum[i][j - 1], sum[i][j]);
	}
	int regionSum(int[][] sum, int lx, int rx, int ly, int ry)
	{
		--lx; --ly;
		return add(add(sum[lx][ly],sum[rx][ry]), mod - add(sum[lx][ry],sum[rx][ly]));
	}
	void run()
	{
		String[] str = Console.ReadLine().Split(' ');
		n = Convert.ToInt32(str[0]);
		m = Convert.ToInt32(str[1]);
		int[][][] dp11 = new int[n + 1][][],
			dp10 = new int[n + 1][][],
			dp01 = new int[n + 1][][],
			dp00 = new int[n + 1][][];
		dp11[1] = newMatrix(m + 1);
		dp10[1] = newMatrix(m + 1);
		dp01[1] = newMatrix(m + 1);
		dp00[1] = newMatrix(m + 1);
		for (int i = 1; i <= m; i++)
			for (int j = i; j <= m; j++)
				dp11[1][i][j] = 1;
		int[][] sum = newMatrix(m + 1);
		for (int i = 2; i <= n; i++)
		{
			dp11[i] = newMatrix(m + 1);
			dp10[i] = newMatrix(m + 1);
			dp01[i] = newMatrix(m + 1);
			dp00[i] = newMatrix(m + 1);
			calcSum(ref sum, dp11[i - 1]);
			for (int j = 1; j <= m; j++)
				for (int k = j; k <= m; k++)
				{
					dp11[i][j][k] = add(dp11[i][j][k], regionSum(sum, j, k, j, k));
					dp10[i][j][k] = add(dp10[i][j][k], regionSum(sum, j, k, k + 1, m));
					dp01[i][j][k] = add(dp01[i][j][k], regionSum(sum, 1, j - 1, j, k));
					dp00[i][j][k] = add(dp00[i][j][k], regionSum(sum, 1, j - 1, k + 1, m));
				}
			calcSum(ref sum, dp10[i - 1]);
			for (int j = 1; j <= m; j++)
				for (int k = j; k <= m; k++)
				{
					dp10[i][j][k] = add(dp10[i][j][k], regionSum(sum, j, k, k, m));
					dp00[i][j][k] = add(dp00[i][j][k], regionSum(sum, 1, j - 1, k, m));
				}
			calcSum(ref sum, dp01[i - 1]);
			for (int j = 1; j <= m; j++)
				for (int k = j; k <= m; k++)
				{
					dp01[i][j][k] = add(dp01[i][j][k], regionSum(sum, 1, j, j, k));
					dp00[i][j][k] = add(dp00[i][j][k], regionSum(sum, 1, j, k + 1, m));
				}
			calcSum(ref sum, dp00[i - 1]);
			for (int j = 1; j <= m; j++)
				for (int k = j; k <= m; k++)
				{
					dp00[i][j][k] = add(dp00[i][j][k], regionSum(sum, 1, j, k, m));
				}
		}
		int res = 0;
		for (int i = 1; i <= n; i++)
			for (int j = 1; j <= m; j++)
				for (int k = 1; k <= m; k++)
					res = add(res, mul(n - i + 1, add(add(dp00[i][j][k],dp01[i][j][k]), add(dp10[i][j][k],dp11[i][j][k]))));
		Console.WriteLine(res);
	}
	static void Main(String[] args)
	{
		new Program().run();
	}
}

