    public static Dictionary<long, int> Factorize(long N)
    {
        var dic = new Dictionary<long, int>();
        for (long i = 2; i * i <= N; i++)
        {
            var ct = 0;
            while (N % i == 0)
            {
                ct++;
                N /= i;
            }
            if (ct != 0) dic[i] = ct;
        }
        if (N != 1) dic[N] = 1;
        return dic;
    }
}

