    {
        private static void SolveCase()
        {
            const long MOD = 1000000000 + 7;

            int n = ReadInt();
            long k = ReadLong();
            int[] a = ReadIntArray();

            int m = a.Sum();

            if (m == n)
            {
                Writer.WriteLine(1);
                return;
            }

            long[,] b = new long[m + 1, m + 1];
            for (int i = 0; i < m + 1; i++)
            {
                long l = Math.Max(0, 2 * i * (n + i - 2 * m));
                long r = 2 * (m - i) * (m - i);
                long e = n * (n - 1) - l - r;
                long inv = Inv(n * (n - 1), MOD);
                if (l > 0)
                {
                    b[i, i - 1] = l * inv % MOD;
                }
                b[i, i] = e * inv % MOD;
                if (r > 0)
                {
                    b[i, i + 1] = r * inv % MOD;
                }
            }

            long[,] c = MatrixBinPower(m + 1, b, k, MOD);

            int st = 0;
            for (int i = 0; i < m; i++)
            {
                st += a[n - i - 1];
            }

            long ans = c[st, m];

            Writer.WriteLine(ans);
        }

        public static long Inv(long a, long mod)
        {
            return BinPower(a, mod - 2, mod);
        }

        public static long BinPower(long a, long n, long mod)
        {
            long result = 1;

            while (n > 0)
            {
                if ((n & 1) != 0)
                {
                    result = (result * a) % mod;
                }

                a = (a * a) % mod;
                n >>= 1;
            }

            return result;
        }

        public static long[,] MatrixBinPower(int n, long[,] a, long p, long mod)
        {
            long[,] result = new long[n, n];
            for (int i = 0; i < n; i++)
            {
                result[i, i] = 1;
            }

            while (p > 0)
            {
                if ((p & 1) != 0)
                {
                    result = MatrixMult(n, result, a, mod);
                }

                a = MatrixMult(n, a, a, mod);
                p >>= 1;
            }

            return result;
        }

        public static long[,] MatrixMult(int n, long[,] a, long[,] b, long mod)
        {
            long[,] c = new long[n, n];

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    for (int k = 0; k < n; k++)
                    {
                        c[i, j] = (c[i, j] + a[i, k] * b[k, j]) % mod;
                    }
                }
            }

            return c;
        }

        public static void Solve()
        {
#if DEBUG
