class Solution
{
    public class GCD
    {
        public static int Euclidean(int n1, int n2)
        {
            if (n1 == n2) return n1;
            else if (n1 < n2)
            {
                var tmp = n1;
                n1 = n2;
                n2 = tmp;
            }

            while (n1 % n2 > 0)
            {
                var tmp = n2;
                n2 = n1 % n2;
                n1 = tmp;
            }
            return n2;
        }
        public static long Euclidean(long n1, long n2)
        {
            if (n1 == n2) return n1;
            else if (n1 < n2)
            {
                var tmp = n1;
                n1 = n2;
                n2 = tmp;
            }

            while (n1 % n2 > 0)
            {
                var tmp = n2;
                n2 = n1 % n2;
                n1 = tmp;
            }
            return n2;
        }

        public static long Inverse(long a, long n)
        {
            long x, y = 0;
            EuclideanExt(a, n, out x, out y);
            return x < 0 ? n + x : x;
        }

        public static long EuclideanExt(long n1, long n2, out long x, out long y)
        {
            x = 0;
            y = 1;

            bool r = false;
            if (n1 == n2) return n1;

            else if (n1 < n2)
            {
                r = true;
                var tmp = n1;
                n1 = n2;
                n2 = tmp;
            }
            long q = 0;
            long xl = 1;
            long yl = 0;

            while (n2 > 0)
            {
                q = n1 / n2;

                var tmp = n2;
                n2 = n1 % n2;
                n1 = tmp;

                tmp = x;
                x = xl - q * x;
                xl = tmp;

                tmp = y;
                y = yl - q * y;
                yl = tmp;


            }
            x = xl;
            y = yl;
            if (r)
            {
                x = yl;
                y = xl;
            }
            return x * n1 + y * n2;
        }
    }

    public static Tuple<long, long>[,] multiply(Tuple<long, long>[,] m1, Tuple<long, long>[,] m2)
    {
        Tuple<long, long>[,] ret = new Tuple<long, long>[m1.GetLength(0), m2.GetLength(1)];
        for (int i = 0; i < ret.GetLength(0); i++)
            for (int j = 0; j < ret.GetLength(1); j++)
            {
                ret[i, j] = new Tuple<long, long>(0, 0);
                for (int k = 0; k < m1.GetLength(1); k++)
                    ret[i, j] = sum(ret[i, j], prod(m1[i, k], m2[k, j]));
            }
        return ret;
    }

    public static Tuple<long, long>[,] recPow(Tuple<long, long>[,] m, long pow)
    {
        if (pow == 1)
            return m;

        var powered = recPow(m, pow / 2);
        var mult = multiply(powered, powered);
        if (pow % 2 == 1)
        {

            mult = multiply(mult, m);
        }
        return mult;
    }

    static Tuple<long, long> sum(Tuple<long, long> a, Tuple<long, long> b)
    {
        if (a.Item1 == 0)
            return b;
        if (b.Item1 == 0)
            return a;
        return Tuple.Create(
            ((a.Item1 * b.Item2) % mod + (b.Item1 * a.Item2) % mod) % mod,
            (a.Item2 * b.Item2) % mod
        );
    }

    static Tuple<long, long> prod(Tuple<long, long> a, Tuple<long, long> b)
    {
        return Tuple.Create(
            (a.Item1 * b.Item1) % mod,
            (a.Item2 * b.Item2) % mod
        );
    }


    static Tuple<long, long> PInOneSide(long cnt, long totalcnt)
    {
        return Tuple.Create(
            cnt * (cnt - 1) + (totalcnt - cnt) * (totalcnt - cnt - 1),
            totalcnt * (totalcnt - 1)
        );
    }

    static Tuple<long, long> PIncreaseLeftA(long leftCnt, long leftACnt, long totalcnt)
    {
        return Tuple.Create(
             (leftCnt - leftACnt) * (leftCnt - leftACnt),
            (totalcnt * (totalcnt - 1)) / 2
        );
    }

    static Tuple<long, long> PDecreaseLeftA(long leftCnt, long leftACnt, long totalcnt)
    {
        return Tuple.Create(
            leftACnt * (totalcnt - 2 * leftCnt + leftACnt),
            (totalcnt * (totalcnt - 1)) / 2
        );
    }

    static void CalcCashe(long lowerBnd, long leftCnt, long totalcnt)
    {
        PInOneSideCache = PInOneSide(leftCnt, totalcnt);

        PIncreaseLeftACache = new Tuple<long, long>[leftCnt - lowerBnd + 1];
        PDecreaseLeftACache = new Tuple<long, long>[leftCnt - lowerBnd + 1];
        PSameInBothSideCache = new Tuple<long, long>[leftCnt - lowerBnd + 1];

        for (long i = lowerBnd; i <= leftCnt; i++)
        {
            PIncreaseLeftACache[(int)(i - lowerBnd)] = PIncreaseLeftA(leftCnt, i, totalcnt);
            PDecreaseLeftACache[(int)(i - lowerBnd)] = PDecreaseLeftA(leftCnt, i, totalcnt);
            PSameInBothSideCache[(int)(i - lowerBnd)] = PSameInBothSide(leftCnt, i, totalcnt);
        }
    }
    static Tuple<long, long> PInOneSideCache;
    static Tuple<long, long>[] PSameInBothSideCache;
    static Tuple<long, long>[] PIncreaseLeftACache;
    static Tuple<long, long>[] PDecreaseLeftACache;
    static Tuple<long, long> PSameInBothSide(long leftCnt, long leftACnt, long totalcnt)
    {

        return Tuple.Create(
             (leftCnt - leftACnt) * (totalcnt + 2 * leftACnt - 2 * leftCnt),
            (totalcnt * (totalcnt - 1)) / 2
        );
    }

    const long mod = 1000000007L;
    static void Main(string[] args)
    {

        // var n = int.Parse( Console.ReadLine());
        var tmp = Array.ConvertAll(Console.ReadLine().Trim().Split(), Convert.ToInt64);
        var n = (long)tmp[0];
        var k = tmp[1];

        var arr = Array.ConvertAll(Console.ReadLine().Trim().Split(), Convert.ToByte);

        var leftcnt = (long)arr.Count(el => el == 0);
        var leftAcnt = (long)arr.Where((el, i) => el == 0 && i < leftcnt).Count();
        if (k < (leftcnt - leftAcnt))
        {
            Console.WriteLine("0");
            return;
        }
        if (leftcnt == n || leftcnt == 0)
        {
            Console.WriteLine("1");
            return;
        }



        var lowerBnd = (long)Math.Max(0, (int)(2 * (int)leftcnt - (int)n));

        Tuple<long, long>[,] A = new Tuple<long, long>[(int)(leftcnt - lowerBnd + 1), (int)(leftcnt - lowerBnd + 1)];

        CalcCashe(lowerBnd, leftcnt, n);

        for (int i = 0; i < A.GetLength(0); i++)
        {
            for (int j = 0; j < A.GetLength(0); j++)
            {
                if (i == j)
                {
                    A[i, j] = sum(PInOneSideCache, PSameInBothSideCache[i]);
                }
                else if (i == j + 1)
                {
                    A[i, j] = PIncreaseLeftACache[i - 1];
                }
                else if (i == j - 1)
                {
                    A[i, j] = PDecreaseLeftACache[i + 1];
                }
                else
                {
                    A[i, j] = Tuple.Create<long, long>(0, 0);
                }
            }
        }

        A = recPow(A, k);

        Tuple<long, long>[,] F = new Tuple<long, long>[leftcnt - lowerBnd + 1, 1];
        for (int i = 0; i < F.GetLength(0); i++)
        {
            if (i == leftAcnt - lowerBnd)
            {
                F[i, 0] = Tuple.Create(1l, 1L);
            }
            else
            {
                F[i, 0] = new Tuple<long, long>(0, 0);
            }
        }
        F = multiply(A, F);
        var tpl = F[F.GetLength(0) - 1, 0];
        if (tpl.Item1 == 0)
        {
            Console.WriteLine("0");
            return;
        }
        var gcd = GCD.Euclidean(tpl.Item1, tpl.Item2);
        var ret = Tuple.Create(tpl.Item1 / gcd, tpl.Item2 / gcd);

        var ret2 = ((long)ret.Item1 * GCD.Inverse((long)ret.Item2, (long)mod)) % (long)mod;

        Console.WriteLine($"{ret2}");

    }
}

