    class Program
    {
        private static List<int>[] war;
        private static bool[] p;

        private static bool Check(int i)
        {
            return war[i].Count(e => p[e] == p[i]) <= 1;
        }

        private static void Fix(int i)
        {
            p[i] = !p[i];

            foreach (var e in war[i])
            {
                if (p[e] == p[i] && !Check(e))
                {
                    Fix(e);
                }
            }
        }

        private static void FixAll()
        {
            for (int i = 0; i < p.Length; i++)
            {
                if (!p[i] && !Check(i))
                {
                    Fix(i);                    
                }
            }
        }            

        static void Main(string[] args)
        {
            // var fin = File.OpenText("test.txt");
            // Console.SetIn(fin);

            string[] nm = Console.ReadLine().Split(' ');
            int n = int.Parse(nm[0]);
            int m = int.Parse(nm[1]);

            war = new List<int>[n];
            p = new bool[n];
            for (int i = 0; i < n; i++)
            {
                war[i] = new List<int>();
                p[i] = false;
            }

            for (int i = 0; i < m; i++)
            {
                string[] ab = Console.ReadLine().Split(' ');
                int a = int.Parse(ab[0]) - 1;
                int b = int.Parse(ab[1]) - 1;

                war[a].Add(b);
                war[b].Add(a);
            }

            FixAll();
            Console.WriteLine(string.Concat(p.Select(x => x ? 1 : 0)));

            // fin.Close();
        }
