        int[] tmp = intSplit(' ');
        int n = tmp[0];
        int m = tmp[1];
        int[] type = new int[n];
        List<int>[] edges = new List<int>[n];
        for (int i = 0; i < n; i++)
            edges[i] = new List<int>();
        for (int i = 0; i < m; i++)
        {
            tmp = intSplit(' ');
            int a = tmp[0] - 1;
            int b = tmp[1] - 1;
            edges[a].Add(b);
            edges[b].Add(a);
        }//for i
        Queue<int> que = new Queue<int>();
        for (int i = 0; i < n; i++)
            que.Enqueue(i);
        while (que.Count!=0)
        {
            int deq = que.Dequeue();
            int cnt = 0;
            foreach (int item in edges[deq])
            {
                if (type[item] == type[deq])
                    cnt++;
            }//foreach item
            if (cnt>=2)
            {
                type[deq] ^= 1;
                foreach (int item in edges[deq])
                {
                    if (type[item] == type[deq])
                        que.Enqueue(item);
                }//foreach item
            }//if
        }//while
        StringBuilder sb = new StringBuilder();
        foreach (int item in type)
        {
