    static List<int[]> g;

    class Dsu
    {
        public readonly List<int> parent;

        public Dsu(int n)
        {
            parent = Enumerable.Range(0, n).ToList();
            g = new List<int[]>();
            for (int i = 0; i < n; i++)
                g.Add(new int[] { -1, -1 });
        }

        public int FindSet(int v)
        {
            if (v == parent[v])
                return v;
            return parent[v] = FindSet(parent[v]);
        }

        public void UnionSets(int a, int b)
        {
            a = FindSet(a);
            b = FindSet(b);
            if (a != b)
            {
                parent[a] = parent[b] = parent.Count;
                g.Add(new[] { a, b });
                parent.Add(parent.Count);
            }
        }
    }

    int[] c;
    int[] tree;

    int Cmp(int l, int r)
    {
        return c2[l] > c2[r] ? l : r;
    }

    void Build(int x, int xl, int xr)
    {
        if (xl == xr)
        {
            tree[x] = xl;
            return;        
        }
        int xm = (xl + xr) / 2;
        Build(x * 2, xl, xm);
        Build(x * 2 + 1, xm + 1, xr);
        tree[x] = Cmp(tree[2 * x], tree[2 * x + 1]);
    }

    void Set(int x, int xl, int xr, int idx)
    {
        if (xl == xr)
        {
            c2[xl] = 0;
            return;
        }

        int xm = (xl + xr) / 2;
        if (idx <= xm)
            Set(x * 2, xl, xm, idx);
        else
            Set(x * 2 + 1, xm + 1, xr, idx);
        tree[x] = Cmp(tree[2 * x], tree[2 * x + 1]);
    }

    int Query(int x, int xl, int xr, int l, int r)
    {
        if (l == xl && r == xr)
            return tree[x];
        int xm = (xl + xr) / 2;
        if (r <= xm)
            return Query(x * 2, xl, xm, l, r);
        if (l > xm)
            return Query(x * 2 + 1, xm + 1, xr, l, r);
        return Cmp(Query(x * 2, xl, xm, l, xm), Query(x * 2 + 1, xm + 1, xr, xm + 1, r));
    }

    int n;
    bool[] vis;
    int[] tin, tout, c2;
    int timer;
    void Dfs(int x)
    {
        if (x < n)
            c2[timer] = c[x];
        vis[x] = true;
        tin[x] = timer++;
        foreach (int e in g[x])
            if (e != -1)
                Dfs(e);
        tout[x] = timer;
    }

