        //    else
        //    {
        //        b[i][1] = cnt++;
        //    }
        //}

        var f = new bool[m];
        for (int i = 0; i < q; i++)
        {
            b[i][1]--;
            if (b[i][0] == 2)
                f[b[i][1]] = true;
        }

        var dsu = new Dsu(n);
        for (int i = 0; i < m; i++)
        {
            a[i][0]--;
            a[i][1]--;
            if (!f[i])
                dsu.UnionSets(a[i][0], a[i][1]);
        }

        for (int i = q - 1; i >= 0; i--)
        {
            if (b[i][0] == 1)
            {
                b[i][1] = dsu.FindSet(b[i][1]);
            }
            else
            {
                dsu.UnionSets(a[b[i][1]][0], a[b[i][1]][1]);
            }
        }

        int n2 = dsu.parent.Count;
        tin = new int[n2];
        tout = new int[n2];
        vis = new bool[n2];
        c2 = new int[n2];
        for (int i = n2 - 1; i >= 0; i--)
            if (!vis[i])
                Dfs(i);

        tree = new int[4 * n2];
        Build(1, 0, n2 - 1);
        for (int i = 0; i < q; i++)
            if (b[i][0] == 1)
            {
                int x = Query(1, 0, n2 - 1, tin[b[i][1]], tout[b[i][1]] - 1);
                Write(c2[x]);
                Set(1, 0, n2 - 1, x);
