    {
        private const int MOD = (int)1e9 + 7,
            INF = 1000000010;

        public void Solve()
        {
            int N = ReadInt;
            int K = ReadInt;

            if (N == 1 && K == 1)
            {
                Console.WriteLine(0);
                return;
            }

            long now = 1;
            int i = 1;
            while (true)
            {
                now += ++i;
                if (now < K) continue;

                int actionCount = i;
                long mustEatCount = now - K;
                if (actionCount + mustEatCount == N ) break;
            }

            Console.WriteLine(now - K );

        }
    }
