namespace CodeForces
{
    class Program
    {
        static void Main(string[] args)
        {
            var arr = Console.ReadLine().Split(' ');
            var p0 = Int32.Parse(arr[0]);
            var t0 = long.Parse(arr[1]);
            arr = Console.ReadLine().Split(' ');
            var p1 = Int32.Parse(arr[0]);
            var t1 = long.Parse(arr[1]);
            arr = Console.ReadLine().Split(' ');
            var h = Int32.Parse(arr[0]);
            var s = Int32.Parse(arr[1]);
            Console.WriteLine(GetMinCost(t0, t1, p0, p1, s, h));

            // Test();

            // BruteGetMaxVal("110000");
        }

        private static long GetMinCost(long t0, long t1, int p0, int p1, int s, int h)
        {
            var bags = new List<(int,long)>
            {
                (p0-s,t0),
                (p1-s,t1)
            }; 
            var allCost0 = (h/(p0-s) + 1) * t0;
            var allCost1 = (h/(p1-s) + 1) * t1;
            var maxCost = allCost0<=allCost1?allCost0:allCost1;
            var damage = 0;
            var t0Count = 1;
            while(damage < h && t0 * t0Count < maxCost)
            {
                if (t0 * t0Count >= t1)
                {
                    damage = (t0Count-1) * (p0 - s) +
                        (int)(t0 * t0Count / t1 - 1) * (p1 - s) + 
                        (p0 + p1 -s);
                    bags.Add((damage, t0 * t0Count));
                }
                else
                {
                    damage = t0Count * (p0-s);
                }
                t0Count++;
            }

            damage = 0;
            var t1Count = 1;
            while (damage < h && t1 * t1Count < maxCost)
            {
                if (t1 * t1Count >= t0)
                {
                    damage = (t1Count-1) * (p1 - s) +
                        (int)(t1 * t1Count / t0 - 1) * (p0 - s) + 
                        (p0 + p1 -s);
                    bags.Add((damage, t1 * t1Count));
                }
                else
                {
                    damage = t1Count * (p1-s);
                }
                t1Count++;
            }
            return GetMinCost(h, bags);
        }

        private static long GetMinCost(int h, List<(int, long)> bags)
        {
            var newBags = new List<(int, long)>();
            foreach(var (damage, cost) in bags)
            {
                var newDamage = damage;
                var newCost = cost;
                while(newDamage < h + damage)
                {
                    newBags.Add((newDamage, newCost));
                    newDamage<<=1;
                    newCost<<=1;
                }
            }
            return Get01MinCost(h, newBags);
        }

        private static long Get01MinCost(int h, List<(int, long)> bags)
        {
            var n = bags.Count;
            var dp = new long[h+1];
            for(var i = 1;i<=h;i++)
            {
                dp[i] = long.MaxValue;
            }
            foreach(var (damage, cost) in bags)
            {
                var jBegin = h - damage;
                if (jBegin < 0) jBegin = 0;
                for(var j = jBegin;j<=h;j++)
                {
                    if (dp[j] != long.MaxValue && dp[j] + cost < dp[h])
                    {
                        dp[h] = dp[j] + cost;
                    }
                }
                for(var j= h - damage-1;j>=0;j--)
                {
                    if (dp[j] != long.MaxValue && dp[j] + cost < dp[j+ damage])
                    {
                        dp[j+ damage] = dp[j] + cost;
                    }
                }

                
            }
            return dp[h];
        }
        
    }
}

