﻿using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Diagnostics;
using System.Numerics;
using Enu = System.Linq.Enumerable;

class Program
{
    static readonly int Mod = (int)1e9 + 7;

    public void Solve()
    {
        int N = Reader.Int();
        int K = Reader.Int();
        long[] Y = new long[K + 2];

        for (int i = 1; i < Y.Length; i++)
            Y[i] = (Y[i - 1] + ModPower(i, K, Mod)) % Mod;

        long ans = new LagrangeInterpolation(Y, Mod).Get(N);
        Console.WriteLine(ans);
        Console.ReadLine();
    }

    class LagrangeInterpolation
    {
        readonly int N;
        readonly long M;
        readonly long[] Y, C;

        public LagrangeInterpolation(long[] Y, long mod)
        {
            this.N = Y.Length - 1;
            this.M = mod;
            this.Y = Y;
            this.C = new long[N + 1];
            long q = 1;
            for (int i = 1; i <= N; i++)
                q = q * Mod(-i) % mod;
            C[0] = Mod(Y[0] * ModInverse(q, mod));
            for (int i = 1; i <= N; i++)
            {
                q = Mod(q * ModInverse(-N + (i - 1), mod));
                q = Mod(q * i);
                C[i] = Mod(Y[i] * ModInverse(q, mod));
            }
        }

        public long Get(long x)
        {
            if (x <= N) return Y[x];
            long fraq = 1;
            for (int i = 0; i <= N; i++)
                fraq = Mod(fraq * (x - i));
            long res = 0;
            for (int i = 0; i <= N; i++)
            {
                res += Mod(Mod(C[i] * fraq) * ModInverse(x - i, M));
                if (res >= M) res -= M;
            }
            return res;
        }

        long Mod(long x)
        {
            if (x >= M) return x % M;
            else if (x < 0) return (x % M + M);
            else return x;
        }
    }

    static long ModPower(long x, long n, long mod) // x ^ n
    {
        long res = 1;
        while (n > 0)
        {
            if ((n & 1) == 1) res = (res * x) % mod;
            x = (x * x) % mod;
            n >>= 1;
        }
        return res;
    }
    static long ModInverse(long N, long mod)
    {
        long x = 0, y = 0;
        N = (N % mod + mod) % mod;
        ExtGCD(N, mod, ref x, ref y);
        return (x % mod + mod) % mod;
    }
    static long ExtGCD(long a, long b, ref long x, ref long y)
    {
        if (b == 0) { x = 1; y = 0; return a; }
        long res = ExtGCD(b, a % b, ref y, ref x);
        y -= (a / b) * x;
        return res;
    }
}


