    private long go(int y1, int y2, int rem, int a, int b)
    {
        if (a < 0 || b < 0)
            return 0;
        if (rem == 0)
        {
            if (a == 0 && b == 0)
                return 1;
            else
                return 0;
        }
        if (dp[y1, y2, rem, a, b] != -1)
            return dp[y1, y2, rem, a, b];
        long ret = 0;
        for (int y3 = 1; y3 <= 4; y3++)
        {
            if (y3 == y2)
                continue;
            if (y2 > y1 && y2 > y3)
            {
                ret += go(y2, y3, rem - 1, a - 1, b);
            }
            else if (y2 < y1 && y2 < y3)
                ret += go(y2, y3, rem - 1, a, b - 1);
            else
                ret += go(y2, y3, rem - 1, a, b);
        }
        return dp[y1, y2, rem, a, b]=ret;
