using System;
using System.Collections.Generic;
using System.Linq;

namespace CodeForces
{
    class Program
    {
        static void Main(string[] args)
        {
            
            var n = Int32.Parse(Console.ReadLine());

            Console.WriteLine(GetVal(n));
        }


        const int MOD_VAL = 1000000007;
        private static int GetVal(int n)
        {
            var primes = GetAllPrimes(n);
            var res = 0;
            var primeCache = GetPrimeCache(primes, n);
            var dfsSolver = new DFSSolver(primeCache);
            for(var i = 1;i<=n-2;i++)
            {
                var primeFactors = GetPrimeFactors(i, primes);
                var primeMap = new Dictionary<int,int>();
                foreach(var (prime, primeCnt) in primeFactors)
                {
                    primeMap[prime] = primeCnt;
                }
                dfsSolver.SetPrimeMap(primeMap);
                dfsSolver.SetPrimeFactors(GetPrimeFactors(n-i, primes));
                res = (int)((res + (long)dfsSolver.GetRes()*i ) % MOD_VAL);
            }
            return res;
        }

        private class DFSSolver
        {
            private int _res;
            private Dictionary<int,int> _primeMap;
            private List<(int,int)> _primeFactors;

            private Dictionary<int, int[]> _primeCache;
            public DFSSolver(Dictionary<int, int[]> primeCache)
            {
                _primeCache = primeCache;
            }

            public void SetPrimeMap(Dictionary<int,int> primeMap)
            {
                _primeMap = primeMap;
            }

            public void SetPrimeFactors(List<(int,int)> primeFactors)
            {
                _primeFactors = primeFactors;                
            }

            public int GetRes()
            {
                _res = 0;
                DFS(0,1);
                var tmp = 1;
                foreach(var (prime, cnt) in _primeFactors)
                {
                    if(_primeMap.ContainsKey(prime))
                    {
                        if(cnt > _primeMap[prime])
                        {
                            tmp*= _primeCache[prime][cnt-_primeMap[prime]];
                        }
                    }
                    else
                    {
                        tmp*= _primeCache[prime][cnt];
                    }
                }
                _res-=tmp;
                if (_res < MOD_VAL) _res+=MOD_VAL;
                return _res;
            }

            private void DFS(int index, int val)
            {
                if(index == _primeFactors.Count)
                {
                    _res = (_res + val) % MOD_VAL;
                    return;
                }
                var prime = _primeFactors[index].Item1;
                var cnt = _primeFactors[index].Item2;
                for(var i = 0;i<= cnt;i++)
                {
                    var append = 1;
                    if(_primeMap.ContainsKey(prime))
                    {
                        if(i > _primeMap[prime])
                        {
                            append = _primeCache[prime][i - _primeMap[prime]];
                        }
                    }
                    else
                    {
                        append = _primeCache[prime][i];
                    }

                    if (i < cnt)
                    {
                        append = append * (prime - 1) * _primeCache[prime][cnt-i-1]; 
                    }
                    DFS(index+1, (int)((long)val * append % MOD_VAL));
                }
            }
        }

        private static Dictionary<int, int[]> GetPrimeCache(List<int> primes, int n)
        {
            var primeCache = new Dictionary<int, int[]>();
            foreach(var prime in primes)
            {
                var list = new List<int>();
                list.Add(1);
                var tmp = prime;
                while(tmp <= n)
                {
                    list.Add(tmp);
                    tmp*=prime;
                }
                primeCache[prime] = list.ToArray();
            }
            return primeCache;
        }

        private static int GetLCM(int num0, int num1)
        {
            return (int)((long)num0 * num1 /GetGCD(num0, num1));
        }

        private static int GetGCD(int num0, int num1)
        {
            if (num0 < num1)
            {
                var tmp = num1;
                num1 = num0;
                num0 = tmp;
            }
            while (num1 > 0)
            {
                var tmp = num1;
                num1 = num0 % num1;
                num0 = tmp;
            }
            return num0;
        }

        static List<int> GetAllPrimes(int n)
        {
            var isNotPrimes = new bool[n+1];
            var primes = new List<int>();
            for(var i = 2;i<=n;i++)
            {
                if (!isNotPrimes[i])
                {
                    primes.Add(i);
                    var num = i * 2;
                    while(num <= n)
                    {
                        isNotPrimes[num]= true;
                        num+=i;
                    }
                }
            }
            return primes;
        }

        static List<(int,int)> GetPrimeFactors(int num, List<int> primes)
        {
            var primeFactors = new List<(int,int)>();
            foreach(var prime in primes)
            {
                if (num < prime * prime) break;
                var cnt = 0;
                while(num % prime == 0)
                {
                    cnt++;
                    num/=prime;
                }
                if (cnt > 0)
                {
                    primeFactors.Add((prime, cnt));
                }
            }
            if (num!=1)
            {
                primeFactors.Add((num, 1));
            }
            return primeFactors;
        }

        static int[] GetFactors(int num, List<int> primes)
        {
            return GetFactors(GetPrimeFactors(num, primes));
        }

        static int[] GetFactors(List<(int,int)> primeFactors)
        {
            var factorCnt = 1;
            foreach(var (_, cnt) in primeFactors)
            {
                factorCnt*=cnt+1;
            }
            var factors = new int[factorCnt];
            var preCnt = 1;
            var index = 1;
            factors[0] = 1;
            foreach(var (prime, cnt) in primeFactors)
            {
                var factor = prime;
                for(var i = 1;i<=cnt;i++)
                {
                    for(var j = 0;j<preCnt;j++)
                    {
                        factors[index++] = factors[j] * factor;
                    }
                    factor *= prime;
                }
                preCnt = index;
            }
            return factors;
        }

        
    }
}

