public class Program
{
    int N;
    List<int>[] Div;

    int[] Sieve;

    int[] S;

    public void Solve()
    {


        var sc = new Scanner();
        N = sc.NextInt();
        Div = new List<int>[N + 1];
        for (int i = 1; i <= N; i++)
        {
            Div[i] = new List<int>();
        }

        for (int i = 1; i <= N; i++)
        {
            for (int j = i; j <= N; j += i)
            {
                Div[j].Add(i);
            }
        }

        S = new int[N + 1];
        S[1] = 0;
        for (int i = 2; i <= N; i++)
        {
            S[i] = i - 1;
            foreach (int d in Div[i])
            {
                if (i == d) continue;
                // Console.WriteLine($"{S[i / d]}");
                S[i] -= S[d];
            }
        }

        //for (int i = 1; i < 20; i++)
        //{
        //    Console.WriteLine($"{i} {F2(i)} {S[i]}");
        //}

        ModInt ans = 0;
        for (int c = 1; c + 2 <= N; c++)
        {
            int sumAB = N - c;
            foreach (int gcdAB in Div[sumAB])
            {
                int d = sumAB / gcdAB;

                // a + b = d
                // gcd(a,b) = 1


                ans += S[d] * MathEx.LCM(c, gcdAB);
            }
        }

        Console.WriteLine(ans);


    }
    ModInt F2(int n)
    {
        int cnt = 0;
        for (int a = 1; a + 1 <= n; a++)
        {
            cnt += MathEx.GCD(a, n - a) == 1 ? 1 : 0;
        }
        return cnt;
    }

    public static void Main(string[] args) => new Program().Solve();
