    class Program
    {
        const int MAXN = 1000000007;
        static long QMul(long a, long b)
        {
            long res = 1;
            long tmp = a;

            while(b != 0)
            {
                if((b & 1L) == 1)
                {
                    res *= tmp;
                    res %= MAXN;
                }
                tmp *= tmp;
                tmp %= MAXN;
                b >>= 1;
            }

            return res;
        }

        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            long[] arr = input.Select(x => Convert.ToInt64(x)).ToArray();

            long n = arr[0];
            long m = arr[1];
            long k = arr[2];

            if(k == -1 && (n+m) % 2 == 1)
            {
                Console.WriteLine("0");
            }
            else
            {
                Console.WriteLine(QMul(QMul(2, (m - 1)), (n - 1)).ToString());
            }
        }
    }
