public class HelloWorld {
    public static void SolveCodeForces() {
        var n = cin.NextInt();
        var m = cin.NextInt();
        var a = cin.NextInt();
        var b = cin.NextInt();

        var Arr = Helpers.CreateArray(n, _ => new ulong[m]);
        {
            var g0 = cin.NextUlong();
            var x = cin.NextUlong();
            var y = cin.NextUlong();
            var z = cin.NextUlong();
            for (var i = 0; i < n; i++)
                for (var j = 0; j < m; j++) {
                    Arr[i][j] = g0;
                    g0 = (g0 * x + y) % z;
                }
        }

// System.Console.WriteLine("Arr:");
// foreach (var row in Arr)
//     System.Console.WriteLine(row.Join());

        var QVers = new Deque<QueueItem>[m];
        for (var j = 0; j < m; j++) {
            var Q = new Deque<QueueItem>();
            for (var i = 0; i < a; i++) {
                var x = Arr[i][j];
                AppendRight(Q, i, x);
            }
            QVers[j] = Q;
        }

        var ans = 0ul;

        for (var i = a - 1; i < n; i++) {
            var rowAns = 0ul;

            var Q = new Deque<QueueItem>();
            for (var j = 0; j < b; j++) {
                AppendRight(Q, j, QVers[j].Left.Val);
            }

            rowAns += Q.Left.Val;
            for (var j = b; j < m; j++) {
                Shift(Q, j - b);
                AppendRight(Q, j, QVers[j].Left.Val);
                rowAns += Q.Left.Val;
            }

            for (var j = 0; j < m; j++) {
                Shift(QVers[j], i - a + 1);
                if (i + 1 < n)
                    AppendRight(QVers[j], i + 1, Arr[i + 1][j]);
            }

// System.Console.WriteLine(new {i, rowAns});
            ans += rowAns;
        }
// System.Console.WriteLine(new {brute = SolveBrute(Arr, n, m, a, b)});

        System.Console.WriteLine(ans);
    }

    static ulong SolveBrute(ulong[][] Arr, int n, int m, int a, int b) {
        var ans = 0ul;

        for (var i = a-1; i < n; i++)
            for (var j = b-1; j < m; j++) {
                var min = Arr[i][j];
                for (var ii = 0; ii < a; ii++)
                    for (var jj = 0; jj < b; jj++)
                        min = Math.Min(min, Arr[i - ii][j - jj]);
                ans += min;
            }

        return ans;
    }

    static void AppendRight(Deque<QueueItem> Q, int i, ulong x) {
        while (Q.Count > 0 && Q.Right.Val >= x) Q.RemoveRight();
        Q.AppendRight(new QueueItem{ Val = x, Index = i });
    }

    static void Shift(Deque<QueueItem> Q, int i) {
        if (Q.Left.Index == i) Q.RemoveLeft();
    }

