public class Deque<T> : IEnumerable<T> {
    private T[] arr;
    private int index;
    private int count;
    private int n;

    public Deque(T[] arr) {
        this.arr = arr;
        n = arr.Length;
        count = arr.Length;
    }

    public Deque(int capacity = 8) {
        n = capacity;
        arr = new T[capacity];
    }

    public int Count => count;

    public T Left => this[0];
    public T Right => this[count - 1];

    public T this[int i] {
        get {
            if (i < 0 || i >= count) throw new InvalidOperationException(string.Format("Index {0} is out of range (count = {1})", i, count));
            return arr[(index + i) % n];
        }
    }

    public void AppendRight(T val) {
        EnsureSize();
        arr[(index + count) % n] = val;
        count++;
    }

    public void AppendLeft(T val) {
        EnsureSize();
        index = (index + n - 1) % n;
        arr[index] = val;
        count++;
    }

    public T RemoveLeft() {
        if (count == 0) throw new InvalidOperationException("Can't remove left because deque is empty");

        var result = arr[index];
        index = (index + 1) % n;
        count--;
        return result;
    }

    public T RemoveRight() {
        if (count == 0) throw new InvalidOperationException("Can't remove right because deque is empty");

        var result = arr[(index + count + n - 1) % n];
        count--;
        return result;
    }

    private void EnsureSize() {
        if (count == arr.Length) {
            var newArr = new T[arr.Length * 2];
            var left = Math.Min(count, arr.Length - index);
            Array.Copy(arr, index, newArr, 0, left);
            if (left < count)
                Array.Copy(arr, 0, newArr, left, count - left);
            arr = newArr;
            index = 0;
            n = newArr.Length;
        }
    }

    public IEnumerator<T> GetEnumerator()
    {
        for (var i = 0; i < count; i++) {
            yield return arr[(index + i) % n];
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}

