        static long solve(int a, int b) {
            f = new long[b + 1];
            f[b] = 1;
            for (int i = 0; i < a; ++i) {
                for (int j = 0; j < b; ++j) {
                    f[j] = (f[j] + f[j + 1] * (j + 1)) % MOD;
                }
            }

            long ans = 0;
            for (int i = 0; i <= b; ++i) {
                ans = (ans + f[i]) % MOD;
            }

            return ans;
        }
