            cout = Console.Out;
            int a, b, c;
            cin.Read(out a).Read(out b).Read(out c);
            long ans = 1;
            ans = (ans * solve(a, b)) % MOD;
            ans = (ans * solve(a, c)) % MOD;
            ans = (ans * solve(c, b)) % MOD;
            cout.WriteLine(ans);

        }
