    internal class Task : IDisposable
    {
        private readonly InputReader sr;
        private readonly TextWriter sw;
        private bool isDispose;

        const long mod = 998244353L;

        public Task(InputReader sr, TextWriter sw)
        {
            this.sr = sr;
            this.sw = sw;
        }

        public void Solve()
        {
            var a = sr.NextInt32();
            var b = sr.NextInt32();
            var c = sr.NextInt32();
            var facts = Facts(Math.Max(a, Math.Max(b, c)));
            var coeffs = BinCoeff(Math.Max(a, Math.Max(b, c)));
            sw.WriteLine(((Func(a, b, facts, coeffs)*Func(b, c, facts, coeffs)%mod)*Func(c, a, facts, coeffs))%mod);
        }

        private long[] Facts(int max)
        {
            var facts = new long[max + 1];
            facts[0] = 1L;
            for (var i = 1; i <= max; i++) {
                facts[i] = (facts[i - 1] * i) % mod;
            }

            return facts;
        }

        private long Func(long a, long b, long[] facts, long[,] binCoeff)
        {
            var max = Math.Max(a, b);
            var r = 0L;
            for (var i = 0; i <= max; i++) {
                r = (r + binCoeff[a, i] * binCoeff[b, i]%mod * facts[i] % mod) % mod;
            }

            return r;
        }

        private long[,] BinCoeff(int max)
        {
            var coeff = new long[max + 1, max + 1];
            for (var i = 0; i <= max; i++) {
                coeff[i, 0] = 1;
                coeff[i, i] = 1;
            }
            for (var i = 1; i <= max; i++) {
                for (var j = 1; j <= i; j++) {
                    coeff[i, j] = (coeff[i - 1, j] + coeff[i - 1, j - 1])%mod;
                }
            }

            return coeff;
        }

        ~Task()
        {
            Dispose(false);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        private void Dispose(bool disposing)
        {
            if (!isDispose) {
                if (disposing) {
                    if(sr != null)
                        sr.Dispose();

                    if(sw != null)
                        sw.Dispose();
                }

                isDispose = true;
            }   
        }
    }
}

internal class InputReader : IDisposable
{
    private bool isDispose;
    private readonly TextReader sr;
    private string[] buffer;
    private int seek;

    public InputReader(TextReader stream)
    {
        sr = stream;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public string NextString()
    {
        var result = sr.ReadLine();
        return result;
    }

    public int NextInt32()
    {
        return Int32.Parse(ReadNextToken());
    }

    private string ReadNextToken()
    {
        if (buffer == null || seek == buffer.Length) {
            seek = 0;
            buffer = NextSplitStrings();
        }

        return buffer[seek++];
    }

    public long NextInt64()
    {
        return Int64.Parse(ReadNextToken());
    }

    public int[] ReadArrayOfInt32()
    {
        return ReadArray(Int32.Parse);
    }

    public long[] ReadArrayOfInt64()
    {
        return ReadArray(Int64.Parse);
    }

    public string[] NextSplitStrings()
    {
        return NextString()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
    {
        return NextSplitStrings()
            .Select(s => func(s, CultureInfo.InvariantCulture))
            .ToArray();
    }

    public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
    {
        return
            str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => func(s, CultureInfo.InvariantCulture))
                .ToArray();
    }

    protected void Dispose(bool dispose)
    {
        if (!isDispose)
        {
            if (dispose)
                sr.Close();

            isDispose = true;
        }
    }

    ~InputReader()
    {
        Dispose(false);
    }
}

