        int i, j, x;
        for (i = 4; i <= 7; i += 3)
        {
            st[k] = i;
            if (k < 9) back(k + 1);
            x = 0;
            for (j = 1; j <= k; j++) x = x * 10 + st[j];
            L[++LPos] = x;
         }
    }

    public static long Intersectie(int stA, int drA, int stB, int drB)
    {
        if (drA < stB || drB < stA) return 0;
        if (stA <= stB && drB <= drA) return drB - stB + 1;
        if (stB <= stA && drA <= drB) return drA - stA + 1;
        if (stA <= stB && drA <= drB) return drA - stB + 1;
        if (stB <= stA && drB <= drA) return drB - stA + 1;
        return 0;
    }
