namespace ConsoleApplication1
{
    class Program
    {
        static class Scanner
        {
            readonly static IEnumerator<string> Tokens;
            static Scanner()
            {
                Tokens = Enumerable.Range(Int32.MinValue, Int32.MaxValue).
                    Select(s => Console.ReadLine()).
                    TakeWhile(s => s != null).
                    SelectMany(s => s.Split(new[] { ' ', '\r', '\n', '\t' }, StringSplitOptions.RemoveEmptyEntries)).
                    Concat(Enumerable.Repeat(0, 1).Select(_ => (string)null)).
                    GetEnumerator();
            }

            public static string NextToken()
            {
                Tokens.MoveNext();
                return Tokens.Current;
            }
        }

        int nextInt()
        {
            return int.Parse(Scanner.NextToken());
        }

        bool GoodValue(int a)
        {
            if (a <= 0) return false;
            while (a != 0)
            {
                if (a % 10 != 7 && a % 10 != 4) return false;
                a /= 10;
            }
            return true;
        }

        int[] GenSequence()
        {
            var l = new List<int>();
            var q = new Queue<int>();
            q.Enqueue(0);
            while (q.Count != 0)
            {
                int cur = q.Dequeue();
                l.Add(cur);
                if (GoodValue(cur * 10 + 4)) q.Enqueue(cur * 10 + 4);
                if (GoodValue(cur * 10 + 7)) q.Enqueue(cur * 10 + 7);
            }
            return l.Concat(Enumerable.Range(1111111111, 1)).OrderBy(c => c).ToArray();
        }

        int LowerBound(int v, int[] a)
        {
            int x = 0, y = a.Length;
            while (y - x > 1)
            {
                int z = (x + y) / 2;
                if (a[z] <= v) x = z;
                else y = z;
            }
            return x;
        }

        int Len(int x, int y, int[] a, int p)
        {
            if (p < 1 || p >= a.Length) return 0;
            int tx = Math.Max(x, a[p - 1]), ty = Math.Min(y, a[p]);
            if (GoodValue(tx)) tx++;
            if (GoodValue(ty)) ty--;
            return Math.Max(ty - tx + 1, 0);
        }

        void Solve()
        {
            var values = GenSequence();
            int pl = nextInt(), pr = nextInt(),
                vl = nextInt(), vr = nextInt(),
                k = nextInt();
            long res = 0;
            for (int x = 1; x < values.Length; x++)
            {
                long pc = Len(pl, pr, values, x);
                long rc1 = Len(vl, vr, values, x + k),
                    rc2 = Len(vl, vr, values, x - k);
                res += pc * (rc1 + rc2);
                if (x + k - 1 < values.Length && values[x + k - 1] >= vl && values[x + k - 1] <= vr) res += pc;
                if (x - k > 0 && values[x - k] >= vl && values[x - k] <= vr) res += pc;

                if (values[x] >= pl && values[x] <= pr)
                {
                    res += Len(vl, vr, values, x - k + 1);
                    res += Len(vl, vr, values, x + k);

                    res += new[] { x + k - 1, x - k + 1 }.Distinct().Where(
                        c => c > 0 && c < values.Length &&
                            values[c] >= vl && values[c] <= vr
                        ).Count();
                }
            }
            long all = (pr - pl + 1);
            all *= (vr - vl + 1);
            Console.Write("{0:F12}", (double)res / (double)(all));
        }

        static void Main()
        {
#if MY_SUPER_PUPER_ONLINE_JUDGE
            string dir = Directory.GetCurrentDirectory();
            dir = Directory.GetParent(dir).FullName;
            dir = Directory.GetParent(dir).FullName;
            Console.SetIn(new StreamReader(dir + "\\input.txt"));
            Console.SetOut(new StreamWriter(dir + "\\output.txt"));
#endif
            Thread.CurrentThread.CurrentCulture = System.Globalization.CultureInfo.InvariantCulture;
            new Program().Solve();
#if MY_SUPER_PUPER_ONLINE_JUDGE
            Console.In.Close();
            Console.Out.Close();
#endif
        }
    }
}

