class E
{
	static void Main()
	{
		var N = long.Parse(Console.ReadLine());
		if (N == 0) { Console.WriteLine("0 0"); return; }
		var k = FirstBinary(0, Math.Min(600000000, N), t => 3 * (t + 1) * (t + 2) >= N) + 1;
		var x = 2 * k;
		var y = 0L;
		var dx = new long[] { -1, -2, -1, 1, 2, 1 };
		var dy = new long[] { 2, 0, -2, -2, 0, 2 };
		N -= 3 * k * (k - 1) + 1;
		if (N < 0) N += 6 * k;
		for (var i = 0; i < 6; i++)
		{
			if (N < k)
			{
				N++;
				x += N * dx[i];
				y += N * dy[i];
				Console.WriteLine("{0} {1}", x, y);
				break;
			}
			N -= k;
			x += k * dx[i];
			y += k * dy[i];
		}
	}
	public static long FirstBinary(long min, long max, Predicate<long> pred)
	{
		var left = min;
		var right = max;
		while (left < right)
		{
			var mid = (left + right) >> 1;
			if (pred(mid)) right = mid;
			else left = mid + 1;
		}
		return left;
	}
}

