        object Get()
        {
            checked
            {
                var m = ReadLong();
                var res = Recurse(m);
                return res.Item1 + " " + res.Item2;
            }
        }

        Tuple<long, long> Recurse(long m)
        {
            if (m < 8)
                return Tuple.Create(m, m);
            var root = MaxRoot(m);
            var cube = root * root * root;
            var lesserCube = (root - 1) * (root - 1) * (root - 1);
            var firstAns = Recurse(m - cube);
            var secondAns = Recurse(cube - 1 - lesserCube);
            return firstAns.Item1 >= secondAns.Item1
                ? Tuple.Create(firstAns.Item1 + 1, cube + firstAns.Item2)
                : Tuple.Create(secondAns.Item1 + 1, lesserCube + secondAns.Item2);

        }

        long MaxRoot(long x)
        {
            var root = (long) Math.Floor(Math.Pow(x, 1d / 3));
            if ((root + 1) * (root + 1) * (root + 1) <= x)
                root++;
            return root;
        }

        int Solve(string s1, string s2, int L, int m)
        {
            var diff = s1.Length + s2.Length - L;
            if (diff > 0)
            {
                if (s1.Substring(s1.Length - diff) == s2.Substring(0, diff))
                    return 1 % m;
                else
                    return 0;
            }
            else
            {
                return FastPow(26, Math.Abs(diff), m);
            }
        }

        public int FastPow(int b, int pow, int mod)
        {
            if (pow == 0)
                return 1 % mod;
            if (pow == 1)
                return b % mod;
            if ((pow & 1) == 0)
                return FastPow(b * b % mod, pow / 2, mod);
            return b * FastPow(b, pow - 1, mod) % mod;
        }

