public class Solution
{
    public void Solve()
    {
        int n = ReadInt();
        int mod = ReadInt();

        var dp = new long[n + 1];
        dp[1] = 1;
        long sum = 1;
        for (int i = 2; i <= n; i++)
        {
            dp[i] = sum;
            int j;
            for (j = 2; j * j <= i; j++)
                dp[i] = (dp[i] + dp[i / j]) % mod;
            int p = j - 1;
            for (j = i / j; j > 0; j--)
            {
                int o = i / j;
                dp[i] = (dp[i] + (o - p) * dp[j]) % mod;
                p = o;
            }
            sum = (sum + dp[i]) % mod;
        }

        Write(dp[n]);
    }

