namespace CodeForces
{
    public class Program
    {
        static void Main()
        {
            Stopwatch stopwatch = Stopwatch.StartNew();
            Solve(In, Out);
            PrintTime(stopwatch);
        }
        public static void Solve(TextReader In, TextWriter Out)
        {
            int[] input = In.ReadLine().Split().Select(str => int.Parse(str)).ToArray();
            int N = input[0], m = input[1];

            int[] f = new int[N * 2 + 1];
            f[N] = 1;
            for (long n = N - 1; n > 0; n--)
            {
                f[n] = 2 * f[n + 1] % m;
                for (int i = 2; i <= N / n; i++)
                {
                    f[n] = (f[n] + f[i * n] - f[(n + 1) * i]) % m;
                    if (f[n] < 0)
                    {
                        f[n] += m;
                    }
                }
            }
            int res = (f[1] - f[2]) % m;
            if (res < 0)
            {
                res += m;
            }

            Out.WriteLine(res);
        }

        [Conditional("DEBUG")]
        internal static void PrintTime(Stopwatch stopwatch) => WriteLine(stopwatch.Elapsed);
    }
}

