namespace CF3
{
    class Program
    {
        public static int SmallDiv(int n)
        {
            int div = 1;
            for (int i = 2; i <= n/2; i++)
                if (n % i == 0)
                {
                    div = i;
                    break;
                }

            return (div == 1) ? n : div;
        }

        static void Main(string[] args)
        {
            string[] a = Console.ReadLine().Split(' ');
            int n = int.Parse(a[0]);
            int k = int.Parse(a[1]);
            string s = "";
            int div;

            for (int i = 0; i < k; i++)
            {
                div = SmallDiv(n);
                if(i < k - 1 && div == n)
                {
                    s = "-1";
                    break;
                }
                s += (i != k - 1) ? div : n;
                s += " ";
                n /= div;
            }
            Console.WriteLine(s);
        }
    }
}

