namespace Logo_Turtle
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            string s = reader.ReadLine();
            int n = int.Parse(reader.ReadLine());

            int sl = s.Length*2;
            var dp = new bool[n + 1,sl + 1,2];
            dp[0, s.Length, 0] = true;

            foreach (char c in s)
            {
                var next = new bool[n + 1,sl + 1,2];

                for (int i = 0; i <= n; i++)
                {
                    for (int j = 0; j <= sl; j++)
                    {
                        if (dp[i, j, 0])
                        {
                            if (c == 'F')
                            {
                                for (int k = i; k <= n; k += 2) next[k, j + 1, 0] = true;
                                for (int k = i + 1; k <= n; k += 2) next[k, j, 1] = true;
                            }
                            else
                            {
                                for (int k = i; k <= n; k += 2) next[k, j, 1] = true;
                                for (int k = i + 1; k <= n; k += 2) next[k, j + 1, 0] = true;
                            }
                        }
                        if (dp[i, j, 1])
                        {
                            if (c == 'F')
                            {
                                for (int k = i; k <= n; k += 2) next[k, j - 1, 1] = true;
                                for (int k = i + 1; k <= n; k += 2) next[k, j, 0] = true;
                            }
                            else
                            {
                                for (int k = i; k <= n; k += 2) next[k, j, 0] = true;
                                for (int k = i + 1; k <= n; k += 2) next[k, j - 1, 1] = true;
                            }
                        }
                    }
                }

                dp = next;
            }

            for (int i = s.Length;; i--)
            {
                if (dp[n, s.Length - i, 0] || dp[n, s.Length - i, 1] || dp[n, s.Length + i, 0] || dp[n, s.Length + i, 1])
                {
                    writer.WriteLine(i);
                    break;
                }
            }

            writer.Flush();
        }
    }
}

