class Myon
{
    Scanner cin;
    Myon() { }

    public static void Main()
    {
        new Myon().calc();
    }


    bool[,, ,] dp;
    int n;
    string s;
    int len;
    int ret;

    void calc()
    {
        cin = new Scanner();
        int i, j, k;
        s = Console.ReadLine();
        n = cin.nextInt();
        len = s.Length;
        dp = new bool[101, 300, n + 1, 2];
        ret = 0;
        dfs(0, 150, 0, 0);
        Console.WriteLine(ret);
    }


    void dfs(int now, int pos, int change, int a)
    {
        if (change > n) return;
        if (now == len)
        {
            if (change % 2 != n % 2) return;
            //Console.WriteLine(pos);
            ret = Math.Max(ret, Math.Abs(pos - 150)); return;
        }
        if (dp[now, pos, change, a]) return;
        dp[now, pos, change, a] = true;
        int memo = 1;
        if (s[now] == 'F') memo = 0;
        int v = 1;
        if (a == 1) v = -1;

        dfs(now + 1, pos + v, change + memo, a);
        dfs(now + 1, pos, change + (1 - memo), 1 - a);
    }
}

