namespace Acm
{
    /// <summary>
    /// For the simplicity of hacking / reading / exploring.
    /// Problem solution is in this class only!
    /// </summary>
    class ProblemSolution
    {
        public LineReader In { get; }

        public TextWriter Out { get; }

        public ProblemSolution(LineReader @in, TextWriter @out)
        {
            In = @in;
            Out = @out;
        }

        /// <summary>
        /// </summary>
        /// <param name="testId">
        /// For multi-test inputs: ID of test, from 1 to T
        /// For single-test inputs: -1
        /// </param>
        public void SolveTest(int testId)
        {
            long[] line = In.Read();
            long a = line[0], b = line[1];

            long diff = Math.Abs(a - b);

            List<long> divisors = new List<long>();

            for (long divisor = 1; divisor * divisor <= diff; divisor++)
            {
                if (diff % divisor == 0)
                {
                    divisors.Add(divisor);

                    if (divisor * divisor != diff)
                        divisors.Add(diff / divisor);
                }
            }

            long answerK = 0;
            long answerLcm = long.MaxValue;
            foreach (long divisor in divisors)
            {
                long k = (divisor - (a % divisor)) % divisor;
                long lcm = (a + k) * (b + k) / divisor;

                if (lcm < answerLcm)
                {
                    answerLcm = lcm;
                    answerK = k;
                }
            }

            Out.WriteLine(answerK);
        }
    }

