﻿using System;
using System.IO;
using System.Text;

namespace Neko_does_Maths
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            writer.WriteLine(Solve(args));
            writer.Flush();
        }

        private static long Solve(string[] args)
        {
            long a = Next();
            long b = Next();

            long d = Math.Abs(a - b);

            long min = Math.Min(a, b);

            if (d == 0)
                return 0;

            if (min > d)
            {
                long r = a%d;
                if (r == 0)
                    return 0;

                return d - r;
            }

            {
                for (long k = min; k*k<=d; k++)
                {
                    if (d % k == 0)
                        return k - min;
                }
                for (long k = d/min; k >= 1; k--)
                {
                    if (d%k == 0)
                    {
                        return d/k - min;
                    }
                }
                return d - min;
            }
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

