        public static bool Solve()
        {
            var points = new List<Point>();
            for (int i = 0; i < 8; i++)
            {
                var line = Console.ReadLine().Split(' ');
                points.Add(new Point(int.Parse(line[0]), int.Parse(line[1])));
            }

            int maxX = points.Select(p => p.x).Max();
            int minX = points.Select(p => p.x).Min();
            int maxY = points.Select(p => p.y).Max();
            int minY = points.Select(p => p.y).Min();

            int midX, midY;
            try
            {
                midX = points.Select(p => p.x).Where(x => x < maxX && x > minX).First();
                midY = points.Select(p => p.y).Where(y => y < maxY && y > minY).First();
            }
            catch { return false; }

            if (points.Contains(new Point(minX, minY)) &&
                points.Contains(new Point(midX, minY)) &&
                points.Contains(new Point(maxX, minY)) &&
                points.Contains(new Point(minX, midY)) &&
                points.Contains(new Point(maxX, midY)) &&
                points.Contains(new Point(minX, maxY)) &&
                points.Contains(new Point(midX, maxY)) &&
                points.Contains(new Point(maxX, maxY)))
                return true;
