        for (int i = 0; i < Max(N,M) + 1; i++)
        {
            zero[0][i] = 1;
        }
        for (int i = 1; i <= N; i++)
            for (int j = i; j <= Max(M,N); j++)
            {
                zero[i][j] = zero[i - 1][j] + zero[i][j - 1];
            }
        var dp = Create(N + 1, () => new ModInt[M + 1]);
        //1,-1を先頭に追加する
        for (int i = 1; i <= N; i++)
            for (int j = 0; j <= M; j++)
            {
                dp[i][j] += dp[i - 1][j];
                dp[i][j] += ModInt.Comb(i - 1 + j, i - 1);//先頭に1を追加するとmaxは1増える
                if (j > 0)
                {
                    dp[i][j] += dp[i][j - 1];
                    //先頭に-1を追加するとmaxは元から0であるものを除いて1減る
                    dp[i][j] -= ModInt.Comb(i + j - 1, i) - zero[i][j - 1];
                }
            }
        Console.WriteLine(dp[N][M]);
    }
