class Program
{
    private static int Next()
    {
        int c;
        int res = 0;
        do
        {
            c = reader.Read();
            if (c == -1)
                return res;
        } while (c < '0' || c > '9');
        res = c - '0';
        while (true)
        {
            c = reader.Read();
            if (c < '0' || c > '9')
                return res;
            res *= 10;
            res += c - '0';
        }
    }
    private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024 * 10), Encoding.ASCII, false, 1024 * 10);
    private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024 * 10), Encoding.ASCII, 1024 * 10);


    static string getNext(string current)
    {
        if (current.Length == 1)
        {
            var num = int.Parse(current);
            if (num < 9)
            {
                return (num + 1).ToString();
            }
            else
            {
                return (11).ToString();
            }
        }
        var first = int.Parse(current[0].ToString());
        var last = int.Parse(current[current.Length - 1].ToString());

        var sb = new StringBuilder(current);
        for (var i = 1; i < current.Length - 1; i++)
        {
            sb[i] = '0';
        }

        if (last < first)
        {
            last = first;

            sb[current.Length - 1] = char.Parse(last.ToString());
            return sb.ToString();
        }
        else
        {
            first++;
            if (first == 10)
            {
                first = 1;
                sb.Insert(0, char.Parse(first.ToString()));
            }
            last = first;
            sb[current.Length - 1] = char.Parse(last.ToString());
            sb[0] = char.Parse(first.ToString());
            return sb.ToString();
        }

    }

