namespace ProgrammingContest.Codeforces.Round63
{
    class D
    {
        int[,,] win = new int[4,500, 500];
        int offset = 200;
        int[] vx, vy;
        int d;

        bool isLose(int x, int y) { return d*d < x*x + y*y; }

        bool solve(int reflect, int x, int y)
        {
            if (isLose(x, y))
                return true;

            if (win[reflect, x + offset, y + offset] != 0)
                return win[reflect, x + offset, y + offset] > 0;

            if (reflect % 2 == 1)
            {
                if (!solve(reflect >> 1, y, x))
                    return (win[reflect, x + offset, y + offset] = 1) > 0;
            }

            int r = ((reflect % 2) << 1) | (reflect >> 1);
            for (int i = 0; i < vx.Length; i++)
                if (!solve(r, x + vx[i], y + vy[i]))
                    return (win[reflect, x + offset, y + offset] = 1) > 0;

            return (win[reflect, x + offset, y + offset] = -1) > 0;
        }

        D()
        {
            var xs = Array.ConvertAll(Console.ReadLine().Split(' '), sss => int.Parse(sss));
