namespace Orchestra
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int r = Next(), c = Next(), n = Next(), k = Next();

            var nn = new int[r + 1,c + 1];
            for (int i = 0; i < n; i++)
            {
                int x = Next();
                int y = Next();
                nn[x, y] = 1;
            }
            var sum = new int[r + 1,c + 1];
            for (int i = 1; i <= r; i++)
            {
                for (int j = 1; j <= c; j++)
                {
                    sum[i, j] = nn[i, j] + sum[i - 1, j] + sum[i, j - 1] - sum[i - 1, j - 1];
                }
            }
            int count = 0;

            for (int i = 1; i <= r; i++)
            {
                for (int j = 1; j <= c; j++)
                {
                    if (sum[i, j] < k)
                        continue;
                    for (int l = 0; l < i; l++)
                    {
                        int delta = sum[i, j] - sum[l, j];
                        if (delta < k)
                            break;

                        for (int m = 0; m < j; m++)
                        {
                            int d = delta + sum[l, m] - sum[i, m];
                            if (d >= k)
                                count++;
                        }
                    }
                }
            }

            writer.WriteLine(count);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

