            long[] z = p[2];
            long _x = x[0];
            long _y = y[0];

            if (x[0] == y[0] && y[0] == z[0])
                return 1;

            if (x[1] == y[1] && y[1] == z[1])
                return 1;
            if (check(x, y, z) || check(x, z, y) || check(y, x, z))
                return 2;

            return 3;

