            }

            if ((x[0] == x[1] && x[0] == x[2]) || (y[0] == y[1] && y[0] == y[2]))
                writer.WriteLine("1");
            else if ((x[0] == x[1] && -1 != Math.Sign(y[0] - y[2])*Math.Sign(y[1] - y[2]))
                     || (x[0] == x[2] && -1 != Math.Sign(y[0] - y[1])*Math.Sign(y[2] - y[1]))
                     || (x[2] == x[1] && -1 != Math.Sign(y[2] - y[0])*Math.Sign(y[1] - y[0]))
                     || (y[0] == y[1] && -1 != Math.Sign(x[0] - x[2])*Math.Sign(x[1] - x[2]))
                     || (y[0] == y[2] && -1 != Math.Sign(x[0] - x[1])*Math.Sign(x[2] - x[1]))
                     || (y[2] == y[1] && -1 != Math.Sign(x[2] - x[0])*Math.Sign(x[1] - x[0]))
                )

            {
                writer.WriteLine("2");
            }
            else
                writer.WriteLine("3");


