    {
        long max = 0;
        for (int i = l; i <= r; i++)
        {
            int tmp = i;
            Stack<int> ds = new Stack<int>();
            for (; ; )
            {
                if (tmp == 0)
                    break;
                ds.Push(tmp % 10);
                tmp/= 10;
            }

            long o=0;
            foreach (var d in ds)
            {
                o *= 10;
                o += (9-d);
            }

            long p = (long)o * i;
            max = Math.Max(p, max);
        }
        return max;
