            Int64[] parametrs = Array.ConvertAll(Console.ReadLine().Split(' '),Int64.Parse);

            Int64 n = parametrs[0], l = parametrs[1],r = parametrs[2];

            Int64 lengthString = (Int64)Math.Pow(2, ((Int64)Math.Log(n, 2)) + 1) - 1;

            int counter = 0;
            for (Int64 i = l; i < r + 1; i++)
            {
                if (BinarySearch(lengthString, n, i) >= 1)
                    counter++;
            }

            Console.WriteLine(counter);
        }

        static int BinarySearch(Int64 lengthValue,Int64 root,Int64 index)
        {
            Int64 current = lengthValue / 2 + 1;
            Int64 path = current;
            while (current!=index)   
            {
                path = path / 2;
                if (index < current)
                    current = current - path;
                else
                    current = current + path;
                if (root > 1) 
                    root = root / 2;
            }

            if (index % 2 == 0)
                return (int)(root % 2);
            else return (int)(root);
        }

    }
}

