    internal class Task
    {
        private long l;
        private long r;
        private int answ;

        public void Solve(InputReader sr, TextWriter sw)
        {
            var input = sr.ReadArray(Int64.Parse);
            var n = input[0];
            l = input[1];
            r = input[2];
            Divide(n, 1L);
            sw.WriteLine(answ);
        }

        private void Divide(long n, long indx)
        {
            if (indx > r)
            {
                return;
            }
            if (n == 0 || n == 1)
            {
                if (indx >= l && indx <= r && n == 1L)
                {
                    answ++;
                }
                return;
            }
            var log = GetLog2(n);
            var power = GetPower(2L, log) / 2 - 1L;
            if (indx + (power) * 2 + 1L < l)
            {
                return;
            }
            Divide(n / 2, indx);
            if (indx + power >= l && indx + power <= r && n % 2 == 1L)
            {
                answ++;
            }
            Divide(n / 2, indx + power + 1L);
        }

        private long GetLog2(long n)
        {
            var log = 0;
            while (n > 0) {
                n /= 2;
                log++;
            }

            return log;
        }

        public long GetPower(long n, long p)
        {
            var power = 1L;
            for (var i = 0; i < p; i++) {
                power *= n;
            }

            return power;
        }
    }
