    internal class Task : IDisposable
    {
        private readonly InputReader sr;
        private readonly TextWriter sw;
        private bool isDispose;

        public Task(InputReader sr, TextWriter sw)
        {
            this.sr = sr;
            this.sw = sw;
        }

        public void Solve()
        {
            var n = sr.NextInt32();
            var m = sr.NextInt32();
            var coffee = sr.ReadArrayOfInt64();
            var start = 1;
            var end = n;
            var sum = coffee.Sum();
            if (sum < m)
            {
                sw.WriteLine(-1);
                return;
            }

            Array.Sort(coffee, (a, b) => -a.CompareTo(b));
            var answ = -1;
            while (start <= end)
            {
                var mid = (start + end) / 2;
                var res = 0L;
                for (var i = 0; i < mid; i++)
                {
                    res += coffee[i];
                }

                var indx = 0;
                var usedCount = Enumerable.Repeat(1, mid).ToArray();
                    for (var i = mid; i < n; i++)
                    {
                        res += Math.Max(0, coffee[i] - usedCount[indx]);
                        usedCount[indx]++;
                        indx++;
                        indx = indx % mid;
                    }

                if (res >= m)
                {
                    end = mid - 1;
                    answ = mid;
                }
                else
                {
                    start = mid + 1;
                }
            }

            sw.WriteLine(answ);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        private void Dispose(bool disposing)
        {
            if (!isDispose) {
                if (disposing) {
                    if(sr != null)
                        sr.Dispose();

                    if(sw != null)
                        sw.Dispose();
                }

                isDispose = true;
            }
        }
    }
