using System;
using System.Linq;
using CompLib.Util;

public class Program
{
    int N;
    long M;
    long[] A;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();

        A = sc.LongArray();

        Array.Sort(A, (l, r) => r.CompareTo(l));

        /*
         * mページ書く
         * 
         * n個コーヒー
         * 
         * iはa_iカフェイン
         * 
         * k杯飲む
         * 1杯目 a_i
         * 2    a_i-1
         * ...
         * 
         * 最小日数
         */

        int ok = N + 1;
        int ng = 0;
        while (ok - ng > 1)
        {
            int mid = (ok + ng) / 2;
            if (F(mid)) ok = mid;
            else ng = mid;
        }

        if(ok <= N)
        {
            Console.WriteLine(ok);
        }
        else
        {
            Console.WriteLine("-1");
        }
    }

    // d日
    bool F(int d)
    {
        // 
        long t = 0;
        for (int i = 0; i < N; i++)
        {
            t += Math.Max(0, A[i] - i / d);
        }

        return t >= M;

    }

    public static void Main(string[] args) => new Program().Solve();
    // public static void Main(string[] args) => new Thread(new Program().Solve, 1 << 27).Start();
}

