namespace Caesar
{
	class MainClass
	{
		public static void Main(string[] args)
		{
			int n1, n2, k1, k2, mod = 100000000;
			string[] line = Console.ReadLine().Split();
			n1 = Convert.ToInt32(line[0]);
			n2 = Convert.ToInt32(line[1]);
			k1 = Convert.ToInt32(line[2]);
			k2 = Convert.ToInt32(line[3]);
			int[,,] dp = new int[n1 + 1, n2 + 1, 2];
			dp[0, 0, 0] = dp[0, 0, 1] = 1;
			for (int i = 0; i <= n1; i++)
			{
				for (int j = 0; j <= n2; j++)
				{
					if (i == 0 && j != 0)
					{
						if (j <= k2) dp[i, j, 1] = 1;
						else dp[i, j, 1] = 0;
						dp[i, j, 0] = 0;
					}
					else if (i != 0 && j == 0)
					{
						if (i <= k1) dp[i, j, 0] = 1;
						else dp[i, j, 0] = 0;
						dp[i, j, 1] = 0;
					}
					else
					{
						for (int k = 1; k <= k1; k++)
						{
							if (k <= i)
							{
								dp[i, j, 0] = (dp[i, j, 0] + dp[i - k, j, 1]) % mod;
							}
						}
						for (int k = 1; k <= k2; k++)
						{
							if (k <= j)
							{
								dp[i, j, 1] = (dp[i, j, 1] + dp[i, j - k, 0]) % mod;
							}
						}
					}
				}
			}
			Console.WriteLine((dp[n1, n2, 0] + dp[n1, n2, 1]) % mod);
			Console.ReadLine();
		}
	}
}

