		private static readonly long[] Inverses = new long[500];

		public static long[,] GetNext(long[,] current, long mod)
		{
			var total = current.GetLength(0) - 1;
			var next = new long[total + 2, total + 1];

			for (int i = 0; i <= total; i++)
				for (int last = 0; last < total; last++)
				{
					var prev = current[i, last];
					if (prev == 0)
						continue;

					var dist = total + 1 - last;

					var nVal = prev * 2 * (i + 1) % mod * Inverses[dist] % mod;
					next[i + 1, last] = (next[i + 1, last] + nVal) % mod;

					if (last != total - 1)
					{
						var val = prev * Inverses[2] % mod * (dist - 1) % mod;
						next[i, total] = (next[i, total] + val) % mod;
					}
				}

			return next;
		}

		public static long ModularMultiplicativeInverse(long remainder, long mod)
		{
			if (mod == 1)
				return 0;

			var other = mod;
			long next = 0;
			long inverse = 1;

			while (remainder > 1)
			{
				(inverse, next) = (next, inverse - remainder / other * next);
				(remainder, other) = (other, remainder % other);
			}

			if (inverse < 0)
				inverse += mod;

			return inverse;
		}

