		private static void GetPermutationsRec(int[] list, List<int[]> result, int k, int m)
		{
			if (k == m)
				result.Add(list.ToArray());
			else
				for (int i = k; i <= m; i++)
				{
					Swap(ref list[k], ref list[i]);
					GetPermutationsRec(list, result, k + 1, m);
					Swap(ref list[k], ref list[i]);
				}
		}

