		public static long LowerBound(long min, long max, Predicate<long> test)
		{
			long e = max;
			long s = min;

			while (s < e)
			{
				long mid = (s + e) / 2;
				if (test(mid))
					e = mid;
				else
					s = mid + 1;
			}

			return e;
		}

		public static long UpperBound(long min, long max, Predicate<long> test)
		{
			long s = min;
			long e = max;

			while (s < e)
			{
				long mid = (s + e) / 2;
				if (test(mid))
					s = mid + 1;
				else
					e = mid;
			}

			return s - 1;
		}


