    private static char[,] Rotate(char[,] m, int n)
    {
        var newMap = new char[n, n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
            {
                newMap[j, n - i - 1] = m[i, j];
            }

        return newMap;
    }

    private static bool IsSame(char[,] m1, char[,] m2, int n)
    {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (m1[i, j] != m2[i, j]) return false;

        return true;
    }

    private static bool Compare(char[,] m1, char[,] m2, int n)
    {
        return IsSame(m1, Flip(m2, n, false, false), n) ||
            IsSame(m1, Flip(m2, n, true, false), n) ||
            IsSame(m1, Flip(m2, n, false, true), n) ||
            IsSame(m1, Flip(m2, n, true, true), n);
    }


    private static char[,] Flip(char[,] m, int n, bool byX, bool byY)
    {
        var newMap = new char[n, n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
            {
                var newX = i;
                var newY = j;
                if (byX) newX = n - i - 1;
                if (byY) newY = n - j - 1;

                newMap[newX, newY] = m[i, j];
            }

        return newMap;
    }


