﻿using System;
using System.IO;
using System.Text;

namespace Primes_on_Interval
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int a = Next();
            int b = Next();
            int k = Next();

            bool[] ff = GetPrimes(b + 100);

            for (int i = a; i <= b; i++)
            {
                if (ff[i])
                {
                    k--;
                    if (k == 0)
                    {
                        int l = i - a + 1;
                        for (int x = a + 1; x <= b - l + 1; x++)
                        {
                            if (ff[x - 1])
                                k++;
                            if (ff[x + l - 1])
                                k--;
                            while (k > 0)
                            {
                                l++;
                                if (ff[x + l - 1])
                                    k--;
                            }
                            if (x+l-1>b)
                            {
                                l = b - x+2;
                                break;
                            }
                        }
                        //l = Math.Min(l, b - a + 1);
                        writer.WriteLine(l);
                        writer.Flush();
                        return;
                    }
                }
            }

            writer.WriteLine("-1");
            writer.Flush();
        }


        public static bool[] GetPrimes(int n)
        {
            n = Math.Max(n, 2);
            var prime = new bool[n + 1];
            for (int i = 2; i <= n; i++)
            {
                prime[i] = true;
            }

            for (int i = 2; i*i <= n; i++)
            {
                if (prime[i])
                {
                    if ((long) i*i <= n)
                    {
                        for (int j = i*i; j <= n; j += i)
                        {
                            prime[j] = false;
                        }
                    }
                }
            }

            return prime;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

class Andy
{

    public static void Main()
    {

        var inn = Console.ReadLine().Split(' ');
        var a = int.Parse(inn[0]);
        var b = int.Parse(inn[1]);
        var k = int.Parse(inn[2]);

        int[] prime = new int[b + 1];

        for (int i = 2; i <= b; i++)
        {
            prime[i] = 1;
        }

        for (int i = 2; i * i <= b; i++)
        {
            if (prime[i] == 1)
            {
                for (int j = i * i; j <= b; j = j + i)
                {
                    prime[j] = 0;
                }
            }
        }

        int[] cntPrime = new int[b + 2];
        cntPrime[0] = prime[0];
        for (int i = 1; i <= b; i++)
        {
            cntPrime[i] = cntPrime[i - 1] + prime[i];
        }

        if (cntPrime[b] - cntPrime[a - 1] < k)
        {
            Console.Write("-1\n");
            return;
        }
        else
        {
            int L = 0, R = b - a + 1, M;
            while (R - L > 1)
            {
                bool check = true;
                M = (L + R) / 2;
                for (int i = a + M - 1; i <= b; i++)
                    if (cntPrime[i] - cntPrime[i - M] < k)
                        check = false;

                if (check)
                    R = M;
                else
                    L = M;
            }
            Console.Write(R + "\n");
        }

    }

}

