		private long bar(int h, Int64 n, char next)
		{
			if (h == 0)
				return 0;

			Int64 l = 1L << (h - 1);
			if (next == 'L')
			{
				if (n <= l)
				{
					return 1 + bar(h - 1, n, 'R');
				}
				else
				{
					return (1L << h) + bar(h - 1, n - l, 'L');
				}
			}
			else
			{
				if (n <= l)
				{
					return (1L << h) + bar(h - 1, n, 'R');
				}
				else
				{
					return 1 + bar(h - 1, n - l, 'L');
				}
			}
		}
