    public class Solver
    {
        public void Solve()
        {
            var h = sc.Integer();
            var n = sc.Long();
            long l = 1;
            long r = 1L << h;
            long count = 0;
            var goL = true;
            for (int i = 0; i < h; i++)
            {
                var m = (l + r) >> 1;
                //Debug.WriteLine(m);
                count++;
                if (n <= m)
                {
                    if (!goL)
                    {
                        count += (1L << (h - i)) - 1;
                    }
                    goL = false;
                    r = m - 1;
                }
                else
                {
                    if (goL)
                    {
                        count += (1L << (h - i)) - 1;
                    }
                    goL = true;
                    l = m + 1;
                }
            }
            IO.Printer.Out.WriteLine(count);

        }


