        private const string test = "C2";

        private static void Solve()
        {
            int a, b, n;
            Read(out a, out b, out n);
            var mod = 1000000007;
            var fact = new long[n+1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++)
            {
                fact[i] = fact[i-1]*i;
                fact[i] %= mod;
            }
            var res = 0L;
            for (int aCount= 0; aCount <= n; aCount++)
            {
                var bCount = n - aCount;
                if (IsGood(aCount*a + bCount*b, a, b))
                {
                    var denominator = fact[aCount]*fact[bCount];
                    denominator %= mod;
                    var temp = fact[n]* BinPow(denominator, mod-2,mod);
                    var tempint = (int)(temp%mod);
                    res += tempint;
                    res %= mod;
                }
            }
            WriteLine(res);
        }

        private static long BinPow(long a, int pow, int mod)
        {
            if (pow == 0)
                return 1;

            if (pow%2 == 1)
                return (BinPow(a, pow - 1, mod)*a) %mod;

            var b = BinPow(a, pow/2, mod);
            b %= mod;
            var res = b*b;
            res %= mod;
            return res;
        }

        private static bool IsGood(int n, int a, int b)
        {
            var res = (n!=0);
            while (n > 0)
            {
                var end = n%10;
                n /= 10;
                res &= (end == a || end == b);
            }
            return res;
        }

