namespace ProgrammingContest.Codeforces.Round53
{
    class C
    {
        const long mod = 1000000007L;
        static void ExtGcd(long a, long b, out long x, out long y, out long c)
        {
            if (b == 0)
            {
                x = 1;
                y = 0;
                c = a;
                return;
            }
            long q = a / b;
            long r = a % b;
            long x1, y1;
            ExtGcd(b, r, out x1, out y1, out c);
            x = y1;
            y = x1 - y1 * q;
        }

        static long PowMod(long x, long y, long m)
        {
            long res = 1;
            for (; y != 0; y >>= 1, x = x * x % m)
                if ((y & 1) == 1)
                    res = res * x % m;
            return res;
        }

        static long comb(long n, long r)
        {
            const bool debug = true;
            checked
            {
                long res = 1;
                for (long i = 0; i < r; i++)
                {
                    long x, y, c;
                    if (debug)
                    {
                        x = PowMod(i + 1, mod - 2, mod);
                    }
                    else
                    {
                        ExtGcd(i + 1, mod, out x, out y, out c);
                    }
                    ExtGcd(i + 1, mod, out x, out y, out c);
                    x = (x % mod + mod) % mod;
                    res = res * (n - i) % mod * x % mod;
                }
                return res;
            }
        }

        public static void Main()
        {
            int n = int.Parse(Console.ReadLine());
            long x = comb(2 * (n - 1) + 1, n);
