        private static int Score(int[] cites, int k)
        {
            var highest = 0;
            for (var i = 0; i < cites.Length; i++)
            {
                var score = 0;
                for (var j = 0; j < cites.Length; j++)
                {
                    if ((j - i) % k == 0) continue;
                    score += cites[j];
                }

                if (Math.Abs(score) > highest)
                {
                    highest = Math.Abs(score);
                }
            }

            return highest;
        }
    }
}

