class Solver
{
    public Scanner sc;
    public void Solve()
    {
        int N, M;
        sc.Make(out N, out M);
        var A = sc.ArrInt;
        var L = Create(2, () => new HashSet<int>());
        for(int k = 0; k < 2; k++)
        {
            int[] a;
            if (k == 0) a = A.Take(N / 2).ToArray();
            else a = A.Skip(N / 2).ToArray();
            for(int j = 0; j < (1 << a.Length); j++)
            {
                var sum = 0;
                for (int l = 0; l < a.Length; l++)
                    if ((1 & j >> l) == 1) { sum += a[l]%M; if (sum >= M) sum -= M; }
                L[k].Add(sum);
            }
        }
        var dat = Create(2, id => {
            var r = new int[L[id].Count];
            var now = 0;
            foreach (var d in L[id]) r[now++] = d;
            Array.Sort(r);
            return r;
        });
        var max = 0;
        for(int i = 0; i < dat[0].Length; i++)
        {
            var l = LowerBound(dat[1], M - dat[0][i]);
            for(int k = -1; k < 2; k++)
            {
                int idx = (l + k + dat[1].Length) % dat[1].Length;
                chmax(ref max, (dat[1][idx] + dat[0][i]) % M);
            }
        }
        Console.WriteLine(max);
    }
     #region UpperBound/LowerBound
    public static int UpperBound<T>(IList<T> array, T value, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var low = -1;
        var high = array.Count;
        while (high - low > 1)
        {
            var mid = (high + low) / 2;
            if (cmp(array[mid], value) == 1) high = mid;
            else low = mid;
        }
        return high;
    }

    public static int LowerBound<T>(IList<T> array, T value, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var low = -1;
        var high = array.Count;
        while (high - low > 1)
        {
            var mid = (high + low) / 2;
            if (cmp(array[mid], value) != -1) high = mid;
            else low = mid;
        }
        return high;
    }
    #endregion
}

