using System.Collections.Generic;
using System.IO;
using System.Text;

namespace Maximum_Subsequence
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            writer.WriteLine(Solve(args));
            writer.Flush();
        }

        private static long Solve(string[] args)
        {
            int n = Next();
            int m = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next()%m;
            }

            if (n == 1)
                return nn[0];

            int mid = n/2;
            var p1 = new List<long>();
            var p2 = new List<long>();

            for (int i = 0; i < mid; i++)
            {
                int cnt = p1.Count;
                for (int j = 0; j < cnt; j++)
                {
                    p1.Add((p1[j] + nn[i])%m);
                }
                p1.Add(nn[i]);
            }
            p1.Add(0);
            p1.Sort();

            for (int i = mid; i < n; i++)
            {
                int cnt = p2.Count;
                for (int j = 0; j < cnt; j++)
                {
                    p2.Add((p2[j] + nn[i])%m);
                }
                p2.Add(nn[i]);
            }


            p2.Add(0);

            long max = 0;
            foreach (long l in p2)
            {
                long v = m - l - 1;
                int index = p1.BinarySearch(v);
                if (index < 0)
                {
                    index = ~index;
                    index--;
                }
                if (index >= 0)
                {
                    max = Math.Max(max, l + p1[index]);
                }
            }

            return max;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

