public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var v = ReadIntArray();

        if (n == 1)
        {
            Write(v[0] % m);
            return;
        }

        int na = n / 2;
        int nb = n - na;

        var a = new List<int>();
        for (int i = 0; i < 1 << na; i++)
        {
            long s = 0;
            for (int j = 0; j < na; j++)
                if ((i >> j & 1) == 1)
                    s += v[j];
            a.Add((int)(s % m));
        }

        var b = new List<int>();
        for (int i = 0; i < 1 << nb; i++)
        {
            long s = 0;
            for (int j = 0; j < nb; j++)
                if ((i >> j & 1) == 1)
                    s += v[j + na];
            b.Add((int)(s % m));
        }

        a.Sort();
        b.Sort();
        int ans = (a[a.Count - 1] + b[b.Count - 1]) % m;
        int p = b.Count - 1;
        for (int i = 0; i < a.Count; i++)
        {
            while (p >= 0 && a[i] + b[p] >= m)
                p--;
            if (p < 0)
                break;
            ans = Math.Max(ans, a[i] + b[p]);
        }

        Write(ans);
    }

