  class MainClass
  {
    class Box
    {
      public int pos;
      public int candy;
      public int color;
    }

    static int n, s, k;
    static Box[] r;

    static int[,] dp;

    static int find(int at, int candy)
    {
      if (candy >= k)
        return 0;

      if (dp[at, candy] != -1)
        return dp[at, candy];

      int result = int.MaxValue;

      for (int i = at + 1; i < n; ++i)
      {
        if (r[i].color != r[at].color && r[i].candy > r[at].candy)
        {
          int v = find(i, candy + r[i].candy);
          if (v != int.MaxValue)
            result = Math.Min(result, v + Math.Abs(r[at].pos - r[i].pos));
        }
      }

      dp[at, candy] = result;
      return result;
    }

    public static void Main(string[] args)
    {
      //var line = Array.ConvertAll("5 3 10".Split(' '), int.Parse);
      var line = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
