      //line = Array.ConvertAll("1 2 3 4 5".Split(' '), int.Parse);
      line = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
      //var color = "RGBRR";
      var color = Console.ReadLine();

      for (int i = 0; i < n; ++i)
      {
        var box = new Box();
        box.pos = i;
        box.candy = line[i];
        box.color = color[i];
        r[i] = box;
      }

      Array.Sort(r, (x, y) => {
        return x.candy - y.candy;
      });

      dp = new int[n, 2018];
      for (int i = 0; i < n; ++i)
        for (int j = 0; j < 2018; ++j)
          dp[i, j] = -1;

