      for (int i = 0; i < n; ++i)
      {
        var v = find(i, r[i].candy);

        if (v != int.MaxValue)
          result = Math.Min(result, v + Math.Abs(s - r[i].pos));
      }

      if (result == int.MaxValue)
        result = -1;

      Console.WriteLine(result);
    }
  }
