    internal class Program
    {
        long getShapeSquare(long t)
        {
            long sum = (t - 1) * t / 2;
            return sum * 4 + 1;
        }

        long getTriangleSquare(long t, long x)
        {
            if (t <= 0)
                return 0;
            long sum = (t - 1) * t / 2;
            long cut = Math.Max(0,t - x);
            return sum * 2 + t - cut * (cut + 1) / 2;
        }

        long getSquare(int n, int x, int y, int t)
        {
            if (t == 0)
                return 0;

            long cutLeft = getTriangleSquare(t - x, y);
            long cutRight = getTriangleSquare(t - (n - x + 1), n - y + 1);
            long cutTop = getTriangleSquare(t - y, n - x + 1);
            long cutBottom = getTriangleSquare(t - (n - y + 1), x);
            return getShapeSquare(t) - cutLeft - cutRight - cutTop - cutBottom;                
        }

        private void Solve()
        {
            int n = io.NextInt();
            int x = io.NextInt();
            int y = io.NextInt();
            long c = io.NextLong();

            int ans = int.MaxValue;

            int low = 0;
            int high = 2 * n;

            while (low <= high)
            {
                int med = (low + high) / 2;
                long s = getSquare(n, x, y, med);
                if (s >= c)
                {
                    ans = Math.Min(ans, med);
                    high = med - 1;
                }
                else
                    low = med + 1;
            }

            io.Print(ans - 1);
        }

