    internal class Program
    {
        #region Program

        private readonly MyIo io;

        public Program(MyIo io)
        {
            this.io = io;
        }

        public static void Main(string[] args)
        {
            using (MyIo io = new MyIo())
            {
                new Program(io)
                    .Solve();
            }
        }



        #endregion

        public const long MOD = 1000000007;
        public const double EPS = 1e-14;




        private void Solve()
        {
            var n = io.NextLong();

            var x = io.NextLong();
            var y = io.NextLong();

            var c = io.NextLong();


            long s = 0;

            if (c > 1)
            {

                var ub = (long)Math.Sqrt(1+8*c);
                var lb = Math.Max(ub / 4L - 1L, 0L);

                s = ub;




                do
                {

                    var m = (ub + lb) >> 1;

                    var cn = Calc(n, x, y, m);

                    if (cn >= c)
                    {
                        ub--;
                        s = Math.Min(m, s);
                    }
                    else if (cn < c)
                    {
                        lb++;
                    }


                } while (ub > lb);

            }

            io.Print(s);
        }

        private long Pos0(long x)
        {
            return x > 0 ? x : 0;
        }

        private long Pow2(long x)
        {

            return x*x;
        }


        private long Pow2120(long x)
        {
            x = Pos0(x);

            return x * (x + 1L) / 2;
        }

        private long Calc(long n, long x, long y, long s)
        {


            if (s == 0)
                return 1;


            var r = Pos0(s + y - n);
            var b = Pos0(s + x - n);

            var l = Pos0(1 - y + s);
            var t = Pos0(1 - x + s);

            var ix = 1 + n - x;
            var iy = 1 + n - y;

            var bse = s*s + (s + 1)*(s + 1) - Pow2(r) - Pow2(t) - Pow2(b) - Pow2(l);

            bse += Pow2120(l - x);
            bse += Pow2120(r - x);

            bse += Pow2120(l - ix);
            bse += Pow2120(r - ix);


            return bse;
        }
    }

