    private static long pow(int p, int n, int m)
    {
        long res = 0;
        if (n == 0) return 1;

        if ((n % 2) == 0)
        {
            res = pow(p, n / 2, m);
            res = res * res;
            res %= m;

        }
        else
        {
            res = pow(p, n - 1, m);
            res = res * p;
            return res;
        }
        res %= m;
        return res;
    }

}

