        static long Solve(long N, long A, long B, long C)
        {
            switch (N % 4)
            {
                case 1:
                    return Math.Min(Math.Min(3L * A, C), A + B);

                case 2:
                    return Math.Min(Math.Min(2L * A, B), 2L * C);

                case 3:
                    return Math.Min(Math.Min(A, 3L * C), 3L * B + C);

                default:
                    return 0;
            }
        }

