namespace ProgrammingContest.Codeforces.Round51
{
    class B
    {
        public static void Main()
        {
            long[] xs = Array.ConvertAll(Console.ReadLine().Split(' '), sss => long.Parse(sss));
            bool[] ops = Array.ConvertAll(Console.ReadLine().Split(' '), sss=>sss=="+");
            long res = long.MaxValue;
            foreach (long[] ys in Permutations(xs))
            {
                long[] ys2 = new long[] { ops[0] ? ys[0] + ys[1] : ys[0] * ys[1], ys[2], ys[3] };
                foreach (long[] zs in Permutations(ys2))
                {
                    long tmp = 0;
                    tmp += ops[1] ? zs[0] + zs[1] : zs[0] * zs[1];
                    tmp = ops[2] ? tmp + zs[2] : tmp * zs[2];
                    res = Math.Min(res, tmp);
                }
            }
            Console.WriteLine(res);
        }

        private static void Swap<T>(T[] ts, int i, int j)
        {
            T tmp = ts[i];
            ts[i] = ts[j];
            ts[j] = tmp;
        }

        public static IEnumerable<T[]> Permutations<T>(T[] ts)
        {
            foreach (T[] p in Permutations(ts, 0, ts.Length))
            {
                yield return p;
            }
        }

        private static IEnumerable<T[]> Permutations<T>(T[] ts, int start, int end)
        {
            if (start == end) yield return ts;
            for (int i = start; i < end; i++)
            {
                for (int j = i - 1; j >= start; j--) Swap(ts, j, j + 1);
                foreach (T[] p in Permutations(ts, start + 1, end)) yield return p;
                for (int j = start; j < i; j++) Swap(ts, j, j + 1);
            }
        }
    }
}

