    public long Dist(long x)
    {
        x = x % 360L;
        return Math.Min(Math.Abs(x), 360 - Math.Abs(x));
    }
    public void Solve()
    {
        var n = (cin.Read<long>()) % 360L;
        var min = 0L;
        for (var i = 1L; i <= 4; i++)
        {
            var x = Dist(min * 90L - n);
            var y = Dist(i * 90L - n);
            if (y < x)
            {
                min = i;
            }
        }
        cout.WriteLine(min);
    }
}

