        {
            var top = a.A * b.B + b.A * a.B;
            var bot = a.B * b.B;

            return new Num(top, bot);
        }

        public static Num operator -(Num a, Num b)
        {
            return a + new Num(-b.A, b.B);
        }

        public static Num operator *(Num a, Num b)
        {
            var top = a.A * b.A;
            var bot = a.B * b.B;

            return new Num(top, bot);
        }

        public static Num operator /(Num a, Num b)
        {
            var top = a.A * b.B;
            var bot = a.B * b.A;

            return new Num(top, bot);
        }

        public void Normalize()
        {
            var gcd = GCD(A, B);
            if (gcd > 1)
            {
                this.A /= gcd;
                this.B /= gcd;
            }
        }

        public override string ToString()
        {
            return this.A.ToString() + "/" + this.B.ToString();
        }

        public int CompareTo(Num other)
        {
            return (this.A * other.B).CompareTo(this.B * other.A);
        }
