	class CF526_ZeptoCodeRush2015_C
	{
		public void Solve(XOI xoi)
		{
			long C, Wr, Wb, Hr, Hb, Nb, Nr, v, ans;

			C = xoi.ReadLong();
			Hr = xoi.ReadLong();
			Hb = xoi.ReadLong();
			Wr = xoi.ReadLong();
			Wb = xoi.ReadLong();

			if (Hb * Wr < Hr * Wb)
			{
				long tw = Wb, th = Hb;
				Wb = Wr; Hb = Hr;
				Wr = tw; Hr = th;
			}

			for (Nr = ans = 0; (Nr < 10000000) && (Nr * Wr <= C); Nr++)
			{
				Nb = (C - Nr * Wr) / Wb;
				v = Nb * Hb + ((C - Nb * Wb) / Wr) * Hr;
				ans = Math.Max(ans, v);
			}

			xoi.o.WriteLine(ans);
		}
	}

