class Tree
{
    public int Index;

    public Tree Left;
    public Tree Right;

    public int Price;

    public void RecalcPrice()
    {
        if(Left != null && Right != null)
        {
            var min = Math.Min(Left.Price, Right.Price);
            Left.Price -= min;
            Right.Price -= min;

            Price += min;
        }
    }

    public long CalcPrice()
    {
        long res = 0;

        if (Left != null && Right != null)
        {
            res += Left.CalcPrice();
            res += Right.CalcPrice();

            RecalcPrice();
            res += Math.Max(Left.Price, Right.Price);
            Price += Math.Max(Left.Price, Right.Price);

            Left.Price = Right.Price = 0;
        }

        return res;
    }
    public void Build(int h)
    {
        if (h == 0) return;

        Left = new Tree();
        Right = new Tree();

        Left.Build(h - 1);
        Right.Build(h - 1);
    }
    public void CalcIndex(Tree[] output)
    {
        var index = 0;

        Queue<Tree> q = new Queue<Tree>();
        q.Enqueue(this);

        while(q.Count > 0)
        {
            var t = q.Dequeue();
            t.Index = index++;
            output[t.Index] = t;

            if (t.Left != null) q.Enqueue(t.Left);
            if (t.Right != null) q.Enqueue(t.Right);
        }
    }
}
