    static long Slow(long c, long hr, long hb, long wr, long wb)
    {
        var min = 0;
        var max = c / wr;

        long res = 0;

        for (var i = min; i <= max; i++)
        {
            long c1 = i;
            long c2 = (c - wr * i) / wb;
            c1 += (c - wr * c1 - wb * c2) / wr;

            long t = c1 * hr + c2 * hb;

            res = Math.Max(t, res);
        }
        return res;
    }
    static long Fast(long c, long hr, long hb, long wr, long wb)
    {
        if (hr * wb < hb * wr)
        {
            return Fast(c, hb, hr, wb, wr);
        }

        long res1 = c / wr * hr + ((c - (c / wr) * wr) / wb) * hb;
        long res2 = 0;

        long x = ((c - (c / wr) * wr) / wb);
        for (var i = 0; i * i <= c; i++)
        {
            x++;
            if (x * wb <= c)
            {
                var t = x * hb + ((c - x * wb) / wr) * hr;
                res2 = Math.Max(t, res2);
            }
        }

        return Math.Max(res1, res2);
    }
