            {
                string[] input = Console.In.ReadToEnd().Split(new char[] { '\r', '\n', '\t', ' ' }, StringSplitOptions.RemoveEmptyEntries);
                nms = new int[3];
                for (int i = 2, curr; i < input.Length; ++i)
                {
                    curr = int.Parse(input[i]);
                    nms[0] += curr / 4;
                    curr %= 4;
                    if (curr == 3) nms[0]++;
                    else if(curr!=0) nms[curr]++;
                }
                n = Math.Min(nms[1], nms[2]);
                nms[0] += n;
                nms[1] -= n;
                nms[2] -= n;
                n = int.Parse(input[0])*4;
            }
            if (nms[2] > 0) Helper(ref n, ref nms[2], false);
            else Helper(ref n, ref nms[1], true);
            if (nms[0] * 4 > n) Console.WriteLine("NO");
            else Console.WriteLine("YES");
        }
        private static void Helper(ref int n, ref int a, bool one)
        {
            a = n - a * 2;
            if (a >= 0) n += a;
            else
            {
                a = Math.Abs(a);
                if(one) { if (a % 4 != 0) a += 2; n-=a; }
                else { n -= (int)(Math.Ceiling(a / 3d) * 4d); }
            }
        }
    }

