        static int[,] h = new int[6, 6];
        static int[,] a = new int[6, 6];
        static int[,] flow = new int[6, 6];

        static int resultFlow;
        static int resultCost;

        static void per(int v, int w, int q)
        {
            if (q < 0) throw new Exception();

            int j_bak = j[w];

            if (w == n - 1)
            {
                if (q >= l[v, w] && q <= h[v, w])
                {
                    flow[v, w] = q;
                    j[w] = j_bak + q;
                    visit(v + 1);
                }
            }
            else
            {
                for (int i = l[v, w]; i <= h[v, w]; i++)
                {
                    if (i > q) break;
                    if (q - i > 5 * (n - 1 - w)) continue;
                    flow[v, w] = i;
                    j[w] = j_bak + i;
                    per(v, w + 1, q - i);
                }
            }

            flow[v, w] = 0;
            j[w] = j_bak;
        }

        static void visit(int v)
        {
            if (v == n - 1)
            {
                if (j[n - 1] != j[0]) throw new Exception();
                if (j[n - 1] <= resultFlow)
                {
                    int cost = 0;
                    for (v = 0; v < n; v++)
                        for (int w = v + 1; w < n; w++)
                            if (flow[v, w] > 0) cost += a[v, w] + flow[v, w] * flow[v, w];
                    if (j[n - 1] < resultFlow || cost > resultCost) resultCost = cost;
                    resultFlow = j[n - 1];
                }
            }
            else
            {
                per(v, v + 1, j[v]);
            }
        }

