    class C
    {
        static int n;
        static int[] fuel;
        static List<int[]>[] xs;
        static int f,c;

        static void chk(int cost)
        {
            if (fuel[n - 1] < 0) return;
            if (f == fuel[n - 1] && c < cost) { c = cost; }
            if (f == -1 || f > fuel[n - 1]) { f = fuel[n - 1]; c = cost; }
        }

        static void dfs(int i, int j, int cost)
        {
            if (i >= n - 1) { chk(cost); return; }
            if (i == 1 && j == 0 && f != -1 && f < -fuel[0])
                return;
            if (j >= xs[i].Count)
            {
                if (i == 0 || fuel[i] == 0)
                    dfs(i + 1, 0, cost);
                return;
            }

            int dst = xs[i][j][1];
            for (int k = xs[i][j][2]; k <= xs[i][j][3]; k++)
                if (i == 0 || k <= fuel[i])
                {
                    fuel[i] -= k;
                    fuel[dst] += k;

                    int nc = k == 0 ? cost : (cost + k * k + xs[i][j][4]);
                    dfs(i, j + 1, nc);

                    fuel[dst] -= k;
                    fuel[i] += k;
                }
        }

        public static void Main()
        {
            n = int.Parse(Console.ReadLine());
            xs = new List<int[]>[n];
            fuel = new int[n];
            for (int i = 0; i < n; i++)
                xs[i] = new List<int[]>();
            for (int i = 0; i < n * (n - 1) / 2; i++)
            {
                var ys = Array.ConvertAll(Console.ReadLine().Split(' '), sss => int.Parse(sss));
                ys[0]--; ys[1]--;
                xs[ys[0]].Add(ys);
            }
            f = -1; c = -1;
            dfs(0, 0, 0);
            Console.WriteLine("{0} {1}", f, c);
        }
    }
