            r = ioHelper.ReadNextInt();

            // n = p0 * p1 *  ... * pk. pi = numar prim. p[i+1]>=p[i].
            // R = n/2 * ( (p0-1) + (p1-1)/p0 + (p2-1)/(p0*p1) + (p3-1)/(p0*p1*p2) + ... ).

            primeLimit = (int)Math.Ceiling(Math.Sqrt(r)+1);

            ans = new long[r+1];

            ans[0] = 0;
            ans[1] = 0;

            int i, j;

            primes.Add(2);

            for (i = 3; i <= primeLimit; i++)
                if (IsPrime(i))
                    primes.Add(i);

            for (i = primeLimit + 1; i <= r; i++)
                if (IsPrime(i))
                    ans[i] = (i * (long)(i - 1) / 2) % prime;

            for (j = primes.Count - 1; j >= 0; j--)
                for (i = 1; i * primes[j] <= r; i++)
                    if (ans[i] > 0 || i==1)
                    {
                        var p = primes[j];
                        var n = i * p;

                        long rz = n * (long)(p - 1) / 2;
                        rz += ans[i];

                        rz %= prime;

                        ans[n] = rz;
                    }

            long coeff = 1;
            long rez = 0;

            for(i=l;i<=r;i++)
            {
                if (ans[i] == 0)
                    ans[i] = i * (long)(i - 1) / 2;

                ans[i] %= prime;

                rez += (ans[i] * coeff) % prime;

                rez %= prime;

                coeff *= t;
                coeff %= prime;
            }

            ioHelper.WriteLine(rez.ToString());
            ioHelper.Flush();

            //Console.ReadKey();
        }

        public Program(string inputFile, string outputFile)
        {
            ioHelper = new IOHelper(inputFile, outputFile, Encoding.Default);
            Solve();
            ioHelper.Dispose();
        }

        static void Main(string[] args)
        {
            Program myProgram = new Program(null, null);
        }
    }
}

