class A
{
    public static List<long> GetDivisors(long n)
    {

        // Note that this loop runs  
        // till square root 
        var list = new List<long>();
        for (long i = 1; i <= Math.Sqrt(n); i++)
        {
            if (n % i == 0)
            {
                // If divisors are equal, 
                // print only one 
                if (n / i == i)
                {
                    list.Add(i);
                }
                else
                {
                    list.Add(i);
                    list.Add(n / i);
                }
            }
        }
        return list;
    }

    public static long GCD(long a, long b)
    {
        if (b == 0)
        {
            return a;
        }

        return GCD(b, a % b);
    }
    public static void Main(string[] args)
    {
        int t = 1;
        while (t > 0)
        {
            var n = long.Parse(Console.ReadLine());
            var div = GetDivisors(n);
            if (div.Count <= 2)
                Console.WriteLine(n);
            else
            {
                var sorted = div.OrderBy(x => x).ToArray();
                var ans = sorted[1];
                for (int i = 2; i < sorted.Count(); i++)
                {
                    ans = GCD(ans, sorted[i]);
                }
                Console.WriteLine(ans);
            }
            t--;
        }
    }
}

