            var res = tutu(a, s, 0, s.Count - 1);
            Console.WriteLine(res);
        }

        // tutu(a, s, 0, s.Count - 1)
        static int tutu(int[,] a, List<char> s, int from, int to)
        {
            if (a[from, to] == 0)
            {
                if (from == to)
                    return 1;
                var res = int.MaxValue;

                if (s[from] == s[to])
                {
                    res = tutu(a, s, from + 1, to);
                }
                else
                {
                    for (int i = from; i < to; i++)
                    {
                        var z = tutu(a, s, from, i) + tutu(a, s, i + 1, to);
                        if (s[from] == s[i + 1] || s[i] == s[to])
                            z--;
                        res = Math.Min(res, z);
                    }
                }
                a[from, to] = res;
            }
            return a[from, to];
        }



    }
}

