namespace cf_82_div2
{

    class Program
    {
        private static HashSet<int> delims =
            new HashSet<int> { (int)' ', (int)'\t', (int)'\n', (int)'\r' };
        private static StringBuilder token = new StringBuilder();

        private static void Skip()
        {
            while (delims.Contains(Console.In.Peek()))
                Console.Read();
        }

        public static bool EndOfStream()
        {
            Skip();
            return Console.In.Peek() == -1;
        }

        public static string Read()
        {
            Skip();
            int c = Console.Read();
            while (c != -1 && !delims.Contains(c))
            {
                token.Append((char)c);
                c = Console.Read();
            }
            string ret = token.ToString();
            token.Length = 0;
            return ret;
        }

        public static int ReadInt()
        {
            return int.Parse(Read());
        }

        public static double ReadDouble()
        {
            return double.Parse(Read());
        }

        public static bool solve()
        {
            int[][] dp;
            int[] cnt, cost, weight;
            int n, W, a, b, c;
            W = ReadInt();
            n = ReadInt();
            n++;

            cnt = new int[n];
            cost = new int[n];
            weight = new int[n];
            dp = new int[2][];
            for (int i = 0; i < 2; i++)
                dp[i] = new int[W + 1];

            c = ReadInt();
            weight[0] = c;
            cost[0] = ReadInt();
            cnt[0] = W / c;
            for (int i = 1; i < n; i++)
            {
                a = ReadInt();
                b = ReadInt();
                c = ReadInt();
                cost[i] = ReadInt();
                cnt[i] = System.Math.Min(a / b, W / c);
                weight[i] = c;
            }

            for (int i = 0; i < n; i++)
            {
                for (int it = 0; it < cnt[i]; it++)
                {
                    for (int w = 0; w + weight[i] <= W; w++)
                    {
                        dp[1][w + weight[i]] = System.Math.Max(dp[1][w + weight[i]], dp[0][w] + cost[i]);
                    }
                    System.Array.Copy(dp[1], dp[0], dp[1].Length);
                }
            }

            int ans = 0;
            for (int i = 0; i <= W; i++)
                ans = System.Math.Max(ans, dp[0][i]);
            Console.WriteLine(ans);
            return false;
        }

        static void Main(string[] args)
        {
            //StreamReader reader = new StreamReader("input.txt");
            //StreamWriter writer = new StreamWriter("output.txt");
            //Console.SetIn(reader);
            //Console.SetOut(writer);
            while (solve() == true);
        }
    }
}

