public class Program
{

    BinomialCoefficient C;
    public void Solve()
    {
        C = new BinomialCoefficient(500000);

        var sc = new Scanner();
#if !DEBUG
        Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
#endif
        int t = sc.NextInt();
        for (int i = 0; i < t; i++)
        {
            Q(sc);
        }
        Console.Out.Flush();
    }

    void Q(Scanner sc)
    {
        int n = sc.NextInt();
        int k = sc.NextInt();

        var dp = new ModInt[k + 1, 2];
        dp[0, 0] = 1;
        ModInt t1 = 0;
        for (int i = 0; i < n; i += 2)
        {
            t1 += C[n, i];
        }
        for (int i = 0; i < k; i++)
        {
            // 
            {
                // j=0
                // 全部1
                // and側 1
                // xor側 n%2
                if (n % 2 == 0)
                {
                    dp[i + 1, 1] += dp[i, 0];
                }
                else
                {
                    dp[i + 1, 0] += dp[i, 0];
                }

                // 1じゃないやつある
                // and側0
                // xor側 1の個数偶数
                // 
                dp[i + 1, 0] += dp[i, 0] * t1;
            }
            {
                // j =1
                dp[i + 1, 1] += dp[i, 1] * ModInt.Pow(2, n);
            }
        }

        Console.WriteLine(dp[k, 0] + dp[k, 1]);
    }

    public static void Main(string[] args) => new Program().Solve();
