    class Heap<T> : IEnumerable<T> where T : IComparable<T> {
        private List<T> heap = new List<T>();
        private int heapSize;
        private int Parent(int index) {
            return (index - 1) >> 1;
        }
        public int Count {
            get { return heap.Count; }
        }
        private int Left(int index) {
            return (index << 1) | 1;
        }
        private int Right(int index) {
            return (index << 1) + 2;
        }
        private void Max_Heapify(int i) {
            int l = Left(i);
            int r = Right(i);
            int largest = i;
            if (l < heapSize && heap[l].CompareTo(heap[i]) > 0)
                largest = l;
            if (r < heapSize && heap[r].CompareTo(heap[largest]) > 0)
                largest = r;
            if (largest != i) {
                T temp = heap[largest];
                heap[largest] = heap[i];
                heap[i] = temp;
                Max_Heapify(largest);
            }
        }
        private void BuildMaxHeap() {
            for (int i = heap.Count >> 1; i >= 0; --i)
                Max_Heapify(i);
        }

        public IEnumerator<T> GetEnumerator() {
            return heap.GetEnumerator();
        }

        public void Sort() {
            for (int i = heap.Count - 1; i > 0; --i) {
                T temp = heap[i];
                heap[i] = heap[0];
                heap[0] = temp;
                --heapSize;
                Max_Heapify(0);
            }
        }

        public T Heap_Extract_Max() {
            T max = heap[0];
            heap[0] = heap[--heapSize];
            Max_Heapify(0);
            return max;
        }

        public void Clear() {
            heap.Clear();
            heapSize = 0;
        }

        public void Insert(T item) {
            if (heapSize < heap.Count)
                heap[heapSize] = item;
            else
                heap.Add(item);
            int i = heapSize;
            while (i > 0 && heap[Parent(i)].CompareTo(heap[i]) < 0) {
                T temp = heap[i];
                heap[i] = heap[Parent(i)];
                heap[Parent(i)] = temp;
                i = Parent(i);
            }
            ++heapSize;
        }

        IEnumerator IEnumerable.GetEnumerator() {
            return ((IEnumerable)heap).GetEnumerator();
        }
    }    
    public class Treap<T> where T:IComparable<T> {
        private static Random rand = new Random();
        public static Treap<T> Merge(Treap<T> l, Treap<T> r) {
            if (l == null) return r;
            if (r == null) return l;
            Treap<T> res = null;
            if (l.y > r.y) {
                Treap<T> newR = Merge(l.right, r);
                res = new Treap<T>(l.x, l.y, l.left, newR);
            }
            else {
                Treap<T> newL = Merge(l, r.left);
                res = new Treap<T>(r.x, r.y, newL, r.right);
            }            
            return res;
        }

        public bool Contains(T key) {
            if (x.CompareTo(key) > 0)
                return left == null ? false : left.Contains(key);
            else if (x.CompareTo(key) < 0)
                return right == null ? false : right.Contains(key);
            return true;
        }

        public void Split(T x, out Treap<T> l, out Treap<T> r) {
            Treap<T> newTree = null;
            if (this.x.CompareTo(x)<0) {
                if (right == null)
                    r = null;
                else
                    right.Split(x, out newTree, out r);
                l = new Treap<T>(this.x, y, left, newTree);        
            }
            else {
                if (left == null)
                    l = null;
                else
                    left.Split(x, out l, out newTree);
                r = new Treap<T>(this.x, y, newTree, right);                
            }
        }

        public Treap<T> Add(T x) {
            Treap<T> l, r;
            Split(x, out l, out r);
            Treap<T> m = new Treap<T>(x, rand.Next());
            return Merge(Merge(l, m), r);
        }

        private T x;
        private int y;
        private Treap<T> left, right;
        public Treap(T x, int y, Treap<T> l, Treap<T> r) {
            this.x = x;
            this.y = y;
            left = l;
            right = r;
        }
        public Treap(T x, int y) : this(x, y, null, null) { }
        public Treap(T x) : this(x, rand.Next()) { }
    }
