        {
            if(b==3)
            {
                return (a==1||a==2||a==4||a==5);
            }
            if (b % 2 == 0)
            {
                int mod = a % 4;
                if (mod > 0) return false;
                int div = a / 4;
                int can = (((b - 1) / 2) * ((b - 1) / 2) + 1) / 2;
                return div <= can;
