    class Program
    {
        int getCount(int curNum, int maxNum)
        {
            int res = curNum == 0 ? 0 : 1;
            if (curNum * 10L + 4 <= maxNum)
                res += getCount(curNum * 10 + 4, maxNum);
            if (curNum * 10L + 7 <= maxNum)
                res += getCount(curNum * 10 + 7, maxNum);
            return res;
        }

        void swap(int[] arr, int a, int b)
        {
            int temp = arr[a];
            arr[a] = arr[b];
            arr[b] = temp;
        }

        void permute(int[] array, int k)
        {
            while (k > 1)
            {
                int curFact = 1;
                int prevFact = 1;
                int pos = 1;
                while (curFact < k)
                {
                    pos++;
                    prevFact = curFact;
                    curFact *= pos;
                }
                int absPos0 = array.Length - pos;
                int shift = (k - 1) / prevFact;
                int absPos1 = absPos0 + shift;
                swap(array, absPos0, absPos1);
                if (pos > 1)
                {
                    Array.Sort(array, absPos0 + 1, pos - 1);
                }

                k -= prevFact * shift;
            }
        }

        bool isLucky(int x)
        {
            while (x > 0)
            {
                if (x % 10 != 4 && x % 10 != 7)
                    return false;
                x /= 10;
            }
            return true;
        }

