    class ProgramPermutations
    {
        public static int[] Digits(int num)
        {
            var d = new Stack<int>();
            if (num == 0) d.Push(0);

            while (num > 0)
            {
                d.Push(num % 10);
                num /= 10;
            }

            return d.ToArray();
        }

        public static int DigitsToNum(int[] digits)
        {
            var result = 0;
            var mult = 1;
            for (var i = digits.Length - 1; i >= 0; i--)
            {
                result += digits[i] * mult;
                mult *= 10;
            }

            return result;
        }

        static IEnumerable<int[]> GetPerms(List<int> seq)
        {
            seq.Sort();
            var len = seq.Count();
            var n = len - 1;
            var lst = new List<int[]> {seq.ToArray()};

            while (true)
            {
                var k = -1;
                for (var i = 0; i < n; i++)
                {
                    if (seq[i] < seq[i + 1]) k = i;
                }
                if (k == -1) break;
                var l = -1;
                for (var i = 0; i < len; i++)
                {
                    if (seq[k] < seq[i]) l = i;
                }
                var temp = seq[k];
                seq[k] = seq[l];
                seq[l] = temp;

                var seqNext = new int[len];
                for (var i = 0; i <= k; i++)
                {
                    seqNext[i] = seq[i];
                }
                for (var i = n; i > k; i--)
                {
                    seqNext[k + len - i] = seq[i];
                }
                lst.Add(seqNext);
                seq = new List<int>(seqNext);
                //Console.WriteLine(DigitsToNum(seqNext));
            }

            return lst;
        }

        static bool GreaterThan(IList<int> num1, IList<int> num2, int k)
        {
            for (var i = 0; i < k; i++)
            {
                if (num1[i] < num2[i]) return false;
                if (num1[i] > num2[i]) return true;
            }
            return false;
        }

        static bool LessThan(IList<int> num1, IList<int> num2, int k)
        {
            for (var i=0; i<k; i++)
            {
                if (num1[i] > num2[i]) return false;
                if (num1[i] < num2[i]) return true;
            }
            return false;
        }

        static void Main(string[] args)
        {
            if (args.Count() > 0)
            {
                var r = new Random(1021);

                Console.WriteLine("{0} {1}", args[0], args[1]);
                for (var i=0; i<int.Parse(args[0]); i++)
                {
                    for (var j=0; j<int.Parse(args[1]); j++)
                    {
                        Console.Write(r.Next(0, 10));
                    }
                    Console.WriteLine();
                }

                return;
            }

            var strParams = Console.ReadLine();
            if (string.IsNullOrEmpty(strParams)) return;
            var strnk = strParams.Split();
            var n = int.Parse(strnk[0]);
            var k = int.Parse(strnk[1]);
            var nums = new List<List<int>>();
            for (var i = 0; i < n; i++)
            {
                var strNum = Console.ReadLine();
                if (string.IsNullOrEmpty(strNum)) return;
                var num = strNum.Select(c => c - 48).ToList();
                nums.Add(num);
            }

            // Numbers from 0..k-1 in order
            var seq = new List<int>();
            for (var i=0; i<k; i++)
            {
                seq.Add(i);
            }

            // Permute them
            var permsTemplate = GetPerms(seq);

/*
            foreach (var intse in permsTemplate)
            {
                Console.WriteLine(DigitsToNum(intse));
            }
            return;
*/

            var minDifference = Int32.MaxValue;
            foreach (var perm in permsTemplate)
            {
                // Permute each input number according to the same permutation rule
                //var maxNum = Int32.MinValue;
                //var minNum = Int32.MaxValue;
                var maxNum = new List<int>();
                var minNum = new List<int>();
                for (var i = 0; i < k; i++)
                {
                    maxNum.Add(0);
                    minNum.Add(9);
                }

                foreach (var i in nums)
                {
                    var permDigits = new int[k];
                    for (var j = 0; j < k; j++)
                    {
                        permDigits[j] = i[perm[j]];
                    }
                    if (GreaterThan(permDigits, maxNum, k)) maxNum = new List<int>(permDigits);
                    if (LessThan(permDigits, minNum, k)) minNum = new List<int>(permDigits);
                    //var newNum = DigitsToNum(permDigits);
