    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();
            int k = Next();

            var nn = new int[n][];
            for (int i = 0; i < nn.Length; i++)
            {
                nn[i] = new int[k];
            }
            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < k; j++)
                {
                    nn[i][j] = Next();
                }
            }

            var perm = new int[k];
            for (int i = 0; i < k; i++)
            {
                perm[i] = i;
            }

            int min = int.MaxValue;

            do
            {
                int mi = int.MaxValue;
                int ma = int.MinValue;

                for (int i = 0; i < n; i++)
                {
                    int sum = 0;
                    for (int j = 0; j < k; j++)
                    {
                        sum = sum*10 + nn[i][perm[j]];
                    }
                    mi = Math.Min(mi, sum);
                    ma = Math.Max(ma, sum);
                }

                min = Math.Min(min, ma - mi);
            } while (NextPermutation(perm));

            writer.WriteLine(min);
            writer.Flush();
        }

        private static bool NextPermutation(int[] nn)
        {
            if (nn.Length <= 1) return false;
            int i = nn.Length - 1;
            int last = nn.Length;

            while (true)
            {
                int i1 = i;
                if (nn[--i] < nn[i1])
                {
                    int i2 = last;
                    while (!(nn[i] < nn[--i2]))
                    {
                        ;
                    }
                    int c = nn[i];
                    nn[i] = nn[i2];
                    nn[i2] = c;

                    Reverse(nn, i1, last);
                    return true;
                }
                if (i == 0)
                {
                    Reverse(nn, 0, last);
                    return false;
                }
            }
        }

        private static void Reverse(int[] nn, int first, int last)
        {
            while ((first != last) && (first != --last))
            {
                int c = nn[first];
                nn[first] = nn[last];
                nn[last] = c;
                first++;
            }
        }

        private static int Next()
        {
            int c;
            do
            {
                c = reader.Read();
            } while (c < '0' || c > '9');
            return c - '0';
        }
    }
