﻿using System;
using System.Collections.Generic;
using System.Text;

namespace round516
{
  class MainClass
  {
    static long solve(long n, long a, long b, long k, long p)
    {
      long result = -1;
      if (n <= k / n / n)
      { // by sweet tooth
        for (long a_extra = p; a_extra <= a; ++a_extra)
          for (long b_extra = 0; b_extra <= b; ++b_extra)
            if ((k - a - a_extra) % (n + a_extra + b_extra) == 0)
              result = Math.Max(result, a_extra + b_extra);
      }
      else
      {
        for (long round = (k - 2 * a - 1) / (2 * n) + 1; round <= (k - a) / n; ++round)
        {
          long a_extra = (k - a) % round;
          if (a_extra < p) a_extra += round;
          long b_extra = (k - a - a_extra) / round - n - a_extra;
          if (b_extra > n - a)
          {
            long t = (b_extra - n + a - 1) / (round + 1) + 1;
            a_extra += round * t;
            b_extra -= (round + 1) * t;
          }
          if (a_extra <= a && b_extra >= 0)
            result = Math.Max(result, a_extra + b_extra);
        }
      }
      return result;
    }

    public static void Main(string[] args)
    {
      var line = Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
      var n = line[0];
      var l = line[1];
      var r = line[2];
      var k = line[3];

      if (l > r)
        r = n - l + r + 1;
      else
        r = r - l + 1;
      l = 1;
      var b = n - r;

      long result = -1;

      if (k <= n || k <= r * 2)
      {
        if (r <= k && k <= r * 2)
        {
          long a_extra = k - r;
          result = Math.Min(b + a_extra + 1, n);
        }
      }
      else
      { 
        result = Math.Max(solve(n, r, b, k, 0), solve(n, r, b, k + 1, 1));
      }

      Console.WriteLine(result);
    }
  }
}

