        private static bool s_time = false;
        private static double s_eps = 1e-16;

        HashSet<long>[] adj;

        private void Go()
        {
            long n = GetInt();
            long m = GetInt();

            adj = new HashSet<long>[n];
            for (int i = 0; i < n; i++)
            {
                adj[i] = new HashSet<long>();
            }

            for (int i = 0; i < m; i++)
            {
                long x = GetInt() - 1;
                long y = GetInt() - 1;
                adj[x].Add(y);
                adj[y].Add(x);
            }

            int[] visited = new int[n];

            for (int i = 0; i < n; i++)
            {
                if (adj[i].Count == n - 1)
                    visited[i] = -1;
            }

            int compCount = 0;

            for (int i = 0; i < n; i++)
            {
                if (visited[i] == 0)
                {
                    Queue<Tuple<long, int>> q = new Queue<Tuple<long, int>>();
                    visited[i] = ++compCount;
                    q.Enqueue(new Tuple<long, int>(i, compCount));
                    while (q.Count > 0)
                    {
                        var node = q.Dequeue();
                        long x = node.Item1;
                        foreach (long child in adj[x])
                        {
                            if (visited[child] == 0)
                            {
                                q.Enqueue(new Tuple<long, int>(child, compCount));
                                visited[child] = compCount;
                            }
                        }
                    }
                }
            }

            if (compCount > 2)
            {
                Wl("No");
                return;
            }

            for (int i = 0; i < n; i++)
            {
                for (int j = 0; j < n; j++)
                {
                    if (i != j && !adj[i].Contains(j) && (visited[i] + visited[j]) != 3)
                    {
                        Wl("No");
                        return;
                    }
                }
            }

            Wl("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++)
            {
                if (visited[i] == -1) sb.Append('b');
                else if (visited[i] == 1) sb.Append('a');
                else sb.Append('c');
            }
            Wl(sb.ToString());
        }

        #region Template

        public static void Main(string[] args)
        {
            System.Diagnostics.Stopwatch timer = new System.Diagnostics.Stopwatch();
            Thread main = new Thread(new ThreadStart(s_threadStart), 200 * 1024 * 1024);
            timer.Start();
            main.Start();
            main.Join();
            timer.Stop();
            if (s_time)
                Wl(timer.ElapsedMilliseconds);
        }

        private static IEnumerator<string> ioEnum;
        private static string GetString()
        {
            while (ioEnum == null || !ioEnum.MoveNext())
            {
                ioEnum = Console.ReadLine().Split().AsEnumerable().GetEnumerator();
            }

            return ioEnum.Current;
        }

        private static int GetInt()
        {
            return int.Parse(GetString(), CultureInfo.InvariantCulture);
        }

        private static long GetLong()
        {
            return long.Parse(GetString(), CultureInfo.InvariantCulture);
        }

