﻿using System;
using System.Linq;

namespace Hamburgers
{
    class Hamburgers
    {
        static void Main(string[] args)
        {
            string hamburger;
            long[] kitchenPieces, shopPrices;
            long rubles, count, numB = 0, numS = 0, numC = 0;

            hamburger = Console.ReadLine();
            kitchenPieces = Console.ReadLine().Split().Select(long.Parse).ToArray();
            shopPrices = Console.ReadLine().Split().Select(long.Parse).ToArray();
            rubles = long.Parse(Console.ReadLine());

            for (int i = 0; i < hamburger.Length; i++)
            {
                if (hamburger[i] == 'B')
                    numB++;
                else if (hamburger[i] == 'S')
                    numS++;
                else
                    numC++;
            }

            Console.WriteLine(BinarySearch(0, 1L<<45, numB, numS, numC, kitchenPieces, shopPrices, rubles));
        }

        private static long BinarySearch(long start, long end, long numB, long numS, long numC, long[] kitchenPieces, long[] shopPrices, long rubles)
        {
            long mid = (start + end) / 2;

            if (end - start <= 1)
            {
                if (MaxRublesUsed(end, numB, numS, numC, kitchenPieces, shopPrices, rubles))
                    return end;
                else
                    return start;
            }

            if (MaxRublesUsed(mid, numB, numS, numC, kitchenPieces, shopPrices, rubles))
                return BinarySearch(mid, end, numB, numS, numC, kitchenPieces, shopPrices, rubles);
            else
                return BinarySearch(start, mid, numB, numS, numC, kitchenPieces, shopPrices, rubles);
        }

        private static bool MaxRublesUsed(long num, long numB, long numS, long numC, long[] kitchenPieces, long[] shopPrices, long rubles)
        {
            long b, s, c;

            b = Math.Max(0, (numB * num) - kitchenPieces[0]) * shopPrices[0];
            s = Math.Max(0, (numS * num) - kitchenPieces[1]) * shopPrices[1];
            c = Math.Max(0, (numC * num) - kitchenPieces[2]) * shopPrices[2];

            return rubles >= (b + s + c);
        }
    }
}

