        static void Main(string[] args)
        {
            var str = Console.ReadLine();
            var n = Int32.Parse(str);

            var fi = new int[n + 1];
            var used = new int[3 * n];
            var kucha = new int[n + 1];

            for (int i = 3; i <= n; ++i)
            {
                for (int k = 2; k <= 4 * (int)Math.Sqrt(i); ++k)
                {
                    var delta = i - (k*(k - 1))/2;
                    if (delta <= 0)
                        break;

                    if (delta % k != 0)
                        continue;

                    var c = delta/k;
                    var curFi = 0;
                    for (int j = 0; j < k; ++j)
                    {
                        curFi = curFi ^ fi[c + j];
                    }
                    used[curFi] = i;
                    if (curFi == 0 && kucha[i] == 0)
                    {
                        kucha[i] = k;
                    }
                }

                if (kucha[i] > 0)
                {
                    for (int j = 0; j <= n; ++j)
                    {
                        if (used[j] != i)
                        {
                            fi[i] = j;
                            break;
                        }
                    }
                }
            }
            if (fi[n] == 0)
            {
                Console.WriteLine(-1);
            }
            else
            {
                Console.WriteLine(kucha[n]);
            }
        }
    }
}

