        List<int> a;
        int n, result;

        public override void SolveProblem()
        {
            a = new List<int>();
            n = int.Parse(Console.ReadLine());
            result = Math.Min(n, 2);

            String[] input = Console.ReadLine().Split();
            foreach (String s in input)
                a.Add(int.Parse(s));

            for (int i = 1; i < n-1; i++)
            {
                result = Math.Max(result, GetMaxNonDec(0, i) + GetMaxNonDec(i, n - i));
            }
            Console.WriteLine(result);

        }

        int GetMaxNonDec(int start, int length)
        {
            if (length <= 0)
                return 0;

            int[] oneNum, twoNum;
            oneNum = new int[length];
            twoNum = new int[length];
            oneNum[0] = a[start] == 1 ? 1 : 0;
            twoNum[0] = a[start + length - 1] == 2 ? 1 : 0;

            for (int i = 1; i < length; i++ )
            {
                oneNum[i] = oneNum[i-1];
                twoNum[i] = twoNum[i-1];
                if (a[start + i] == 1)
                    oneNum[i]++;
                if (a[start + length - 1 - i] == 2)
                    twoNum[i]++;
            }

            int result = Math.Min(length, 2);
            for (int i = 0; i < length; i++)
                result = Math.Max(result, oneNum[i] + twoNum[length - i - 1]);
            return result;
        }
    }

