            foreach (String s in input)
                b.Add(Int64.Parse(s));

            a.Sort();
            b.Sort();

            Int64 p11, p12, p21, p22;
            p11 = Math.Max(a[1] * b[0], a[1] * b[m-1]);
            p12 = Math.Max(a[n - 1] * b[0], a[n - 1] * b[m - 1]);
            p21 = Math.Max(a[0] * b[0], a[0] * b[m - 1]);
            p22 = Math.Max(a[n - 2] * b[0], a[n - 2] * b[m - 1]);

            result = Math.Min(Math.Max(p11, p12), Math.Max(p21, p22));

