class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        long p = cin.nextLong();
        long k = cin.nextLong();

        long now = p;
        List<long> ans = new List<long>();
        while (now < 0 || now >= k)
        {
            if (ans.Count >= 1000000) break;
            long mul;
            if (now > 0) mul = now / k;
            else mul = -((-now + (k - 1)) / k);
            now -= mul * k;
            ans.Add(now);
            now = -mul;
        }
        if(ans.Count >= 1000000)
        {
            Console.WriteLine(-1);
            return;
        }
        ans.Add(now);

        Console.WriteLine(ans.Count);
        Console.WriteLine(string.Join(" ", ans));
    }


}

class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
