        public class NTTFastLong
        {
            private int curBase = 1;
            private long[] roots = { 0, 1 };
            private int[] rev = { 0, 1 };
            private int maxBase = -1;
            private int root = -1;

            private readonly long MOD;

            public NTTFastLong(long mod)
            {
                MOD = mod;
            }

            private void Init()
            {
                long tmp = MOD - 1;
                maxBase = 0;
                while (tmp % 2 == 0)
                {
                    tmp /= 2;
                    maxBase++;
                }
                root = 2;
                while (true)
                {
                    if (Power(root, 1 << maxBase) == 1)
                    {
                        if (Power(root, 1 << (maxBase - 1)) != 1)
                        {
                            break;
                        }
                    }
                    root++;
                }
            }

            void ensure_base(int nBase)
            {
                if (maxBase == -1)
                {
                    Init();
                }
                if (nBase <= curBase)
                {
                    return;
                }
                if (nBase > maxBase)
                {
                    throw new InvalidOperationException();
                }
                Array.Resize(ref rev, 1 << nBase);
                for (int i = 0; i < (1 << nBase); i++)
                {
                    rev[i] = (rev[i >> 1] >> 1) + ((i & 1) << (nBase - 1));
                }
                Array.Resize(ref roots, 1 << nBase);
                while (curBase < nBase)
                {
                    long z = Power(root, 1 << (maxBase - 1 - curBase));
                    for (int i = 1 << (curBase - 1); i < (1 << curBase); i++)
                    {
                        roots[i << 1] = roots[i];
                        roots[(i << 1) + 1] = roots[i] * z % MOD;
                    }
                    curBase++;
                }
            }

            public void FFT(long[] a)
            {
                int n = a.Length;
                if ((n & (n - 1)) != 0)
                {
                    throw new InvalidOperationException();
                }
                int zeros = get__builtin_ctz(n);
                ensure_base(zeros);
                int shift = curBase - zeros;
                for (int i = 0; i < n; i++)
                {
                    if (i < (rev[i] >> shift))
                    {
                        long tmp = a[i];
                        a[i] = a[rev[i] >> shift];
                        a[rev[i] >> shift] = tmp;
                    }
                }
                for (int k = 1; k < n; k <<= 1)
                {
                    for (int i = 0; i < n; i += 2 * k)
                    {
                        for (int j = 0; j < k; j++)
                        {
                            long x = a[i + j];
                            long y = a[i + j + k] * roots[j + k] % MOD;
                            a[i + j] = x + y - MOD;
                            if (a[i + j] < 0)
                            {
                                a[i + j] += MOD;
                            }
                            a[i + j + k] = x - y + MOD;
                            if (a[i + j + k] >= MOD)
                            {
                                a[i + j + k] -= MOD;
                            }
                        }
                    }
                }
            }

            // todo: rename? remove?
            private int get__builtin_ctz(int n)
            {
                int c = 0;
                while (n > 0 && (n & 1) == 0)
                {
                    c++;
                    n >>= 1;
                }
                return c;
            }

            public long[] Multiply(long[] a, long[] b, int eq = 0)
            {
                int need = a.Length + b.Length - 1;
                int nbase = 0;
                while ((1 << nbase) < need)
                {
                    nbase++;
                }
                ensure_base(nbase);
                int sz = 1 << nbase;
                Array.Resize(ref a, sz);
                Array.Resize(ref b, sz);
                FFT(a);
                if (eq != 0)
                {
                    b = a;
                }
                else
                {
                    FFT(b);
                }
                long invSz = Inv(sz);
                for (int i = 0; i < sz; i++)
                {
                    a[i] = a[i] * b[i] % MOD * invSz % MOD;
                }
                Array.Reverse(a, 1, a.Length - 1);
                FFT(a);

                int newSize = need;
                while (newSize > 0 && a[newSize - 1] == 0)
                {
                    newSize--;
                }
                Array.Resize(ref a, newSize);

                return a;
            }

            public long[] Square(long[] a)
            {
                return Multiply(a, a, 1);
            }

            public long Power(long a, long b)
            {
                long res = 1;
                while (b > 0)
                {
                    if ((b & 1) > 0)
                    {
                        res = res * a % MOD;
                    }
                    a = a * a % MOD;
                    b >>= 1;
                }
                return res;
            }

            public long Inv(long a)
            {
                a %= MOD;
                if (a < 0)
                {
                    a += MOD;
                }
                long b = MOD;
                long u = 0;
                long v = 1;
                while (a != 0)
                {
                    long t = b / a;
                    b -= t * a;

                    long tmp = a;
                    a = b;
                    b = tmp;

                    u -= t * v;

                    tmp = u;
                    u = v;
                    v = tmp;
                }
                if (u < 0)
                {
                    u += MOD;
                }
                return u;
            }
        }

