    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();
            int k = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next();
            }

            var near = new int[n];
            var last = new int[n + 1];

            for (int i = 0; i < last.Length; i++)
            {
                last[i] = n;
            }

            for (int i = n - 1; i >= 0; i--)
            {
                near[i] = last[nn[i]];
                last[nn[i]] = i;
            }

            int count = 0;
            var heap = new MaxBinaryHeapObject<Point>(new Point());
            var f = new bool[n + 1];
            for (int i = 0; i < nn.Length; i++)
            {
                if (k <= 0 && !f[nn[i]])
                {
                    remove:
                    var t = heap.GetMax();
                    if (!f[t.index])
                    {
                        goto remove;
                    }

                    f[t.index] = false;
                }

                if (!f[nn[i]])
                {
                    count++;
                    f[nn[i]] = true;
                    k--;
                }
                heap.Add(new Point {index = nn[i], near = near[i]});
            }

            writer.WriteLine(count);
            writer.Flush();
        }


        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }

        #region Nested type: MaxBinaryHeapObject

        public class MaxBinaryHeapObject<T>
        {
            private readonly IComparer<T> _comparer;
            private readonly List<T> _list;

            public MaxBinaryHeapObject(IComparer<T> comparer)
            {
                _comparer = comparer ?? Comparer<T>.Default;
                _list = new List<T>();
            }

            public int HeapSize
            {
                get { return _list.Count; }
            }

            public void Add(T value)
            {
                _list.Add(value);
                int i = HeapSize - 1;
                int parent = (i - 1)/2;

                while (i > 0 && _comparer.Compare(_list[parent], _list[i]) == -1)
                {
                    T temp = _list[i];
                    _list[i] = _list[parent];
                    _list[parent] = temp;

                    i = parent;
                    parent = (i - 1)/2;
                }
            }

            public void Heapify(int i)
            {
                for (;;)
                {
                    int leftChild = 2*i + 1;
                    int rightChild = 2*i + 2;
                    int largestChild = i;

                    if (leftChild < HeapSize && _comparer.Compare(_list[leftChild], _list[largestChild]) == 1)
                    {
                        largestChild = leftChild;
                    }

                    if (rightChild < HeapSize && _comparer.Compare(_list[rightChild], _list[largestChild]) == 1)
                    {
                        largestChild = rightChild;
                    }

                    if (largestChild == i)
                    {
                        break;
                    }

                    T temp = _list[i];
                    _list[i] = _list[largestChild];
                    _list[largestChild] = temp;
                    i = largestChild;
                }
            }

            public T Max()
            {
                return _list[0];
            }

            public T GetMax()
            {
                T result = _list[0];
                _list[0] = _list[HeapSize - 1];
                _list.RemoveAt(HeapSize - 1);
                Heapify(0);
                return result;
            }
        }

        #endregion

        #region Nested type: Point

        private class Point : IComparer<Point>
        {
            public int index;
            public int near;

            #region IComparer<Point> Members

            public int Compare(Point x, Point y)
            {
                return x.near.CompareTo(y.near);
            }

            #endregion
        }

        #endregion
    }
}

