    class Program
    {
        MyIo io = new MyIo();

        enum State
        {
            Empty = 0,
            OwnerOnly = 1,
            WithGuest = 2
        }

        int R, C;

        State[,] map;

        Dictionary<long, int> memo;

        long makeConfig(int r, int c)
        {
            long cfg = 0;
            int lowR = Math.Max(0, r - 1);
            int highR = Math.Min(R - 1, r + 1);

            int abs = r * C + c;

            int lowAbs = Math.Max(0, abs - C);
            int highAbs = Math.Min(R * C - 1, abs + C);

            for (int curAbs = lowAbs; curAbs <= highAbs; curAbs++)
            {
                int curR = curAbs / C;
                int curC = curAbs % C;

                cfg <<= 2;
                cfg |= (uint)map[curR, curC];
            }
            cfg <<= 6;
            cfg |= (uint)r;
            cfg <<= 6;
            cfg |= (uint)c;

            return cfg;
        }

        int[][] dirs = new int[][]
        {
            new int[] {0, -1},
            new int[] {0, 1},
            new int[] {1, 0},
            new int[] {-1, 0}
        };

        int xfx(int r, int c)
        {
            if (r == R)
            {
                return 0;
            }
            if (c == C)
            {
                return xfx(r + 1, 0);
            }

            long cfg = makeConfig(r, c);
            if (memo.ContainsKey(cfg))
            {
                return memo[cfg];
            }

            if (map[r, c] == State.Empty)
            {
                return xfx(r, c + 1);
            }

            if (map[r, c] == State.WithGuest)
            {
                return xfx(r, c + 1);
            }

            int ans = xfx(r, c + 1); // no move

            map[r, c] = State.Empty;

            foreach (int[] d in dirs)
            {
                int nR = r + d[0];
                int nC = c + d[1];

                if (nR >= 0 && nR < R && nC >= 0 && nC < C)
                {
                    var oldState = map[nR, nC];
                    int curAns = oldState == State.Empty ? 0 : 1;

                    map[nR, nC] = State.WithGuest;

                    curAns += xfx(r, c + 1);
                    map[nR, nC] = oldState;

                    ans = Math.Max(ans, curAns);
                }
            }

            map[r, c] = State.OwnerOnly;

            memo[cfg] = ans;

            return ans;
        }

        void Solve()
        {
            memo = new Dictionary<long, int>();

            R = io.NextInt();
            C = io.NextInt();

            if (C > R)
            {
                R += C;
                C = R - C;
                R = R - C;
            }

            map = new State[R, C];

            for (int r = 0; r < R; r++)
            {
                for (int c = 0; c < C; c++)
                {
                    map[r, c] = State.OwnerOnly;
                }
            }

            int ans = xfx(0, 0);
            io.Print(ans);
        }

        static void Main(string[] args)
        {
            var p = new Program();
            p.Solve();
            p.io.Close();
        }
    }
