            for (int r = 0; r < R; r++)
            {
                for (int c = 0; c < C; c++)
                {
                    map[r, c] = State.OwnerOnly;
                }
            }

            int ans = xfx(0, 0);
            io.Print(ans);
        }

        static void Main(string[] args)
        {
            var p = new Program();
            p.Solve();
            p.io.Close();
        }
    }
}

