public class HelloWorld {
    public static void SolveCodeForces() {
        var n = cin.NextUlong();
        var b = cin.NextUlong();

        var ans = ulong.MaxValue;
        foreach (var ppow in GetPrimeDivisors(b)) {
            ans = Math.Min(ans, FF( n, ppow[0], ppow[1] ));
        }
        System.Console.WriteLine(ans);
    }

    static Scanner cin = new Scanner();
    static StringBuilder cout = new StringBuilder();

    static IEnumerable<ulong[]> GetPrimeDivisors(ulong n) {
        for (var p = 2ul; p * p <= n; p++)
            if (n % p == 0) {

                n /= p;
                var pow = 1ul;
                while (n % p == 0) { pow++; n /= p; }

                yield return new[] { p, pow };
            }
        if (n > 1)
            yield return new[] { n, 1ul };
    }

    static ulong F(ulong n, ulong p) {
        if (n == 1) return 0;

        var ans = 0ul;

        var i = 1ul;
        var pow = p;
        while (pow <= n) {
            ans += n / pow;
            i++;

            if (pow > n / p)
            // if (pow * p > n)
                break;

            pow *= p;
        }

        return ans;
    }

    static ulong FF(ulong n, ulong p, ulong pow) {
        return F(n, p) / pow;
    }

    static void TestSol() {
        for (var n = 1ul; n <= 10ul; n++) {
            var fact = 1ul;
            for (var i = 1ul; i <= n; i++)
                fact *= i;

            System.Console.WriteLine(new { n, fact });

            for (var b = 2ul; b <= 11ul; b++) {

                var actual = ulong.MaxValue;
                foreach (var ppow in GetPrimeDivisors(b)) {
                    actual = Math.Min(actual, FF( n, ppow[0], ppow[1] ));
                }

                var expected = 0ul;
                var rem = fact;
                while (rem % b == 0) {
                    expected++;
                    rem /= b;
                }

                if (expected != actual) {
                    System.Console.WriteLine("Err");
                    System.Console.WriteLine(new { n, b, fact, actual, expected });
                    return;
                }
            }
        }
    }

    static void TestF() {
        for (var n = 2ul; n <= 9ul; n++) {
            System.Console.WriteLine(n);

            var fact = 1ul;
            for (var i = 1ul; i <= n; i++)
                fact *= i;

            for (var prime = 2ul; prime <= fact; prime++) {
                if (!Brute_IsPrime(prime)) continue;

                for (var pow = 1ul; Math.Pow(prime, pow) <= fact; pow++) {

                    // System.Console.WriteLine(new { n, prime, pow });

                    var actual = FF(n, prime, pow);

                    var apow = (ulong)Math.Pow(prime, pow);
                    var expected = 0ul;
                    var rem = fact;
                    while (rem % apow == 0) {
                        expected++;
                        rem /= apow;
                    }

                    if (expected != actual) {
                        System.Console.WriteLine("Err");
                        System.Console.WriteLine(new { n, fact, prime, pow, actual, expected });
                        return;
                    }

                }
            }
        }
    }

    static bool Brute_IsPrime(ulong a) {
        if (a <= 1ul) return false;
        for (var i = 2ul; i * i <= a; i++)
            if (a % i == 0)
                return false;
        return true;
    }

    static public void Main () {
        SolveCodeForces();
        // TestSol();
        // System.Console.Write(cout.ToString());
    }
}

public static class Helpers {
