        for (int i = 2; i <= N; i++)
        {
            for (int j = 1; j < i && j <= X; j++)
            {
                ModInt tmp = ModInt.Pow(j, i) - ModInt.Pow(j - 1, i);
                dp[i, j] += tmp;
            }
        }

