namespace Program
{
    public class Solver
    {
        public void Solve()
        {
            var n = sc.Integer();
            var k = sc.Long();
            var m = sc.Long();
            var dp = new long[1001, 101, 2];
            for (int i = 0; i < 1001; i++)
                for (int j = 0; j < 101; j++)
                    for (int l = 0; l < 2; l++)
                        dp[i, j, l] = -1;
            var pow1 = new long[1001];
            var pow2 = new long[1001];
            for (long i = 0, u = 1, v = 1; i < 1001; i++)
            {
                pow1[i] = u;
                pow2[i] = v;
                u = u * 10 % m;
                v = v * 10 % k;
            }
            Func<int, int, int, long> dfs = null;
            dfs = (id, rem, f) =>
                {
                    if (rem == 0 && f == 1)
                        if (id != n) return (pow1[n - id - 1] * 9) % m;
                        else return 1;
                    if (id == n || (rem == 0 && f == 1)) return 0;
                    if (dp[id, rem, f] >= 0) return dp[id, rem, f];
                    long ret = 0;
                    for (int i = 0; i < 10; i++)
                        ret = (ret + dfs(id + 1,
                            (int)((rem + i * pow2[id]) % k),
                            ((f == 1 || i > 0) ? 1 : 0))) % m;
