namespace Moodular_Arithmetic
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);


        private static int[] pa;
        private static int[] size;

        private static int mod = 1000000007;

        private static long Pow(long a, int k)
        {
            long r = 1;
            while (k > 0)
            {
                if ((k & 1) == 1)
                {
                    r = (r*a)%mod;
                }
                a = (a*a)%mod;
                k >>= 1;
            }
            return r;
        }

        private static void Main(string[] args)
        {
            int p = Next();
            long k = Next();

            if (k == 0)
            {
                writer.WriteLine(Pow(p, p - 1));
                writer.Flush();
                return;
            }
            if (k == 1)
            {
                writer.WriteLine(Pow(p, p));
                writer.Flush();
                return;
            }

            pa = new int[p];
            size = new int[p];

            for (int i = 0; i < pa.Length; i++)
            {
                pa[i] = i;
                size[i] = 1;
            }

            for (int i = 1; i < p; i++)
            {
                int pi = GP(i);
                int kpi = GP((int) ((k*i)%p));

                if (pi != kpi)
                {
                    pa[pi] = kpi;
                    size[kpi] += size[pi];
                }
            }

            var d = new Dictionary<int, int>();
            for (int i = 1; i < p; i++)
            {
                if (pa[i] == i)
                {
                    if (d.ContainsKey(size[i]))
                        d[size[i]] = 1 + d[size[i]];
                    else
                    {
                        d[size[i]] = 1;
                    }
                }
            }

            long count = 1;

            foreach (var dd in d)
            {
                count = (count*Pow(dd.Key*dd.Value + 1, dd.Value))%mod;
            }


            writer.WriteLine(count);
            writer.Flush();
        }

        private static int GP(int i)
        {
            if (pa[i] == i)
                return i;
            return pa[i] = GP(pa[i]);
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

