namespace CF
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            using (var sr = new InputReader(Console.In))
//			using (var sr = new InputReader(new StreamReader("input.txt")))
            using (var sw = Console.Out)
                //using (var sw = new StreamWriter("output.txt"))
            using (var task = new Task(sr, sw)) {
                task.Solve();
//                Console.ReadKey();
            }
        }
    }

    internal class Task : IDisposable
    {
        private readonly InputReader sr;
        private readonly TextWriter sw;
        private bool isDispose;
        private long[] array;
        private Tuple<long, long, double>[] costs;
        private long best = Int64.MaxValue;
        private Dictionary<long, long> cache = new Dictionary<long, long>();

        public Task(InputReader sr, TextWriter sw)
        {
            this.sr = sr;
            this.sw = sw;
        }

        public void Solve()
        {
            var n = sr.NextInt32();
            var l = sr.NextInt64();
            array = sr.ReadArrayOfInt64();
            costs = new Tuple<long, long, double>[n];
            for (var i = 0; i < n; i++) {
                var pow = (long) Math.Pow(2, i);
                costs[i] = Tuple.Create(array[i], pow, (double)array[i]/pow);
            }
            sw.WriteLine(Min(l, n, 0L));
        }

        private long Min(long l, int indx, long val)
        {
            if (cache.ContainsKey(val))
                return cache[val];

            if (val >= best)
                return best;

            if (l <= 0) {
                best = Math.Min(val, best);
                return val;
            }

            var result = Int64.MaxValue;
            for (var i = indx - 1; i >= 0; i--) {
                var d = l / costs[i].Item2;
                if (d == 0)
                    d++;

                var curr = val + d * costs[i].Item1;
                var res = Min(l - d * costs[i].Item2, i, curr);

                result = Math.Min(res, result);
                if (l > d * costs[i].Item2) {
                    result = Math.Min(result, curr + costs[i].Item1);
                    best = Math.Min(best, result);
                }
            }
            cache.Add(val, result);

            return result;
        }

        ~Task()
        {
            Dispose(false);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        private void Dispose(bool disposing)
        {
            if (!isDispose) {
                if (disposing) {
                    if(sr != null)
                        sr.Dispose();

                    if(sw != null)
                        sw.Dispose();
                }

                isDispose = true;
            }
        }
    }
}

