class Program
{
    static void Main(string[] args)
    {
        int[] input = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int n = input[0];
        long L = input[1];
        int[] c = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

        for (var i = 1; i < n; ++i)
            // Replace a bottle with multiple smaller bottles.
            c[i] = Math.Min(c[i], 2 * c[i - 1]);
        for (var i = n - 2; i >= 0; --i)
            // Replace a bottle with a bigger one.
            c[i] = Math.Min(c[i], c[i + 1]);

        var minPrice = long.MaxValue;
        var price = 0L;
        for (var i = n - 1; i >= 0; --i)
        {
            int vi = 1 << i;
            price += (L / vi) * c[i];
            L %= vi;
            if (L == 0)
            {
                minPrice = Math.Min(price, minPrice);
                break;
            }
            // One option is to add another bottle for the rest.
            minPrice = Math.Min(price + c[i], minPrice);
            // Another is to keep filling smaller bottles.
        }
        Console.WriteLine(minPrice);
    }
}

