        public string NextToken()
        {
            if (pos == tokens.Length)
            {
                tokens = reader.ReadLine().Split(' ');
                pos = 0;
            }
            return tokens [pos++];
        }

        public int NextInt()
        {
            return int.Parse(NextToken());
        }
    }

    class MainClass
    {
        static Tokenizer t;
        static TextWriter w;

        public static void Init()
        {
            t = new Tokenizer(Console.In);
            w = Console.Out;
            //t = new Tokenizer(File.OpenText(@"../../in.txt"));
            //w = File.CreateText(@"../../out.txt");
        }

        public static void Main(string[] args)
        {
            Init();
            int n = t.NextInt();

            int[] machine = new int[n + 1];
            int[] inDegree = new int[n + 1];

            for (int i = 1; i <= n; i++)
                machine [i] = t.NextInt();

            var a = new List<int>[n + 1];
            for (int i = 1; i <= n; i++)
                a [i] = new List<int>();

            for (int i = 1; i <= n; i++)
            {
                int k = t.NextInt();
                inDegree [i] = k;
                while (k-- > 0)
                {
                    a [t.NextInt()].Add(i);
                }
            }

            int cost = int.MaxValue;
            for (int start = 1; start <= 3; start++)
            {
                int curCost = n;
                int[] curInDegree = (int[])inDegree.Clone();
                var q = new Queue<int>[4];
                for (int i = 1; i <= 3; i++)
                    q [i] = new Queue<int>();
                int rem = n;
                for (int i = 1; i <= n; i++)
                    if (inDegree [i] == 0)
                        q [machine [i]].Enqueue(i);
                int curMachine = start;
                while (true)
                {
                    while (q[curMachine].Count != 0)
                    {
                        int curJob = q [curMachine].Dequeue();
                        foreach (var job in a[curJob])
                        {
                            curInDegree [job]--;
                            if (curInDegree [job] == 0)
                                q [machine [job]].Enqueue(job);
                        }
                        rem--;
                    }
                    if (rem == 0)
                        break;

                    curCost++;
                    curMachine++;
                    if (curMachine == 4)
                        curMachine = 1;
                }
                cost = Math.Min(cost, curCost);

            }

            w.WriteLine(cost);
        }
    }
}

