namespace CodeForces
{
    class Tokenizer
    {
        int pos;
        string[] tokens;
        TextReader reader;

        public Tokenizer(TextReader reader)
        {
            pos = 0;
            tokens = new string[] { };
            this.reader = reader;
        }


        public string NextToken()
        {
            if (pos == tokens.Length)
            {
                tokens = reader.ReadLine().Split(' ');
                pos = 0;
            }
            return tokens [pos++];
        }

        public int NextInt()
        {
            return int.Parse(NextToken());
        }
    }

    class MainClass
    {
        static Tokenizer t;
        static TextWriter w;

        public static void Init()
        {
            t = new Tokenizer(Console.In);
            w = Console.Out;
            //t = new Tokenizer(File.OpenText(@"../../in.txt"));
            //w = File.CreateText(@"../../out.txt");
        }

        public static void Main(string[] args)
        {
            Init();
            int n = t.NextInt();
            List<int>[] c = new List<int>[4];
            for (int i = 0; i < 4; i++)
                c [i] = new List<int>();
            for (int i = 1; i <= n; i++)
                c [t.NextInt()].Add(i);

            List<int>[] dep = new List<int>[n + 1];
            for (int i = 1; i <= n; i++)
                dep [i] = new List<int>();
            int[] waitCount = new int[n + 1];
            for (int i = 1; i <= n; i++)
            {
                int k = t.NextInt();
                waitCount [i] = k;
                for (int j = 0; j < k; j++)
                    dep [t.NextInt()].Add(i);
            }

            int cost = int.MaxValue;
            for (int start = 1; start <= 3; start++)
            {
                bool[] done = new bool[n + 1];
                int[] curWaitCount = (int[])waitCount.Clone();

                int cur = start;
                int rem = n;
                int curCost = 0;
                while (rem > 0)
                {
                    for (int j = 0; j < c[cur].Count; j++)
                    {
                        foreach (var a in c[cur])
                        {
                            if (done [a])
                                continue;
                            if (curWaitCount [a] == 0)
                            {
                                foreach (var b in dep[a])
                                    curWaitCount [b]--;
                                done [a] = true;
                                rem--;
                            }
                        }
                    }
                    cur++;
                    if (cur == 4)
                        cur = 1;
                    if (rem > 0)
                        curCost++;
                }

                cost = Math.Min(cost, curCost);
            }

            cost += n;
            w.WriteLine(cost);
            w.Close();
        }
    }
}

