namespace Task2_2
{
    class Program
    {
        static void Main(string[] args)
        {
            string line = Console.ReadLine();
            string[] arg1 = line.Split();

            int n = int.Parse(arg1[0]);
            int m = int.Parse(arg1[1]);

            line = Console.ReadLine();
            int x = int.Parse(line);

            int[] counts = new int[Math.Max(n,m)];
            int i = 0;
            while (n > 0 && m > 0)
            {
                counts[i] = Count(n, m);
                n -= 2;
                m -= 2;
                i++;
            }


            for (int j = 0; j < i-1; j++)
            {
                counts[j] -= counts[j + 1];
            }

            if (x > i)
                Console.WriteLine(0);
            else
                Console.WriteLine(counts[x-1]);
        }

        private static int Count(int n, int m)
        {
            int sum = 0;

            if (m % 2 == 0)
            {
                for (int i = 0; i < n; i++)
                    sum += m / 2;
            }
            else
            {
                for (int i = 0; i < n; i++)
                    sum += (m + Minus1(i) )/2;
            }

            return sum;
        }

        private static int Minus1(int n)
        {
            return (n%2 == 0 ? 1 : -1);
        }
    }
}

