			int [] input = Console.ReadLine().Split().Select(x => Convert.ToInt32(x)).ToArray();

			long [] a = new long[N];

			int A = input[0];
			int B = input[1];
			int C = input[2];
			int D = input[3];

			for (int i = A; i <= B; ++i)
			{
				++a[i + B];
				--a[i + C + 1];
			}

			for (int i = 1; i < N; ++i)
			{
				a[i] += a[i - 1];
			}

			for (int i = 1; i < N; ++i)
			{
				a[i] += a[i - 1];
			}

			long result = 0;
			for (int i = C; i <= D; ++i)
			{
				result += a[N - 1] - a[i];
			}

			Console.WriteLine(result);

			return 0;
		}
	}
