            ulong p = 998244353;
            var primes = new HashSet<int>();
            var s = 2;
            primes.Add(2);
            for (var i = 2; i < 1000; i++)
            {
                if (s * s < i)
                    s++;
                if (!Enumerable.Range(2, Math.Max(s - 1, 0)).Any(x => i % x == 0))
                {
                    primes.Add(i);
                }
            }
            for (var iter = 0; iter < 1; iter++)
            {
                var strrep = Console.ReadLine().Split(' ').Select(x => ulong.Parse(x)).ToList();
                var n = strrep[0];
