                long all = 0;
                ulong curgcd = 1;
                ulong prev = m % p;
                ulong prevbad = m % p;
                var f = true;
                for (ulong i = 2; i <= n; i++)
                {
                    prev *= (m % p);
                    prev %= p;
                    if (!f)
                    {
                        all += (long)prev;
                        all %= (long)p;
                        continue;
                    }
                    if(primes.Contains((int)i))
                        curgcd = curgcd * i;
                    if (m < curgcd)
                        f = false;
                    prevbad *= ((m / curgcd) % p);
                    prevbad %= p;
