        }
        
        public static bool Solve(int n, int m, int k)
        {
            if (n % 2 == 0 && m % 2 == 0)
            {
                return k % 2 == 0;
            }

            if (n % 2 == 0)
            {
                var maxHorizontal = n * (m / 2);
                return k <= maxHorizontal && k % 2 == 0;
            }

            var horizontalSize = m / 2;
            return k >= horizontalSize && Solve(n - 1, m, k - horizontalSize);
        }
    }
