        //dist:=iにいて，jまでクリアしていて，駒が0:knight,1:bishop,2:rookのとき
        var dist = Create(N * N, () => Create(N * N, () => Create(3, () => long.MaxValue / 2)));
        var pq = new PriorityQueue<(long c, int now, int cl, int pi)>((a, b) => a.c.CompareTo(b.c));
        dist[R[0]][0][0] = dist[R[0]][0][1] = dist[R[0]][0][2] = 0;
        pq.Push((0, R[0], 0, 0));
        pq.Push((0, R[0], 0, 1));
        pq.Push((0, R[0], 0, 2));
        while (pq.Any())
        {
            var (cst, now, cl, pi) = pq.Pop();
            int h = now / N, w = now % N;
            if (pi == 0)
            {
                for(int k = 0; k < knH.Length; k++)
                {
                    int nh = h + knH[k], nw = w + knW[k];
                    if (!Inside(nh, nw, N, N)) continue;
                    var p = cl;
                    if (Id(nh, nw) == R[cl + 1]) p++;
                    if (chmin(ref dist[Id(nh, nw)][p][pi], cst + W))
                    {
                        pq.Push((cst + W, Id(nh, nw), p, pi));
                    }
                }
            }
            else if (pi == 1)
            {
                for(int i = -N + 1; i <= N - 1; i++)
                {
                    {
                        int nh = i + h, nw = i + w;
                        if (!Inside(nh, nw, N, N)) goto SEC;
                        var p = cl;
                        if (Id(nh, nw) == R[cl + 1]) p++;
                        if (chmin(ref dist[Id(nh, nw)][p][pi], cst + W))
                        {
                            pq.Push((cst + W, Id(nh, nw), p, pi));
                        }
                    }
                SEC:;
                    {
                        int nh = i + h, nw = -i + w;
                        if (!Inside(nh, nw, N, N)) continue;
                        var p = cl;
                        if (Id(nh, nw) == R[cl + 1]) p++;
                        if (chmin(ref dist[Id(nh, nw)][p][pi], cst + W))
                        {
                            pq.Push((cst + W, Id(nh, nw), p, pi));
                        }
                    }
                }
            }
            else
            {
                for(int i = -N + 1; i <= N - 1; i++)
                {

                    {
                        int nh = h, nw = i + w;
                        if (!Inside(nh, nw, N, N)) goto SEC;
                        var p = cl;
                        if (Id(nh, nw) == R[cl + 1]) p++;
                        if (chmin(ref dist[Id(nh, nw)][p][pi], cst + W))
                        {
                            pq.Push((cst + W, Id(nh, nw), p, pi));
                        }
                    }
                SEC:;
                    {
                        int nh = i + h, nw = w;
                        if (!Inside(nh, nw, N, N)) continue;
                        var p = cl;
                        if (Id(nh, nw) == R[cl + 1]) p++;
                        if (chmin(ref dist[Id(nh, nw)][p][pi], cst + W))
                        {
                            pq.Push((cst + W, Id(nh, nw), p, pi));
                        }
                    }
                }
            }
            for(int k = 0; k < 3; k++)
            {
                if(chmin(ref dist[now][cl][k],cst+1+W))
                {
                    pq.Push((cst + 1+W, now, cl, k));
                }
            }
        }
        var res = dist[R[N * N - 1]][N * N - 1].Min();
        Console.WriteLine($"{res / W} {res % W}");
    }
    int N;
    const long W = (long)1e9;
    public int Id(int h, int w) => h * N + w;
    int[] knH = new[] { -2, -2, -1, -1, 1, 1, 2, 2 }, knW = new[] { 1, -1, 2, -2, 2, -2, 1, -1 };
    public static bool Inside(int h, int w, int H, int W)
        => 0 <= h && h < H && 0 <= w && w < W;
}

public class PriorityQueue<T>
{
    private List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
}
