using System;
using System.Collections.Generic;
using System.Linq;

public class HelloWorld {
    static public void Main () {
        SolveCodeForces();
    }

    private enum Fig { K, L, S };

    private static int N;
    private static int[][] arr;

    public static void SolveCodeForces() {
        N = int.Parse(Console.ReadLine());
        arr = new int[N][];
        for (var i = 0; i < arr.Length; i++)
            arr[i] = Console.ReadLine().Split().Select(int.Parse).ToArray();

        var numPos = new int[N*N+1][];
        for (var r = 0; r < arr.Length; r++)
            for (var c = 0; c < arr[r].Length; c++)
                numPos[ arr[r][c] ] = new[] {r, c};

        var bestAnswers = new Dictionary<Fig, int[]>{
            { Fig.K, new[] {0, 0} },
            { Fig.L, new[] {0, 0} },
            { Fig.S, new[] {0, 0} },
        };
        for (var d = 2; d <= N * N; d++) {
            var rcFrom = numPos[d - 1];
            var hopAns = new Dictionary<Fig, int[]>{
                { Fig.K, new[] {int.MaxValue, int.MaxValue} },
                { Fig.L, new[] {int.MaxValue, int.MaxValue} },
                { Fig.S, new[] {int.MaxValue, int.MaxValue} },
            };
            foreach (var fig in AllFigs) {
                if (bestAnswers[fig][0] < int.MaxValue)
                    foreach (var state in SolveHop(fig, rcFrom[0], rcFrom[1], d)) {
                        // System.Console.WriteLine("Digits: {0}->{1}, start fig {5}, end fig {2}, moves {3}, switches {4}", d-1, d, state.Fig, state.Moves, state.Switches, fig);
                        var newMoves = bestAnswers[fig][0] + state.Moves;
                        var newSwitches = bestAnswers[fig][1] + state.Switches;

                        var prevAns = hopAns[state.Fig];
                        if (prevAns[0] == int.MaxValue) {
                            prevAns[0] = newMoves;
                            prevAns[1] = newSwitches;
                        }
                        else if (newMoves < prevAns[0] || (newMoves == prevAns[0] && newSwitches < prevAns[1])) {
                            prevAns[0] = newMoves;
                            prevAns[1] = newSwitches;
                        }
                    }
            }
            bestAnswers = hopAns;
        }

        var bestAns = bestAnswers.OrderBy(kvp => kvp.Value[0]).ThenBy(kvp => kvp.Value[1]).First().Value;
        System.Console.WriteLine("{0} {1}", bestAns[0], bestAns[1]);
    }

    private struct State { public int R; public int C; public Fig Fig; public int Moves; public int Switches; }

    private static bool AreIndicesAllowed(int r, int c) {
        return r >= 0 && r < N && c >= 0 && c < N;
    }

    private static readonly int[][] K_Moves = new[] {
        new[] { -2, -1 },
        new[] { -2, 1 },
        new[] { -1, -2 },
        new[] { -1, 2 },
        new[] { 1, -2 },
        new[] { 1, 2 },
        new[] { 2, -1 },
        new[] { 2, 1 },
    };

    private static readonly int[][] S_Moves = new[] {
        new[] { -1, -1 },
        new[] { -1, 1 },
        new[] { 1, -1 },
        new[] { 1, 1 },
    };

    private static Fig[] AllFigs = new[] { Fig.L, Fig.S, Fig.K };

    private static IEnumerable<State> ExpandState(State state) {
        if (state.Fig == Fig.K) {
            foreach (var drdc in K_Moves) {
                var r = drdc[0] + state.R;
                var c = drdc[1] + state.C;
                if (AreIndicesAllowed(r, c))
                    yield return new State { Fig = Fig.K, R = r, C = c, Moves = state.Moves + 1, Switches = state.Switches };
            }
        }
        else if (state.Fig == Fig.L) {
            for (var r = 0; r < N; r++)
                if (r != state.R)
                    yield return new State { Fig = Fig.L, R = r, C = state.C, Moves = state.Moves + 1, Switches = state.Switches };
            for (var c = 0; c < N; c++)
                if (c != state.C)
                    yield return new State { Fig = Fig.L, R = state.R, C = c, Moves = state.Moves + 1, Switches = state.Switches };
        }
        else if (state.Fig == Fig.S) {
            for (var d = 1; d < N; d++)
                foreach (var drdc in S_Moves) {
                    var r = d * drdc[0] + state.R;
                    var c = d * drdc[1] + state.C;
                    if (AreIndicesAllowed(r, c))
                        yield return new State { Fig = Fig.S, R = r, C = c, Moves = state.Moves + 1, Switches = state.Switches };
                }
        }
        foreach (var fig in AllFigs)
            if (fig != state.Fig)
                yield return new State { Fig = fig, R = state.R, C = state.C, Moves = state.Moves + 1, Switches = state.Switches + 1 };
    }

    // Returns: end fig => [ number of moves, number of fig switches ]
    private static IEnumerable<State> SolveHop(Fig startFig, int rFrom, int cFrom, int targetDigit) {
        var Q = new Queue<State>();
        Q.Enqueue(new State { Fig = startFig, R = rFrom, C = cFrom });
        while (Q.Count > 0) {
            var state = Q.Dequeue();
            if (arr[state.R][state.C] == targetDigit)
                yield return state;
            // There is an always solution with 3 moves: switch to L, hop horizontally, hop vertically
            else if (state.Moves < 3)
                foreach (var neigh in ExpandState(state)) {
                    Q.Enqueue(neigh);
                }
        }
    }
}

