namespace ConsoleTidbits
{
    class JustCodeForces
    {
        int N;
        int[,] board;
        Dictionary<int, Tuple<int, int>> locations;

        public static void Main()
        {
            JustCodeForces obj = new JustCodeForces();

            //while (true)
                obj.ThreePieces_ContestAnalysis();
        }

        int M;
        Tuple<int, int>[][] dist;
        Tuple<int, int>[] pos;

        int[] X = new int[] { 2, 2, -2, -2, 1, 1, -1, -1 };
        int[] Y = new int[] { -1, 1, -1, 1, 2, -2, 2, -2 };
        private bool In(int x, int y)
        {
            if (x >= 0 && y >= 0 && x < N && y < N) return true;
            return false;
        }

        private int Get(int x, int y, int p)
        {
            return x * 3 * N + y * 3 + p;
        }
        private void ThreePieces_ContestAnalysis()
        {
            N = int.Parse(Console.ReadLine());

            pos = new Tuple<int, int>[N * N];
            M = (N - 1) * N * 3 + N * 3 + 3;
            dist = new Tuple<int, int>[M][];
            for (int i = 0; i < M; i++)
                dist[i] = new Tuple<int, int>[M];

            for (int i = 0; i < N; i++)
            {
                var array = Array.ConvertAll(Console.ReadLine().Split(new char[] { ' ' }), int.Parse);

                for (int j = 0; j < N; j++)
                {
                    pos[--array[j]] = Tuple.Create(i, j);
                }
            }

            for (int i = 0; i < M; i++)
            {
                for (int j = 0; j < M; j++)
                {
                    dist[i][j] = Tuple.Create(100000, 100000);
                    if (i == j) dist[i][j] = Tuple.Create(0, 0);
                }
            }


            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < N; j++)
                {
                    //Get Knights distance
                    for (int k = 0; k < 8; k++)
                    {
                        int nx = i + X[k];
                        int ny = j + Y[k];

                        if (In(nx, ny))
                            dist[Get(i, j, 0)][Get(nx, ny, 0)] = Tuple.Create(1, 0);

                    }

                    //Get Bishops distances
                    for (int k = -N + 1; k <= N - 1; k++)
                    {
                        int nx = i + k;
                        int ny = j + k;

                        if (In(nx, ny))
                        {
                            dist[Get(i, j, 1)][Get(nx, ny, 1)] = Tuple.Create(1, 0);
                        }

                        ny = j - k;
                        if (In(nx, ny))
                            dist[Get(i, j, 1)][Get(nx, ny, 1)] = Tuple.Create(1, 0);
                    }

                    //Get Rook distance
                    for (int k = 0; k < N; k++)
                    {
                        int nx = i;
                        int ny = k;
                        dist[Get(i, j, 2)][Get(nx, ny, 2)] = Tuple.Create(1, 0);

                        nx = k;
                        ny = j;

                        dist[Get(i, j, 2)][Get(nx, ny, 2)] = Tuple.Create(1, 0);
                    }

                    //Replace at the exact location
                    for (int k = 0; k < 3; k++)
                    {
                        for (int m = 0; m < 3; m++)
                        {
                            if (k != m)
                                dist[Get(i, j, k)][Get(i, j, m)] = Tuple.Create(1, 1);
                        }
                    }
                }
            }

            for (int k = 0; k < M; k++)
            {
                for (int i = 0; i < M; i++)
                {
                    for (int j = 0; j < M; j++)
                    {
                        if (dist[i][j].Item1 > dist[i][k].Item1 + dist[k][j].Item1)
                        {
                            dist[i][j] = Tuple.Create(dist[i][k].Item1 + dist[k][j].Item1,
                                dist[i][k].Item2 + dist[k][j].Item2);
                        }
                        else if (dist[i][j].Item1 == dist[i][k].Item1 + dist[k][j].Item1
                            && dist[i][j].Item2 > dist[i][k].Item2 + dist[k][j].Item2)
                        {
                            dist[i][j] = Tuple.Create(dist[i][j].Item1, dist[i][k].Item2 + dist[k][j].Item2);
                        }
                    }
                }
            }

            var dp = new Tuple<int, int>[N * N][];
            for (int i = 0; i < N * N; i++)
            {
                dp[i] = new Tuple<int, int>[3];

                for (int k = 0; k < 3; k++)
                {
                    dp[i][k] = Tuple.Create(100000, 100000);
                }
            }
            dp[0][0] = Tuple.Create(0, 0);
            dp[0][1] = Tuple.Create(0, 0);
            dp[0][2] = Tuple.Create(0, 0);

            for (int i = 0; i < N * N - 1; i++)
            {
                for (int j = 0; j < 3; j++)
                {
                    for (int k = 0; k < 3; k++)
                    {
                        var new_min = dp[i][j].Item1 + dist[Get(pos[i].Item1, pos[i].Item2, j)][Get(pos[i + 1].Item1, pos[i + 1].Item2, k)].Item1;
                        if (dp[i + 1][k].Item1 > new_min)
                        {
                            dp[i + 1][k] = Tuple.Create(new_min, dp[i][j].Item2 + dist[Get(pos[i].Item1, pos[i].Item2, j)][Get(pos[i + 1].Item1, pos[i + 1].Item2, k)].Item2);
                        }
                        else if (dp[i + 1][k].Item1 == new_min
                            && dp[i + 1][k].Item2 > dp[i][j].Item2 + dist[Get(pos[i].Item1, pos[i].Item2, j)][Get(pos[i + 1].Item1, pos[i + 1].Item2, k)].Item2)
                        {
                            dp[i + 1][k] = Tuple.Create(new_min, dp[i][j].Item2 + dist[Get(pos[i].Item1, pos[i].Item2, j)][Get(pos[i + 1].Item1, pos[i + 1].Item2, k)].Item2);
                        }
                    }
                }
            }

            var res = dp[N * N - 1][0];
            if (res.Item1 > dp[N * N - 1][1].Item1
                || (res.Item1 == dp[N * N - 1][1].Item1 && res.Item2 > dp[N * N - 1][1].Item2))
            {
                res = dp[N * N - 1][1];
            }
            if (res.Item1 > dp[N * N - 1][2].Item1
                || (res.Item1 == dp[N * N - 1][2].Item1 && res.Item2 > dp[N * N - 1][2].Item2))
            {
                res = dp[N * N - 1][2];
            }

            Console.WriteLine("" + res.Item1 + " " + res.Item2);
        }
    }
}

