#if _ONLINE_JUDGE_
	[OnlineJudge.Task("Codeforces 200C")]
#endif
	class Task200C
	{
		private InputTokenizer input = new InputTokenizer();
		private TextWriter output = Console.Out;

		struct Annoyed
		{
			public string name;
			public Team info;
		}

		struct Team
		{
			public int goals, missed_goals, plays, points;
		}

		struct Comp : IComparer<Annoyed>
		{
			public int Compare(Annoyed x, Annoyed y)
			{
				{
					int a = x.info.points, b = y.info.points;
					if (a != b) return b - a;
				}

				{
					int a = x.info.goals - x.info.missed_goals, b = y.info.goals - y.info.missed_goals;
					if (a != b) return b - a;
				}

				{
					int a = x.info.goals, b = y.info.goals;
					if (a != b) return b - a;
				}

				return x.name.CompareTo(y.name);
			}
		}

		private void Solve()
		{
			var teams = new Dictionary<String, Team>();

			string a, b, g;
			for (int i = 0; i < 5; ++i) {
				input.Line().Read(out a).Read(out b).Read(out g);
				int g1 = g[0] - '0', g2 = g[2] - '0';

				Team A = new Team(), B = new Team();
				if (teams.ContainsKey(a)) A = teams[a];
				if (teams.ContainsKey(b)) B = teams[b];

				if (g1 > g2) {
					A.points += 3;
				} else if (g1 < g2) {
					B.points += 3;
				} else {
					++A.points;
					++B.points;
				}

				A.goals += g1;
				A.missed_goals += g2;
				++A.plays;
				teams[a] = A;

				B.goals += g2;
				B.missed_goals += g1;
				++B.plays;
				teams[b] = B;
			}

			var comp = new Comp();

			var nt = (from x in teams
								select new Annoyed {
									name = x.Key,
									info = x.Value
								}).ToArray();

			int asd = -1, asr = -1;
			for (int i = 0; i < 4; ++i) {
				if (nt[i].name == "BERLAND")
					asd = i;
				else if (nt[i].info.plays == 2)
					asr = i;
			}

			int X = 10000, Y = 10000, dXY = 10000000;
			for (int _X = 0; _X < 100; ++_X)
				for (int _Y = 0; _Y < 100; ++_Y) {
					nt[asd].info.points += 3;
					nt[asd].info.goals += _X;
					nt[asd].info.missed_goals += _Y;

					nt[asr].info.goals += _Y;
					nt[asr].info.missed_goals += _X;

					var st = nt.OrderBy(t => t, comp).ToArray();
					if (_X > _Y && (st[0].name == "BERLAND" || st[1].name == "BERLAND") && (_X - _Y < dXY || (_X - _Y == dXY && _Y < Y))) {
						X = _X;
						Y = _Y;
						dXY = X - Y;
					}

					nt[asd].info.points -= 3;
					nt[asd].info.goals -= _X;
					nt[asd].info.missed_goals -= _Y;

					nt[asr].info.goals -= _Y;
					nt[asr].info.missed_goals -= _X;
				}

			if (X == 10000)
				output.WriteLine("IMPOSSIBLE");
			else
				output.WriteLine("{0}:{1}", X, Y);
		}

		#region
		public static void Main()
		{
			var obj = new Task200C();
			obj.Solve();
		}

		private class InputTokenizer
		{
			private List<string> _tokens = new List<string>();
			private int _offset = 0;

			public InputTokenizer()
			{
			}

			public InputTokenizer String(String s)
			{
				_tokens.AddRange(s.Split(new char[] { ' ', '\n', '\t', '\r' }, StringSplitOptions.RemoveEmptyEntries));
				return this;
			}

			public InputTokenizer Line()
			{
				return String(Console.In.ReadLine());
			}

			public InputTokenizer Read(out int v)
			{
				v = int.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out int[] v)
			{
				v = new int[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out long v)
			{
				v = long.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out long[] v)
			{
				v = new long[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out ulong v)
			{
				v = ulong.Parse(_tokens[_offset++]);
				return this;
			}

			public InputTokenizer Read(int n, out ulong[] v)
			{
				v = new ulong[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out double v)
			{
				v = double.Parse(_tokens[_offset++].Replace('.', ','));
				return this;
			}

			public InputTokenizer Read(int n, out double[] v)
			{
				v = new double[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}

			public InputTokenizer Read(out string v)
			{
				v = _tokens[_offset++];
				return this;
			}

			public InputTokenizer Read(int n, out string[] v)
			{
				v = new string[n];
				for (int i = 0; i < n; ++i) Read(out v[i]);
				return this;
			}
		}
		#endregion
	}
