        public int CompareTo(Team y)
        {
            if (this.point > y.point)
            {
                return 1;
            }
            else
            {
                if (this.point == y.point)
                {
                    if (this.goal - this.miss > y.goal - y.miss)
                    {
                        return 1;
                    }
                    else
                    {
                        if (this.goal - this.miss == y.goal - y.miss)
                        {
                            if (this.goal > y.goal)
                            {
                                return 1;
                            }
                            else
                            {
                                if (this.goal == y.goal)
                                {
                                    if (this.name.CompareTo(y.name) < 0)
                                        return 1;
                                    else
                                        return -1;
                                }
                                else
                                {
                                    return -1;
                                }
                            }

                        }
                        else
                        {
                            return -1;
                        }
                    }
                }
                else
                {
                    return -1;
                }
            }
        }
