            int[] pos = new int[10];
            for (int i = 0; i < 10; i++)
                pos[i] = -1;
            for (int i = 0; i < 4; i++)
                pos[xs[i]] = i;
            for (int m = data[0], i = 3; i >= 0; i--, m /= 10)
