namespace Equalizing_by_Division
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            writer.WriteLine(Solve(args));
            writer.Flush();
        }

        private static int Solve(string[] args)
        {
            int n = Next();
            int k = Next();

            var nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next();
            }
            Array.Sort(nn);

            var head = new Leaf();

            foreach (int i in nn)
            {
                var st = new Stack<int>();
                int ii = i;
                while (ii > 0)
                {
                    st.Push(ii & 1);
                    ii >>= 1;
                }

                Leaf c = head;
                c.count++;
                while (st.Count > 0)
                {
                    if (c.count <= k)
                    {
                        c.cost += st.Count;
                    }
                    int p = st.Pop();
                    if (p == 0)
                    {
                        if (c.l == null)
                            c.l = new Leaf();
                        c = c.l;
                    }
                    else
                    {
                        if (c.r == null)
                            c.r = new Leaf();
                        c = c.r;
                    }
                    c.count++;
                }
            }
            int min = head.cost;
            var q = new Queue<Leaf>();
            q.Enqueue(head);
            while (q.Count > 0)
            {
                Leaf t = q.Dequeue();
                if (t.l != null && t.l.count >= k)
                {
                    min = Math.Min(min, t.l.cost);
                    q.Enqueue(t.l);
                }
                if (t.r != null && t.r.count >= k)
                {
                    min = Math.Min(min, t.r.cost);
                    q.Enqueue(t.r);
                }
            }
            return min;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }

        #region Nested type: Leaf

        private class Leaf
        {
            public int cost;
            public int count;
            public Leaf l, r;
        }

        #endregion
    }
}

