    public static class Solver
    {
        private static void SolveCase()
        {
            const long MOD = 998244353;

            int n = ReadInt();
            int k = ReadInt();
            long l = ReadInt();

            int N = 2 * n + 2;
            long[][,] a = new long[2][,];
            a[0] = new long[N, 2];
            a[0][0, 0] = 1;

            for (int i = 0; i < 2 * n + 1; i++)
            {
                int t = i % 2;
                a[1 - t] = new long[N, 2];
                for (int j = 0; j <= i; j++)
                {
                    for (int e = 0; e < 2; e++)
                    {
                        if (e == 0 && j >= k)
                        {
                            a[1 - t][j, 1] += a[t][j, e];
                            Fix(ref a[1 - t][j, 1], MOD);
                        }
                        if (j > 0)
                        {
                            a[1 - t][j - 1, e] = (a[1 - t][j - 1, e] + j * a[t][j, e]) % MOD;
                        }
                        if (i + j - e <= 2 * n - 2)
                        {
                            a[1 - t][j + 1, e] += a[t][j, e];
                            Fix(ref a[1 - t][j + 1, e], MOD);
                        }
                    }
                }
            }

            long ans = a[1][0, 1];
            ans = ans * BinPower(2, n, MOD) % MOD;
            ans = ans * l % MOD;

            long f = 1;
            for (int i = 1; i <= n; i++)
            {
                f = f * i % MOD;
            }
            ans = ans * f % MOD;
            for (int i = n + 1; i <= 2 * n + 1; i++)
            {
                f = f * i % MOD;
            }
            ans = ans * Inv(f, MOD) % MOD;

            Writer.WriteLine(ans);
        }

        public static void Fix(ref long x, long mod)
        {
            if (x >= mod)
            {
                x -= mod;
            }
        }

        public static long Inv(long a, long mod)
        {
            return BinPower(a, mod - 2, mod);
        }

        public static long BinPower(long a, long n, long mod)
        {
            long result = 1;

            while (n > 0)
            {
                if ((n & 1) != 0)
                {
                    result = (result * a) % mod;
                }

                a = (a * a) % mod;
                n >>= 1;
            }

            return result;
        }

