class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, t;
        sc.Multi(out n, out t);
        var s = new int[n];
        var g = new int[n];
        for (int i = 0; i < n; i++)
        {
            sc.Multi(out s[i], out g[i]);
            --g[i];
        }
        memo = new long[n + 1][][][];
        for (int i = 0; i < n + 1; i++)
        {
            memo[i] = new long[n + 1][][];
            for (int j = 0; j < n + 1; j++)
            {
                memo[i][j] = new long[n + 1][];
                for (int k = 0; k < n + 1; k++)
                {
                    memo[i][j][k] = new long[4];
                    for (int l = 0; l < 4; l++)
                    {
                        memo[i][j][k][l] = -1;
                    }
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < (1 << n); i++)
        {
            int sum = 0;
            var cnt = new int[3];
            for (int j = 0; j < n; j++)
            {
                if (((i >> j) & 1) == 1) {
                    sum += s[j];
                    ++cnt[g[j]];
                }
            }
            if (sum != t) continue;
            ans += dfs(cnt[0], cnt[1], cnt[2], 3);
        }
        Prt(ans % M);
    }
    long[][][][] memo;
    long dfs(int a, int b, int c, int prev) {
        if (a < 0 || b < 0 || c < 0) return 0;
        if (a == 0 && b == 0 && c == 0) return 1;
        if (memo[a][b][c][prev] != -1) return memo[a][b][c][prev];
        long sum = 0;
        if (prev != 0) sum += dfs(a - 1, b, c, 0) * a;
        if (prev != 1) sum += dfs(a, b - 1, c, 1) * b;
        if (prev != 2) sum += dfs(a, b, c - 1, 2) * c;
        return memo[a][b][c][prev] = sum % M;
    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
    public pair() : this(default(T), default(U)) {}
    public pair(T v1, U v2) { this.v1 = v1; this.v2 = v2; }
