namespace Little_Elephant_and_Interval
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            string[] ss = reader.ReadLine().Split(' ');

            string sl = ss[0];
            string sr = ss[1];

            long count = 0;
            long d = 1;
            for (int i = 0; i < sl.Length - 1; i++)
            {
                d *= 10;
            }
            for (int i = sl.Length + 1; i < sr.Length; i++)
            {
                count += 9*d;
                d *= 10;
            }

            if (sl.Length == sr.Length)
            {
                count += Bigger(sl, true) - Bigger(sr, false);
            }
            else
            {
                count += Bigger(sl, true);
                count += 9*d - Bigger(sr, false);
            }

            writer.WriteLine(count);
            writer.Flush();
        }

        private static long Bigger(string sl, bool border)
        {
            long l = long.Parse(sl);
            if (sl.Length == 1)
            {
                return 10 - l - (border ? 0 : 1);
            }

            long d = 1;
            for (int i = 0; i < sl.Length - 2; i++)
            {
                d *= 10;
            }
            long count = d*(10 - (sl[0] - '0') - 1);

            char[] cl = sl.ToCharArray();
            cl[cl.Length - 1] = cl[0];

            var sd = new string(cl, 1, cl.Length - 2);
            if (sd.Length == 0)
                sd = "0";
            long dd = long.Parse(sd);
            long ll = long.Parse(new string(cl));

            if (ll < l || (ll == l && !border))
                dd++;

            count += d - dd;

            return count;
        }
    }
}

