            catch
            {
            }
            inp = new ConsoleInput ( );
            inp.ReadAll ( );
            long L = inp.NextLong ( );
            long R = inp.NextLong ( );
            long[] cntNumDigit = new long[20];
            cntNumDigit[1] = 10; //0~9
            cntNumDigit[2] = cntNumDigit[1] + 9; //0~99
            cntNumDigit[3] = cntNumDigit[2] + 10 * 9;
            long k=10;
            for ( int i = 4; i < 20; i++ )
            {
                k *= 10;
                cntNumDigit[i] = cntNumDigit[i - 1] + ( k * 9 );
            }
            long fr = F ( R, cntNumDigit );
            long fl = F ( L - 1, cntNumDigit );
            long ans = fr - fl;

            // start here
            // ====
            WriteLine ( ans );

        }

        private static long F ( long n, long[] cntNumDigit )
        {
            if ( n < 100 )
            {
                int cnt=0;
                for ( int i = 0; i <= n; i++ )
                {
                    string s = i.ToString ( );
                    if ( s[0] == s[s.Length - 1] )
                        cnt++;
                }
                return cnt;
            }
            else
            {
                int len = n.ToString().Length;
                long res=cntNumDigit[len - 1];
                long left = n.ToString ( )[0] - '0';
                long right = n % 10;
                long mid = long.Parse ( n.ToString ( ).Substring ( 1, len - 2 ) );
                for ( int i = 1; i <= 9; i++ )
                {
                    if ( i < left )
                    {
                        long add = long.Parse ( "1" + new string ( '0', len - 2 ) );
                        res += add;
                    }
                    else if ( i == left )
                    {
                        res += mid + 1;
                        if ( right < left )
                            res -= 1;
                    }
                }
                return res;
            }
        }

        private static void WriteLine ( object value )
        {
            Console.WriteLine ( string.Format ( CultureInfo.InvariantCulture, "{0}", value ) );
        }

