            public int NextInt ( )
            {
                return int.Parse ( lines[idx++] );
            }

            public long NextLong ( )
            {
                return long.Parse ( lines[idx++] );
            }

            public double NextDouble ( )
            {
                return double.Parse ( lines[idx++] );
