namespace BlockedPoints
{
    partial class BlockedPoints
    {
        static void Main(string[] args)
        {
            long n;

            n = NextLong();

            Console.WriteLine(FindMinBlockedPoints(n));
        }

        private static long FindMinBlockedPoints(long n)
        {
            long count = 0, x, y, nSquared;
            bool hasMove = false;

            if (n == 0)
                return 1;

            if (n == 1)
                return 4;

            x = 1;
            y = n - 1;
            nSquared = n * n;

            while (x < n && y > 0)
            {
                if (x * x + y * y <= nSquared)
                {
                    count++;
                    x++;
                    hasMove = false;
                }
                else
                {
                    if (!hasMove)
                    {
                        y--;
                        hasMove = true;
                    }
                    else
                    {
                        x--;
                    }
                }
            }

