﻿using System;
using System.IO;
using System.Text;

namespace Blocked_Points
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            long n = Next();

            long count;
            if (n == 1)
                count = 4;
            else if (n == 0)
                count = 1;
            else if (n == 2)
                count = 8;
            else
            {

                long y = (long)Math.Sqrt(n/2*n)+2;
                long nn = n*n;

                while (2*y*y > nn)
                {
                    y--;
                }
                if (y*y + (y+1)*(y+1) > nn)
                {
                    count = (y)*8;
                }
                else
                {
                    count = (2*y + 1)*4;
                }
            }

            writer.WriteLine(count);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
