class Solve
{


    public void solve(string data)
    {
        string[] Input = Console.ReadLine().Split(new char[] { ' ' });
      //  string[] Input = data.Split(new char[] { ' ' });
        int xl1 = Input[0][0] - 'a' + 1, yl1 = Input[0][1] - '0';
        int xl2 = Input[1][0] - 'a' + 1, yl2 = Input[1][1] - '0';
        int xk1 = Input[2][0] - 'a' + 1, yk1 = Input[2][1] - '0';
        int xk2 = Input[3][0] - 'a' + 1, yk2 = Input[3][1] - '0';

        int[,] P = new int[10, 10];
        P = Init();
        P[xl1, yl1] = 2;
        P[xl2, yl2] = 2;
        P[xk1, yk1] = 2;
        int x, y;

        //---------------------------first------------------
        x = xl1 - 1; y = yl1;
        while (P[x, y] != 2)        
            P[x--, y] = 1;                    

        x = xl1 + 1; y = yl1;
        while (P[x, y] != 2)        
            P[x++, y] = 1;

        x = xl1; y = yl1 - 1;
        while (P[x, y] != 2)
            P[x, y--] = 1;

        x = xl1; y = yl1 + 1;
        while (P[x, y] != 2)
            P[x, y++] = 1;


        //---------------------------second------------------
        x = xl2 - 1; y = yl2;
        while (P[x, y] != 2)
            P[x--, y] = 1;

        x = xl2 + 1; y = yl2;
        while (P[x, y] != 2)
            P[x++, y] = 1;

        x = xl2; y = yl2 - 1;
        while (P[x, y] != 2)
            P[x, y--] = 1;

        x = xl2; y = yl2 + 1;
        while (P[x, y] != 2)
            P[x, y++] = 1;            


        int[] dx = { 1, -1, -1, +1, 0, -1, 0, +1 };
        int[] dy = { 1, -1, +1, -1, -1, 0, +1, 0 };

        P[xk1, yk1] = 1;
        for (int k = 0; k < dx.Length; ++k)
            P[xk1 + dx[k], yk1 + dy[k]] = 1;


        if (P[xl1, yl1] == 2)
        {
            if (xl1 == xl2 || yl1 == yl2)
                P[xl1, yl1] = 1;
            else
                P[xl1, yl1] = 0;
        }

        if (P[xl2, yl2] == 2)
        {
            if (xl2 == xl1 || yl2 == yl1)
                P[xl2, yl2] = 1;
            else
                P[xl2, yl2] = 0;
        }


        bool ok = true;
        if (P[xk2, yk2] == 0)
            ok = false;

        for (int k = 0; k < dx.Length; ++k)
            if (P[xk2 + dx[k], yk2 + dy[k]] == 0)
                ok = false;

        if (ok)
            Console.WriteLine("CHECKMATE");
        else
            Console.WriteLine("OTHER");
    }

    private int[,] Init()
    {
        int[,] tmp = new int[10, 10];

        for (int i = 1; i <= 8; ++i)
            for (int j = 1; j <= 8; ++j)
                tmp[i, j] = 0;

        for (int k = 0; k < 10; ++k)
        {
            tmp[k, 0] = 2;
            tmp[k, 9] = 2;
            tmp[0, k] = 2;
            tmp[9, k] = 2;
        }

        return tmp;
    }
