            long[] f = Enumerable.Repeat(-1L, (int)a).ToArray();
            f[0] = 0;
            long[] l = new long[a];

            var queue = new Queue<long>();
            queue.Enqueue(0);
            while (queue.Count > 0)
            {
                long cur = queue.Dequeue();
                long d = cur + (b - cur + a - 1) / a * a;
                long t = d - b;
                while (t >= 0 && f[t % a] < 0)
                {
                    f[t % a] = Math.Max(d, f[cur % a]);
                    l[t % a] = t;
                    // Writer.WriteLine($"{t % a} - {f[t % a]} {l[t % a]}");
                    queue.Enqueue(t);
                    t -= b;
                }
            }

            // WriteArray(f);

            long ans = 0;
            for (int i = 0; i < a; i++)
            {
                if (f[i] >= 0 && f[i] <= m)
                {
                    long k = Calc(m, l[i], a) - Calc(f[i] - 1, l[i], a);
                    // Writer.WriteLine($"{i} : {k}");
                    ans += k;
                }
            }

            Writer.WriteLine(ans);
        }

        public static long Calc(long st, long k, long a)
        {
            long full = (st - k + 1) / a;
            long ans = a * full * (full + 1) / 2;
            ans += (st - k + 1) % a * (full + 1);
            return ans;
        }

