namespace Program
{
    public class Solver
    {

        public void Solve()
        {
            var n = sc.Integer();
            var s = sc.Scan();
            var X = new List<int>();
            var Y = new List<int>();
            var Z = new List<int>();
            for (int i = 0; i < n; i++)
            {
                var c = s[i];
                if (c == 'V') { X.Add(i); }
                else if (c == 'K') { Y.Add(i); }
                else { Z.Add(i); }
            }
            var x = X.Count; var y = Y.Count; var z = Z.Count;
            X.Add(n + 1000000); Y.Add(n + 1000000); Z.Add(n + 1000000);
            var D = new List<int>[] { X, Y, Z };
            var dp = new int[x + 2, y + 2, 2];
            for (int i = 0; i < x + 2; i++)
                for (int j = 0; j < y + 2; j++)
                    for (int k = 0; k < 2; k++)
                        dp[i, j, k] = 1000000;
            dp[0, 0, 0] = 0;
            for (int pos = 0; pos < n; pos++)
            {
                var next = new int[x + 2, y + 2, 2];
                for (int i = 0; i < x + 2; i++)
                    for (int j = 0; j < y + 2; j++)
                        for (int k = 0; k < 2; k++)
                            next[i, j, k] = 1000000;
                for (int a = 0; a < x + 1; a++)
                    for (int b = 0; b < y + 1; b++)
                    {
                        var c = pos - a - b;
                        if (c < 0) continue;
                        if (c > z) continue;
                        var vec = new int[] { a, b, c };
                        for (int k = 0; k < 2; k++)
                        {
                            if (dp[a, b, k] >= 1000000) continue;
                            next[a + 1, b, 1] = Math.Min(next[a + 1, b, 1], dp[a, b, k] + d(X[a], 0, vec, D));
                            if (k != 1)
                                next[a, b + 1, 0] = Math.Min(next[a, b + 1, 0], dp[a, b, k] + d(Y[b], 1, vec, D));
                            next[a, b, 0] = Math.Min(next[a, b, 0], dp[a, b, k] + d(Z[c], 2, vec, D));
                        }
                    }
                dp = next;
            }
            IO.Printer.Out.WriteLine(Math.Min(dp[x, y, 0], dp[x, y, 1]));

        }
        int d(int p, int k, int[] P, List<int>[] D)
        {
            var v = 0;
            for (int i = 0; i < 3; i++)
            {
                if (i == k) continue;
                for (int j = 0; j < P[i]; j++)
                    if (p < D[i][j]) v++;
            }
            return v;
        }

        public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());
        static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; ++i) a[i] = f(i); return a; }
        static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
    }
