namespace codeforces
{

    public class Program
    {
        private const int MOD = 1000 * 1000 * 1000 + 7;
        private const int NMax = 1000;

        private static int k;
        private static int pA;
        private static int pB;
        private static int ipB;
        private static int[,] dp = new int[NMax, NMax];
        private static bool[,] marked = new bool[NMax, NMax];

        private static int Add(int a, int b)
        {
            a += b;
            if (a >= MOD)
            {
                a -= MOD;
            }
            return a;
        }

        private static int Mult(int a, int b)
        {
            return (int)(1L * a * b % MOD);
        }

        private static int BinPow(int a, int n)
        {
            int result = 1;
            while (n > 0)
            {
                if (n % 2 == 1)
                {
                    result = Mult(result, a);
                }
                a = Mult(a, a);
                n /= 2;
            }
            return result;
        }

        private static int Solve(int count, int tk)
        {
            if (tk >= k)
            {
                return tk;
            }
            if (count + tk >= k)
            {
                return Add(Add(count, tk), ipB);
            }
            if (marked[count, tk])
            {
                return dp[count, tk];
            }
            marked[count, tk] = true;
            dp[count, tk] = Add(Mult(Solve(count + 1, tk), pA), Mult(Solve(count, tk + count), pB));
            return dp[count, tk];
        }

        private static void Main(string[] args)
        {
            var values = Console.ReadLine().Split(' ');
            k = Convert.ToInt32(values[0]);
            int pa = Convert.ToInt32(values[1]);
            int pb = Convert.ToInt32(values[2]);
            pA = Mult(pa, BinPow(Add(pa, pb), MOD - 2));
            pB = Mult(pb, BinPow(Add(pa, pb), MOD - 2));
            ipB = Mult(pa, BinPow(pb, MOD - 2));
            Console.WriteLine(Solve(1, 0));
        }
    }
}

