        static void Swap<T>(ref T a, ref T b) { T t = a; a = b; b = t; }
        static int Sqr(int a) { return a * a; }
        static long SqrL(int a) { return (long)a * a; }
        static long Sqr(long a) { return a * a; }
        static double Sqr(double a) { return a * a; }

        static StringBuilder sb = new StringBuilder();
        static Random rand = new Random(5);

        #endregion Helpers

        static int[] minQ;

        const int M = 1000000007;

        static int[,] C = GetCountModTable(100, 100, M);

        static public int[,] GetCountModTable(int maxN, int maxK, int Mod)
        {
            if (maxN < 0 || maxK < 0) throw new ArgumentException();
            if (Mod > int.MaxValue / 2) throw new ArgumentOutOfRangeException();
            var result = new int[maxN + 1, maxK + 1];
            for (int n = 0; n <= maxN; n++)
                for (int k = 0; k <= maxK; k++)
                    if (k == 0) result[n, k] = 1;
                    else if (n == 0) result[n, k] = 0;
                    else result[n, k] = (result[n - 1, k] + result[n, k - 1]) % Mod;
            return result;
        }

        static int[,] fcache;

        static long f(int n, int d)
        {
            checked
            {
                //if (d == 10) return n == 0 ? 1 : 0;
                if (n < minQ[d]) return 0;
                //if (n == 0) return 0;

                if (n == 0 || d > 9) throw new Exception();

                if (fcache[n, d] != 0) return fcache[n, d] - 1;

                long result = 0;
                for (int i = minQ[d]; i <= n; i++)
                {
                    long t1;

                    if (i == 0)
                    {
                        if (d == 9) t1 = n == 0 ? 1 : 0;
                        else t1 = f(n, d + 1);
                    }
                    else if (i == n)
                    {
                        if (minQ.Skip(d + 1).Any(q => q > 0)) t1 = 0;
                        else if (d == 0 && i > 1) t1 = 0;
                        else t1 = 1;
                    }
                    else
                    {
                        if (d == 9)
                            t1 = 0;
                        else
                        {
                            t1 = f(n - i, d + 1);
                            var t2 = d == 0 ? C[n - i, i] : C[n - i + 1, i];
                            t1 *= t2;
                        }
                    }

                    t1 %= M;
                    result = (result + t1) % M;
                }

                fcache[n, d] = (int)result + 1;
                return result;
            }
        }

        static void Main(string[] args)
        {
            checked
            {
                //Console.SetIn(File.OpenText("_input"));
                var parser = new Parser();
                while (!parser.SeekEOF)
                {
                    int n = parser.ReadInt();
                    minQ = parser.ReadIntArr(10);

                    //for (int i = 100; i <= 999; i++) if (i.ToString().Contains('0') && i.ToString().Contains('1')) Console.WriteLine(i);
                    //Console.WriteLine("");

                    //Console.WriteLine(f(3, 0));

                    //for (int d = 0; d <= 9; d++)
                    //{
                    //    Console.Write("d=" + d + ": ");
                    //    for (int i = 1; i <= n; i++)
                    //        Console.Write(f(i, d) + " ");
                    //    Console.WriteLine();
                    //}

                    fcache = new int[101, 10];
                    long result = 0;
                    for (int i = 1; i <= n; i++)
                        result = (result + f(i, 0)) % M;

                    if (minQ[0] <= 1 && minQ.Skip(1).All(q => q == 0)) result--;

                    Console.WriteLine(result);
                }
            }
        }

