            long k = f - 1;
            bool flag = true;
            foreach (int p in primes) {
                if (k % p == 0) {
                    flag = false;
                    long x = 1;
                    while (x < k) x *= p;
                    if (x == k) {
                        pmap.Add(f, p);
                    } else {
                        break;
                    }
                }
