public class Solution
{
    const int MAXN = 50;
    const int MAX_INV = MAXN * MAXN;

    long Fun(int n, int mod)
    {
        var d = new long[MAX_INV];
        d[0] = 1;
        int max = 0;
        long ans = 0;
        for (int i = 1; i < n; i++)
        {
            var nd = new long[MAX_INV];
            int nmax = max;
            long sum = 0;
            for (int j = 0; j <= i; j++)
                for (int k = 0; k <= i; k++)
                {
                    for (int p = 0; p <= max; p++)
                    {
                        int o = p + j - k;
                        nmax = Math.Max(nmax, o);
                        if (o >= 0)
                        {
                            nd[o] = (nd[o] + d[p]) % mod;
                            if (j < k && o > 0)
                                sum = (sum + d[p]) % mod;
                        }
                        if (p == 0)
                            continue;
                        o = -p + j - k;
                        nmax = Math.Max(nmax, o);
                        if (o >= 0)
                        {
                            nd[o] = (nd[o] + d[p]) % mod;
                            if (j < k && o > 0)
                                sum = (sum + d[p]) % mod;
                        }
                    }
                }
            ans = ((i + 1) * ans + sum) % mod;
            max = nmax;
            d = nd;
        }

        return ans;
    }

    public void Solve()
    {
        int n = ReadInt();
        int mod = ReadInt();

        Write(Fun(n, mod));
    }

