            }

            for (var i = 0; i < 4; i++) {
                if (Inside(coords1[i * 2], coords1[i * 2 + 1], coords2)) {
                    sw.WriteLine("YES");
                    return;
                }
            }

            for (var i = 0; i < 4; i++) {
                if (Inside(coords2[i * 2], coords2[i * 2 + 1], coords1)) {
                    sw.WriteLine("YES");
                    return;
                }
            }

            sw.WriteLine("NO");
        }

        private bool Inside(int x1, int y1, int[] coords)
        {
            var intersectsCount = 0;
            for (var i = 0; i < 4; i++) {
                if (IsIntersect(x1, y1, 100, 100, coords[i * 2], coords[i * 2 + 1], coords[(i + 1) * 2], coords[(i + 1) * 2 + 1])) {
                    intersectsCount++;
                }
            }

            return intersectsCount == 1;
        }

        private int Cross(int x1, int y1, int x2, int y2, int x, int y)
        {
            return (x1 - x) * (y2 - y) - (x2 - x) * (y1 - y);
        }

        private bool IsIntersect(int x1, int y1, int x2, int y2, int x3, int y3, int x4, int y4)
        {
            var d1 = Cross(x2, y2, x3, y3, x1, y1);
            var d2 = Cross(x2, y2, x4, y4, x1, y1);
            var d3 = Cross(x4, y4, x2, y2, x3, y3);
            var d4 = Cross(x4, y4, x1, y1, x3, y3);
            if (((d1 > 0 && d2 < 0) || (d2 > 0 && d1 < 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0)))
                return true;
            if (d1 == 0 && InSegment(x1, y1, x2, y2, x3, y3))
                return true;
            if (d2 == 0 && InSegment(x1, y1, x2, y2, x4, y4))
                return true;
            if (d3 == 0 && InSegment(x3, y3, x4, y4, x2, y2))
                return true;
            if (d4 == 0 && InSegment(x3, y3, x4, y4, x1, y1))
                return true;

            return false;
        }

        private bool InSegment(int x1, int y1, int x2, int y2, int x, int y)
        {
            return x >= Math.Min(x1, x2) && x <= Math.Max(x1, x2) && y >= Math.Min(y1, y2) && y <= Math.Max(y1, y2);
        }

        ~Task()
        {
            Dispose(false);
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        private void Dispose(bool disposing)
        {
            if (!isDispose) {
                if (disposing) {
                    if(sr != null)
                        sr.Dispose();

                    if(sw != null)
                        sw.Dispose();
                }

                isDispose = true;
            }
        }
    }
}

internal class InputReader : IDisposable
{
    private bool isDispose;
    private readonly TextReader sr;
    private string[] buffer;
    private int seek;

    public InputReader(TextReader stream)
    {
        sr = stream;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    public string NextString()
    {
        var result = sr.ReadLine();
        return result;
    }

    public int NextInt32()
    {
        return Int32.Parse(ReadNextToken());
    }

    private string ReadNextToken()
    {
        if (buffer == null || seek == buffer.Length) {
            seek = 0;
            buffer = NextSplitStrings();
        }

        return buffer[seek++];
    }

    public long NextInt64()
    {
        return Int64.Parse(ReadNextToken());
    }

    public int[] ReadArrayOfInt32()
    {
        return ReadArray(Int32.Parse);
    }

    public long[] ReadArrayOfInt64()
    {
        return ReadArray(Int64.Parse);
    }

    public string[] NextSplitStrings()
    {
        return NextString()
            .Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public T[] ReadArray<T>(Func<string, CultureInfo, T> func)
    {
        return NextSplitStrings()
            .Select(s => func(s, CultureInfo.InvariantCulture))
            .ToArray();
    }

    public T[] ReadArrayFromString<T>(Func<string, CultureInfo, T> func, string str)
    {
        return
            str.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(s => func(s, CultureInfo.InvariantCulture))
                .ToArray();
    }

    protected void Dispose(bool dispose)
    {
        if (!isDispose)
        {
            if (dispose)
                sr.Close();

            isDispose = true;
        }
    }

    ~InputReader()
    {
        Dispose(false);
    }
}

﻿using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.NetworkInformation;

namespace Codeforces.R318.E
{
    public static class Solver
    {
        public static void Main()
        {
            using (var sw = new StreamWriter(Console.OpenStandardOutput()) {
                AutoFlush = false
            })
            {
                Solve(Console.In, sw);
            }
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            WriteAnswer(tw, Parse(tr));
        }

        private static void WriteAnswer(TextWriter tw, long[] res)
        {
            if (res == null)
            {
                tw.WriteLine("NO");
                return;
            }

            tw.WriteLine(res.Length);

            foreach (var t in res)
            {
                var prev = t & ((1 << 16) - 1);
                var to = (t >> 16) & ((1 << 16) - 1);
                var d = t >> 32;
                tw.WriteLine("{0} {1} {2}", prev + 1, to + 1, d);
            }
        }

        private static long[] Parse(TextReader tr)
        {
            var w = tr.ReadLine().Split();
            var e = int.Parse(w[2]);

            var a = from x in tr.ReadLine().Split() select int.Parse(x);
            var b = from x in tr.ReadLine().Split() select int.Parse(x);

            var edges = new (int, int)[e];
            for (int i = 0; i < e; ++i)
            {
                var l = tr.ReadLine().Split();
                edges[i] = (int.Parse(l[0]) - 1, int.Parse(l[1]) - 1);
            }

            return Calc(a.ToArray(), b.ToArray(), edges);
        }

        public static long[] Calc(int[] a, int[] b, (int, int)[] edges)
        {
            var n = a.Length;
            var mat = new (int, int)[n, n];

            for (int i = 0; i < n; ++i)
            {
                for (int j = 0; j < n; ++j)
                {
                    mat[i, j] = i == j ? (0, i) : (9999, i);
                }
            }

            foreach (var edge in edges)
            {
                mat[edge.Item1, edge.Item2] = (1, edge.Item1);
                mat[edge.Item2, edge.Item1] = (1, edge.Item2);
            }

            for (int k = 0; k < n; ++k)
            {
                for (int i = 0; i < n; ++i)
                {
                    for (int j = 0; j < n; ++j)
                    {
                        if (mat[i, k].Item1 + mat[k, j].Item1 < mat[i, j].Item1)
                        {
                            mat[i, j] = (mat[i, k].Item1 + mat[k, j].Item1, mat[k, j].Item2);
                        }
                    }
                }
            }

            var res = Execute(a, b, mat);

            if (!a.SequenceEqual(b))
            {
                return null;
            }

            return res.ToArray();
        }

        public static List<long> Execute(int[] a, int[] b, (int, int)[,] mat)
        {
            var calculator = new Calculator(a, b, mat);
            return calculator.Solve();
        }
    }

    internal class Calculator
    {
        List<long> res = new List<long>();
        int[] a;
        int[] b;
        (int, int)[,] mat;

        public Calculator(int[] a, int[] b, (int, int)[,] mat)
        {
            this.a = a;
            this.b = b;
            this.mat = mat;
        }

        public List<long> Solve()
        {
            var n = a.Length;
            for (; ; )
            {
                var prev = res.Count;
                for (int i = 0; i < n; ++i)
                {
                    for (int j = 0; j < n; ++j)
                    {
                        if (a[i] > b[i] && a[j] < b[j] && mat[i, j].Item1 <= n)
                        { 
                            Pour(i, j, Math.Min(a[i] - b[i], b[j] - a[j]));
                        }
                    }
                }
                if (prev == res.Count)
                {
                    break;
                }
            }

            return res;
        }

        private void Pour(int from, int to, int d)
        {
            if (from == to)
            {
                return;
            }

            var prev = mat[from, to].Item2;
            var p = Math.Min(a[prev], d);
            if (p > 0)
            {
                a[prev] -= p;
                a[to] += p;
                res.Add(CreateKey(prev, to, p));
            }

            Pour(from, prev, d);

            if (d - p > 0)
            {
                a[prev] -= d - p;
                a[to] += d - p;
                res.Add(CreateKey(prev, to, d - p));
            }
        }

        private long CreateKey(long prev, long to, long d)
        {
            return (d << 32) + (to << 16) + prev;
        }
    }
}

