class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().solve();
        return 0;
    }

    long mod = 1000000007;
    void solve()
    {
        Scanner cin = new Scanner();

        int n = cin.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = cin.nextInt();
        }

        int MAX = 1 << n;

        long[] now = new long[MAX];

        long[] plus = new long[n + 100];
        plus[0] = 0;
        plus[1] = 0;
        plus[2] = 1;


        for (int i = 3; i <= n; i++)
        {
            plus[i] = (plus[i - 1] * (i - 1)) % mod;
        }

        for (int i = 0; i < MAX; i++)
        {
            int count = 0;
            int sum = 0;
            for (int j = 0; j < n; j++)
            {
                if ((i >> j) % 2 == 0) continue;
                count++;
                sum += a[j] - 1;
            }
            sum += 2;
            if (sum >= count)
            {
                now[i] = plus[count];
            }
        }

        long ret = 0;
        long[] dp = new long[MAX];
        for (int i = 0; i < MAX; i++)
        {
            int revi = MAX - 1 - i;
            for (int j = revi; j > 0; j = ((j - 1) & revi))
            {
                dp[i + j] = (dp[i + j] + now[i] * dp[j]) % mod;
            }
            dp[i] = (dp[i] + now[i]) % mod;
        }
        for (int i = 0; i < MAX; i++)
        {
            ret = (ret + dp[i]) % mod;
        }
        ret = (ret + 1) % mod;
        Console.WriteLine(ret);

    }

    int bitCount(long x)
    {
        x = (x & 0x5555555555555555) + (x >> 1 & 0x5555555555555555);
        x = (x & 0x3333333333333333) + (x >> 2 & 0x3333333333333333);
        x = (x & 0x0f0f0f0f0f0f0f0f) + (x >> 4 & 0x0f0f0f0f0f0f0f0f);
        x = (x & 0x00ff00ff00ff00ff) + (x >> 8 & 0x00ff00ff00ff00ff);
        x = (x & 0x0000ffff0000ffff) + (x >> 16 & 0x0000ffff0000ffff);
        return (int)((x & 0x00000000ffffffff) + (x >> 32 & 0x00000000ffffffff));
    }


}



