namespace Codeforces.R355.D
{
    public static class Solver
    {
        public static void Main()
        {
            using (var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Solve(Console.In, sw);
            }
        }

        public static void Solve(TextReader tr, TextWriter tw)
        {
            WriteAnswer(tw, Parse(tr));
        }

        struct Answer
        {
            public string Winner;
        }

        private static void WriteAnswer(TextWriter tw, Answer answer)
        {
            tw.WriteLine(answer.Winner);
        }

        private static Answer Parse(TextReader tr)
        {
            var n = int.Parse(tr.ReadLine());
            var board = new string[n];
            for (var i = 0; i < n; ++i)
                board[i] = tr.ReadLine();
            return Calc(board);
        }

        private static Answer Calc(string[] board)
        {
            var answer = new Answer();
            var memo = new Dictionary<(int, int), int>();
            var r = Rec("" + board[0][0], 1, 0, board, memo);

            if (r > 0)
                answer.Winner = "FIRST";
            else if (r < 0)
                answer.Winner = "SECOND";
            else
                answer.Winner = "DRAW";

            return answer;
        }

        private static int Rec(string str, int mask, int currentC, string[] board, Dictionary<(int, int), int> memo)
        {
            var n = board.Length;
            var numStr = str.Length;

            var key = (numStr, mask);
            if (memo.ContainsKey(key))
                return memo[key];


            if (numStr == n * 2 - 1)
            {
                if (str.Last() == 'a')
                    return 1;
                else if (str.Last() == 'b')
                    return -1;
                return 0;
            }

            var res = numStr % 2 == 0 ? int.MinValue : int.MaxValue;

            for (var ch = 'a'; ch <= 'z'; ++ch)
            {
                var nm = 0;

                for (var y = 0; y < n; ++y)
                {
                    if ((mask & (1 << y)) == 0)
                        continue;
                    var x = numStr - y - 1;
                    if (x < 0 || x >= n)
                        continue;
                    if (x < n - 1 && board[y][x + 1] == ch)
                        nm |= 1 << y;
                    if (y < n - 1 && board[y + 1][x] == ch)
                        nm |= 1 << y + 1;
                }
                if (nm == 0)
                    continue;

                if (numStr % 2 == 0)
                    res = Math.Max(res, Rec(str + ch, nm, 0, board, memo));
                else
                    res = Math.Min(res, Rec(str + ch, nm, 0, board, memo));
            }

            if (str.Last() == 'a')
                res += 1;
            else if (str.Last() == 'b')
                res += -1;

            return memo[key] = res;
        }
    }
}

