// (づ°ω°)づﾐ★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
public class Solver
{
    private int n;

    private string[] table;
    private int?[,] mem;

    List<Tuple<int, int>> Decode(int x, int mask)
    {
        var ret = new List<Tuple<int, int>>();
        if (x >= n)
        {
            int d = x - n;
            for (int i = 0; i < n - 1 - d; i++)
                if ((mask >> i & 1) == 1)
                    ret.Add(Tuple.Create(d + 1 + i, n - 1 - i));
        }
        else
        {
            for (int i = 0; i <= x; i++)
                if ((mask >> i & 1) == 1)
                    ret.Add(Tuple.Create(i, x - i));
        }
        return ret;
    }

    int Encode(int r, int c)
    {
        if (r + c >= n)
            return 1 << n - c - 1;
        return 1 << r;
    }

    int Fun(int x, int mask)
    {
        if (mem[x, mask].HasValue)
            return mem[x, mask].Value;

        if (x == 2 * (n - 1))
            return 0;

        var cpos = Decode(x, mask);

        int ret = x % 2 == 1 ? int.MinValue : int.MaxValue;
        for (char ch = 'a'; ch <= 'z'; ch++)
        {
            int nmask = 0;
            foreach (var p in cpos)
            {
                if (p.Item1 + 1 < n && table[p.Item1 + 1][p.Item2] == ch)
                    nmask |= Encode(p.Item1 + 1, p.Item2);
                if (p.Item2 + 1 < n && table[p.Item1][p.Item2 + 1] == ch)
                    nmask |= Encode(p.Item1, p.Item2 + 1);
            }
            if (nmask > 0)
            {
                int y = Fun(x + 1, nmask);
                if (ch == 'a')
                    y++;
                else if (ch == 'b')
                    y--;
                if (x % 2 == 1)
                    ret = Math.Max(ret, y);
                else
                    ret = Math.Min(ret, y);
            }
        }

        return (mem[x, mask] = ret).Value;
    }

    public object Solve()
    {
        n = ReadInt();
        table = ReadLines(n);

        mem = new int?[n << 1,1 << n];
        int r = Fun(0, 1);
        if (table[0][0] == 'a')
            r++;
        if (table[0][0] == 'b')
            r--;

        return r > 0 ? "FIRST" : (r == 0 ? "DRAW" : "SECOND");
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;

    static void Main()
    {
#if DEBUG
        reader = new StreamReader("..\\..\\input.txt");
        writer = Console.Out;
        //writer = new StreamWriter("..\\..\\output.txt");
#else
        reader = new StreamReader(Console.OpenStandardInput());
