class Solver
{
    int N;const int MOD = (int)1e9 + 7;
    string S;
    int[][] dp;
    public void Solve(Scanner sc)
    {
        N = sc.Int;S = ReadLine();
        dp = Create(N, () => Create(1<<20,()=>-1));
        int res = 0;
        for (var i = 0; i < N; i++)
        { res += memo(0, i); if (res >= MOD) res -= MOD; }
        WriteLine(res);
    }
    int memo(int s,int i)
    {
        var ct = 0;
        for (var j = 0; j < 20; j++)
            ct += 1 & s >> j;
        if (i == N)
            return ToInt32(ct != 0 && (1 << ct) - 1 == s);
        if (dp[i][s] != -1) return dp[i][s];
        int res = 0;
        if (S[i] == '0') return dp[i][s] = memo(s, i + 1);
        var c = 0;
        for (var j = i; j < N; j++)
        {
            c <<= 1;c += S[j] - '0';
            if (c > 20) break;
            res += memo(s | (1 << (c - 1)), j + 1);
            if (res >= MOD) res -= MOD;
        }
        if (ct != 0 && (1 << ct)-1 == s) res++;
        if (res >= MOD) res -= MOD;
        return dp[i][s] = res;
    }
}

