using System;

namespace Task_D
{
    class Solution
    {
        static void Main(string[] args)
        {
            new Solution().Solve();
        }

        private int n;
        private int d;
        private long x;
        private int[] a;
        private int[] b;
        private int[] c;

        private void Solve()
        {
            var parts = Console.ReadLine().Split();
            n = int.Parse(parts[0]);
            d = int.Parse(parts[1]);
            x = long.Parse(parts[2]);

            a = new int[n];
            b = new int[n];
            c = new int[n];

            initAB();

            var bCount = 0;
            var bPos = new int[n];
            for (int i = 0; i < n; i++)
            {
                if (b[i] == 1)
                {
                    bPos[bCount++] = i;
                }
            }

            var aOrder = new int[n];
            for (int i = 0; i < n; i++)
            {
                aOrder[a[i] - 1] = i;
            }

            int s = 50;

            for (int i = 0; i < n; i++)
            {
                for (int q = 0; q < s && q < n; q++)
                {
                    int j = aOrder[n - q - 1];
                    if (i - j >= 0 && b[i - j] == 1)
                    {
                        c[i] = a[j];
                        break;
                    }
                }

                if (c[i] != 0)
                {
                    continue;
                }

                for (int z = 0; z < bCount; z++)
                {
                    var bIndex = bPos[z];
                    var j = i - bIndex;
                    if (j >= 0)
                    {
                        c[i] = Math.Max(c[i], a[j]);
                    }
                }
            }

            for (int i = 0; i < n; i++)
            {
                Console.WriteLine(c[i]);
            }
        }

        private long getNextX()
        {
            x = (x * 37 + 10007) % 1000000007;
            return x;
        }

        private void initAB()
        {
            for (int i = 0; i < n; i = i + 1)
            {
                a[i] = i + 1;
            }

            for (int i = 0; i < n; i = i + 1)
            {
                swap(ref a[i], ref a[getNextX() % (i + 1)]);
            }

            for (int i = 0; i < n; i = i + 1)
            {
                if (i < d)
                    b[i] = 1;
                else
                    b[i] = 0;
            }

            for (int i = 0; i < n; i = i + 1)
            {
                swap(ref b[i], ref b[getNextX() % (i + 1)]);
            }
        }

        private void swap<T>(ref T first, ref T second)
        {
            T tmp = first;
            first = second;
            second = tmp;
        }
    }
}

