{
    long Tot(long n)
    {
        long ret = n;
        for (long i = 2; i * i <= n; i++)
            if (n % i == 0)
            {
                ret = ret / i * (i - 1);
                while (n % i == 0)
                {
                    n /= i;
                }
            }
        if (n > 1)
            ret = ret / n * (n - 1);
        return ret;
    }

