class Program
{
    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
//    static Scan sc = new ScanCHK();
    const int M = 1000000007;
    const double eps = 1e-9;
    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    static SortedDictionary<long, long> memo;
    static void Main()
    {
        long n, k;
        sc.Multi(out n, out k);
        k = (k + 1) / 2;
        memo = new SortedDictionary<long, long>();

        Prt(calc(n, k) % M);
        sw.Flush();
    }
    static long f(long n)
    {
        if (n < 3) return 1;
        if (memo.ContainsKey(n))
            return memo[n];

        long ret = n - 1;
        for (long i = 2; i * i <= n; i++)
        {
            if (n % i == 0)
            {
                ret -= f(i);
                if (i != n / i)
                {
                    ret -= f(n / i);
                }
            }
        }
        memo.Add(n, ret);
        return ret;
    }
    static long calc(long n, long k)
    {
        if (n == 1) return 1;
        if (k == 0) return n;

        long nn = n - 1;
        for (long i = 2; i * i <= n; i++)
        {
            if (n % i == 0)
            {
                nn -= f(i);
                if (i != n / i)
                {
                    nn -= f(n / i);
                }
            }
        }
        return calc(nn, k - 1);
    }

