    internal class Solution
    {
        long[] a = new long[11];
        long[] p = new long[11];
        long[] r = new long[7];
        long[,] c = new long[11, 11];
        long mod = 1000000000 + 7;
        long[] p2 = new long[11];
        long[] p8 = new long[11];
        private int m;

        private long ans = 0;

        public void Solve()
        {
            for (int i = 0; i < 11; i++)
            {
                c[i, 0] = 1;
            }

            for (int i = 1; i < 11; i++)
            {
                for (int j = 1; j < 11; j++)
                {
                    c[i, j] = c[i - 1, j - 1] + c[i - 1, j];
                }
            }

            p2[0] = 1;
            p8[0] = 1;
            for (int i = 1; i < 11; i++)
            {
                p2[i] = 2 * p2[i - 1];
                p8[i] = 8 * p8[i - 1];
            }

            Reader.ReadInt(out m);
            p[1] = 1;
            for (int i = 2; i <= 10; i++)
            {
                p[i] = 10 * p[i - 1];
            }
            Go(10, 0, 0);
            a[0]--;

            CalcAns(0, 1);

            Console.WriteLine(ans);
        }

        private void CalcAns(int t, long count)
        {
            if (t > 0 && (r.Sum() - r[0] >= r[0]))
            {
                return;
            }

            if (t == 7)
            {
                if (r.Sum() - r[0] < r[0])
                {
                    ans = (ans + count)%mod;
                }
                return;
            }

            for (int i = 0; i < 10; i++)
            {
                if (a[i] > 0)
                {
                    r[t] = i;
                    long next = (count*a[i])%mod;
                    a[i]--;
                    CalcAns(t + 1, next);
                    a[i]++;
                    r[t] = 0;
                }
            }
        }

        private void Go(int t, int count, long current)
        {
            if (t == 0)
            {
                a[count]++;
                return;
            }

            for (int i = 0; i < 10; i++)
            {
                if (current + (i + 1) * p[t] <= m)
                {
                    int d = (i == 4 || i == 7) ? 1 : 0;
                    for (int j = 0; j < t; j++)
                    {
                        a[count + d + j] += c[t - 1, j]*p2[j]*p8[t - 1 - j];
                    }
                }
                else
                {
                    int d = (i == 4 || i == 7) ? 1 : 0;
                    Go(t - 1, count + d, current + i * p[t]);
                    break;
                }
            }
        }
    }
}

