public class Solver
{
    double Fun(double x, double y, double z)
    {
        return z * Math.Log(y) + Math.Log(Math.Log(x));
    }

    double Fun2(double x, double y, double z)
    {
        return Math.Log(y) + Math.Log(z) + Math.Log(Math.Log(x));
    }

    double Fun3(double x, double y, double z)
    {
        return Math.Pow(x, Math.Pow(y, z));
    }

    double Fun4(double x, double y, double z)
    {
        return Math.Pow(Math.Pow(x, y), z);
    }

    public void Solve()
    {
        double x = ReadDouble();
        double y = ReadDouble();
        double z = ReadDouble();

        double max = double.MinValue;
        string ans = "";
        Action<double, string> act = (v, s) =>
        {
            if (v > max + 1e-9)
            {
                max = v;
                ans = s;
            }
        };
        if (x <= 1 && y <= 1 && z <= 1)
        {
            act(Fun3(x, y, z), "x^y^z");
            act(Fun3(x, z, y), "x^z^y");
            act(Fun4(x, y, z), "(x^y)^z");
            act(Fun4(x, z, y), "(x^z)^y");
            act(Fun3(y, x, z), "y^x^z");
            act(Fun3(y, z, x), "y^z^x");
            act(Fun4(y, x, z), "(y^x)^z");
            act(Fun4(y, z, x), "(y^z)^x");
            act(Fun3(z, x, y), "z^x^y");
            act(Fun3(z, y, x), "z^y^x");
            act(Fun4(z, x, y), "(z^x)^y");
            act(Fun4(z, y, x), "(z^y)^x");
            Write(ans);
            return;
        }

        if (x > 1)
        {
            act(Fun(x, y, z), "x^y^z");
            act(Fun(x, z, y), "x^z^y");
            act(Fun2(x, y, z), "(x^y)^z");
            act(Fun2(x, z, y), "(x^z)^y");
        }
        if (y > 1)
        {
            act(Fun(y, x, z), "y^x^z");
            act(Fun(y, z, x), "y^z^x");
            act(Fun2(y, x, z), "(y^x)^z");
            act(Fun2(y, z, x), "(y^z)^x");
        }
        if (z > 1)
        {
            act(Fun(z, x, y), "z^x^y");
            act(Fun(z, y, x), "z^y^x");
            act(Fun2(z, x, y), "(z^x)^y");
            act(Fun2(z, y, x), "(z^y)^x");
        }

        Write(ans);
    }

