using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.IO;

class Program
{
	int[][] c;
	int n, m;
	int mod = 1000000007;
	int add(int x, int y)
	{
		x+=y;
		return x < mod ? x : x - mod;
	}
	int mul(int x, int y)
	{
		return Convert.ToInt32(Convert.ToInt64(x) * y % mod);
	}
	void run()
	{
		String[] str = Console.ReadLine().Split(' ');
		n = Convert.ToInt32(str[0]);
		m = Convert.ToInt32(str[1]);
		int[][] dp=new int[n+1][];
		for (int i = 1; i <= n; i++)
		{
			dp[i] = new int[m-1];
			if (i == 1)
			{
				for (int j = 0; j <= m - 2; j++)
					dp[i][j] = 1;
				continue;
			}
			int now = 0;
			for (int j = 0; j <= m-2; j++)
			{
				now= add(now,dp[i-1][j]);
				dp[i][j] = add(j == 0 ? 0 : dp[i][j - 1], now);
			}
		}

		int[][] sum = new int[n+1][];
		for (int i = 0; i <= n; i++)
		{
			sum[i] = new int[m - 1];
			for (int j = 0; j <= m - 2; j++)
				sum[i][j] = i == 0 ? 0 : add(sum[i - 1][j] , dp[i][j]);
		}

		int res = 0;
		for (int i = 1; i <= n; i++)
			for (int j = 0; j <= m - 2; j++)
			{
				res = add(res, mul(mul(sum[i][j], add(sum[n - i + 1][j], mod - sum[n - i][j])), m - 1 - j));
			}
		Console.WriteLine(res);
	}
	static void Main(String[] args)
	{
		new Program().run();
	}
}

