public class Solver
{
    int MOD;

    long[,] MatMult(long[,] a, long[,] b, int n)
    {
        var ret = new long[n, n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                    ret[i, j] = (ret[i, j] + a[i, k] * b[k, j]) % MOD;
        return ret;
    }

    long[,] MatPow(long[,] a, int n, long p)
    {
        var ret = new long[n, n];
        for (int i = 0; i < n; i++)
            ret[i, i] = 1;
        while (p > 0)
        {
            if ((p & 1) == 1)
                ret = MatMult(ret, a, n);
            a = MatMult(a, a, n);
            p >>= 1;
        }
        return ret;
    }

    long Fib(long n)
    {
        var a = new long[,] { { 1, 1 }, { 1, 0 } };
        a = MatPow(a, 2, n + 1);
        return a[0, 0];
    }

    int ModPow(long x, long p)
    {
        long ret = 1;
        while (p > 0)
        {
            if ((p & 1) == 1)
                ret = ret * x % MOD;
            x = x * x % MOD;
            p >>= 1;
        }
        return (int)ret;
    }

    void Solve()
    {
        long n = ReadLong();
        long k = ReadLong();
        int l = ReadInt();
        MOD = ReadInt();

        long f = Fib(n);
        long p = (ModPow(2, n) + MOD - f) % MOD;
        long ans = 1;
        for (int i = 0; i < l; i++)
            if ((k >> i & 1) == 1)
                ans = ans * p % MOD;
            else
                ans = ans * f % MOD;

        if (l < 60 && (k >> l) != 0)
            Write(0);
        else
            Write(ans % MOD);
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;
