        const int P = 1000000007;
        public int pow(int a, int b)
        {
            if (b == 0) return 1;
            int res = pow(a, (b >> 1));
            res = (int)((1L * res * res) % P);
            if ((b & 1) == 1)
            {
                return (int)((1L * res * a) % P);
            }
            return res;
        }

        int comb(int n, int k, int[] fac, int[] finv)
        {
            if (k > n) return 0;
            if (k == 0 || k == n) return 1;
            return (int) (((1L * (1L * fac[n] * finv[k]) % P) * finv[n-k]) % P);
        }

        public void solve()
        {
            string[] inputs = Console.ReadLine().Split(' ');
            int f = int.Parse(inputs[0]);
            int w = int.Parse(inputs[1]);
            int h = int.Parse(inputs[2]);

            if (w == 0 || h == 0)
            {
                Console.WriteLine(1);
                return;
            }
            else if (f == 0)
            {
                if (w > h)
                {
                    Console.WriteLine(1);
                    return;
                }
                else
                {
                    Console.WriteLine(0);
                    return;
                }
            }
            if (w <= h && w > 0)
            {
                Console.WriteLine(0);
                return;
            }
            int n = Math.Max(f + 1, w - 1) + 1;
            int[] fac = new int[n];
            int[] finv = new int[n];
            fac[0] = finv[0] = 1;
            fac[1] = finv[1] = 1;
            for (int i = 2; i < n; i++)
            {
                fac[i] = (int)((1L * fac[i - 1] * i) % P);
                finv[i] = pow(fac[i], P - 2); 
            }

            int all = 0, good = 0, f1 = f + 1, w1 = w - 1, upper = w / (h + 1);
            for (int u = 1; u <= w; u++)
            {
                if (u > f1) break;
                int f1u = comb(f1, u, fac, finv);
                all += mult(f1u, comb(w1, u - 1, fac, finv));
                all %= P;
                if (u <= upper)
                {
                    good += mult(f1u, comb(w - u * h - 1, u - 1, fac, finv));
                    good %= P;
                }
            }
            //Console.WriteLine(pow(all, P-2));
            int res = (int)(1L * good * pow(all, P - 2) % P);
            //Console.WriteLine(res + " = " + good +" / " + all);
            Console.WriteLine(res);

            //Console.Read();
        }
        public int mult(int a, int b)
        {
            return (int)((1L * a * b) % P);
        }
    }
