    void Fun(int x, int lim, int k, long s, SDictionary<long, int>[] dicts)
    {
        if (s < 0)
            return;
        if (x == lim)
        {
            dicts[k][s]++;
            return;
        }

        if (a[x] < 19 && k > 0)
            Fun(x + 1, lim, k - 1, s - fact[a[x]], dicts);
        Fun(x + 1, lim, k, s - a[x], dicts);
        Fun(x + 1, lim, k, s, dicts);
    }

