        var d1 = Enumerable.Repeat(0, k + 1).Select(x => new SDictionary<long, int>()).ToArray();
        Fun(0, n / 2, k, s, d1);
        var d2 = Enumerable.Repeat(0, k + 1).Select(x => new SDictionary<long, int>()).ToArray();
        Fun(n / 2, n, k, s, d2);

        long ans = 0;
        for (int i = 0; i <= k; i++)
            foreach (var p in d1[i])
                for (int j = k - i; j <= k; j++)
                    ans += p.Value * d2[j][s - p.Key];

        Write(ans);
    }

