    {
        1, 1, 2, 6, 24,
        120, 720, 5040, 40320, 362880,
        3628800, 39916800, 479001600, 6227020800, 87178291200,
        1307674368000, 20922789888000, 355687428096000, 6402373705728000, 121645100408832000
    };

    static Dictionary<long, long>[] dm;
    static void Build(int[] a, int p, int k, int mk, long s)
    {
        if (p == a.Length)
        {
            for (var t = mk - k; t <= mk; t++)
            {
                if (!dm[t].ContainsKey(s))
                {
                    dm[t][s] = 0;
                }
                dm[t][s]++;
            }
            return;
        }

        var x = a[p];
        if(x < 19 && k > 0)
        {
            Build(a, p + 1, k - 1, mk, s + fact[x]);
        }
        Build(a, p + 1, k, mk, s + x);
        Build(a, p + 1, k, mk, s);
    }
    static long Search(int[] a, int p, int to, int k, long s)
    {
        if (s < 0) return 0;
        if(p == to)
        {
            long r;
            dm[k].TryGetValue(s, out r);
            return r;
        }

        long res = 0;
        if(a[p] < 19 && k > 0)
        {
            res += Search(a, p + 1, to, k - 1, s - fact[a[p]]);
        }
        res += Search(a, p + 1, to, k, s);
        res += Search(a, p + 1, to, k, s - a[p]);

        return res;
    }

