public class Solution
{
    int mod;

    long Fun(int n)
    {
        var dp = new long[n + 1];
        dp[1] = 1;
        long sum = 1;
        var pdp = new long[n + 1];
        for (int i = 1; i <= n; i++)
        {
            pdp[i] = (pdp[i] + pdp[i - 1]) % mod;
            dp[i] = (sum + pdp[i]) % mod;
            
            for (int j = i * 2, k = 2; j <= n; j += i, k++)
            {
                pdp[j] = (pdp[j] + dp[i]) % mod;
                if (j + k <= n)
                    pdp[j + k] = (pdp[j + k] + mod - dp[i]) % mod;
            }

            if (i > 1)
                sum = (sum + dp[i]) % mod;
        }
        return dp[n];
    }

    public void Solve()
    {
        int n = ReadInt();
        mod = ReadInt();
        Write(Fun(n));
    }

