            long v = f[i - 1] * (i - m + ps[i - 1] - ps[i - m - 1] + MOD) % MOD;
            ps[i] = (ps[i - 1] + v * rf[i]) % MOD;
        }

        Write(ps[n - 1] * f[n - 1] % MOD);
