{
    public class FastScanner : StreamReader
    {
        private string[] _line;
        private int _iterator;

        public FastScanner(Stream stream) : base(stream)
        {
            _line = null;
            _iterator = 0;
        }
        public string NextToken()
        {
            if (_line == null || _iterator >= _line.Length)
            {
                _line = base.ReadLine().Split(' ');
                _iterator = 0;
            }
            if (_line.Count() == 0) throw new IndexOutOfRangeException("Input string is empty");
            return _line[_iterator++];
        }
        public int NextInt()
        {
            return Convert.ToInt32(NextToken());
        }
        public long NextLong()
        {
            return Convert.ToInt64(NextToken());
        }
        public float NextFloat()
        {
            return float.Parse(NextToken());
        }
        public double NextDouble()
        {
            return Convert.ToDouble(NextToken());
        }
    }
    class MemoryAndScores370
    {
        private static int a, b, k, t;
        private static long[] comb, combSum;
        private static long mod;
        public static void Main(string[] args)
        {
            using (FastScanner fs = new FastScanner(new BufferedStream(Console.OpenStandardInput())))
            using (StreamWriter writer = new StreamWriter(new BufferedStream(Console.OpenStandardOutput())))
            {
                a = fs.NextInt();
                b = fs.NextInt();
                k = fs.NextInt();
                t = fs.NextInt();
                comb = new long[2 * k * t + 1];
                combSum = new long[2 * k * t + 1];
                mod = (int)1e9 + 7;
                for (int i = 0; i <= 2 * k; i++)
                {
                    comb[i] = 1;
                }
                for (int i = 1; i < t; i++)
                {
                    long sum = 0;
                    long[] tcomb = new long[2 * k * t + 1];
                    for (int j = 0; j < comb.Length; j++)
                    {
                        sum = (sum + comb[j]) % mod;
                        if (j > 2 * k)
                        {
                            sum = (mod + (sum - comb[j - 2 * k - 1]) % mod) % mod;
                        }
                        tcomb[j] = sum;
                    }
                    comb = tcomb;
                }
                combSum[0] = comb[0];
                for (int i = 1; i < comb.Length; i++)
                {
                    combSum[i] = (comb[i] + combSum[i - 1]) % mod;
                }

                long ans = 0;
                for (int i = 0; i < comb.Length; i++)
                {
                    int index = Math.Min(i + a - b - 1, combSum.Length - 1);
                    if (index >= 0) ans = (ans + (comb[i] * combSum[index]) % mod) % mod;
                }
                writer.WriteLine(ans);
            }
        }
    }
}

using System;
