namespace ProgrammingContest.Codeforces.Round70
{
    class E
    {
        static int t,n;
        static int[,] dist, dist2;
        static string[] b1, b2;

        static void bfs(int x, int y, bool chk)
        {
            int[] dx = new int[4] { 1, 0, -1, 0 },
                  dy = new int[4] { 0, -1, 0, 1 };
            bool[,] visited = new bool[n, n];
            Queue<int> q = new Queue<int>();
            q.Enqueue(x * n + y);
            visited[x, y] = true;
            for (int a = 0; a < n; a++)
                for (int b = 0; b < n; b++)
                    dist[a, b] = 100000;
            dist[x, y] = 0;
            while (q.Any())
            {
                int v = q.Dequeue();
                x = v / n; y = v % n;
                for (int i = 0; i < 4; i++)
                    if (InRange(x + dx[i]) && InRange(y + dy[i]))
                    {
                        int d = dist[x, y] + 1;
                        if (visited[x + dx[i], y + dy[i]] || d > t)
                        {
                            continue;
                        }
                        visited[x + dx[i], y + dy[i]] = true;
                        if (!chk)
                        {
                            dist[x + dx[i], y + dy[i]] = d;
                            if (char.IsDigit(b1[y + dy[i]][x + dx[i]]))
                                q.Enqueue((x + dx[i]) * n + (y + dy[i]));
                        }
                        else
                        {
                            char b = b2[y + dy[i]][x + dx[i]];
                            if (!char.IsDigit(b1[y + dy[i]][x + dx[i]]))
                            {
                                dist[x + dx[i], y + dy[i]] = d;
                            }
                            else if (d < dist2[x + dx[i], y + dy[i]])
                            {
                                q.Enqueue((x + dx[i]) * n + (y + dy[i]));
                                dist[x + dx[i], y + dy[i]] = d;
                            }
                            else if ('0' <= b && b <= '9' && d == dist2[x + dx[i], y + dy[i]])
                                dist[x + dx[i], y + dy[i]] = d;
                        }
                    }
            }
        }

        static bool InRange(int v) { return 0 <= v && v < n; }

        public static void Main()
        {
            var xs = Array.ConvertAll(Console.ReadLine().Split(' '), sss => int.Parse(sss));
            n = xs[0];
            t = xs[1];
            dist = new int[n, n];
            b1 = new string[n];
            b2 = new string[n];
            for (int y = 0; y < n; y++)
                b1[y] = Console.ReadLine();
            Console.ReadLine();
            for (int y = 0; y < n; y++)
                b2[y] = Console.ReadLine();
            Dinic dinic = new Dinic(2000);
            int scnt = 2;
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                    if (b1[y][x] == 'Z')
                    {
                        bfs(x,y,false);
                        dist2 = (int[,])dist.Clone();
                    }
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    if ('1' <= b1[y][x] && b1[y][x] <= '9')
                    {
                        //Console.WriteLine("check {0} {1}", x, y);
                        bfs(x, y, true);
                        int scientists = b1[y][x] - '0';
                        for (int j = 0; j < scientists; j++)
                            dinic.AddEdge(0, scnt + j, 1);
                        int idx = 1000;
                        for (int a = 0; a < n; a++)
                            for (int b = 0; b < n; b++)
                                if ('1' <= b2[a][b] && b2[a][b] <= '9')
                                {
                                    int cnt = b2[a][b] - '0';
                                    for (int i = 0; i < cnt; i++, idx++)
                                        if (dist[b, a] < 100000)
                                        {
                                            //Console.WriteLine("{0} {1} -> {2} {3}", x, y, b, a);
                                            for (int j = 0; j < scientists; j++)
                                                dinic.AddEdge(scnt + j, idx, 1);
                                        }
                                }
                        scnt += scientists;
                    }
                }
            for (int y = 0, k = 1000; y < n; y++)
                for (int x = 0; x < n; x++)
                    if ('1' <= b2[y][x] && b2[y][x] <= '9')
                    {
                        int cnt = b2[y][x] - '0';
                        for (int i = 0; i < cnt; i++, k++)
                            dinic.AddEdge(k, 1, 1);
                    }
            Console.WriteLine(dinic.BipartiteMatching(0,1));
        }

        #region MaximumFlow
        class Dinic
        {
            const int INF = 1 << 29;

            class Edge
            {
                public int to, cap, rev;
                public Edge(int to_, int cap_, int rev_) { to = to_; cap = cap_; rev = rev_; }
            }

            List<Edge>[] G;
            int[] level, iter;

            void bfs(int s)
            {
                for (int i = 0; i < level.Length; i++) level[i] = -1;
                Queue<int> q = new Queue<int>();
                level[s] = 0;
                q.Enqueue(s);
                while (q.Count > 0)
                {
                    int v = q.Dequeue();
                    for (int i = 0; i < G[v].Count; i++)
                    {
                        Edge e = G[v][i];
                        if (e.cap > 0 && level[e.to] < 0)
                        {
                            level[e.to] = level[v] + 1;
                            q.Enqueue(e.to);
                        }
                    }
                }
            }

            int dfs(int v, int t, int f)
            {
                if (v == t) return f;
                for (int i = iter[v]; i < G[v].Count; i++, iter[v]++)
                {
                    Edge e = G[v][i];
                    if (e.cap > 0 && level[v] < level[e.to])
                    {
                        int d = dfs(e.to, t, Math.Min(f, e.cap));
                        if (d > 0)
                        {
                            e.cap -= d;
                            G[e.to][e.rev].cap += d;
                            return d;
                        }
                    }
                }
                return 0;
            }

            public void AddEdge(int from, int to, int cap)
            {
                G[from].Add(new Edge(to, cap, G[to].Count));
                G[to].Add(new Edge(from, 0, G[from].Count - 1));
            }

            public int MaxFlow(int s, int t)
            {
                int flow = 0;
                for (; ; )
                {
                    bfs(s);
                    if (level[t] < 0) return flow;
                    for (int i = 0; i < iter.Length; i++) iter[i] = 0;
                    for (int f = 0; (f = dfs(s, t, INF)) > 0; )
                        flow += f;
                }
            }

            public int BipartiteMatching(int s, int t)
            {
                return MaxFlow(s, t);
            }

            public Dinic(int size)
            {
                level = new int[size];
                iter = new int[size];
                G = new List<Edge>[size];
                for (int i = 0; i < size; i++)
                    G[i] = new List<Edge>();
            }
        }
        #endregion
    }
}

