namespace TheTournamentC1
{
    partial class TheTournamentC1
    {
        static void Main(string[] args)
        {
            int n, k, min;
            int[] points, effort, record, minEffort;

            n = NextInt();
            k = NextInt();

            points = new int[n];
            effort = new int[n];
            record = new int[n];
            minEffort = new int[2];

            for (int i = 0; i < n; i++)
            {
                points[i] = NextInt() + 1;
                effort[i] = NextInt();
                record[i] = 0;
            }

            minEffort[0] = Solve(0, k, 1, 0, 0, (int[])points.Clone(), (int[])effort.Clone(), (int[])record.Clone());
            minEffort[1] = Solve(0, k, 0, 0, 0, (int[])points.Clone(), (int[])effort.Clone(), (int[])record.Clone());

            min = minEffort.Min();
            min = min == int.MaxValue ? -1 : min;

            Console.WriteLine(min);
        }

        private static int Solve(int fighter, int k, int win, int currentPoints, int currentEffort, int[] points, int[] effort, int[] record)
        {
            int[] minEffort = new int[2];

            if (win == 1)
            {
                currentPoints++;
                currentEffort += effort[fighter];
                points[fighter]--;
                record[fighter] = 1;
            }

            fighter++;

            if (fighter < points.Length)
            {
                minEffort[0] = Solve(fighter, k, 1, currentPoints, currentEffort, (int[])points.Clone(), (int[])effort.Clone(), (int[])record.Clone());
                minEffort[1] = Solve(fighter, k, 0, currentPoints, currentEffort, (int[])points.Clone(), (int[])effort.Clone(), (int[])record.Clone());
            }
            else
            {
                if (IsWithinKRank((int[])points.Clone(), currentPoints, k, (int[])record.Clone()))
                    return currentEffort;
                else
                    return int.MaxValue;
            }

            return minEffort.Min();
        }

        private static bool IsWithinKRank(int[] points, int currentPoints, int k, int[] record)
        {
            int n = points.Length, rank = n + 1;
            int[] fighters = Enumerable.Range(0, n).ToArray();

            Array.Sort(points, fighters);

            for (int i = 0; i < n; i++)
            {
                if (currentPoints > points[i] || (currentPoints == points[i] && record[fighters[i]] == 1))
                    rank--;
            }

            return rank <= k;
        }
    }

