    const int MOD = 51123987;
    const int MAX = 50;

    public void Solve()
    {
        int n = ReadInt();
        string s = ReadToken();

        var g = new List<int>();
        for (int i = 0; i < n; i++)
            if (i == n - 1 || s[i] != s[i + 1])
                g.Add(s[i] - 'a');

        int m = g.Count;
        var next = new int[m, 3];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < 3; j++)
            {
                int k;
                for (k = i; k < m; k++)
                    if (g[k] == j)
                        break;
                next[i, j] = k;
            }

        var dp = new int[m + 1, MAX + 2, MAX + 2];
        dp[0, 0, 0] = 1;
        for (int i = 0; i < n; i++)
        {
            var ndp = new int[m + 1, MAX + 2, MAX + 2];
            for (int j = 0; j < m; j++)
                for (int xa = 0; xa <= i && xa <= MAX; xa++)
                    for (int xb = 0; xa + xb <= i && xb <= MAX; xb++)
                    {
                        ndp[next[j, 0], xa + 1, xb] = (ndp[next[j, 0], xa + 1, xb] + dp[j, xa, xb]) % MOD;
                        ndp[next[j, 1], xa, xb + 1] = (ndp[next[j, 1], xa, xb + 1] + dp[j, xa, xb]) % MOD;
                        ndp[next[j, 2], xa, xb] = (ndp[next[j, 2], xa, xb] + dp[j, xa, xb]) % MOD;
                    }
            dp = ndp;
        }

        int ans = 0;
        for (int i = 0; i < m; i++)
            for (int j = n / 3; j < n / 3 + 2; j++)
                for (int k = n / 3; k < n / 3 + 2; k++)
                    if (Math.Abs(j - k) < 2 && Math.Abs(j - (n - j - k)) < 2 && Math.Abs(k - (n - j - k)) < 2)
                        ans = (ans + dp[i, j, k]) % MOD;
        Write(ans);
    }

