public class Program
{
    long X, Y;
    public void Solve()
    {
        var sc = new Scanner();
        X = sc.NextLong();
        Y = sc.NextLong();

        if (X == Y)
        {
            Console.WriteLine("YES");
            return;
        }

        bool[] by = ToArray(Y);

        bool[] bx1 = ToArray(2 * X + 1);
        if (F(by, bx1))
        {
            Console.WriteLine("YES");
            return;
        }
        Array.Reverse(bx1);
        if (F(by, bx1))
        {
            Console.WriteLine("YES");
            return;
        }

        while (X % 2 == 0) X /= 2;
        bool[] bx2 = ToArray(X);
        if (F(by, bx2))
        {
            Console.WriteLine("YES");
            return;
        }
        Array.Reverse(bx2);
        if (F(by, bx2))
        {
            Console.WriteLine("YES");
            return;
        }

        Console.WriteLine("NO");
    }


    bool F(bool[] fy, bool[] fx)
    {
        if (fy.Length < fx.Length) return false;
        bool left = true;
        for (int i = 0; i + fx.Length <= fy.Length && left; i++)
        {
            bool flag = true;
            for (int j = 0; j < fx.Length && flag; j++)
            {
                flag &= fx[j] == fy[i + j];
            }
            if (flag)
            {
                for (int j = i + fx.Length; j < fy.Length && flag; j++)
                {
                    flag &= fy[j];
                }
                if (flag) return true;
            }

            left &= fy[i];
        }
        return false;
    }

    bool[] ToArray(long n)
    {
        int lg = 0;
        long tmp = n;
        while (tmp > 0)
        {
            lg++;
            tmp /= 2;
        }

        tmp = n;
        bool[] ret = new bool[lg];
        for (int i = 0; i < lg; i++)
        {
            ret[i] = tmp % 2 == 1;
            tmp /= 2;
        }
        return ret;
    }

    public static void Main(string[] args) => new Program().Solve();
    // public static void Main(string[] args) => new Thread(new Program().Solve, 1 << 27).Start();
}

