	[Serializable]
	class VNode<TNode, TEdge>
		where TNode : ICloneable
	{
		VGraph<TNode, TEdge> _graph;

		Stack<VNodeValue<TNode>> _valueStack = new Stack<VNodeValue<TNode>>();
		Stack<VEdges<TNode, TEdge>> _ins = new Stack<VEdges<TNode, TEdge>>();
		Stack<VEdges<TNode, TEdge>> _outs = new Stack<VEdges<TNode, TEdge>>();

		internal VNode(VGraph<TNode, TEdge> graph, TNode nodeValue)
		{
			_graph = graph;
			var newNode = new VNodeValue<TNode>(_graph.Version);
			newNode.Value = nodeValue;
			_valueStack.Push(newNode);
			_ins.Push(new VEdges<TNode, TEdge>(_graph.Version));
			_outs.Push(new VEdges<TNode, TEdge>(_graph.Version));
		}

		public TNode ReadValue
		{
			get { return _valueStack.Peek().Value; }
		}

		public TNode WriteValue
		{
			get
			{
				if (_valueStack.Peek().Version != _graph.Version)
				{
					var newVersion = new VNodeValue<TNode>(_graph.Version);
					if (_valueStack.Peek().Value != null)
						newVersion.Value = (TNode)_valueStack.Peek().Value.Clone();
					_valueStack.Push(newVersion);
					_graph.SheduleValueRollback(this);
				}

				return _valueStack.Peek().Value;
			}
		}

		public IEnumerable<VEdge<TNode, TEdge>> Ins
		{
			get
			{
				foreach (var edges in _ins)
					foreach (var e in edges.Edges)
					{
						yield return e;
					}
			}
		}

		public IEnumerable<VEdge<TNode, TEdge>> Outs
		{
			get
			{
				foreach (var edges in _outs)
					foreach (var e in edges.Edges)
					{
						yield return e;
					}
			}
		}

		public void AddIns(VEdge<TNode, TEdge> edge)
		{
			if (_ins.Peek().Version != _graph.Version)
			{
				var newVersion = new VEdges<TNode, TEdge>(_graph.Version);
				_ins.Push(newVersion);
				_graph.SheduleInEdgeRollback(this);
			}
			_ins.Peek().Edges.Add(edge);
		}

		public void AddOut(VEdge<TNode, TEdge> edge)
		{
			if (_outs.Peek().Version != _graph.Version)
			{
				var newVersion = new VEdges<TNode, TEdge>(_graph.Version);
				_outs.Push(newVersion);
				_graph.SheduleOutEdgeRollback(this);
			}
			_outs.Peek().Edges.Add(edge);
		}

		internal void RollbackValue()
		{
			_valueStack.Pop();
		}

		internal void RollbackIns()
		{
			_ins.Pop();
		}

		internal void RollbackOuts()
		{
			_outs.Pop();
		}

		public override string ToString()
		{
			return ReadValue.ToString();
		}
	}

	[Serializable]
	class VGraph<TNode, TEdge> : IDisposable
		where TNode : ICloneable
	{
		public int Version = 0;

		Stack<List<VNode<TNode, TEdge>>> _valueRollbacks = new Stack<List<VNode<TNode, TEdge>>>();
		Stack<List<VNode<TNode, TEdge>>> _inEdgeRollbacks = new Stack<List<VNode<TNode, TEdge>>>();
		Stack<List<VNode<TNode, TEdge>>> _outEdgeRollbacks = new Stack<List<VNode<TNode, TEdge>>>();

		public VGraph()
		{
			StartTransaction();
		}

		public void SheduleValueRollback(VNode<TNode, TEdge> node)
		{
			_valueRollbacks.Peek().Add(node);
		}

		public void SheduleInEdgeRollback(VNode<TNode, TEdge> node)
		{
			_inEdgeRollbacks.Peek().Add(node);
		}

		public void SheduleOutEdgeRollback(VNode<TNode, TEdge> node)
		{
			_outEdgeRollbacks.Peek().Add(node);
		}

		public VNode<TNode, TEdge> AddNode(TNode nodeValue)
		{
			return new VNode<TNode, TEdge>(this, nodeValue);
		}

		public void AddEdge(VNode<TNode, TEdge> a, VNode<TNode, TEdge> b, TEdge edgeValue)
		{
			var newEdge = new VEdge<TNode, TEdge>();
			newEdge.Source = a;
			newEdge.Target = b;
			newEdge.Value = edgeValue;

			a.AddOut(newEdge);
			b.AddIns(newEdge);
		}

		public VGraph<TNode, TEdge> StartTransaction()
		{
			this.Version++;
			_valueRollbacks.Push(new List<VNode<TNode, TEdge>>());
			_inEdgeRollbacks.Push(new List<VNode<TNode, TEdge>>());
			_outEdgeRollbacks.Push(new List<VNode<TNode, TEdge>>());
			return this;
		}

		public void Rollback()
		{
			foreach (var values in _valueRollbacks.Pop())
				values.RollbackValue();
			foreach (var values in _inEdgeRollbacks.Pop())
				values.RollbackIns();
			foreach (var values in _outEdgeRollbacks.Pop())
				values.RollbackOuts();
			this.Version--;
		}

		public void Dispose()
		{
			Rollback();
		}
	}

