	[Serializable]
	class GameState : IDisposable
	{
		VGraph<ExpressionNode, ExpressionPath> _graph = new VGraph<ExpressionNode, ExpressionPath>();
		Stack<List<VNode<ExpressionNode, ExpressionPath>>> nodes = new Stack<List<VNode<ExpressionNode, ExpressionPath>>>();
		Stack<VNode<ExpressionNode, ExpressionPath>[]> playerNodes = new Stack<VNode<ExpressionNode, ExpressionPath>[]>();
		VNode<ExpressionNode, ExpressionPath>[] playerStartNodes = new VNode<ExpressionNode, ExpressionPath>[3];
		int nodesCount = 0;

		public IEnumerable<VNode<ExpressionNode, ExpressionPath>> Nodes
		{
			get
			{
				foreach (var ns in nodes)
					foreach (var node in ns)
						yield return node; 
			}
		}

		public void ClearTrace(Player[] players)
		{
			foreach (var node in Nodes)
			{
				node.WriteValue.Min = int.MinValue/2;
				node.WriteValue.Max = int.MaxValue/2;
			}

			for (int i = 0; i < 3; i++)
			{
				playerStartNodes[i].WriteValue.Min = playerStartNodes[i].WriteValue.Max = players[i].Start;
			}
		}

		public GameState(Player[] players)
		{
			nodes.Push(new List<VNode<ExpressionNode, ExpressionPath>>());

			playerNodes.Push(new VNode<ExpressionNode, ExpressionPath>[3]);
			for (int i = 0; i < 3; i++)
			{
				var node = _graph.AddNode(new ExpressionNode() { Id = i, Min = players[i].Start, Max = players[i].Start, Comment = "S("+ i.ToString() +")" });
				nodes.Peek().Add(node);
				playerStartNodes[i] = node;
				playerNodes.Peek()[i] = node;
			}
			nodesCount = 3;
		}

		public GameState StartTransaction()
		{
			_graph.StartTransaction();
			nodes.Push(new List<VNode<ExpressionNode, ExpressionPath>>());
			playerNodes.Push( (VNode<ExpressionNode, ExpressionPath>[])playerNodes.Peek().Clone());
			return this;
		}

		public void Dispose()
		{
			_graph.Rollback();

			nodesCount -= nodes.Pop().Count;
			playerNodes.Pop();
		}

		public int Max
		{
			get
			{
				int max = Int32.MinValue;
				foreach (var node in Nodes)
				{
					if (max < node.ReadValue.Max)
						max = node.ReadValue.Max;
				}

				return max;
			}
		}

		public VNode<ExpressionNode, ExpressionPath> AddPlayerNode(int i, string comment)
		{
			var nodeValue = new ExpressionNode() { Id = nodesCount++ };
			nodeValue.Comment = comment;
			var node = _graph.AddNode(nodeValue);
			nodes.Peek().Add(node);
			playerNodes.Peek()[i] = node;
			return node;
		}

		public VNode<ExpressionNode, ExpressionPath> GetPlayerNode(int i)
		{
			return playerNodes.Peek()[i];
		}

		public VNode<ExpressionNode, ExpressionPath> GetPlayerStartNode(int i)
		{
			return playerStartNodes[i];
		}

		//a <= b + c
		public bool AddMin(VNode<ExpressionNode, ExpressionPath> a, VNode<ExpressionNode, ExpressionPath> b, int c)
		{
			var path = new ExpressionPath() { Mark = c };
			_graph.AddEdge(b, a, path);

			if (a.ReadValue.Max > b.ReadValue.Max + c)
				a.WriteValue.Max = b.ReadValue.Max + c;

			if (b.ReadValue.Min < a.ReadValue.Min - c)
				b.WriteValue.Min = a.ReadValue.Min - c;

			if (!Trace(a))
				return false;
			if (!Trace(b))
				return false;
			if (!Validate())
				return false;

			return true;
		}

		bool Trace(VNode<ExpressionNode, ExpressionPath> a)
		{
			if (!TraceMin(this, a))
				return false;
			if (!TraceMax(this, a))
				return  false;
			return true;
		}

		static bool TraceMin(GameState state, VNode<ExpressionNode, ExpressionPath> x)
		{
			x.WriteValue.Traced = true;

			try
			{
				foreach (var vector in state.Maximize(x))
				{
					// x <= path.Max + path.Mark

					if (vector.Target.ReadValue.Traced)
					{
						if (vector.Target.ReadValue.Min < x.ReadValue.Min - vector.Mark)
							return false;
					}
					else
					{
						if (vector.Target.ReadValue.Min < x.ReadValue.Min - vector.Mark)
						{
							vector.Target.WriteValue.Min = x.ReadValue.Min - vector.Mark;
							if (!TraceMin(state, vector.Target))
								return false;
						}
					}
				}
				return true;
			}
			finally
			{
				x.WriteValue.Traced = false;
			}
		}

		static bool TraceMax(GameState state, VNode<ExpressionNode, ExpressionPath> x)
		{
			x.WriteValue.Traced = true;

			try
			{
				foreach (var vector in state.Minimize(x))
				{
					if (vector.Target.ReadValue.Traced)
					{
						if (vector.Target.ReadValue.Max > x.ReadValue.Max + vector.Mark)
							return false;
					}
					else
					{
						if (vector.Target.ReadValue.Max > x.ReadValue.Max + vector.Mark)
						{
							vector.Target.WriteValue.Max = x.ReadValue.Max + vector.Mark;
							if (!TraceMax(state, vector.Target))
								return false;
						}
					}
				}
				return true;
			}
			finally
			{
				x.WriteValue.Traced = false;
			}
		}

		public IEnumerable<Vector> Maximize(VNode<ExpressionNode, ExpressionPath> a)
		{
			return a.Ins.Select(path => new Vector(path.Value.Mark, path.Source));
		}

		public IEnumerable<Vector> Minimize(VNode<ExpressionNode, ExpressionPath> a)
		{
			return a.Outs.Select(path => new Vector(path.Value.Mark, path.Target));
		}

		public bool Validate()
		{
			foreach (var node in Nodes)
			{
				if (node.ReadValue.Min > node.ReadValue.Max)
					return false;
			}

			return true;
		}

		public override string ToString()
		{
			string result = "";

			foreach (var node in Nodes.Reverse())
			{
				result += node.ReadValue.ToString();
			}

			return result;
		}
	}

