		}

		static int AbsoluteMax = int.MinValue;
		static string AbsoluteMaxStr = "";

		static void Main(string[] args)
		{
			Player[] players = new Player[3];
			for (int i = 0; i < 3; i++)
			{
				players[i] = new Player();
				string[] arg = ReadLine().Split();
				players[i].Start = int.Parse(arg[0]);
				players[i].Walk = int.Parse(arg[1]);
				players[i].Throws = int.Parse(arg[2]);
			}


			var state = new GameState(players);

			Solve(state, players);
			Console.WriteLine(AbsoluteMax);
			//Console.WriteLine(AbsoluteMaxStr);
		}


		static void Solve(GameState state, Player[] players)
		{
			if (EuristicGetMax(state, players) <= AbsoluteMax)
				return;

			int max = state.Max;
			if (AbsoluteMax < max)
			{
				AbsoluteMax = max;
				AbsoluteMaxStr = state.ToString();
			}

			for (int i = 0; i < 3; i++)
			{
				using (var clone = state.StartTransaction())
				{
					DoMove(i, clone, players);
				}
			}

			for (int i = 0; i < 3; i++)
				for (int j = 0; j < 3; j++)
					if (i != j)
					{
						using (var clone = state.StartTransaction())
						{
							DoUp(i, j, clone, players);
						}
					}

			for (int i = 0; i < 3; i++)
			{
				using (var clone = state.StartTransaction())
				{
					DoThrow(i, clone, players);
				}
			}
		}

		static private void DoMove(int i, GameState state, Player[] players)
		{
			if (players[i].alreadyWalked || players[i].Up >= 0 || players[i].Upped)
				return;

			players[i].alreadyWalked = true;

			VNode<ExpressionNode, ExpressionPath> a = state.GetPlayerNode(i);
			VNode<ExpressionNode, ExpressionPath> moved = state.AddPlayerNode(i, string.Format("M({0})", i));

			if (!state.AddMin(moved, a, players[i].Walk))
				return;
			if (!state.AddMin(a, moved, players[i].Walk))
				return;

			using (var clone = state.StartTransaction())
			{
				NotEqual(players, i, clone);
			}

			players[i].alreadyWalked = false;
		}

		private static void DoThrow(int i, GameState state, Player[] players)
		{
			if (players[i].alreadyThrowed || players[i].Up < 0 || players[i].Upped)
				return;

			players[i].alreadyThrowed = true;

			int j = players[i].Up;
			players[i].Up = -1;
			players[j].Upped = false;

			VNode<ExpressionNode, ExpressionPath> a = state.GetPlayerNode(i);
			VNode<ExpressionNode, ExpressionPath> moved = state.AddPlayerNode(j, string.Format("T({0}, {1})", i, j));

			if (!state.AddMin(moved, a, players[i].Throws))
				return;
			if (!state.AddMin(a, moved, players[i].Throws))
				return;

			NotEqual(players, j, state);

			players[j].Upped = true;
			players[i].Up = j;
			players[i].alreadyThrowed = false;
		}

		private static void DoUp(int i, int j, GameState state, Player[] players)
		{
			if (players[i].alreadyUpped || players[i].Up >= 0 || players[i].Upped || players[j].Upped || i == j)
				return;

			players[i].alreadyUpped = true;
			players[i].Up = j;
			players[j].Upped = true;

			VNode<ExpressionNode, ExpressionPath> a = state.GetPlayerNode(i);
			VNode<ExpressionNode, ExpressionPath> b = state.GetPlayerNode(j);

			VNode<ExpressionNode, ExpressionPath> moved = state.AddPlayerNode(j, string.Format("U({0}, {1})", i, j));

			if (!state.AddMin(moved, a, 0))
				return;
			if (!state.AddMin(a, moved, 0))
				return;

			Equal(state, players, a, b, 1);
			Equal(state, players, a, b, -1);

			players[j].Upped = false;
			players[i].Up = -1;
			players[i].alreadyUpped = false;
		}

		//a = b + c
		private static void Equal(GameState state, Player[] players, VNode<ExpressionNode, ExpressionPath> a, VNode<ExpressionNode, ExpressionPath> b, int c)
		{
			using (var v1 = state.StartTransaction())
			{
				if (v1.AddMin(b, a, -c) && v1.AddMin(a, b, c))
					Solve(v1, players);
			}
		}

		static private void NotEqual(Player[] players, int i, GameState state)
		{
			VNode<ExpressionNode, ExpressionPath> a = state.GetPlayerNode(i); //current 
			VNode<ExpressionNode, ExpressionPath> b = state.GetPlayerNode((i + 1) % 3); //not equal to
			VNode<ExpressionNode, ExpressionPath> c = state.GetPlayerNode((i + 2) % 3); //and not equal to

			using (var v1 = state.StartTransaction())
			{
				if (v1.AddMin(a, b, -1) && v1.AddMin(a, c, -1))
					Solve(v1, players);
			}

			using (var v2 = state.StartTransaction())
			{
				if (v2.AddMin(b, a, -1) && v2.AddMin(a, c, -1))
					Solve(v2, players);
			}

			using (var v3 = state.StartTransaction())
			{
				if (v3.AddMin(b, a, -1) && v3.AddMin(c, a, -1))
					Solve(v3, players);
			}

			using (var v4 = state.StartTransaction())
			{
				if (v4.AddMin(a, b, -1) && v4.AddMin(c, a, -1))
					Solve(v4, players);
			}
		}

		static int EuristicGetMax(GameState state, Player[] players)
		{
			int radius = 0;

			for (int i = 0; i < 3; i++)
			{
				if (!players[i].alreadyThrowed)
					radius += players[i].Throws;
				if (!players[i].alreadyWalked)
					radius += players[i].Walk;
				if (!players[i].alreadyUpped)
					radius += 1;
			}

			var result = Enumerable.Range(0,3).Max(i => state.GetPlayerNode(i).ReadValue.Max + radius);
			return result;
		}
	}

